window.__D("text/zohar-chadash/c001",{"p":[[9514011456,"<p>קָרֵיב גַּבָּאי, וְלָא סָפֵיק לְמַלָּלָא עִמִּי, אֲמַר לִי אֲנָא חָמֵי בָּךְ, דְּנִשְׁמָתָא חַדְתָּא אִית בָּךְ, מִיּוֹמִין זְעִירִין, וְלָא אִזְדְרִיקַת בָּךְ בְּשַׁעֲתָא דְּנָפְקַת לְעָלְמָא. תְּוָוהִית. אֲמָרִית, כָּךְ הוּא, דְּרַוָּוק הֲוֵינָא, כַּד לָעֵינָא בְּאוֹרַיְיתָא, וְאִתְיַיהֲבַת בִּי נִשְׁמָתָא.</p>"],[9514011457,"<p>אֲמַר לִי, יְדַעְתְּ נֶפֶשׁ חַיָּה, דַּאֲמַר קְרָא, דַּהֲוַות מִן אַרְעָא, וְהָא מַשְׁמַע נֶפֶשׁ חַיָּה, לָמָּה. אֲמָרִית, אֵימָא בְּרִי.</p>"],[9514011458,"<p>אֲמַר, הָכֵי אָמַר לִי מוֹרִי, דְּהִיא נַפְשָׁא דַּאֲפֵיקַת אַרְעָא. וּמִן אַרְעָא אִתְגְּזָרַת. אֲבָל הִיא חַיְיתָא, לְאִתְנַעְנְעָא לְכָאן וּלְכָאן. כְּמָה דְּעָבְדִין בְּעִירָא וְרִחֲשָׁא, וְכֹלָּא. אֲבָל לֵית בָּהּ סוּכְלְתָנוּתָא וְחָכְמְתָא בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא אִתְבְּרִיאַת אֶלָּא לִבְעִירָא וּלְחַיָּיתָא, לְאִתְנַעְנְעָא בָּהּ בְּלָא סוּכְלְתָנוּ, וּלְאִשְׁתֵּצָאָה, כַּד תֵּפּוֹק, כְּהַאי הֶבֶל דְּפוּמָא.</p>"],[9514011459,"<p>אֲמָרִית לֵיהּ בְּרִי, מָאן הוּא רַבָּךְ. אֲמַר לִי רַבִּי אֲלֶכְּסַנְדְּרָאי. אֲמָרִית לֵיהּ, וּמָה לָעֵית יוֹמָא דֵין. אֲמַר לִי, הַאי קְרָא דִּכְתִיב, (תהלים קיא) רֵאשִׁית חָכְמָה יִרְאַת ה' שֵׂכֶל טוֹב לְכָל עוֹשֵׂיהֶם. כָּךְ אָמַר רִבִּי אֲלֶכְּסַנְדְּרָאי, מָה הוּא חָכְמָה. הוּא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהוּא חָכְמָה. וּמֵעוֹלָם לֹא גִּילָּה לְשׁוּם אָדָם, וְלֹא עָתִיד לְהִגָּלוֹת, אֶלָּא קְצָת הֵימֶנָּהּ לְמשֶׁה לְבַד.</p>"],[9514011460,"<p>וְלֹא עָמַד עַל כָּל יְדִיעָתָהּ, אֶלָּא עָמַד עַל מַה שֶּׁלֹּא עָמַד אָדָם, עַל הַאי רֵאשִׁית, שֶׁהִיא חָכְמָה. דִּכְתִיב בֵּיהּ בְּמשֶׁה, (דברים ל״ג:כ״א) וַיַּרְא רֵאשִׁית לוֹ, וְזֶהוּ חָכְמָה.</p>"],[9514011461,"<p>וְאִם תֹּאמַר, הָא כְתִיב (מלכים א ה׳:כ״ו) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה. תָּא חֲזֵי, לֹא כְתִיב נָתַן הַחָכְמָה, אֶלָא חָכְמָה, שֶׁעָמַד עַל קְצַת אֲמִיתָּתָהּ. הַמָּשִׁיחַ עָתִיד לָדַעַת קְצָתוֹ, דִּכְתִיב בֵּיהּ, (ישעיהו י״א:ב׳) וְנָחָה עָלָיו רוּחַ ה' רוּחַ חָכְמָה וּבִינָה כו'.</p>"],[9514011462,"<p>וְהַחָכְמָה הִיא רֵאשִׁית הַכֹּל, וְקוֹדֶם הַכֹּל, אֲבָל יִרְאַת ה', שֵׂכֶל טוֹב. כְּלוֹמַר, הַיִּרְאָה נִשְׁאֲרָה בַּשֵׂכֶל וּבִינָה, לָדַעַת וְלַחֲקוֹר יִרְאַת ה'. לְכָל עוֹשֵׂיהֶם, לְעוֹשֶׂה הַמִּצְוֹת בְּיִרְאָה בַּתְּחִלָּה, עַד שֶׁיַּרְגִּיל עַצְמוֹ לַעֲשׂוֹת מֵאַהֲבָה.</p>"],[9514011463,"<p>אָמַרְתִּי לוֹ, מַה שִּׁמְךָ. אָמַר לִי, אַהֲבָה. אָמַרְתִּי לוֹ, מַר אַהֲבָה, וְקָרִיתִי עָלָיו, (ירמיהו ל״א:ג׳) וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ. וַאֲנָא זָכֵינָא לְמֶחֱמֵי לְרַב אַדָּא בְּרֵיהּ, וְסָחֵינָא לֵיהּ הַאי.</p>"],[9514011464,"<p>אָמַר רִבִּי יַעֲקֹב בַּר אִידֵי, חָכָם הָיָה אָדָם הָרִאשׁוֹן, שֶׁהָיָה מַכִּיר וְיוֹדֵעַ לְכָל מִי שֶׁהָיָה בוֹ נֶפֶשׁ חַיָּה, וּמִי שֶׁהָיָה בוֹ נְשָׁמָה, כְּשֶׁבָּאוּ אֶצְלוֹ הִכִּיר אֶת כֻּלָּם. הֲדָא הוּא דִכְתִיב (בראשית ב׳:י״ט) וְכָל אֲשֶׁר יִקְרָא לוֹ הָאָדָם נֶפֶשׁ חַיָּה, לְמִי שֶׁאֵינוֹ יוֹדֵעַ וּמַכִּיר בַּעֲבוֹדַת בּוֹרְאוֹ. וּנְשָׁמָה לְמִי שֶׁהָיָה יוֹדֵעַ וּמַכִּיר בַּעֲבוֹדַת בּוֹרְאוֹ. וְכָךְ הוּא עַד הַיּוֹם, מִי שֶׁאֵינוֹ יוֹדֵעַ וּמַכִּיר בַּעֲבוֹדַת בּוֹרְאוֹ, וְאֵינוֹ עוֹסֵק בַּתּוֹרָה, הוּא יֵשׁ לוֹ נֶפֶשׁ חַיָּה, וְלֹא נְשָׁמָה.</p>"],[9514011465,"<p>אָמַר רִבִּי יְהוּדָה, אַף עַל גַּב דְּהַאי נֶפֶשׁ חַיָּה אִית בִּבְהֵמוֹת וּבְחַיּוֹת וּבְמִינִיהֶם, וְהִתִּירָם לִבְנֵי אָדָם, חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם בְּמִיתָתָם, שֶׁלֹּא יְצַעֲרוּם לְאוֹתָם בַּעֲלֵי נֶפֶשׁ הַחַיָּה. דְּלֵית לָךְ כָּל אֵינַשׁ, דְּלֵית בֵּיהּ נֶפֶשׁ חַיָּה, כְּדֵי שֶׁיָּשׁוּב לַעֲבוֹד בּוֹרְאוֹ, לְהַבְדִּיל עַצְמוֹ מִשְּׁאָר כָּל אָדָם, כְּדֵי לְהִתְעַסֵּק בַּתּוֹרָה וּבַמִּצְוֹת, שֶׁמַּרְוִיחַ בָּזֶה הַנְּשָׁמָה הַקְּדוֹשָׁה.</p>"],[9514011466,"<p>לְפִיכָךָ הַאי טַבְּחָא, דְּנָפְקָא נְבֵילָה אוֹ טְרֵיפָה מִתְּחוֹת יְדוֹהִי. זִמְנָא חָדָא, מְשַׁמְתִּינָן לֵיהּ. שֵׁנִית, מַעֲבִירִינָן לֵיהּ. שְׁלִישִׁית, מַכְרִיזִין עֲלֵיהּ בְּשׁוּקֵי, דְּכָל מַה דְּשָּׁחִיט הוּא טְרֵיפָה. וּלְעוֹלָם לָא נוֹקִים לֵיהּ לְטַבְּחָא.</p>"],[9514011467,"<p>אָמַר רִבִּי יִצְחָק, וְכִי עַל זִמְנָא חָדָא לָא לֵיעָנֵישׁ בַּר מֵהַאי. וְהָא תָּנִינָן, הַאי טַבְּחָא דְּלָא סָר סַכִּינָא קַמֵּי חָכָם, מְשַׁמְתִּינָן וּמַעַבִרִינָן לֵיהּ, וּמַכְרְזִינָן אַבִּשְׂרֵיהּ דִּטְרֵפָה הִיא, וּמַה עַל סַכִּינָא דְּלָא נִמְצֵאת יָפָה הוּא כָּךְ. עַל מִי שֶׁיָּצְאָה נְבֵלָה אוֹ טְרֵפָה מִתַּחַת יָדוֹ, אֵינוֹ דִּין דִּמְשַׁמְתִּין לֵיהּ וּמַעֲבִירִינָן לֵיהּ, וּמַכְרְזִינָן אַבִּשְׂרֵיהּ דִּטְרֵפָה.</p>"],[9514011468,"<p>אָמַר רִבִּי יוֹסֵי, אֲנָא חָמִית לְרַבִּי יְהוּדָה דְּזַמִּין לְרַבִּי יוֹסֵי וְרַבִּי חַגַּי, וַהֲוָה טַבָּחָא, וְרַבִּי אַבָּא קָרֵין לֵיהּ. וְנָכֵיס הַהוּא תַּרְנְגוֹלְתָּא, וְנִתְכַּוֵּין לִתְרֵי סִימָנֵי, וּבָדְקוּ וְאַשְׁכָּחוּ דְּנָכֵיס חַד סִימָנָא, וְחַד לָא נָכֵיס.</p>"],[9514011469,"<p>אָמַר לֵיהּ רַבִּי יְהוּדָה, עַל מָה אִתְכַּוַּונְתּ. אֲמַר, עַל תְּרֵין סִימָנִין. אֲמַר, וְהָא אֲנָא אַשְׁכַּחְנָא חַד נָכֵיס. אֶלָּא בִּשְׂרָא הוּא דִּכְשֵׁרָה, וְאַתְּ לָא תְּהֵא טַבָּחָא מִכָּאן וּלְהָלְאָה. וְאַף עַל גַּב דְּלָא בָּעֵינָא כַּוָּונָה בִּשְׁחִיטָה.</p>"],[9514011470,"<p>אָמַר לֵיהּ ר' יוֹסֵי, הַכַּוָּונָה לָאו לְהַאי אִיתְּמָר, אֶלָּא כַּוָּונָה דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּנָכֵיס לַשָּׁמַיִם, וְלָא לְשׁוּם פִּתְגָּם אָחֳרָן. אֲבָל נִתְכַּוֵּון לִתְרֵי סִימָנֵי, וְשָׁחִיט חַד, מוּתָּר הוּא בְּדִיעֲבַד. דִּתְנַן, הַשּׁוֹחֵט אֶחָד בָּעוֹף, דִּיעֲבַד אֵין, לְכַתְּחִלָּה לֹא.</p>"],[9514011471,"<p>אָמַר רִבִּי יַעֲקֹב, תָּא חֲזֵי, כָּל מַה שֶּׁנִּבְרָא מִזּוֹ הַנֶּפֶשׁ הַחַיָּה, הִתִּירוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנֵי אָדָם, מִפְּנֵי שֶׁאֵין לָהֶם נְשָׁמָה לָדַעַת וּלְהַכִּיר בַּעֲבוֹדַת בּוֹרְאָם. דְּאִלְמָלֵי הַוְיָא לְהוֹ נְשָׁמָה, לֹא הוּתְּרוּ.</p>"],[9514011472,"<p>שָׁאַל רַבִּי אַבָּא לְרַבִּי חִיָּיא, אַמְרִיתּוּן דְּנִשְׁמָתָא לָא עַיִּיל בְּבַר נָשׁ, עַד דְּיִסְתַּכֵּל בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּכְדֵין לֶהֱוֵי לֵיהּ נִשְׁמָתָא, וְאַמְרִיתּוּן דְּנִשְׁמָתָא הִיא קַדִּישָׁא, מַעַלְיָא עַל כּוֹלָּא. אִם כֵּן מַאי הַאי דְּאָמַר קְרָא, (שם ז) כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ. לָמָּה מֵתוּ, הוֹאִיל וַהֲוָה לְהוֹ נִשְׁמְתָא, הֲוָה לְהוֹ לְאִשְׁתֵּזָבָא. לָא הֲוָה בִּידֵיהּ.</p>"],[9514011473,"<p>אָתוֹ וְשַׁיְילוּהָ לְרַבִּי אֶלְעָזָר בְּר' שִׁמְעוֹן, אָמַר לֵיהּ כָּךְ הוּא וַדַּאי, וּקְרָא מְסַיֵּיעַ לָן, דְּהָכֵי אָמַר אֲבוֹי, דְּכַד אָתֵי טוֹפָנָא לָא הֲוָה בַּר נָשׁ דְּיַעֲבֵיד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגִינֵיהּ, בַּר מִנֹּחַ וּבְנוֹהִי. וּזְכוּתְהוֹן לָא הֲוָה, אֶלָּא לְאָגֵין עֲלֵיהוֹן וְעַל בָּתֵּיהוֹן, וְלָא הֲוָה סַגֵּי זְכוּתְהוֹן כָּל כָּךְ, לַאֲגָנָא עַל כָּל דָּרָא. וְאִינוּן דַּהֲווֹ זַכָּאִין בְּקַדְמִיתָא, כְּגוֹן חֲנוֹךְ וְיֶרֶד, דְּהֲוָה לְהוֹן נִשְׁמָתָא, וְחַזְיָין לְמֵיעְבַּד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגִינֵיהוֹן, מִיתוּ מִקַּדְמַת דְּנָא. וְהַיְנוּ דַּאֲמַר קְרָא, כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו, דְּעַל אִינוּן דְּנִשְׁמָתָא קַדִּישָׁא הֲוָה בְּהוּ. דְּלָא תֵימָא דְּעַל אִלֵּין דַּהֲווֹ בְּטוֹפָנָא אֲמַר קְרָא. אֶלָּא אָתָא קְרָא, וַאֲמַר, מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ, שֶׁלֹּא הָיוּ בִּימֵי דּוֹר הַמַּבּוּל, וְלָא בְּאוֹתוֹ זְמַן, אֶלָּא בֶּחָרָבָה מֵתוּ, כְּלוֹמַר כְּבָר נִסְתַּלְּקוּ מִן הָעוֹלָם, וְלֹא נִשְׁתַּיֵּיר בָּעוֹלָם צַדִּיק לְהָגֵין עַל דּוֹרוֹ, וְאָז נַעֲשָׂה דִין בָּרְשָׁעִים.</p>"],[9514011474,"<p>אָמַר לֵיהּ ר' חִיָּיא לְרַבִּי אַבָּא, לָא אֲמָרִית לָךְ דְּהַאי גּוּלְגַּלְתָּא דְדַהֲבָא דְּהוּא מִמָּארֵיהוֹן דְּמַתְנִיתִין. לֵימָא, זַכָּאִין אַתּוּן מָארֵיהוֹן דְּמַתְנִיתִין, סַגֵּי חוּלָקֵיהוֹן עַל כּוֹלָּא לְעָלְמָא דְאָתֵי.</p>"],[9514011475,"<p>עוֹד אָמַר רִבִּי אֶלְעָזָר, מַאי דִכְתִיב. (תהילים ק״נ:ג׳-ד׳) הַלְּלוּהוּ בְּתֵקַע שׁוֹפָר הַלְלוּה\"וּ בְּנֵבֶ\"ל וְכִנּוֹ\"ר הַלְּלוּה\"וּ בְּתוֹ\"ף וּמָחוֹל הַלְּלוּה\"וּ בְּמִנִּי\"ם וְעוּגָב. וְכִי צָרִיךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַאי.</p>"],[9514011476,"<p>אֶלָּא אָמַר דָּוִד, כָּל מַה שֶׁתְּשַׁבְּחוּ לְקַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּהַנֵּי מִינֵי זֶמֶר, אֵינוֹ כְּלוּם. כְּאָדָם הָאוֹמֵר לַחֲבֵרוֹ, עַכְשָׁיו עָשָׂה זֶה וְזֶה, וְכָל מַה שֶּׁתַּעֲשֶׂה אֵינוֹ כְּלוּם, עַד שֶׁתַּעֲשֶׂה דָּבָר פְּלוֹנִי. כָּךְ אָמַר דָּוִד, הַלְּלוּהוּ בְּצִלְצְלֵי שָׁמַע הַלְלוּהוּ בְּצִלְצְלֵי תְרוּעָה, כְּלוֹמַר אֵינוֹ הַלְּלוּ, אֶלָּא מַהוּ הַלְּלוּ, כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ הַלְלוּיָהּ. וְהָאַחֵר אֵינוֹ כְּלוּם, אֶלָּא הִלּוּל הַנְּשָׁמָה, הֲדָא הוּא דִכְתִיב, (שם) כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ הַלְּלוּ יָהּ.</p>"],[9514011477,"<p>ט (בראשית א׳:ט׳) וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם וְגו', רַבָּנָן פָּתְחֵי בְּהַאי קְרָא, (תהילים מ״ו:ט׳) לְכוּ חֲזוּ מִפְעֲלוֹת אֱלֹהִים אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. אָמַר רִבִּי אַבָּא, בֹּא וּרְאֵה, שֶׁלֹּא כְּמִדַּת הַקָּדוֹשׁ בָּרוּךְ הוּא מִדַּת בָּשָׂר וָדָם. מִדַּת בָּשָׂר וָדָם מַעֲשָׂיו מְבַלִּין אוֹתוֹ. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא, מְבַלֶּה אֶת מַעֲשָׂיו.</p>"],[9514011478,"<p>וְהַיְינוּ דְּאָמְרָה חַנָּה, (שמואל א ב׳:ב׳) אֵין קָדוֹשׁ כַּה' כִּי אֵין בִּלְתֶּךָ. מַאי כִּי אֵין בִּלְתֶּךָ. אַל תִּקְרֵי בִּלְתֶּךָ, אֶלָּא בַּלּוֹתְךָ.</p>"],[9514011479,"<p>כָךָ הוּא כְּתִיב, לְכוּ חֲזוּ מִפְעֲלוֹת אֱלֹהִים וְגו', אָמַר רִבִּי אַבָּא, עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא דְּעָבִיד לְהוּ בְּעָלְמָא דֵּין, דָּוִד מַלְכָּא הֲוָה בְּהִתְבַּהֲלָא, וַאֲמַר לְכוּ חֲזוּ, בּוֹאוּ מִבָּעֵי לֵיהּ.</p>"],[9514011480,"<p>אֶלָּא אֲמַר דָּוִד, כָּל דָּיְירֵי אַרְעָא דִי בְּעָלְמָא דֵין, זִילוּ, זִילוּ מֵרֵישָׁא דְּעָלְמָא עַד סוֹפֵיהּ, וְתִשְׁכְּחִין עוֹבָדוֹי דְּהַקָדוֹשׁ בָּרוּךְ הוּא, כְּעוֹבָדוֹי בְּרֵישָׁא דְעָלְמָא, כָּךְ עוֹבָדוֹי בְּסֵייפֵי דְעָלְמָא, מַיְיתֵי דִיּוּרִין בְּעָלְמָא, אִי זָכוּ, מוֹתִיב לְהוֹ וְלִבְנַיְיהוּ וְלִבְנֵי בְנַיְיהוּ עַד סוֹפָא דְעָלְמָא. לָא זָכוּ, מַחְרִיב לְהוֹ מִנְהוֹן. וְהַהוּא אַתְרָא, וְהַהוּא קַרְתָּא, לָא אִתְבְּנֵי לְעָלְמִין. לְאַחֲזָאָה לִבְנֵי נְשָׁא, דַּאֲתַר חַיָּיבַיָא הֲוָה הַהוּא אֲתַר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עֲבַד בֵּיהּ דִּינָא, הֲדָא הוּא דִכְתִיב אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ.</p>"],[9514011481,"<p>דָּבָר אַחֵר, לְכוּ חֲזוּ מִפְעֲלוֹת אֱלֹהִים, אָמַר רִבִּי פִּנְחָס, מָה רָאָה דָּוִד דַּאֲמַר מִפְעֲלוֹת אֱלֹהִים, וְלָא אֲמַר מִפְעֲלוֹת ה'. אֶלָּא בִּשְׁמָא דֵּאלֹהִים, אִשְׁתַּכְלֵל עוֹבָדָא דִּבְרֵאשִׁית. וְכַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, הֲווֹ מַיָא אָזְלִין וְנָחֲתִין וְכַד רָמָא אַרְעָא לְתַתָּא, רָמָא לָהּ בֵּין מַיָּא, וַהֲוַת טְמִירְתָּא, וְאִתְקַרְשָׁא בֵּין מַיָא.</p>"],[9514011482,"<p>וְעָבַה הַקָּדוֹשׁ בָּרוּךְ הוּא אָת בְּגוֹ אָת, אוֹרְחֵיהּ וְטִבְעֵיהּ דְּעָלְמָא, דְּמַיָא קְלִילָן, וְאַרְעָא יַקִּירָא. וּמַאן דְּאִיהוּ יַקִּירָא נָחֵית לְתַתָּא. וּקְלִילָא סָלֵיק לְעֵילָא. אֲבָל הַקָדוֹשׁ בָּרוּךְ הוּא, לְאַחֲזָאָה אָתוֹהִי וְעוֹבָדוֹי לִבְנֵי נְשָׁא, אַרְכִין וְאַנְחֵית מַיָא דִקְלִילָן לְתַתָּא, וְאַרְעָא דְּאִיהִי יַקִּירָא, סָלֵיק לְעֵילָא, עַל קְלִילָא. הֲדָא הוּא דִכְתִיב, (תהילים קל״ו:ו׳) לְרוֹקַע הָאָרֶץ עַל הַמָּיִם. כְּלוֹמַר, מַיָא דְּאִינוּן קְלִילִין, לְתַתָּא. וְאַרְעָא, דְּאִיהִי יַקִּירָא, לְעֵילָא.</p>"],[9514011483,"<p>וְעוֹד, דְּמִבֵּין מַיָּא אַחֲזֵי וְאַפִּיק יַבֶּשְׁתָּא, דְּלֵית אֹרַח אַרְעָא לַאֲסָקָא מִגּוֹ מַיָּא יַבֶּשְׁתָּא, אֶלָּא לַחוּתָא. וְכַד אַסֵּיק יַבֶּשְׁתָּא מִבֵּין מַיָּא, קְרָא שְׁמָהּ אֶרֶץ. הֲדָא הוּא דִכְתִיב, (בראשית א׳:י׳) וַיִּקְרָא אֱלֹהִים לַיַּבָּשָׁה אָרֶץ.</p>"],[9514011484,"<p>וְתָנָא, ז' שֵׁמוֹת קָרָא לָהּ: אֶרֶץ. אֲדָמָה. גֵּיא. נְשִׁיָה. צִיָּה. אַרְקָא. תֵּבֵל. גָּדוֹל שֶׁבְּכוּלָּם תֵּבֵל, דִּכְתִיב (תהילים ט׳:ט׳) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק. הֲדָא הוּא דִכְתִיב, אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. אר\"י, ז' רְקִיעִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּנֶגְדָם בָּרָא ז' אֲרָצוֹת. וְתָאנָא, אֶרֶץ אַחַת מַמָּשׁ, הוֹצִיאוּ הַמַּיִם, וּמִמֶּנָּה נִתְהַוּוּ ז' אֲרָצוֹת, כִּדְאֲמָרָן.</p>"],[9514011485,"<p>אָמַר רִבִּי יוֹסֵי, מַיָא הֲווֹ יְסוֹדָא דְּכוֹלָּא. בְּגִין דְּאַשְׁכְּחָן דְּעִיקָּרָא דְּכָל עוֹבָדוֹהִי דִּבְרֵאשִׁית הֲווֹ מִן מַיָא. וְתָאנָא, בַּתְּחִלָּה הָיוּ הַמַּיִם מְפוּזָּרִין תַּחַת הַשָּׁמַיִם, עַד שֶׁגָּעַר הַקָּדוֹשׁ בָּרוּךְ הוּא בָּהֶם, וְהִכְנִיסָם וַאֲסָפָם אֶל מָקוֹם אֶחָד. הֲדָא הוּא דִכְתִיב יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה. וּלְאַחַר כַּךְ נִתְפַּזְּרוּ כְּמִתְּחִלָּה, וְרָקַע הָאָרֶץ עַל הַמָּיִם, הֲדָא הוּא דִכְתִיב, לְרוֹקַע הָאָרֶץ עַל הַמָּיִם כִּי לְעוֹלָם חַסְדּוֹ.</p>"],[9514011486,"<p>אָמַר עוּלָא, וְכִי לְמַאי צָרִיךְ חֶסֶד הָכָא, דִּכְתִיב לְרוֹקַע הָאָרֶץ עַל הַמָּיִם כּל\"ח. אָמַר רִבִּי יוֹסֵי, חֶסֶד גָּדוֹל עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָמוֹ, שֶׁהֶעֱמִיד הָאָרֶץ עַל הַמָּיִם, שֶׁאִלְּמָלֵא לֹא הָיְתָה הָאָרֶץ מִלְמַעְלָה, הָיָה הָעוֹלָם מְטוּשְׁטָשׁ בְּבַת אַחַת.</p>"],[9514011487,"<p>אָמַר רִבִּי חִסְדָּא, אִלְּמָלֵא כָךְ, לֹא הָיוּ בְּנֵי אָדָם נוֹטְעִין וְחוֹרְשִׁין וְזוֹרְעִין, עַכְשָׁיו שֶׁהָאָרֶץ לְמַעְלָה, נוֹטְעִין וְזוֹרְעִין, וְהָאָרֶץ עוֹמֶדֶת בְּכֹחָהּ וּבְקִיּוּמָהּ, מִפְּנֵי לַחוּת הַמַּיִם אֲשֶׁר מִתַּחַת לָאָרֶץ. וּמִלְּמַטָה יוֹצְאִין כַּמָּה נְהָרוֹת, כַּמָּה מַעֲיָינוֹת, כַּמָּה מִקְוָואוֹת, לְדַשֵּׁן כָּל הָעוֹלָם וּלְהַצְמִיחַ הַכֹּל. וְזֶהוּ הַחֶסֶד שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם בְּרִיּוֹתָיו, וְעִם כָּל הָעוֹלָם.</p>"],[9514011488,"<p>תָּנוּ רַבָּנָן, יוֹמָא חַד, הֲוָה יָתֵיב רַבִּי שִׁמְעוֹן אַבָּבָא דְּתַרְעָא דְּלוֹד, וַהֲווּ תַּמָּן רַבִּי יוֹסֵי וְרַבִּי חַגַּי וְרַבִּי אֶלְעָזָר בְּרֵיהּ. אָתָא רַבִּי פִּנְחָס, אָמַר לֵיהּ הָא בּוּצִינָא דְּמַתְנִיתָּא אָתֵי, קָם רַבִּי שִׁמְעוֹן אוֹתְבֵיהּ גַבֵּיהּ. אָמַר לֵיהּ, מַאי יוֹמָא דֵין מִשְּׁאָר יוֹמִין, דְּאַתְּ שָׁתֵיק, וְלֵית פּוּמָךְ מְנַטֵף מִתְקָא דְדוּבְשָׁא דְּחָכְמְתָא.</p>"],[9514011489,"<p>אָמַר לֵיהּ, מִסְתַּכֵּל הֲוֵית בְּלִבָּאי, הַאי דַּאֲמַר יְחֶזְקֵאל, (יחזקאל א׳:כ״ד) וָאֶשְׁמַע קוֹל כַּנְפֵיהֶם כְּקוֹל מַיִם רַבִּים כְּקוֹל שַׁדַּי, שָׁקַל לֵיהּ לְמַיִם רַבִּים, וְשָׁקַל לֵיהּ לְקוֹל שַׁדַּי, וּשְׁמַע מִינָּהּ כְּקוֹל מַיִם רַבִּים, כְּקוֹל שַׁדַּי הוּא. אָמַר לֵיהּ עַל דָּא תְּוַוהְנָא עֲלָךְ, דְּלָא הֲווֹ שִׁפְוָותֵיךְ מְרַחֲשִׁין בְּרָזִין עִלָּאִין.</p>"],[9514011490,"<p>אָמַר לֵיהּ הָא רָזָא דִּרְתִיכָא קַדִּישָׁא הוּא. תָּא חֲזֵי, דִּתְנַן בְּמַתְנִיתִין דִּידָן, אַרְבַּע מַלְאָכִין קַדִּישִׁין, נָטְלִין בְּמַטְלָנוֹהִי דְּכוּרְסָא יְקָרָא דְמַלְכָּא קַדִּישָׁא, וּמַאן אִינוּן מַלְאָכִין. אִינוּן דְּאִתְקְרוֹן חֵיוָתָא קַדִּישָׁא. וְאִילֵּין אַרְבַּע, אִינוּן יַקִּירִין וְעִילָּאִין עַל כָּל שְׁאָר מַלְאָכִין, בַּר מֵחַד.</p>"],[9514011491,"<p>וְאִית דְּאָמְרֵי דְּחַד הוּא מֵאִילֵּין אַרְבַּע, וְלֹא כָךְ הוּא, דְּהָכֵי אַשְׁכְּחָן בְּסִפְרָא דְּחָכְמְתָא דִשְׁלֹמֹה מַלְכָּא.</p>"],[9514011492,"<p>וְאִלֵּין אַרְבַּע כַּד מִתְכַּנְפֵי בְּכִינוּפְיָיא בְּמַטְלָנֵיהוֹן, מִשְׁתְּמַע בְּכָל רְקִיעָא קָל מַטְלָנֵיהוֹן, כְּקָל מַלְאָכִין סַגִּיאִין עִילָּאִין, דְּאִתְקְרוֹן אֶלֶף אַלְפִין, וְרִבּוֹ רִבְבָן. וּבְהַהוּא קָלָא דְהַהוּא שַׁמָּשָׁא חַד, דִּמְשַׁמֵּשׁ קַמֵּיהּ דְּמַלְכָּא עִילָּאָה. וְהַהוּא כִּינּוּפַיָּיא דְּאִינוּן מִתְכַּנְּפֵי, בְּעִידָנָא דְּאָתֵי לְאַשְׁפָּעָה עֲלֵיהוֹן טִיבוּ וִיקַר מַלְכְּהוֹן.</p>"],[9514011493,"<p>בְּכָה רַבִּי פִּנְחָס וַאֲמַר, בִּקְלִידָא דְּקַלְדִּיטִין, גְּלִיפִין דְּאָמִיד נְתוֹזְרִיטָא, בְּכַד מִסְתַּלְּקִין הֲוֵיתָא. בְּמָטוֹ מִינָךְ אַשְׁלֵים פְּסוּקָא.</p>"],[9514011494,"<p>אֲמַר, קוֹל הֲמוּלָּה כְּקוֹל מַחֲנֶה. מַאי קוֹל הֲמוּלָּה. הָכֵי תָּנֵינָן, דְּכַד מְשַׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא, כָּל מִלָּה דְּאִינוּן מְשַׁבְּחִין קַמֵּיהּ, כְּמִלָּה דְּתוּשְׁבַּחְתָּא דְּמַשִּׁרְיָיתָא דְּיִשְׂרָאֵל, כַּד מְשַׁבְּחָן לֵיהּ לְתַתָּא.</p>"],[9514011495,"<p>בְּעָמְהָם תְּרַפֶּינָה כַּנְפֵיהֶן, הַאי בְּעָמְדָם, כְּמוֹ (איוב ל״ב:ט״ז) עָמְדוּ וְלֹא עָנוּ עוֹד. דְּכַד הַאי מַשִּׁרְיָתָא דְיִשְׂרָאֵל לָא מְשַׁבְּחָן לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְתַתָּא, מִיָּד תְּרַפֶּינָה כַּנְפֵיהֶן. מִתְרַפָּן חֵילֵיהוֹן דְּהַאי כְּנוּפְיָיא קַדִּישָׁא, וְלֵית לְהוּ חֵילָא לְשַׁבְּחָא תּוּשְׁבַּחְתָּא שְׁלֵימָתָא קַמֵּיהּ.</p>"],[9514011496,"<p>וְעוֹד קְרָא אַחֵר דִּמְסַיֵּיעַ לְהַאי, דִּכְתִיב (יחזקאל א׳:כ״ה) וַיְהִי קוֹל מֵעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם וְגו', וַיְהִי קוֹל זֶה קוֹלוֹ שֶׁל יַעֲקֹב. כְּשֶׁמַּרְבִּין בִּתְפִלָּה לְהֵיכָן סָלְקָא, מֵעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם שֶׁל חַיּוֹת, שֶׁשָּׁם מֻנַּחַת תְּפִלָּתָן שֶׁל צַדִּיקִים.</p>"],[9514011497,"<p>וּכְשֶׁפּוֹסְקִים לְהַשְׁמִיעַ קוֹלָם וּלְהִתְפַּלֵּל וְלִקְרוֹת בַּתּוֹרָה, מַה כְּתִיב. בְּעָמְדָם, כְּלוֹמַר בִּשְׁתִיקוּתָם מֵהַתּוֹרָה וּמִן הַתְּפִלָּה, תְּרַפֶּינָה כַּנְפֵיהֶן שֶׁל הַחַיּוֹת כִּדְקָאֲמָרָן. אָמַר לֵיהּ, מְטוּל כֵּן אָתֵית לְמִשְׁמַע מִפּוּמָךְ, רוּחַ חָכְמְתָא, שׁוּרַיָיא, וּשְׁלָמָא דִּלְעֵילָא דִּיהַב בָּךְ.</p>"],[9514011498,"<p>אָמַר רִבִּי יְהוּדָה, יִקָּווּ הַמַּיִם, כְּקַו זֶה שֶׁמַּנִּיחִים הָאוּמָּנִים לִבְנוֹת הַבִּנְיָן, שֶׁלֹּא יֵצֵא חוּץ מִמֶּנּוּ לְכָאן וּלְכָאן. כָּךְ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, קַו לַמַּיִם, שֶׁלֹּא יֵצְאוּ מִשְּׂפָתָם לְכָאן וּלְכָאן. הֲדָא הוּא דִכְתִיב, (איוב ל״ח:י״א) וָאֹמַר עַד פֹּה תָבֹא וְלֹא תֹסִיף.</p>"],[9514011499,"<p>וְתָאנָא, גְּבוּל הִגְבִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא לַיָּם. וְאֵי זֶהוּ גְבוּל. רַבִּי אַבָּא אוֹמֵר, זֶה הַחוֹל, דִּכְתִיב (ירמיהו ה׳:כ״ב) אֲשֶׁר שַׂמְתִּי חוֹל גְּבוּל לַיָּם. וּכְשֶׁרוֹאִים זֶה הַחוֹל, חוֹזְרִים לְאָחוֹר, וְאֵינָם יוֹצְאִים לַחוּץ, מֵאוֹתוֹ הַקַּו שֶׁנָּתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9514011500,"<p>אָמַר רִבִּי יִצְחָק, בֹּא וּרְאֵה כַּמָּה הוּא עִיקָּרָא דְעָלְמָא מַיָּא, דְּהָא שָׁמַיִם נָטְלוּ שְׁמָא מִנְּהוֹן, מַיִ\"ם שָׁמַיִ\"ם. וְלָמָּה, אָמַר רִבִּי יִצְחָק שֶׁהוֹסִיף הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַמַּיִם אֵשׁ, וּבָרָא מִמֶּנּוּ הַשָּׁמַיִם, כְּלוֹמַר, אֵשׁ וּמַיִם.</p>"],[9514011501,"<p>אָמַר רִבִּי יוּדָאי, לָאו הָכֵי, דְּהָא מֵחֲבִיבוּתָא דְּקַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִיתְבְּרוּן שָׁמַיִם. אָמַר רִבִּי אֶלְעָזָר, וְשַׁפִּיר קָאָמַר רַבִּי יִצְחָק, וְלָא קַשְׁיָא, בְּמַאי דְּאָמַר רִבִּי יוּדָאי. וְכַד תִּנְדַע מַהוּ מַיִם, תִּנְדַע עִיקָּרָא דְמִילְּתָא.</p>"],[9514011502,"<p>וְכַד אָתָא רַבִּי בָּא, עָאל לְקַמֵּיהּ ר' יְהוּדָה וְר' חִיָּיא, אֲמָרוּ לֵיהּ, לֵימָא לָן מַר עִיקָּרָא דְּחַד מִלָּה, מֵאִינוּן רָזִין עִילָּאִין, אֲמַר, אֵימָא חַד מִלָּה, וְטַב לְמַאן דִּיהֱוֵי לֵיהּ לִבָּא לְמִנְדַע.</p>"],[9514011503,"<p>אֲמָרִין מָארֵי דְרָזָא דְמַתְנִיתָּא, דְּהַאי מַאן דְּבָעֵי לְמִנְדַע וּלְאִסְתַּכָּלָא בְּלִבֵּיהּ, מֵחָכְמְתָא דְמַלְכָּא עִלָּאָה, יִנְדַע בְּקַדְמִיתָא מַהוּ מַיִם. וּמַאן דְּבָעֵי לְמִנְדַע מַהוּ קְרִישׁוּתָא דְּכוּרְסְיֵהּ, יִסְתַּכֵּל בְּקִיּוּמָא דְמִלְּתָא, דִּכְתִיב (במדבר י״ח:י״ט) בְּרִית מֶלַח עוֹלָם הִיא. וּמִתְּרֵין אִלֵּין, יִסְתַּכֵּל בְּחָכְמָתָא קַדִּישָׁא דִלְעֵילָא.</p>"],[9514011504,"<p>אָמַר רִבִּי אַבָּא, מַאן דְּבָעֵי לְמִנְדַע עִנְיָינָא דְקִיּוּמָא דְעָלְמָא דֵין, לִינְדַע עִנְיָינָא דְמִלְחָא, דְּאִתְנַהֵיג מִשַּׁמָּשָׁא, דְּאִתְמְנֵי תְּחוֹתֵיהּ דְּמָארֵיהּ, וְיִנְדַע מַהוּ, וְהֵיךְ יִתְמְחֵי בְּמַיָּא, וְיִסְתַּכֵּל בְּחָכְמְתָא.</p>"],[9514011505,"<p>אָמַר רִבִּי יִצְחָק אָמַר רַב, הַנֵּי קְלוּדָטֵי, דְּזָקְפִין בְּלוּדְטֵיהוֹן מַיָא וּמִלְּחָא, עִנְיָינָא דִּנְהוֹרִיתָא, בּוּצִינָתָא הֲוַות, לְאִסְתַּכָּלָא בְּחָכְמָתָא.</p>"],[9514011506,"<p>דָּבָר אַחֵר (בראשית א׳:ט׳) וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד, רַבִּי פְּתַח, (תהילים צ״ג:ד׳) מִקּוֹלוֹת מַיִם רַבִּים אַדִּירִים מִשְׁבְּרֵי יָם אַדִּיר בַּמָּרוֹם ה', מִקּוֹלוֹת מַיִם רַבִּים, כְּשֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַמַּיִם, שֶׁיִּתְכַּנְּסוּ בְּמָקוֹם אֶחָד, הָיוּ מְשׁוֹטְטִים לְכָאן וּלְכָאן, וְנִתְגָּאוּ לְמַעְלָה.</p>"],[9514011507,"<p>אָמַר רִבִּי יִצְחָק בְּהַאי שַׁעֲתָא נְטָלוּ מַיָּא לְאַרְעָא, דַּהֲוַות כָּנֵיס בְּהוּ, וַהֲווּ מְחַפְיָין לָהּ. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא כָךְ, אֶלָּא הִכָּנְסוּ כֻּלְּכֶם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה. מַשְׁמַע דְּיַבֶּשְׁתָּא הֲוַות אַרְעָא קוֹדֶם, בְּלָא לֵיחוּתָא, בֵּין מַיָּא. יַבָּשָׁה לָא כְתִיב, אֶלָּא הַיַּבָּשָׁה.</p>"],[9514011508,"<p>וַהֲווּ מַיָּא אָזְלִין גָּבְהִין וְנָחֲתִין, וּמְשַׁמְעִין קָלֵיהוֹן לְסֵיְיפֵי שְׁמַיָא, עַד שֶׁגָּעַר בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִכְנִיסָם לַתְּהוֹם, וְתַמָּן הִיא כְּנִישׁוּתָא דְמַיָּא. וְעַד כְּעָן קָלֵיהוֹן לָא שָׁכֵיךְ, וְקָרָא לְהוֹ יַמִּים. וְכַד אִינוּן גָּבְהִין תַּמָּן בְּאַתְרָא הַהוּא, אִתְּבַר תּוֹקְפֵיהוֹן, וְנָחֲתִין וְלָא נָפְקִין לְבַר, מִדְּחִילוּ דִּתְקִיפוּתָא דְמָארֵיהוֹן, הֲדָא הוּא דִכְתִיב, (שם) אַדִּירִים מִשְׁבְּרֵי יָם אַדִּיר בַּמָּרוֹם ה'.</p>"],[9514011509,"<p>אָמַר רִבִּי יוֹסֵי, וְאִם כֵּן מַאי כְּתִיב אַחֲרָיו, עֵדוֹתֶיךָ נֶאְמְנוּ מְאֹד לְבֵיתְךָ נָאֲוָה קֹדֶשׁ, מַאי בָּעֵי פְּסוּקָא דָא, לִפְסוּקָא דִלְעֵילָא. אָמַר רִבִּי יִצְחָק, אֲמַר דָּוִד, רִבּוֹנוֹ שֶׁל עוֹלָם, עֵדוּת שֶׁעָשִׂיתָ בְּמַעֲשֵׂה בְרֵאשִׁית, הֵם אֱמֶת, לְהָעִיד עֲלֵיהֶם בְּכָל יוֹם. דְּהָא תָּנִינָן, כָּל הַמֵּעִיד בְּמַעֲשֵׂה בְרֵאשִׁית בְּכָל יוֹם, מוּבְטָח לוֹ שֶׁהוּא בֶּן עה\"ב.</p>"],[9514011510,"<p>וְאָמַר דָוִד, אַתָּה הוּא שֶׁעָשִׂיתָ אֶת כָּל הָעוֹלָם, וְעָשִׂיתָ אֶת הַמַּיִם, וְהַמַּיִם הָיוּ מְכַסִּין אֶת הָעוֹלָם מֵהָרִבּוּי שֶׁבָּהֶם, וְעָשִׂיתָ לָהֶם שֶׁיִּתְכַּנְּסוּ בְּצִמְצוּם כֻּלָּם אֶל מָקוֹם אֶחָד. כָּךְ יְהִי רָצוֹן מִלְּפָנֶיךָ, שֶׁשְּׁכִינָתְךָ שֶׁהִיא מְלֵאָה כָּל הָעוֹלָם כֻּלּוֹ, שֶׁתְּצַמְצֵם אוֹתָהּ בְּבֵיתְךָ, שֶׁיּוֹתֵר רָאוּי הוּא לִהְיוֹת שָׁם. הֲדָא הוּא דִכְתִיב, לְבֵיתְךָ נָאֲוָה קֹדֶשׁ, וְלֹא לִזְמַן מוּעָט, אֶלָּא לְאוֹרֶךְ יָמִים.</p>"],[9514011511,"<p>דָּבָר אַחֵר וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה. ר' תַּנְחוּם פָּתַח בְּהַאי קְרָא, (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד וְאֵין אִישׁ שָׂם עַל לֵב וְאַנְשֵׁי חֶסֶד נֶאֱסָפִים בְּאֵין מֵבִין כִּי מִפְּנֵי הָרָעָה נֶאֱסַף הַצַּדִּיק. תַּמָּן תָּנִינָן, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִסְתַּכֵּל בָּעוֹלָם, וְרוֹאֶה שֶׁאֵין בְּנֵי אָדָם זַכָּאִין, וּרְשָׁעִים הַרְבֵּה פּוֹרְחִים בָּעוֹלָם, אֲזַי עוֹשֶׂה דִין בָּעוֹלָם. אָמַר רִבִּי תַּנְחוּם, כְּעוֹבָדָא דְגוּפָא עִם נִשְׁמָתָא, עָבִיד הַקָּדוֹשׁ בָּרוּךְ הוּא עִם דָּרָא.</p>"],[9514011512,"<p>אָמַר רִבִּי יִצְחָק הָאֵיךְ. אָמַר לֵיהּ, כִּי הַאי גַּוְונָא, צַדִּיקַיָא אִינוּן נִשְׁמָתָא, וְחַיָּיבַיָא אִינוּן גּוּפָא, כַּד מִסְתַּכֵּל הַקָדוֹשׁ בָּרוּךְ הוּא בְּעָלְמָא, נָטֵיל נִשְׁמָתָא, וְאִשְׁתָּאַר גּוּפָא לְסָרְחָנָא דְבִשְׂרָא. וּמַאי נָטֵיל, נָטֵיל לְנִשְׁמָתָא, דְּאִינוּן צַדִּיקַיָּא, וְיִשְׁתָּאֲרוּן גּוּפָא דְּאִינוּן חַיָּיבַיָא.</p>"],[9514011513,"<p>אָמַר רִבִּי תַּנְחוּם, הֲדָא הוּא דִכְתִיב וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם, אֵלּוּ הַצַּדִּיקִים, הַנֶּאֱסָפִים לְבֵית עוֹלָמָם, שֶׁהִיא מָקוֹם אֶחָד מְיוּחָד לָהֶם לְמַעֲלָתָם. וְכַד יִתְכַּנְּשׁוּן לְעָלְמָא דְאָתֵי, מַאי כְּתִיב, וְתֵרָאֶה הַיַּבָּשָׁה, שֶׁהֵם הָרְשָׁעִים, בְּלִי מַעֲשֶׂה, שֶׁאֵין מִי שֶׁיָּגֵין עֲלֵיהֶם, וִיכַסֶּה עֲלֵיהֶם. כְּמָה דְאַתְּ אָמֵר, וַיִּרְאוּ כָּל הָעֵדָה כִּי גָוַע אַהֲרֹן, אַל תִּקְרֵי וַיִּרְאוּ, אֶלָּא וַיִּירָאוּ.</p>"],[9514011514,"<p>דְּהָא תָּנִינָן, אָמַר רִבִּי יִצְחָק אָמַר רַב, וְאַמְרֵי לָהּ אָמַר רִבִּי יְהוּדָה אָמַר רַב, כָּל זְמַן שֶׁהַצַּדִּיקִים בַּדּוֹר, אֵין מִדַּת הַדִּין יְכוֹלָה לִשְׁלֹט בָּהֶם. הֲדָא הוּא דִכְתִיב, (תהילים ק״ו:כ״ג) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי משֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו לְהָשִׁיב חֲמָתוֹ מֵהַשְׁחִית. וּכְשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לַעֲשׂוֹת דִּין בָּרְשָׁעִים, מְסַלֵּק הַצַּדִּיקִים מִבֵּינֵיהֶם, וְאָז עוֹשֶׂה דִין בָּרְשָׁעִים.</p>"],[9514011515,"<p>מָשָׁל לְמִדַּת הַדִּין, לְמֶלֶךְ שֶׁהָיָה לוֹ פַּרְדֵּס, יוֹמָא חַד עָאל לְגִינֵיהּ, וְחָמָא דַּהֲווֹ תַּמָּן בְּכוּלֵיהּ דַּרְדַּרִין סַגִּיאִין, אֲמַר, אֲנָא בָּעֵי לְבַעֲרָא לוֹן מֵהָכָא, זְקַף עֵינוֹהִי וַחֲזָא וְרָדִין טָבִין יָיאִין. אֲמַר, בְּגִינֵי אִינוּן וְרָדִין, אֶשְׁבּוֹק כָּל הַדַּרְדַּרִין. וְכַד יָהֲבוּ רֵיחָא אִינוּן וְורָדִין, נָטַל לְהוֹן וְעָקַר לְהוֹן מִן גִּנָּא. כֵּיוָן דְּעָקַר לְהוֹן, אֲמַר הָא עִידָן לְאַעֲקָרָא דַּרְדַּרִין דְּגִנָּא, וּלְבַעֲרָא לְהוֹ מֵהָכָא. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל זְמַן שֶׁהַצַּדִּיקִים בַּדּוֹר, אֵין נַעֲשָׂה דִין בָּרְשָׁעִים. נִסְתַּלְּקוּ הַצַּדִּיקִים מִבֵּינֵיהֶם, אָז נַעֲשָׂה דִּין בָּרְשָׁעִים.</p>"],[9514011516,"<p>שָׁאַל רַבִּי יִצְחָק לְרַבִּי אֶלְעָזָר, כַּד הֲוֵי אָזְלֵי בְּמַדְבְּרָא. אֲמַר אֲנָא בָּעֵי לְמִשְׁאַל חַד שְׁאֵילְתָּא, אִי לָאו הֲוָה חֲטָאָה. אָמַר לֵיהּ יָאוֹת אַנְתְּ לְמִשְׁאַל בְּאוֹרַיְיתָא, מַה דְּאַתְּ בָּעֵי שְׁאַל.</p>"],[9514011517,"<p>אֲמַר, הַאי דְּאָמַר קְרָא, (בראשית א׳:י׳) וַיַּרְא אֱלֹהִים כִּי טוֹב. אִי קוֹדֶם הַפְּעוּלָּה הֲוָה, יָאוֹת הוּא וְשַׁפִּיר. אֶלָּא מַה דְּאָמַר לְאַחַר הַפְּעוּלָּה, מַשְׁמַע דְּלָא הֲוָה יָדַע קוֹדֶם לָכֵן עִיקַּר הַפְּעוּלָּה וְתִיקּוּנָהּ וְיוֹפְיָהּ. וּכְשֶׁהָיְתָה הַפְּעוּלָּה נִגְמֶרֶת, מַשְׁמַע דְּהֲוָה מְעַיֵּין בָּהּ כְּמוֹת שֶׁהִיא עוֹמֶדֶת, וַאֲזַי הוּא אוֹמֵר כִּי טוֹב, דִּכְתִיב וַיַּרְא, וְאַחַר כַּךְ אָמַר כִּי טוֹב.</p>"],[9514011518,"<p>אָמַר לֵיהּ לָאו חֲטָאָה הוּא, וְאַתְּ צָרִיךְ לְמִשְׁאַל דָּא. וְדָא הִיא אַזְהָרָה לְבַּר נָשׁ, דְּאָמַר רִבִּי יְהוּדָה, כְּשֶׁיִּלְמוֹד אָדָם בְּמַעֲשֵׂה בְרֵאשִׁית, פְּעוּלָּתוֹ שֶׁל כָּל יוֹם וָיוֹם, אֵין לוֹ לִשְׁאוֹל עַל מַה שֶּׁאֵינוֹ מְצֻוֶּוה, וְלוֹמַר פְּעוּלָּה זוֹ לָמָּה נַעֲשֵׂית כָּךְ בִּדְמוּת זוֹ. וְזוֹ נַעֲשֵׂית כָּךְ בִּדְמוּת זוֹ. וֶאֱמוֹר לוֹ, תֵּדַע לָמָּה, וַיַּרְא אֱלֹהִים כִּי טוֹב לַעֲשׂוֹתוֹ, וְעַל כֵּן אַל תִּשְׁאַל יוֹתֵר.</p>"],[9514011519,"<p>וְעוֹד, כְּדֵי לְהַזְהִיר לִבְנֵי אָדָם, וּלְהוֹרוֹת לָהֶם הַדֶּרֶךְ הַנָּכוֹן, כִּי גָּלוּי וְיָדוּעַ לְפָנָיו הַפְּעוּלָּה קוֹדֶם שֶׁיַּעֲשֶׂהָ, וְלֹא רָצָה לוֹמַר טוֹב הוּא זֶה, עַד גְּמַר הַמְלָאכָה. וְכָךְ אֵין רָאוּי לָאָדָם לְשַׁבֵּחַ הַדָּבָר עַד סִיּוּמוֹ, שֶׁמָּא יִמְצָא בוֹ גֵּרָעוֹן וְיִתְבַּדֶּה, וְיֵאָחֵז בִּדְבָרָיו.</p>"],[9514011520,"<p>אָמַר רִבִּי בְּרֶכְיָה, כֵּן רָאִינוּ בְּכַמָּה מְקוֹמוֹת, שֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא אַזְהָרָה לָאָדָם לְהִזָּהֵר מִמֶּנּוּ, אַף עַל פִּי שֶׁלֹּא הָיָה צָרִיךְ לוֹ, וְהַכֹּל גָּלוּי לְפָנָיו, אֲבָל כְּדֵי לָתֵת אַזְהָרָה לָאָדָם, הוּצְרַךְ לַעֲשׂוֹת כֵּן. תָּא חֲזֵי, דִּכְתִיב (בראשית י״ח:כ״א) אֵרְדָה נָא וְאֶרְאֶה הַכְּצַעֲקָתָהּ הַבָּאָה אֵלַי עָשׂוּ כָּלָה. וְכִי לֹא הָיָה גָלוּי לְפָנָיו, שֶׁהוּא צָרִיךְ לָדַעַת וְלַחְקֹר. אֶלָּא אָמַר רִבִּי בְּרֶכְיָה, מִכָּאן אַזְהָרָה לְבֵּית דִּין, שֶׁאֵין לָהֶם לְהִסָּמֵךְ עַל דַּעְתָּם, אֶלָּא יֵשׁ לָהֶם לָדַעַת וְלַחְקוֹר וְלִדְרוֹשׁ הָעִנְיָן יָפֶה. הֲדָא הוּא דִכְתִיב, (דברים י״ג:ט״ו) וְדָרַשְׁתָּ וְחָקַרְתָּ וְשָׁאַלְתָּ הֵיטֵב, וְאֵין לְךָ רְשׁוּת לְהִסָּמֵךְ עַל דַּעְתְּךָ.</p>"],[9514011521,"<p>עַד דַּהֲווֹ יָתְבֵי, חָמוּ לְרַבִּי אַבָּא דְּהֲוָה אָתֵי. אֲמָרֵי מִמָארֵיהוֹן דְּמַתְנִיתִין אָתֵי. קְרִיבוּ גַבֵּיהּ, שְׁאִילוּ הַאי שְׁאֵילְתָּא.</p>"],[9514011522,"<p>אֲמַר, כָּךְ פָּסְקוּ מָארֵי דְמַתְנִיתִין, דְּכָל מַה דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא, עָבַד לֵיהּ בְּפִיקוּדוֹי, עַל יְדָא דְּאֶמְצָעִי. אֲמַר לְאַרְעָא עֲבִידִי כָךְ, עֲבָדַת כְּמָא דְאִתְפַּקְדַּת, וְלָא שַׁנְיָיא מִינֵּיהּ. אֲמַר לְמַיָא עֲבִידוּ כָךְ, וַעֲבָדוּ מַיָא עֲבִידְתְּהוֹן דְּאִתְפַּקָּדוּ, וְלָא שָׁנוּ מִינֵּיהּ. וְכֵן לִרְקִיעָא כָּךְ כִּי הַאי גַוְונָא.</p>"],[9514011523,"<p>וְכַד הֲוָה עָבִיד שׁוּם חַד מִנְּהוֹן עֲבִידְתֵּיהּ כְּמָא דְּאִתְפַּקַּד, הֲוָה חָזֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דַּעֲבַד כְּהַהוּא גַּוְונָא דְּפַקֵּיד לֵיהּ, וְהוּא מְשַׁבַּח לֵיהּ הַהוּא עוֹבָדָא. הֲדָא הוּא דִכְתִיב וַיַּרְא אֱלֹהִים כִּי טוֹב. כְּלוֹמַר וַיַּרְא בְּאוֹתוֹ הַמַּעֲשֶׂה, שֶׁעֲשָׂאוּהוּ כְּמוֹ שֶׁצִּוָּה. וְהָיָה אוֹמֵר כִּי טוֹב, כְּלוֹמַר, כִּי טוֹב עָשָׂה כְּמָה שֶׁנִּצְטַוָּה. וְזֶהוּ וַיַּרְא אֱלֹהִים כִּי טוֹב. אֲמַר רַבִּי יִצְחָק, כָּלְהוֹ שַׁפִּיר אֲמָרוּ, וְהַאי מִלָּה שַׁפִּיר מִכּוּלְהוֹן.</p>"],[9514011524,"<p>אָמַר רִבִּי בְּרֶכְיָה לְרַבִּי יִצְחָק, אִם כֵּן קַשְׁיָא מִילְּתָא דָא מִכָּל מַה דְּאִיתְּמָר, דְּאִי הָכִי, הֲוָה לֵיהּ לְמֵימַר הַאי קְרָא, (בראשית א׳:ל״א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשׂוּ וְהִנֵּה טוֹב מְאֹד. מַאי אֶת כָּל אֲשֶׁר עָשָׂה. אָמַר רִבִּי יִצְחָק, שַׁפִּיר קָאֲמַרְתְּ.</p>"],[9514011525,"<p>אֲזָלוּ בַּתְרֵיהּ דְּר' אַבָּא, אָמְרֵי לֵיהּ הַאי מִלָּה, אֲמַר לְהוֹ, שַׁפִּירָא הִיא, וּקְרָא דָא מְסַיְיעָא לָן. דִּכְתִיב אֶת כָּל אֲשֶׁר עָשָׂה, בִּכְלַל. וְלֹא נֶאֱמַר אֶת כָּל אֲשֶׁר עָשׂוּ, דְּמַשְׁמַע עַל אִלֵּין אֶמְצָעִיִּים דַּעֲבַד, דַּאֲפִיקוּ כָּל מַה דְּאִתְפַּקָּדוּ, וְהָא טַב. וּבְגִינֵיהּ כְּתִיב אֶת כָּל אֲשֶׁר עָשָׂה.</p>"],[9514011526,"<p>אָמַר רִבִּי חִיָּיא, וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב, לִהְיוֹתָם עוֹמְדִים תָּמִיד, בְּאוֹתוֹ קִיּוּם, וּבְאוֹתוֹ הַדֶּרֶךְ שֶׁעָשָׂהוּ, וְשֶׁלֹּא יִשְׁתַּנּוּ מִדֶּרֶךְ זוֹ לְעוֹלָם.</p>"],[9514011527,"<p>אָמַר רַב הוּנָא אָמַר רַב, לִשְׁלשָׁה קָרָא קוּדְשָׁא בְּרִיךְ הוּא שְׁמוֹתָם בְּמַעֲשֵׂה בְרֵאשִׁית, וְאֵלּוּ הֵן: הַשָּׁמַיִם, וְהָאָרֶץ, וְהַמַּיִם. הַשָּׁמַיִם מְנָא לָן, דִּכְתִיב (שם) וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם. הָאָרֶץ מְנָא לָן, דִּכְתִיב (שם) וַיִּקְרָא אֱלֹהִים לַיַּבָּשָׁה אֶרֶץ. הַמַּיִם מְנָא לָן, דִּכְתִיב (שם) וּלְמִקְוֵה הַמַּיִם קָרָא יַמִּים. וְלָמָּה, לַעֲשׂוֹת בָּהֶם כָּל מְלַאכְתּוֹ.</p>"],[9514011528,"<p>וּמַה שֶּׁיָּצָא מֵהֶם, הִנִּיחוּ לְאָדָם, לִקְרוֹא לָהֶם שֵׁמוֹת. אָמַר רִבִּי בְּרֶכְיָה, כָּל מַה שֶּׁהוֹצִיאוּ הַשָּׁמַיִם וְהָאָרֶץ, אָדָם הָרִאשׁוֹן קָרָא לָהֶם שֵׁמוֹת, שֶׁנֶּאֱמַר (שם ב) וַיִּקְרָא הָאָדָם שֵׁמוֹת לְכָל הַבְּהֵמָה וּלְעוֹף הַשָּׁמַיִם וּלְכָל חַיַּת הַשָּׂדֶה.</p>"],[9514011529,"<p>פָּרָשָׁתָא ה'. (שם א) וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְרִי עוֹשֶׂה פְּרִי לְמִינוֹ. רַבִּי יִצְחָק פָּתַח, (שיר השירים ב) עוּרִי צָפוֹן וּבוֹאִי תֵימָן הָפִיחִי גַנִּי יִזְּלוּ בְשָׂמָיו יָבֹא דוֹדִי לְגַנּוֹ וְיֹאכַל פְּרִי מְגָדָיו. רַבִּי אַבָּהוּ אָמַר, כַּמָּה יֵשׁ לְאָדָם לְהַרְהֵר בְּמַעֲשָׂיו, וְלִפְקוֹד אוֹתָם בְּכָל יוֹם, הוֹאִיל וְנָתַן בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא נְשָׁמָה טְהוֹרָה, לָדַעַת וּלְהַכִּיר לְבוֹרְאוֹ, וּלְהִסְתַּכֵּל בְּנִפְלְאוֹתָיו שֶׁהוּא עוֹשֶׂה בְּכָל יוֹם וָיוֹם.</p>"],[9514011530,"<p>וְתָאנָא, אָמַר רִבִּי יִצְחָק, אַרְבַּע רוּחוֹת מְנַשְּׁבוֹת בְּכָל יוֹם, מֵאַרְבַּע רוּחוֹת הָעוֹלָם. רוּחַ מִזְרָח מְנַשֶּׁבֶת מֵהַבֹּקֶר וְעַד חֲצִי הַיּוֹם. וְנָפְקֵי עִמֵּיהּ מֵהַהוּא אוֹצָר הַחֶמְדָה. דִּתְנַן, אוֹצָר יֵשׁ לְמַעְלָה בְּשַׁעֲרֵי מִזְרָח, וְחֶמְדָה שְׁמוֹ. וְיֵשׁ בּוֹ שְׁלשֶׁת אֲלָפִים וְשִׁבְעִים וְחָמֵשׁ רוּחִין דְּאַסְוָותָא לְעָלְמָא.</p>"],[9514011531,"<p>וְהַיְינוּ דִּתְנַן בְּמַתְנִיתָּא דְרַבִּי אֱלִיעֶזְר, מַאי דִכְתִיב, (שמואל ב כ״ג:ד׳) בֹּקֶר לֹא עָבוֹת, כְּלוֹמַר כְּשֶׁהוּא בֹּקֶר, מַאן דְּאִית לֵיהּ מַרְעִין וָחֳלָיִים, אֵינוֹ נִלְכַּד בְּעָבוֹת.</p>"],[9514011532,"<p>אריב\"ז, יֵשׁ מַלְאָךְ מְמוּנֶּה, מֵהַבֹּקֶר וְעַד חֲצִי הַיּוֹם, בְּהַהוּא רוּחָא דְאָתֵי מִמִּזְרָח, וּמִיכָאֵל שְׁמוֹ, שֶׁהוּא מְמוּנֶּה לְצַד מִזְרָח. וְאריב\"ז הוּא מִיכָאֵל, דִּכְתִיב בֵּיהּ (שמות ל״ב:ל״ד) הִנֵּה מַלְאָכִי יֵלֵךְ לְפָנֶיךָ. בְּאַשְׁגָּחוּתָא תִּשְׁכַּח, מִיכָאֵל מַלְאָכִי. וְדָא הוּא דְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמשֶׁה, הִנֵּה מַלְאָכִי יֵלֵךְ לְפָנֶיךָ. כְּלוֹמַר, הִנֵּה מִיכָאֵל יֵלֵךְ לְפָנֶיךָ.</p>"],[9514011533,"<p>וְתָאנָא, כְּשֶׁרוּחַ מִזְרָח מִתְעוֹרֵר לָצֵאת לָעוֹלָם, מַאן דְּאָזִיל בְּאוֹרְחָא, וִיכַוֵּין רוּחֵיהּ לְהַאי עִנְיָנָא. כָּל בִּרְכְּתָא דְּבָרְכִין לֵיהּ, מִתְקַיֶּימֶת בְּהַהִיא שַׁעֲתָא. וִיהֵא חָדֵי כָּל הַהוּא יוֹמָא.</p>"],[9514011534,"<p>רוּחַ מַעֲרָב, מְנַשֶּׁבֶת מֵחֲצִי הַיּוֹם עַד הַלַּיְלָה, וְנָפְקֵי עִמֵּיהּ מֵאוֹצַר מַעְיָן, ד' מְאָה וְשִׁתִּין וְחָמֵשׁ רוּחִין, לְאַפְרָחָא עִשְׂבִים וְאִילָנִים וִיבוּלִים. וְתָאנָא, מַלְאָךְ מְמוּנֶּה מֵחֲצִי הַיּוֹם עַד הַלַּיְלָה, וּרְפָאֵל שְׁמֵיהּ, וְהוּא מְמוּנֶּה לְצַד מַעֲרָב.</p>"],[9514011535,"<p>אָמַר רִבִּי יוֹסֵי בֶּן פַּזִי, אִם כֵּן קוּשְׁיָא אִיכָּא הָכָא, דְּהָא תָּנִינָן מַלְאָךְ הַמְמוּנֶּה עַל הָרְפוּאָה, רְפָאֵל שְׁמוֹ, וְאַמַרְתְּ דְּאַסְוָותָא אָתֵי מִמִּזְרָח, וּמִיכָאֵל מְמוּנֶּה עָלָיו.</p>"],[9514011536,"<p>תָּא שְׁמַע, אריב\"ז, כָּל עוֹבָדוֹהִי דְּקוּדְשָׁא בְּרִיךְ הוּא גַּבֵּי בְּנֵי נָשָׁא, מְטוּל דְּיִשְׁתְּמוֹדְעוּן לֵיהּ, דְּהוּא מָחֵי, וְהוּא מַסֵּי, וְלָא יַשְׁוִין בְּנֵי נָשָׁא לִבַּיְיהוּ לְמַלְאָכָא, וְלָא לְרַבְרְבָנָא. וּבְגִין כָּךְ מַחֲלִיף עִידָּנִין וְזִמְנִין, דְּלָא יֵימְרוּן מַלְאָכָא פְּלוֹנִי עֲבַד לֵיהּ הַאי, אֶלָּא כּוֹלָּא בִּידֵיהּ.</p>"],[9514011537,"<p>וּלְפִיכָךָ מַחֲלִיף רוּחִין, עַד דְּיִצְלוּ קַמֵּיהּ, וִיתוּבוּן. וּכְדֵין יִפְקוֹד לְאַסְוָותָא לְמִשְׁרֵי עֲלוֹהִי, וְהַהוּא מַלְאָכָא דְאִתְפַּקַּד עַל אַסְוָותָא, עֲבֵיד מַה דְּאִתְפַּקַּד, מֵרְעוּתֵיהּ דְּמָרֵיהּ.</p>"],[9514011538,"<p>וְתָּא חֲזֵי, רַחְמָנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא מָחֵי לְבַּר נָשׁ, עַד דְּסָלְקֵי עוֹבָדוֹהִי בְּמַתְקְלָא בְּבֵי דִינָא דִּלְעֵילָא, וְהַהוּא דְּאִתְמַנֵּי עַל דִּינָא הוּא מִיכָאֵל. וְרַחְמָנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאַף עַל גַּב דִּבְגִינֵיהּ מָטָא לֵיהּ דִּינָא בְּיָדֵיהּ, בְּדִינָא. מַמְטֵי לֵיהּ רוּחָא דְאַסְוָותָא בְּכָל יוֹמָא, עַד דְּיִכְשַׁר אֵינַשׁ עוֹבָדוֹהִי, וִיתוּב מִנַּיְיהוּ קַמֵּי מָארֵיהּ, וּכְדֵין מְשַׁדַּר לֵיהּ אַסְוָותָא עַל יְדוֹהִי דְּהַהוּא שְׁלִיחָא דִּמְמַנָּא עֲלוֹהִי.</p>"],[9514011539,"<p>רוּחַ דָּרוֹם מְנַשֶּׁבֶת מֵרֵישָׁא דְלֵילְיָא עַד פַּלְגוּת לֵילְיָא, וְנָפְקוּ עִמֵּיהּ מֵהַהוּא אוֹצַר הַחֶמְדָה, מָאתָן וְשִׁבְעִין וְחָמֵשׁ רוּחִין, לְדַשְׁנָא אַרְעָא, וּלְחַמְמָא קְרִירוּתָא. וּמַלְאַךְ מְמוּנֶּה עָלָיו, וְאוֹרִיאֵל שְׁמֵיהּ, וְהוּא מְמוּנֶּה לְצַד דָּרוֹם, בְּהַהוּא רוּחָא. וְהַהוּא רוּחָא כַּבְדָא עַל בְּנֵי מַרְעִין, וְדָחֲקִין בֵּיהּ, וְהוּא טַב לְעָלְמָא. וְתָאנָא, בְּהַהוּא זִמְנָא דָּיְינִין לְחַיָיבַיָא בְּנוּרָא דְּגֵיהִנֹּם, וְכָל עָלְמָא שָׁכְבִין, וְהוֹזִים בְּשֵׁינְתָא, וְלֵית מַאן דִּמְצַלֵּי עֲלֵיהֶן.</p>"],[9514011540,"<p>רוּחַ צָפוֹן מְנַשֶּׁבֶת מֵחֲצִי הַלַּיְלָה עַד הַבֹּקֶר. וְתָאנָא, תְּלַת מְאָה אַלְפִין רוּחִין וְעִלְעוּלִין אַתְיָין עִמֵּיהּ, וְהוּא קָשֶׁה מִכָּלְהוֹן לְכוֹלָּא. וְטַב לִבְנֵי מַרְעִין, מִסְגִּיאוּת קְרִירוּתָא לַחֲמִימוּתָא סַגְיָא דִי בְהוֹן.</p>"],[9514011541,"<p>וְתָאנָא, ארִבִּי שִׁמְעוֹן בֶּן יוֹחָאי בֵּיהּ שַׁעֲתָא, נָפַק קוּדְשָׁא בְּרִיךְ הוּא מֵאִינוּן עָלְמִין סַגִּיאִין דִּכְסִיף בְּהוּ, וְאָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָא בְּגִנְתָּא דְעֵדֶן, וְקַל כָּרוֹזָא כָּרֵיז קָדֳמוֹהִי, וַאֲמַר, עוּרִי צָפוֹן וּבוֹאִי תֵימָן. כְּלוֹמַר עוּרִי רוּחַ צָפוֹן, וְאִיתְעַר לְמֵיתֵי לְעָלְמָא וְלַאֲפָחָא בְּבוּסְמַיָא דְעֵדֶן. הֲדָא הוּא דִכְתִיב, (שיר השירים ד׳:ט״ז) הָפִיחִי גַנִי יִזְלוּ בְשָׂמָיו.</p>"],[9514011542,"<p>דְּתָאנָא בִּזְמַן שֶׁרוּחַ צָפוֹן מְנַשֶּׁבֶת בַּחֲצִי הַלַּיְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנַס בַּגַּן עֵדֶן, כָּל הַבְּשָׂמִים, וְכָל הָאִילָנוֹת שֶׁבְּגַן עֵדֶן, עוֹלִים רֵיחָם, וּמְזַמְּרִים לְפָנָיו. דִּכְתִיב, (דברי הימים א ט״ז:ל״ג) אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי ה'. אָמַר רִבִּי שִׁמְעוֹן הַאי יַעַר, כְּמָה דְאַתְּ אָמֵר (שיר השירים ה׳:א׳) אָכַלְתִּי יַעֲרִי עִם דִּבְשִׁי.</p>"],[9514011543,"<p>וְכָל הַצַּדִּיקִים כֻּלָּם נֶהֱנִין מִזִּיו אַסְפַּקְלַרְיָא שֶׁל מַעֲלָה, וְנִיזוֹנִין מִמֶּנּוּ, וּמְזַמְּרִין לִפְנֵי יוֹצְרָם בַּגַּן עֵדֶן. הֲדָא הוּא דִכְתִיב יָבֹא דוֹדִי לְגַנּוֹ וְיֹאכַל פְּרִי מְגָדָיו. אָמַר רִבִּי מְנַחֵם, מַאי יֹאכַל, סָלְקָא דַעְתִּין דְּקוּדְשָׁא בְּרִיךְ הוּא יֹאכַל. לָאו הָכֵי, אֶלָּא כְּמַאן דְּאָמַר יֵיתֵי שׁוּלְטָנָא דְבֵיתָא וְיֹאכַל אוּשְׁפִּיזָא, כָּךְ כְּתִיב יָבֹא דוֹדִי לְגַנּוֹ, כְּלוֹמַר, כְּשֶׁיָּבֹא דוֹדִי לְגַנּוֹ, יֹאכַל הַמַּמְתִּין לוֹ. וְאֵיזֶהוּ, פְּרִי מְגָדָיו. הֵם הַצַּדִּיקִים, שֶׁהֵם פְּרִי מְגָדָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9514011544,"<p>תָּנוּ רַבָּנָן, כְּשֶׁמַּתְחִיל רוּחַ צָפוֹן לְנַשֵּׁב, כָּל הַשָּׁמַיִם, וְכָל הָרְקִיעִים, וְחַיּוֹת הַקֹּדֶשׁ, וְהָאוֹפַנִּים, וְכָל צְבָא הַשָּׁמַיִם, כֻּלָּם מִזְדַּעְזְעִים וּמִתְחַלְחְלִים, וּפוֹצְחִים רִנָּה וְשִׁבְחָה, לְמִי שֶׁאָמַר וְהָיָה הָעוֹלָם, עַד שֶׁנִּכְנַס עִם הַצַּדִּיקִים בְּגַּן עֵדֶן, וְזֶהוּ בַּחֲצוֹת הַלַּיְלָה.</p>"],[9514011545,"<p>אָמַר רַב יְהוּדָה אָמַר רַב, הַאי מַאן דְּנִשְׁמָתָא קַדִּישָׁא אִית בֵּיהּ, וּשְׁמַע קָל תַּרְנְגוֹלָא קָרֵי בְּפַלְגוּת לֵילְיָא, דַּאֲמַר רַב יְהוּדָה אֲמַר רַב, בְּפַלְגוּת לֵילְיָא, כַּד עָיֵיל קוּדְשָׁא בְּרִיךְ הוּא בְּגִנְתָּא דְעֵדֶן, זִיקָא דְּאֶשָׁא נָפֵיק מִבֵּין גַּלְגַּלֵּי חֵיוָתָא, וְאָזֵיל בְּכָל עָלְמָא, וְנוֹגֵעַ תְּחוֹת גַּדְפוֹהִי דְּתַרְנְגוֹלָא, וּבְהַהִיא שַׁעֲתָא, בִּדְחִילוּ מַקִּישׁ גַּדְפוֹי דָּא עִם דָּא, וְקָארֵי, וְדָא הוּא בְּפַלְגּוּת לֵילְיָא.</p>"],[9514011546,"<p>וּמָאן דְּאִית לֵיהּ סוּכְלְתָנוּ בְּלִבּוֹי, וְיִתְעַר וִיקוּם לְאִתְעַסְּקָא בְּאוֹרַיְיתָא, אָזֵיל קָלֵיהּ וְאִשְׁתְּמַע בְּגִנְתָא דְעֵדֶן, וְאַצֵּית קוּדְשָׁא בְּרִיךְ הוּא. וְצַדִּיקַיָא אָמְרִין לֵיהּ, מָארֵי עָלְמָא. מָאן הוּא דָא. וְהוּא אָתֵיב וַאֲמַר פְּלַנְיָא, וְנִשְׁמָתָא קַדִּישָׁא דְּאִית בֵּיהּ, לָעֵי בְּאוֹרָיְיתָא, אֲצִיתוּ כּוּלְכוּ, דְּהַאי נִיחָא קֳדָמָאי, מִכָּל שִׁירָתָא וְתוּשְׁבַּחְתָּא, דְּאָמְרִין לְעֵילָא.</p>"],[9514011547,"<p>הֲדָא הוּא דִכְתִיב, (שם ח) הַיּוֹשֶׁבֶת בַּגַּנִּים. כְּלוֹמַר, נִשְׁמָתָא קַדִּישָׁא דְּאַתְּ יָתְבָא בְּהַהוּא עָלְמָא, בֵּין גְּנוּתָא וְטִנּוּפָא, וְאַתְּ עָסְקַת בְּאוֹרַיְיתָא. בְּשַׁעֲתָא דָא, חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ, שֶׁהוּא עָרֵב. וְהוֹאִיל וְכֵן, הַשְׁמִיעִי וְהָרִימִי קוֹלֵךְ בְּתוֹרָתִי, וְאֶתֵּן לָךְ שְׂכַר חֶסֶד בָּעוֹלָם הַבָּא.</p>"],[9514011548,"<p>אָמַר רִבִּי תַּנְחוּם, בֹּא וּרְאֵה, דָּוִד הֲוָה יָדַע הַהִיא שַׁעֲתָא. דִּתְנַן, כִּנּוֹר הָיָה תָּלוּי לְמַעְלָה מִמִּטָתוֹ שֶׁל דָּוִד, וּכְשֶׁהָיָה חֲצוֹת לַיְלָה, רוּחַ צְפוֹנִית בָּאָה וּמְנַשֶּׁבֶת בּוֹ, וּמִיָּד הָיָה קָם וּמִתְגַּבֵּר בְּשִׁירוֹת וְתִשְׁבָּחוֹת. דִּכְתִיב (תהילים נ״ז:ט׳) עוּרָה כְבוֹדִי עוּרָה הַנֵּבֶל וְכִנּוֹר אָעִירָה שָׁחַר.</p>"],[9514011549,"<p>אָמַר רִבִּי זֵירָא, מְנָא לָן דְּרוּחַ צְפוֹנִית מְנַשֶּׁבֶת בַּכִּנּוֹר. אָמַר רִבִּי יִצְחָק, מֵהָכָא, כְּתִיב הָכָא עוּרָה כְבוֹדִי, וּכְתִיב הָתָם עוּרִי צָפוֹן. מַה לְּהַלָּן צָפוֹן, אַף כָּאן צָפוֹן. וַהֲווּ צַיְיתִין לֵיהּ בְּכָל לֵילְיָא, קוּדְשָׁא בְּרִיךְ הוּא, וְכָל צַדִּיקַיָא דִּי בְּגִנְתָא דְּעֵדֶן, וְזֶה הוּא בַּחֲצִי הַלַּיְלָה.</p>"],[9514011550,"<p>תָּנוּ רַבָּנָן, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא גַּן עֵדֶן לְמַטָה בָּאָרֶץ, וְהוּא מְכֻוָּון כְּנֶגֶד כִּסֵּא הַכָּבוֹד, וּפָרוֹכֶת, הַקֶּרַח הַנּוֹרָא. וְתָאנָא, מָקוֹם יָדוּעַ יֵשׁ עָלָיו, אֲשֶׁר לֹא שָׁלְטָא בּוֹ עֵין נָבִיא לִרְאוֹת, לֹא בַּמַּחֲזֶה, וְלֹא בַּמַּרְאֶה, וְעֵדֶן שְׁמוֹ, דִּכְתִיב (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתֶךָ.</p>"],[9514011551,"<p>וְאָמַר רִבִּי שִׁמְעוֹן, מֵאוֹתוֹ עֵדֶן שֶׁלְּמַעְלָה, מִמֶּנּוּ נִיזּוֹן אוֹתוֹ הַגַּן שֶׁלְּמַטָה הֵימֶנּוּ, וּמִתְדַּשְּׁנִים מִשָּׁם כָּל הָאִילָנוֹת וְכָל הַיְבוּלִים, וְכָל הַצְּמָחִים שֶׁבַּגַּן.</p>"],[9514011552,"<p>וְאָמַר רַבִּי שִׁמְעוֹן, שְׁלשָׁה פְּעָמִים בְּכָל יוֹם, מְנַטֵף אוֹתוֹ עֵדֶן שֶׁלְּמַעְלָה מֵעַל הַגַּן, מִכָּל רֵיחִין טָבִין, וְזָהֲרִין עִלָּאִין, וַהֲנָאוֹת וְכִסּוּפִין, וּמֵהַהוּא רֵיחָא וְכִסּוּפָא וַהֲנָאָתָא דְּנָחֵית עֲלוֹהִי, מִתְּזָן כָּל עָלְמָא מִינֵּיהּ.</p>"],[9514011553,"<p>וְתָאנָא, אָמַר רַבִּי שִׁמְעוֹן כְּשֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא, מִיָּד הִצְמִיחָה הָאָרֶץ כָּל יְבוּלִין, וְכָל דְּשָׁאִים, וְכָל אִילָנוֹת שֶׁבּגַּן עֵדֶן בַּתְּחִלָּה. וְאַחַר כַּךְ הִצְמִיחָה לְכָל הָעוֹלָם. וְאָמַר רִבִּי יְהוּדָה, הָאָרֶץ הִצְמִיחָה לְכָל הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִצְמִיחַ לַגַּן עֵדֶן. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ח׳) וַיִּטַע ה' אֱלֹהִים גַּן בְּעֵדֶן מִקֶּדֶם.</p>"],[9514011554,"<p>אָמַר רַבִּי שִׁמְעוֹן, הָאָרֶץ הִצְמִיחָה הַכֹּל, וְהַקָדוֹשׁ בָּרוּךְ הוּא בֵּירַר כָּל דְּמַעֲלֵי מִנַיְיהוּ, וּשְׁתָלָן בּגַּן עֵדֶן. וּמִמַּה דְּנָחִית מֵעֵדֶן, כֻּלָּם נִזּוֹנִים, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:ט״ז-י״ז) יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע אֲשֶׁר שָׁם צִפָּרִים יְקַנֵּנוּ. מַאן אִינוּן צִפֳּרִים, אִלֵּין אִינוּן צַדִּיקַיָא, דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד לְהוֹ גַּדְפִין כְּצִפֳּרִין, לְאִתְעוֹפְפָא לְעֵילָא, בְּמִנְדַע וְסוּכְלְתָנוּ, וּלְסָלְקָא לְהוֹ לְהַהוּא אֲתַר דְּגָנֵיז לְהוֹן, דִּכְתִיב בֵּיהּ עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתֶךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>"],[9514011555,"<p>אָמַר רִבִּי יְהוּדָה, הוֹלִידָה הָאָרֶץ דְּשָׁאִים הַמְגַדְּלִים לְאַחַר כַּךְ, וְצוֹמְחִים, לַעֲשׂוֹת צוֹרֶךְ הָעוֹלָם. וְכָל הָעֲשָׂבִים שֶׁל רְפוּאָה לְרַפְּאוֹת בָּהֶם הַבְּרִיּוֹת, כֻּלָּם הוֹלִידָה וְהִצְמִיחָה הָאָרֶץ בְּבַת אַחַת.</p>"],[9514011556,"<p>אָמַר רִבִּי יְהוּדָה בַּר שָׁלוֹם, בּוֹ בַּיּוֹם שֶׁנִּבְרְאוּ שָׁמַיִם וָאָרֶץ, בּוֹ בַּיּוֹם עָשׂוּ כֻּלָּם תּוֹלְדוֹתָם. וְלֹא חָסַר מֵהֶם כְּלוּם. מַשְׁמַע דִּכְתִיב, (בראשית ב) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. וְאֵימָתַי נַעֲשׂוּ תּוֹלְדוֹת אֵלּוּ. בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. דַּיְיקָא, בּוֹ בַּיּוֹם נַעֲשָׂה כָּל צָרְכֵי הָעוֹלָם. וּלְאַחַר כֵּן גִּילָּה אוֹתָם, בְּכָל יוֹם וָיוֹם. וְנָתַן טַעַם לְכָל דָּבָר וְדָבָר בְּאוֹתוֹ הַיּוֹם שֶׁנִּתְגַּלָּה.</p>"],[9514011557,"<p>וְכֵן אָמַר רִבִּי יוֹחָנָן, בּוֹ בַּיּוֹם שֶׁנִּבְרֵאת הָאָרֶץ, בּוֹ בַּיּוֹם הוֹלִידָה וְהִצְמִיחָה כָּל תּוֹלְדוֹתֶיהָ, וְהָיוּ כֻּלָּם גְּנוּזוֹת תַּחְתֶּיהָ, עַד שֶׁאָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹצֵא הָאָרֶץ. תִּבְרָא הָאָרֶץ לֹא נֶאֱמַר, אֶלָּא תּוֹצֵא הָאָרֶץ, דָּבָר שֶׁהָיָה גָנוּז בָּהּ, וְהוֹצִיאָה כָּל דָּבָר וְדָבָר, בְּאוֹתָהּ הַטֶבַע הָרָאוּי לָהּ לְהוֹלִיד וּלְהַזְרִיעַ מֵהֶם כַּדּוֹמֶה לָהֶם, הֲדָא הוּא דִכְתִיב לְמִינָהּ.</p>"],[9514011558,"<p>אָמַר רִבִּי יְהוּדָה, כָּךְ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָרֶץ, כִּנְקֵבָה זוֹ הַמְעוּבֶּרֶת, וְאַחַר כַּךְ מוּצִיאָה עוּבָּרָהּ מִמֶּנָּהּ. כָּךְ הָיְתָה הָאָרֶץ, בְּשָׁעָה שֶׁנִּבְרֵאת נִתְעַבְּרָה מֵהַיְסוֹדוֹת כֻּלָּם שֶׁנִּכְנְסוּ בָּהּ, וְהֵם הוֹצִיאוּ כָּל תּוֹלְדוֹת שֶׁלָּהּ.</p>"],[9514011559,"<p>אר\"י כִּוְורָדִין שֶׁל שִׁלְיָא דְּאִשָּׁה, דְּמָלְיָיאן מִן זַרְעָא דְּבַּר נָשׁ, דְּאִית בֵּיהּ הַיְסוֹדוֹת כֻּלָּם, כָּךְ הָאָרֶץ, בּוֹ בַּיּוֹם שֶׁנִּבְרֵאת, בּוֹ בַּיּוֹם נִתְעַבְּרָה, מִכָּל מַה שֶּׁהוֹלִידָה, דִּכְתִיב (בראשית א׳:א׳-ב׳) בְּרֵאשִׁית בָּרָא אֱלֹהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּמִיָּד וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחשֶׁךְ וְרוּחַ. הֲרֵי בְּכָאן אַרְבָּעָה יְסוֹדוֹת, שֶׁהֵם: אֵשׁ. מַיִם. רוּחַ. חשֶׁךְ. וְאֵלּוּ הוֹלִידוּ כָּל תּוֹלְדוֹתֶיהָ, וּמֵאֵלּוּ נִתְיַיסְדוּ כּוּלָּם. וְכָל הַתּוֹלָדוֹת נִתְהַוּוּ, מִכֹּחוֹת אֵלּוּ.</p>"],[9514011560,"<p>אָמַר רִבִּי אַבָּא, בְּצוּצִיתָא דְאַרְעָא, מַלְיָיאן זַרְעָא כִּנְקֵבָה, מֵאִינוּן מַיָא דִלְעֵילָא, וּמִתְעַבֶּרֶת מִנַּיְיהוּ כְּנוּקְבָא דְּמִתְעַבְּרָא מִן דְּכוּרָא.</p>"],[9514011561,"<p>שָׁאַל רַבִּי חַגַּי לְרַבִּי דּוֹסְתָּאי, אָמַר לֵיהּ, הָא כְתִיב (שם) וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי עוֹשֶׂה פְּרִי לְמִינוֹ. אִי אַרְעָא אַפֵּיקַת אִילָנִין וּפֵירִין, מַה כְּתִיב לְאַחַר כַּךְ, (שם ב) וְכֹל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָּאָרֶץ וְכָל עֵשֶׂב הַשָּׂדֶה טֶרֶם יִצְמָח, וּמַשְׁמַע טֶרֶם כְּתַרְגּוּמוֹ.</p>"],[9514011562,"<p>אָמַר לֵיהּ, כָּךְ הוּא, אֲבָל כֹּחוֹת לְהוֹלִיד בְּאוֹתוֹ הַזְּמַן לֹא הָיָה לָהֶם. וּמִפְּנֵי מָהּ, מִפְּנֵי שֶׁלֹּא הִמְטִיר ה' אֱלֹהִים עַל הָאָרֶץ, וְאֵד לֹא הָיָה, שֶׁיַּעֲלֶה מִן הָאָרֶץ, שֶׁאִלְּמָלֵא הָיָה כָךְ, כָּל כֹּחוֹתָם הָיוּ לְהוֹלִיד וּלְהַצְמִיחַ. אֲבָל מִפְּנֵי זֶה לֹא הָיָה בָּאָרֶץ הַכֹּחַ הַמּוֹלִיד.</p>"],[9514011563,"<p>רַבִּי יִצְחָק אָזַל לְגַבֵּי רַבִּי זֵירָא. עָאל לְבֵיתֵיהּ אַשְׁכַּח דְּהֲוָה מְטַיֵּיל בְּהַהוּא גִינָא. פְּתַח וַאֲמַר, (שופטים א׳:ט״ז) וּבְנֵי קֵינִי חוֹתֵן משֶׁה עָלוּ מֵעִיר הַתְּמָרִים. מָה חָזוּ בְּנֵי יִתְרוֹ לְסָלְקָא מִתַּמָּן.</p>"],[9514011564,"<p>דְּאָמַר רַב יְהוּדָה אָמַר רַב, שְׁקוּלָה הָיְתָה יְרִיחוֹ, כְּנֶגֶד כָּל אֶרֶץ יִשְׂרָאֵל, מֵרוֹב הַתַּעֲנוּגִים שֶׁהָיוּ בָהּ. דְּאָמַר רַב יְהוּדָה אָמַר רַב, לָמָּה נִקְרֵאת שְׁמָהּ יְרִיחוֹ, עַל שֵׁם הָרֵיחַ. אָמְרוּ בְּנֵי יִתְרוֹ, אֲנַן צְרִיכִין לְאִתְעַסְּקָא בְּאוֹרָיְיתָא, וְאוֹרָיְיתָא אֵינָהּ צְרִיכָה תַּעֲנוּגִים, נֵיקוּם מִכָּאן לְטוּרָא וְנִתְעַסֵּק בְּאוֹרָיְיתָא.</p>"],[9514011565,"<p>אָמַר רִבִּי זֵירָא, יְדַעְנָא עַל מָה אִתְכַּוַּונְתְּ, אֶלָּא בְּנֵי יִתְרוֹ, עַד כְּעָן לָא הֲווֹ יָדְעֵי אוֹרָיְיתָא, וּצְרִיכֵי לְטוּרָא. אֲבָל אֲנָא יְדַעְנָא בְּאוֹרָיְיתָא, וּצְרִיכְנָא צַחוּתָא לִשְׁמַעְתָּא.</p>"],[9514011566,"<p>אָמַר לֵיהּ, מַאי דִכְתִיב וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא. אָמַר לֵיהּ, הוֹצִיאָה הָאָרֶץ כָּל הַתּוֹלָדוֹת שֶׁהָיוּ בָהּ, וְשֶׁהָיוּ גְּנוּזִים בָּהּ, לַחוּץ. וְלֹא הָיוּ בָּהֶם כּוֹחוֹתָם, עַד שֶׁהִמְטִיר הַקָדוֹשׁ בָּרוּךְ הוּא עַל הָאָרֶץ, וְעָמְדוּ כָּל הַתּוֹלָדוֹת בְּכֹחָם הַשְּׁלֵימָה, וּכְתִיב וַיַּרְא אֱלֹהִים כִּי טוֹב.</p>"],[9514011567,"<p>פָּרָשָׁתָא ו (בראשית א׳:ט״ו) וַיֹּאמֶר אֱלֹהִים יְהִי מְאוֹרוֹת בִּרְקִיעַ הַשָּׁמָיִם לְהָאִיר עַל הָאָרֶץ. תַּמָּן תָּנִינָן, אָמַר רִבִּי יִצְחָק בַּר יַעֲקֹב, מַאי דִכְתִיב, (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעֲיָתִי וּמוּם אֵין בָּךְ, תָּא חֲזֵי, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ, עֲשָׂאוֹ מֵאוֹתוֹ הָאוֹר הַנֶּאֱצָל מִלְּמַעְלָה. וּבָרָא הַשָּׁמַיִם, מֵאוֹתוֹ הָרָקִיעַ הָרִאשׁוֹן שֶׁהֵכִינוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּבְרָאוֹ בַּתְּחִלָּה. וְאוֹתוֹ הָרָקִיעַ הוֹלִיד כָּל שְׁאָר הָרְקִיעִים שֶׁנִּתְהַוּוּ מִמֶּנּוּ.</p>"],[9514011568,"<p>וְאָמַר רַב יְהוּדָה אָמַר רַב, אוֹתוֹ הָרָקִיעַ הוֹלִיד כָּל הַמְאוֹרוֹת, מֵאוֹתוֹ הָאוֹר שֶׁמְקַבֵּל מִלְּמַעְלָה. וּכְשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ רָקִיעַ, נָטַל אֶת הַמְאוֹרוֹת, וְהִנִּיחָם בְּאוֹתוֹ רָקִיעַ, הַנִּקְרָא רְקִיעַ הַשָּׁמָיִם. שֶׁאוֹתוֹ הָרָקִיעַ, נִתְהַוָּה מִן הַשָּׁמָיִם.</p>"],[9514011569,"<p>אָמַר רִבִּי יְהוּדָה אָמַר רַב, הָרָקִיעַ הָעֶלְיוֹן, הוֹלִיד הַשָּׁמַיִם אֲשֶׁר תַּחְתָּיו. וְהַשָּׁמַיִם הוֹלִידוּ הַאי רָקִיעַ, וְנִקְרָא רְקִיעַ הַשָּׁמָיִם. וְנָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא הַנֵּי מְאוֹרוֹת, וּנְתָנָם בּוֹ. הֲדָא הוּא דִכְתִיב, (בראשית א׳:י״ז) וַיִּתֵּן אוֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם.</p>"],[9514011570,"<p>אָמַר רִבִּי יִצְחָק, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הַנֵּי מְאוֹרוֹת, וְהִנִּיחָם בָּזֶה הָרָקִיעַ, לִהְיוֹת מֶמְשָׁלָה עַל הָאָרֶץ, וּלְהִשְׁתַּמֵּשׁ בָּהֶם הַבְּרִיּוֹת, וּכְשֶׁבְּרָאָם, נָתְנוּ אוֹרָם שְׁנֵיהֶם בְּשָׁוֶה. אָמְרָה הַלְּבָנָה, רִבּוֹנוֹ שֶׁל עוֹלָם, אֵין לְךָ לְהִתְנַהֵג בִּשְׁנֵי כְתָרִים בְּשָׁוֶה. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. הִמְעִיט אוֹתָהּ, וְהַיְינוּ הַכַּפָּרָה שֶׁל שְׂעִיר רֹאשׁ חֹדֶשׁ, שֶׁנֶּאֱמר בּוֹ לַה'.</p>"],[9514011571,"<p>אָמַר רִבִּי יַעֲקֹב, בְּכַמָּה דוּכְתֵי תָּנִינָן דָּא, וְלָא אִתְיַישְׁבָא בְּלִבָּאי עִנְיָינָא. כַּד אָתָא רַב נַחְמָן, אָתוֹ וְשָׁיְילוּהָ, אָמַר כְּמַשְׁמָעוֹ. אָמַר רִבִּי יְהוּדָה לְרַבִּי יעֲקֹב, אַתָּה רוֹצֶה לַעֲבוֹר עַל דִּבְרֵי חֲבֵרֶיךָ. אִשְׁתִּיק.</p>"],[9514011572,"<p>רַבִּי יוֹסֵי בֶּן רִבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא, אָתָא לְמֶחֱמֵי לְרַבִּי אֶלְעָזָר בֶּן רִבִּי שִׁמְעוֹן, חֲתְנֵיהּ, נָפְקָא בְּרַתֵּיהּ, וְשָׁקְלָא יְדוֹהִי לְנַשְׁקָא. אֲמַר לָהּ, לְכִי וּמַעֲטִי אֶת עַצְמֵךְ מִקַּמֵּי בַּעֲלֵיךְ, דְּאִיהוּ קַדִּישָׁא. שְׁמַע ר' אֶלְעָזָר, אֲמַר כְּעַן אֲנָא אִדְכַּרְנָא מִלָּה חַד, דְּאִיהוּ מַרְגָּלָא יַקִּירָא, דְּאִיתְּמָר עַל סִיהֲרָא, כִּדְתָנִינָן, דְּקוּדְשָׁא בְּרִיךְ הוּא אֲמַר לְסִיהֲרָא, לְכִי וּמַעֲטִי אֶת עַצְמֵךְ, דְּחָשְׁבַת סִיהֲרָא דְּלָהּ אִתְיְיהֵיב שׁוּלְטָנָא. אָמַר לֵיהּ חָמוֹי, אֲנָא כָּךְ שְׁמַעְנָא, וְכָךְ הוּא מִתְסַדֵּר בְּלִבָּאי, בְּגִין דְּלָא אַעֲבַר עַל דַּעְתּוֹי דְּחַבְרַיָיא.</p>"],[9514011573,"<p>פְּתַח רַבִּי אֶלְעָזָר פּוּמֵיהּ וַאֲמַר, (דברים ל״ג:כ״ט) אַשְׁרֶיךָ יִשְׂרָאֵל מִי כָמוֹךָ עַם נוֹשַׁע בַּה' מָגֵן עֶזְרְךָ וַאֲשֶׁר חֶרֶב גַּאֲוָתֶךָ. וְכִי גַּאֲוָתָן שֶׁל יִשְׂרָאֵל חֶרֶב הוּא. לָא. דְּהָא הַחֶרֶב לְעֵשָׂו אִתְיְיהִיבַת, דִּכְתִיב (בראשית כ״ז:ל״ט-מ׳) וְעַל חַרְבְּךָ תִּחְיֶה. אֲבָל יִשְׂרָאֵל, לָא.</p>"],[9514011574,"<p>אֶלָּא הָכֵי שְׁמַעְנָא מֵאַבָּא, דְּאִלֵּין אִינוּן תָּא חֲזֵי, דְּכַד שָׁמְעִין מִלָּה, וְלָא אִתְיַישֵׁב בְּלִבְּהוֹן, דְּאִינוּן מַגִּיחִין דָּא עִם דָּא, כְּאִינוּן דְּמַגִּיחֵי קְרָבָא בְּחַרְבָּא, וּבָעְיָין לְקָטְלָא דָּא לְדָא.</p>"],[9514011575,"<p>וּמִלָּה דָא דַּאֲמַר חַבְרָנָא, כָּךְ הוּא, וְכֵן גָּזַרְנָא בְּרָזָא דְמַתְנִיתָּא דִילָן, דְּכַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא לְשִׁמְשָׁא וּלְסִיהֲרָא, גְּזַר עַל שִׁמְשָׁא, דְּאִתְחַזַּר לְמֶהֱוֵי שׁוּלְטָנָא דְּעֵשָׂו. וּגְזַר עַל סִיהֲרָא, לְמֶהֱוֵי בְּעָלְמָא דֵין, שׁוּלְטָנָא דְּיַעֲקֹב. וּמַנֵּי עֲלֵיהוֹן רַבְרְבִין תַּקִּיפִין, עַד דְּיֵיתוֹן תְּרֵין אוּמַּיָיא אִלֵּין.</p>"],[9514011576,"<p>וְהַהוּא רַבְרְבָנָא, דְאִתְמַנֵּי עַל סִיהֲרָא, בְּגִין אוּמָּה דְיַעֲקֹב, בָּעָא מִן קוּדְשָׁא בְּרִיךְ הוּא, דְּיִתְיְיהֵב שׁוּלְטָנָא לְסִיהֲרָא בְּעָלְמָא דֵין, כְּלוֹמַר לָאוּמָּה דְּיַעֲקֹב. אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, וְכִי מָה בָּעְיָיא אוּמָּה דְּיַעֲקֹב, אֶלָּא לְעָלְמָא דְאָתֵי, וּלְשַׁלְטָאָה לְהוֹ עַל כָּל עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. אֲבָל בְּעָלְמָא דֵין, לְכִי וּמַעֲטִי אֶת עַצְמֵךְ, וְאִשְׁתַּעְבִּידִי בְּגָלוּתָא, לְמִזְכֵּי לְעָלְמָא דְאָתֵי.</p>"],[9514011577,"<p>כַד אָתֵי אוּמָּה דְיַעֲקֹב, אִתְרַעֲמוּ קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא עַל דְּאִתְנְטַל מִנְּהוֹן שׁוּלְטָנָא, וְאִתְיְהֵיבַת לְעֵשָׂו. אֲמַר לְהוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְכִי מָה אַתּוּן בָּעָאן שׁוּלְטָנָא דְּעָלְמָא דֵין, דְּהָא אֲנָא עַרְבָאָה לְשַׁלְטָאָה לְכוֹ לְעָלְמָא דְאָתֵי, עַל כָּל הָאוּמּוֹת. וּבְגִין כָּךְ הַקְרִיבוּ עָלַי כַּפָּרָה, כְּלוֹמַר עַל אוֹתָהּ הַבְטָחָה שֶׁאֲנִי עָרֵב בוֹ, הַקְרִיבוּ כַּפָּרָה, וְאִתְעַסְּקוּ בְּאוֹרָיְיתָא, וְעָלַי לָתֵת לָכֶם שָׂכָר טוֹב, וְעָלַי לְהַשְׁלִיט אֶתְכֶם עַל כָּל הָאוּמּוֹת, שֶׁעַל כָּךְ מִיעַטְתִּי אֶת הַיָּרֵחַ בָּעוֹלָם הַזֶּה.</p>"],[9514011578,"<p>אָתָא ר' יוֹסֵי חֲמוֹי, וּנְשָׁקֵיהּ בְּרֵישֵׁיהּ, קָרָא לִבְרַתֵּיהּ וַאֲמַר לָהּ, קוֹטְפִּיזָא דִּנְהִירוּתָא, וּבוּצִינָא דְּאִיתְפְּרָשָׁא בְּטַבְוָון, אִית גַּבָּךְ, זַכָּאָה אַנְתְּ, זַכָּאָה חוּלָקָךְ, זַכָּאָה הוּא חוּלָקִי בְּעָלְמָא דֵין, דְּזָכֵינָא לְמֶחֱמֵי כָּךְ.</p>"],[9514011579,"<p>רַבִּי יוֹחָנָן אֲמַר, זָכוֹ יִשְׂרָאֵל, נָהֵיר לְהוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְלֵית אִינוּן צְרִיכִין לְבוּצִינָא אָחֳרָא, דִּכְתִיב (ישעיהו ס׳:י״ט) וְהָיָה לָךְ ה' לְאוֹר עוֹלָם.</p>"],[9514011580,"<p>אָמַר רִבִּי אַבָּהוּ, יִשְׂרָאֵל כֵּיוָן שֶׁנִּתְחַלֵּף לְהוֹ שׁוּלְטָנָא, מוֹנִין חוּשְׁבָּנָא לְסִיהֲרָא. דְּבָהּ מְנַהֲגִין יִשְׂרָאֵל חוּשְׁבַּנְהוֹן. הֲדָא הוּא דִכְתִיב, (שיר השירים ד׳:א׳) הִנָּךְ יָפָה רַעֲיָתִי, מַנְהִיגָתִי. (שם) וּמוּם אֵין בָּךְ, דְּלָא אִשְׁתְּכַח בָּךְ גִּרְעוֹנָא מִן מוֹעֲדִין וְזִמְנִין.</p>"],[9514011581,"<p>דָּבָר אַחֵר, הִנָּךְ יָפָה רַעֲיָתִי וּמוּם אֵין בָּךְ. תָּנוּ רַבָּנָן, בְּאַרְבָּעָה פְּרָקִים בַּשָּׁנָה הָעוֹלָם נִידּוֹן. אָמַר רִבִּי אֲלֶכְּסַנְדְּרָאי, וְכִי לֹא נִידּוֹן הָאָדָם אֶלָּא לִפְרָקִים אֵלּוּ, וְהָא כְתִיב (איוב ז׳:י״ח) וַתִּפְקְדֶנּוּ לַבְּקָרִים לִרְגָעִים תִּבְחָנֶנוּ. וְאָמַר רִבִּי יִצְחָק, אִין לְךָ כָּל רֶגַע וְרֶגַע שֶׁאֵין הַקָדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ בָּאָדָם, בְּכָל מַה שֶּׁהוּא עוֹשֶׂה. וְתָנֵי הָכָא, דִּבְאַרְבָּעָה פִּרְקִין בַּשָּׁנָה הוּא.</p>"],[9514011582,"<p>אָמַר רִבִּי אֲלֶכְּסַנְדְּרָאי, הַדְרֵי בִי. מִלָּה דְאוֹרָיְיתָא בְּעִנְיָינָא דָא. וְלָא בְעִנְיָינָא דְּהַהוּא מִלָּה דְרַבָּנָן. דִּפְסוּקָא אֲמַר, פְּקִידָה וּבְחִינָה. וְרַבָּנָן אָמְרֵי דִּינָא. וּמַשְׁמַע דְּקוּדְשָׁא בְּרִיךְ הוּא מַשְׁגַּח בְּכָל יוֹמָא וְיוֹמָא בְּעָלְמָא. אֲבָל מֵידִין דִּינָא, עַד אַרְבָּעָה זִמְנִין אִלֵּין, לְמֵידַן כָּל עָלְמָא.</p>"],[9514011583,"<p>וְכָלְהוֹ דִּינִין אֵלּוּ, בְּגִינֵיהוֹן דִּבְנֵי נָשָׁא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בְּעָלְמָא. בַּפֶּסַח, עַל הַתְּבוּאָה, מַאי קָא מַשְׁמַע לָן. אָמַר רִבִּי יִצְחָק, עַל תְּבוּאָה מַמָּשׁ. דְּאָמַר רִבִּי יִצְחָק, בַּשָּׁנָה שֶׁעָבְרָה נָתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא תְּבוּאָה סִיפּוּקָא דְעָלְמָא. לָא מְעַשְׂרִין לֵיהּ בְּנֵי נָשָׁא, וְלָא יַהֲבֵי לְמֵיכַל מִנֵּיהּ לְמִסְכְּנֵי וּלְיַתְמֵי וּלְאַרְמַלְתֵּי, כַּד אָתֵי שַׁתָּא דָא דָּאִין לְכָל עָלְמָא עַל הַהוּא תְּבוּאָה דְּהֲוָה בְּשַׁתָּא דְּעָבְרָה.</p>"],[9514011584,"<p>בַּעֲצֶרֶת דָּן אֶת הָעוֹלָם, עַל אֵיזֶה עָוֹן. עַל עֲוֹן פֵּירוֹת הָאִילָן, שֶׁלֹּא הִמְתִּינוּ שְׁנוֹת עָרְלָתָם, וְשֶׁלֹּא הִנִּיחוּם בַּשְּׁבִיעִית לֶעָנִי וְלַגֵּר.</p>"],[9514011585,"<p>בְּרֹאשׁ הַשָּׁנָה דָּן כָּל הָעוֹלָם כֻּלּוֹ, גּוּפוֹת בְּנֵי אָדָם וְהַנְּשָׁמוֹת, וּפוֹקֵד אוֹתָם, וְדָן אוֹתָם עַל כָּל מַה שֶּׁעָשׂוּ כָּל הַשָּׁנָה כֻּלָּהּ. וְתָאנָא, אֲפִילּוּ צְעָדָיו שֶׁל אָדָם נִמְנִין וּבָאִין בַּדִּין בְּאוֹתוֹ הַיּוֹם, הֲדָא הוּא דִכְתִיב, (שם לא) וְכָל צְעָדַי יִסְפּוֹר.</p>"],[9514011586,"<p>תָּאנֵי רַבִּי יוֹסֵי, שָׁלשׁ כִּתּוֹת נִכְנָסִין לְיוֹם הַדִּין. כַּת צַדִּיקִים גְּמוּרִים. כַּת רְשָׁעִים גְּמוּרִים. כַּת בֵּינוֹנִים. וּכְנֶגְדָן שָׁלשׁ כֹּחוֹת בָּאָדָם. כֹּחַ הַנְּשָׁמָה הַקְּדוֹשָׁה. וְכֹחַ הַמִּתְאַוֶּה. וְכֹחַ הַמְנִיעָה. מַאי כֹּחַ הַמְנִיעָה, אָמַר רִבִּי יְהוּדָה, כֹּחַ הַמְגַדֶּלֶת וְהַמְנִיעַ אֶת הַגּוּף בְּכָל צְרָכָיו.</p>"],[9514011587,"<p>רַבִּי יוֹסֵי בֶּן פַּזִי אוֹמֵר, בֹּא וּרְאֵה רַחְמָנוּתוֹ שֶׁל הַקָדוֹשׁ בָּרוּךְ הוּא, אַף עַל פִּי שֶׁבֵּית דִּין שֶׁל מַעְלָה בָּאִין לַעֲמֹד בַּדִּין, וְלָדוּן אֶת הַבְּרִיּוֹת, וּלְהוֹרוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא זְכוּת וְחוֹבָה שֶׁל בְּנֵי אָדָם. דְּתָאנֵי ר' יוֹסֵי בֶּן פַּזִי, שָׁלשׁ כִּתּוֹת שֶׁל מַלְאֲכֵי הַשָּׁרֵת עוֹמְדִין עַל הַדִּין בְּיוֹם רֹאשׁ הַשָּׁנָה. יֵשׁ מֵהֶם שֶׁהֵם מוֹרִים זְכוּת לְטוֹבָה. וְיֵשׁ מֵהֶם חוֹבָה לְרָעָה. וְתָּא חֲזֵי, רַחְמָנוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנָּתַן עֵצָה לְהִנָּצֵל מִן הַדִּין.</p>"],[9514011588,"<p>דְּתַנְיָא מַהוּ דִּכְתִּיב, (ויקרא כ״ג:כ״ד) זִכְרוֹן תְּרוּעָה לָא אַשְׁכַּחְנָא זְכִירָה לִתְרוּעָה, אֶלָּא הַאי דְּאָמַר רִבִּי יוֹסֵי, כְּתִיב (במדבר י׳:ט׳) וְכִי תָבֹאוּ מִלְחָמָה בְּאַרְצְכֶם עַל הַצַּר וְגו' וַהֲרֵעֹתֶם וְגו', וְזֵכֶר לִתְרוּעָה זוֹ, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הָרִיעוּ לְפָנַי בִּתְרוּעָה זוֹ, שֶׁהִיא זִכְרוֹן אוֹתָהּ הַתְּרוּעָה, מִיָּד, וְנוֹשַׁעְתֶּם מֵאֹיְבֵיכֶם.</p>"],[9514011589,"<p>מָאן אִינוּן, אֵלּוּ הֵם הַמּוֹרִים חוֹבָתָם שֶׁל בְּנֵי אָדָם. דְּתַנְיָא אָמַר רִבִּי יוֹחָנָן, מַלְאָכִים יֵשׁ הַמּוֹרִים חוֹבָתָן שֶׁל בְּנֵי אָדָם. וּמַלְאָכִים יֵשׁ הַמּוֹרִים זְכוּתָן. וַאֲפִילּוּ אֶחָד מִנִּי אֶלֶף מוֹרֶה זְכוּתוֹ, שַׁבְקִין לוֹ. הֲדָא הוּא דִכְתִיב, (איוב ל״ג:כ״ג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף. וּכְתִיב בַּתְרֵיהּ, (איוב ל״ג:כ״ג) וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת וְגו'.</p>"],[9514011590,"<p>וְכִי יֵשׁ מַלְאָךְ מַשְׂטִין זְכוּתוֹ שֶׁל אָדָם, אָמַר רִבִּי שִׁמְעוֹן, חַס וְשָׁלוֹם שֶׁמַּלְאָךְ מַשְׂטִין זְכוּת. אֶלָּא, יֵשׁ מַלְאָכִים מְמוּנִּים לְעַיֵּין וּלְהוֹרוֹת בְּחוֹבָתוֹ שֶׁל אָדָם, בְּכָל שָׁעָה שֶׁיַּעֲבוֹר, וְהֵם מוֹרִים אוֹתוֹ דָּבָר שֶׁנִּצְטַוּוּ.</p>"],[9514011591,"<p>כַיּוֹצֵא בַּדָּבָר (מלכים א כ״ב:י״ט) וְכָל צְבָא הַשָּׁמַיִם עוֹמֵד עָלָיו מִימִינוֹ וּמִשְׂמֹאלוֹ. מַאי עָלָיו, עָלָיו שֶׁל אַחְאָב. שֶׁהָיוּ מְעַיְינִים בְּדִינוֹ. מִימִינוֹ וּמִשְׂמֹאלוֹ, וְכִי יֵשׁ יָמִין וכו', אֵלּוּ מַיְמִינִים לִזְכוּת, וְאֵלּוּ מַשְׂמְאִילִים לְכַף חוֹבָה.</p>"],[9514011592,"<p>אָמַר רַב יְהוּדָה אָמַר רַב, מִפְּנֵי מָה בְּרֹאשׁ הַשָּׁנָה דִּין הַגּוּף וְהַנְּשָׁמָה, מִפְּנֵי שֶׁבּוֹ נוֹלַד אָדָם הָרִאשׁוֹן, וּבוֹ בַּיּוֹם נַעֲשָׂה גּוּף, וְנִזְרְקָה בוֹ נְשָׁמָה, וּבוֹ בַּיּוֹם נִידּוֹן וְנִקְבַּע הַדִּין לְדוֹרוֹת.</p>"],[9514011593,"<p>וּבַחַג נִדּוֹנִין עַל שֶׁהֵם מְבַזִּים בִּנְטִילַת יָדַיִם, וְעַל שֶׁהֵם מְזַלְזְלִים בְּמִקְוָאוֹת וּבְטַהֲרוֹת שֶׁהֵם מַיִם. וְעַל כָּךְ נִדּוֹנִין עַל הַמַּיִם, עַל עִנְיַן הַמַּיִם.</p>"],[9514011594,"<p>אָמַר רִבִּי אַחָא, בְּד' פְּרָקִים כְּמוֹ כֵן, הָאָדָם נִדּוֹן. בּוֹ בַּיּוֹם שֶׁמְהַרְהֵר הָעֲבֵירָה. וּבַזְּמַן שֶׁעוֹשֵׂהוּ. וּבְיוֹם רֹאשׁ הַשָּׁנָה. וּבָעוֹלָם הַבָּא. רַבִּי אַבָּהוּ אָמַר, בַּזְּמַן שֶׁעוֹשֶׂה הָעֲבֵירוֹת. וּבַזְּמַן שֶׁיֶּחֱלֶה. דְּאָמַר רִבִּי אַבָּהוּ, כֵּיוָן שֶׁיֶּחֱלֶה הָאָדָם, סָלְקִין לֵיהּ לְדִינָא. וּבַזְּמַן שֶׁמֵּת כְּשֶׁיּוֹצְאָהּ נִשְׁמָתוֹ מִמֶּנּוּ. וּבָעוֹלָם הַבָּא.</p>"],[9514011595,"<p>אָמַר רִבִּי יְהוּדָה, בִּטָחוֹן הַצַּדִּיקִים וְשִׂמְחָתָם, כְּשֶׁיּוֹצְאִין מִן הָעוֹלָם הַזֶּה בְּכִשְׁרוֹן מַעֲשִׂים. וּכְשֶׁבָּאִין לְעַיֵּין בַּנְּשָׁמָה, אֵין מוֹחִין בְּיָדָהּ. וּמָה אוֹמְרִין לָהּ, כֻּלָּךְ יָפָה רַעֲיָתִי. אָמַר רִבִּי אַבָּהוּ, הַצַּדִּיק אוֹמֵר זֶה עַל הַנְּשָׁמָה שֶׁבּוֹ, כֻּלָּךְ יָפָה רַעֲיָתִי, מַנְהִיגָתִי דְּלָא אַבְאֵישַׁת לָךְ בְּעוֹבָדִין בִּישִׁין, דִּכְתִיב (שיר השירים ד׳:ז׳) וּמוּם אֵין בָּךְ.</p>"],[9514011596,"<p>דָּבָר אַחֵר (בראשית א׳:י״ד) וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת, לָמָּה חָסֵר ו', ארִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, תְּפִלַּת הַצַּדִּיקִים שֶׁיֵּצְאוּ מֵהָעוֹלָם הַזֶּה, כְּדֵי שֶׁלֹּא יִתְעַכֵּב שְׂכָרָם לָעוֹלָם הַבָּא. דְארִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, מַאי דִכְתִיב, (יחזקאל א׳:כ״ו) דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְּמַעְלָה. זוֹ מַעֲלָתָן שֶׁל צַדִּיקִים, שֶׁהֵם לְמַעְלָה עַל כָּל הַמַּעֲלוֹת.</p>"],[9514011597,"<p>מַאי עָלָיו. אָמַר רִבִּי יִצְחָק, הוּא יַעֲקֹב, שֶׁמַּעֲלָתוֹ לְמַעְלָה. הֲדָא הוּא דִכְתִיב, כְּמַרְאֵה אָדָם. מַאי מַשְׁמַע, כְּתִיב הָכָא עָלָיו, וּכְתִיב הָתָם (בראשית ל״ה:י״ג) וַיַּעַל מֵעָלָיו אֱלֹהִים.</p>"],[9514011598,"<p>אָמַר רִבִּי חִיָּיא בַּר יַעֲקֹב, אֵין לְךָ בְּכָל לַיְלָה וְלַיְלָה, שֶׁאֵין הַכָּרוֹז יוֹצֵא וְאוֹמֵר, עֲלוּ חֲסִידִים, בֹּאוּ וּבֵרְכוּ לְיוֹצַרְכֶם. הֲדָא הוּא דִכְתִיב, (תהילים קמ״ה:י׳-י״ב) וַחֲסִידֶיךָ יְבָרְכוּכָה. כְּבוֹד מַלְכוּתְךָ יֹאמֵרוּ וּגְבוּרָתְךָ יְדַבֵּרוּ. וְלָמָּה, לְהוֹדִיעַ לִבְנֵי הָאָדָם גְּבוּרוֹתָיו וְגו'.</p>"],[9514011599,"<p>תָּנוּ רַבָּנָן זִימְנָא חָדָא הֲוָה אָזֵיל ר\"י בְּאוֹרְחָא, פָּגַע בֵּיהּ ר' יִרְמְיָה, וְאָזְלוּ כַּחֲדָא. פָּגְעוּ בְּהַהוּא טוּרָא, וַהֲוָה טוּרָא דָּחִיל עֲלֵיהֶן. אָמַר רִבִּי יוֹסֵי לְרַבִּי יִרְמְיָה, נֵימָא מִילֵי דְאוֹרַיְיתָא, וְנֵיזֵיל.</p>"],[9514011600,"<p>אָמַר רִבִּי חִיָּיא, בְּוַדַּאי דְּאָמְרֵי חַכִּימֵי מַתְנִיתָּא, שִׁמְּשָׁא דְּהֲוָה לְיַעֲקֹב, עַד כַּמָּה לֶהֱוֵי דָא. אָמַר רִבִּי יוֹסֵי, אֵימָא לָךְ מִלָּה דְּהֲוָה אֲמַר אַבָּא, דְּהַהוּא שִׁמְשָׁא וּנְהוֹרָא סַגִּיאָה דְּהֲוָה לְיַעֲקֹב, גָנִיז הוּא לַצַּדִּיקִים לֶעָתִיד לָבֹא. וְלָא דָא הוּא שִׁמְשָׁא דְּמִשְׁתַּמְּשִׁין בָּהּ בְּנוֹהִי דְּעֵשָׂו, וְאִתְגַּזַּר דְּיִשְׁתַּעְבְּדוּן בְנוֹהִּי דְּיַעֲקֹב תְּחוֹתוֹהִי.</p>"],[9514011601,"<p>בֵּיהּ שַׁעֲתָא, הֲוָה עָצִיב יַעֲקֹב, אֲמַר מָארֵי עָלְמָא, הָא נְהִירוּתָא דִילִי אִתְיְיהֵיבְתָּא לְעֵשָׂו. יָצְאָה ב\"ק וְאָמְרָה וְאַתָּה אַל תִּירָא עַבְדִי יַעֲקֹב וְגו' וּנְהִירוּתָא דִילָךְ לָךְ אִתְגְּנֵיז וְלִבְנָיךְ. אֲמַר אוֹרֵינָא לִי.</p>"],[9514011602,"<p>בֵּיהּ שַׁעֲתָא אַפֵּיק קוּדְשָׁא בְּרִיךְ הוּא הַהוּא שִׁמְשָׁא דְּחָמֵי לֵיהּ יַעֲקֹב, וְלָא בַר נָשׁ אָחֳרָא. הֲדָא הוּא דִכְתִיב, (בראשית ל״ב:ל״ב) וַיִּזְרַח ל\"וֹ הַשֶּׁמֶשׁ. אוֹתוֹ הַשֶּׁמֶשׁ שֶׁהָיָה גָנוּז. כַּאֲשֶׁר עָבַר אֶת פְּנוּאֵל. אָמַר רַבִּי יוֹסֵי, כְּשֶׁנִּצַּח שָׂרוֹ שֶׁל עֵשָׂו. לוֹ מַשְׁמַע וְלֹא לְאַחֵר.</p>"],[9514011603,"<p>וְאַף עַל גַּב דְּיַעֲקֹב אִתְהַנֵּי לְמֶחְזְיֵיא דְּנָצַח לְרַבְרְבָא דְעֵשָׂו, מַה כְּתִיב בֵּיהּ. (שם) וְהוּא צוֹלֵעַ עַל יְרֵכוֹ. אָמַר רִבִּי אַחָא, נְהוֹרָא נָהֵיר, אֲבָל לִבֵּיהּ הֲוָה חָשׁוּךְ, עַל נָפְקֵי יְרֵכֵיהּ דְּיִשְׁתַּעְבְּדוּן תְּחוֹתוֹהִי דְעֵשָׂו.</p>"],[9514011604,"<p>עַד דַּהֲווֹ אָזְלֵי, שָׁמְעוּ קָל יְנוּקָא בְּטוּרָא, דְּהֲוָה אָזֵיל וּבָכֵי. אָמַר רִבִּי יוֹסֵי, נֵיזֵיל גַּבֵּיהּ דְּהָא לָא מִסְתָּפֵינָא. דְּהָא תְּנַן לְחַד מִתְחֲזֵי וּמַזִּיק, לִתְרֵי מִתְחֲזֵי וְלָא מַזִּיק. אָזְלוּ לְגַבֵּיהּ, וִינוּקָא הֲוָה בָּכֵי.</p>"],[9514011605,"<p>כַד מָטוֹ גַּבֵּיהּ, אָמַר רִבִּי יוֹסֵי, בְּנוֹי דְּמָארֵי עָלְמָא אֲנַן, דְּהַהוּא דְּאִקְרֵי שְׁמֵיהּ חַד עַל תְּרֵי, בְּאַתְוָותָא, תְּלַת רְשִׁימִין, בְּרָזָא דְאַרְבַּע. גְּלִיפִין עַל חַד תְּרֵין, וְאִתְקְרֵי עַל חֵיוָותָא קַדִּישָׁא. מַאי טַעְמָא, אָמַר רִבִּי יוֹסֵי הָכֵי, דְּחַיְישִׁינָן שֶׁמָּא שֵׁד הוּא, וְאִינוּן מִסְתָּפוֹ מִשְׁמֵיהּ דְּמָארֵי עָלְמָא סַגֵּי.</p>"],[9514011606,"<p>הַהוּא יְנוּקָא כַּד שְׁמַע מִלָּה דָא, אֲתֵיב וַאֲמַר, יוֹדָאי אֲנָא, וּבַר בְּרֵיהּ דְּרַבִּי חִיָּיא רַבָּה אֲנָא, וַהֲוָה אֲבוֹי מֵלִיף לִי פְּסוּקֵי דְּשִׁיר הַשִּׁירִים, וּפָרְשָׁתָא דִּבְרֵאשִׁית. וּמִית אֲבוּהִי, וּגְנָבוּ לִי גַּנָבֵי, וּכְעַן אִשְׁתְּזֵיבְנָא מִנְּהוֹן, וְעָרַקְנָא בְּהַאי טוּרָא.</p>"],[9514011607,"<p>בְּכָה רַבִּי יוֹסֵי וַאֲמַר, וַוי דְּבַר בְּרֵיהּ דְּרַבִּי חִיָּיא רַבָּה אָזֵיל כְּדֵין. נְטָלֵיהּ בִּידוֹי וַאֲזָלוּ. אָמַר לֵיהּ רַבִּי יוֹסֵי, אֵימָא בְּרִי מָה הֲוֵית לָעֵי עִם אָבוּךְ. אֲמַר בְּפָרָשַׁת יְהִי מְאוֹרוֹת בִּרְקִיעַ הַשָּׁמָיִם הֲוֵינָא לָעֵי. אָמַר לֵיהּ, מָה הֲוָה אָמַר אֲבוּךְ בְּפָרְשָׁתָא.</p>"],[9514011608,"<p>פְּתַח הַהוּא יְנוּקָא פּוּמֵיהּ וַאֲמַר, (במדבר כ״א:י״ח) בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם בִּמְחוֹקֵק בְּמִשְׁעֲנוֹתָם. תָּאנָא, שָׁלשׁ מַתָּנוֹת טוֹבוֹת נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, עַל יְדֵי שְׁלשָׁה רוֹעִים אַחִים, משֶׁה, אַהֲרֹן, וּמִרְיָם. בִּזְכוּת משֶׁה, הָיָה הַמָּן יוֹרֵד לְיִשְׂרָאֵל. בִּזְכוּת אַהֲרֹן, הָיוּ עֲנַנֵּי כָבוֹד הוֹלְכִים עִם יִשְׂרָאֵל. בִּזְכוּת מִרְיָם, הָיְתָה הַבְּאֵר הוֹלֶכֶת עִמָּהֶם.</p>"],[9514011609,"<p>מֵתָה מִרְיָם, פָּסְקָה הַבְּאֵר. מֵת אַהֲרֹן, נִיטְלוּ עֲנַנֵּי כָבוֹד. הֲדָא הוּא דִכְתִיב. (שם כ) וַיִּרְאוּ כָל הָעֵדָה. אַל תִּקְרֵי וַיִּרְאוּ אֶלָּא וַיִּירָאוּ. מֵתָה מִרְיָם פָּסְקָה הַבְּאֵר, מְנָא לָן. דִּכְתִיב (שם) וַיֵּשֶׁב הָעָם בְּקָדֵשׁ וַתָּמָת שָׁם מִרְיָם. וּכְתִיב בַּתְרֵיהּ וְלֹא הָיָה מַיִם לָעֵדָה. וּבִזְכוּת משֶׁה חָזְרוּ שְׁלָשְׁתָּן. וַהֲוָה אֲמַר אֲבוֹי, תְּלָתֵיהוֹן גְּלִיפִין בִּרְקִיעָא דְּיוֹקְנֵהוֹן, לְאַנְהָרָא זְכוּתְהוֹן עַל יִשְׂרָאֵל. הֲדָא הוּא דִכְתִיב, (בראשית א׳:י״ז) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם לְהָאִיר עַל הָאָרֶץ.</p>"],[9514011610,"<p>וּמְנָא לָן דִּתְלָתֵיהוֹן גְּלִיפִין בִּרְקִיעָא, דְּהָא תְּנַן, בְּכָלְהוֹ כְּתִיב עַל פִּי ה', וּבְמִרְיָם לָא כְתִיב עַל פִּי ה', דְּלָאו אוֹרַח אַרְעָא. אֶלָּא אֲמַר אֲבוֹי, בְּכָלְהוֹ כְּתִיב שָׁם, וַתָּמָת שָׁם מִרְיָם. וַיָּמָת שָׁם אַהֲרֹן. וַיָּמָת שָׁם משֶׁה. כְּתִיב הָכָא שָׁם, וּכְתִיב הָתָם שָׁם. (שמות ל״ד:כ״ח) וַיְהִי שָׁם עִם ה', מַה לְּהַלָּן עִם ה', אַף כָּאן עִם ה'.</p>"],[9514011611,"<p>דִּתְנַן, לָמָּה מֵת משֶׁה בְּחוּצָה לָאָרֶץ, לְהוֹרוֹת, דְּבִזְכוּתֵיהּ יִתְקַיְימוּן מֵתֵי מִדְבָּר. וַאֲמַר אֲבוֹי, אָמַר משֶׁה לִפְנֵי הַקָדוֹשׁ בָּרוּךְ הוּא, רִבּוֹנוֹ שֶׁל עוֹלָם אֶכָּנֵס לָאָרֶץ לְקָיְימָא פִּקּוּדֶיךָ, דְּהָא כְתִיב (ויקרא כ״ג:י׳) כִּי תָבֹאוּ אֶל הָאָרֶץ. (שמות י״ב:כ״ה) וְהָיָה כִי תָבוֹאוּ אֶל הָאָרֶץ. וְתַמָּן הוּא קִיּוּמָא דְּפִיקּוּדֶיךָ.</p>"],[9514011612,"<p>אָמַר לֵיהּ מַה דְּאַזְהָרַת שְׁלִים לָךְ וּמַה דְּיַעַבְדוּן יִשְׂרָאֵל בְּאַרְעָא קַדִּישָׁא יְהִי חוּלָקָךְ עִמְּהוֹן. הֲדָא הוּא דִכְתִיב (ישעיהו נ״ג:י״ב) לָכֵן אֲחַלֵּק לוֹ בָּרַבִּים, אֵלּוּ זַכָּאִין דְּיִשְׂרָאֵל. וְאֶת עֲצוּמִים יְחַלֵּק שָׁלָל, אִלֵּין אֲבָהָתָא, וְלָמָּה, תַּחַת אֲשֶׁר הֶעֱרָה לָמוּת נַפְשׁוֹ.</p>"],[9514011613,"<p>דְּאָמַר רִבִּי חִיָּיא סָבָא, לָא אַשְׁכַּחְנָא רַעֲיָא דִּמְסַר נַפְשֵׁיהּ עַל עָאנֵיהּ, כְּמשֶׁה, דַּאֲמַר (שמות ל״ב:ל״ב) וְעַתָּה אִם תִּשָּׂא חַטָאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ אֲשֶׁר כָּתָבְתָּ. מַאי מְחֵנִי נָא, מִן עָלְמָא דֵין וּמִן עָלְמָא דְאָתֵי. לְקָיְימָא תַּחַת אֲשֶׁר הֶעֱרָה לָמוּת נַפְשׁוֹ.</p>"],[9514011614,"<p>וְאֶת פּוֹשְׁעִים נִמְנָה, שֶׁנִּקְבַּר עִם מֵתֵי מִדְבָּר, דַּהֲווֹ חַיָּיבִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְהוּא חֵטְא רַבִּים נָשָּׂא, שֶׁלֹּא זָז מִשָּׁם עַד שֶׁמָּחַל לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלַפּוֹשְׁעִים יַפְגִּיעַ, שֶׁהִרְבָּה תְּפִלָּתוֹ עֲלֵיהֶם.</p>"],[9514011615,"<p>וְעַל כְּדֵין, תְּלָתֵיהוֹן גְּלִיפִין לְעֵילָא. אָתָא ר' יוֹסֵי וּנְשָׁקֵיהּ, וְאַרְכְּבֵיהּ עַל כִּתְפֵיהּ תְּלַת מִילִּין, וּקְרָא עֲלֵיהּ (ישעיהו נ״ד:י״ג) וְכָל בָּנַיִךְ לִמּוּדֵי ה'.</p>"],[9514011616,"<p>תָּאנֵי רַבִּי שִׁמְעוֹן, בֹּא וּרְאֵה, הַשֶּׁמֶשׁ לֹא עֲשָׂאוֹ הַקָדוֹשׁ בָּרוּךְ הוּא אֶלָּא לְשִׁמּוּשׁ בְּנֵי אָדָם. תָּא חֲזֵי, בִּתְלַת מְאָה וְתִשְׁעִין אַתְרֵי דְּיִשּׁוּבָא דְּאַרְעָא, אָזֵיל שִׁמְשָׁא, וְסָלֵיק וְנָחֵית, וּמַדְרְגוֹת וּמַעֲלוֹת יְדוּעוֹת יֵשׁ לוֹ. וְהַיְינוּ דִכְתִיב, (ישעיהו ל״ח:ח׳) הִנְּנִי מֵשִׁיב אֶת צֵל הַמַּעֲלוֹת אֲשֶׁר יָרְדָה בְּמַעֲלוֹת אָחָז.</p>"],[9514011617,"<p>אָמַר רִבִּי יוֹסֵי, הֵיךְ הִיא סָלֵיק. אָמַר רִבִּי, כְּבָר תָּנִינָא מִמָּארֵיהוֹן דִּמְתִיבְתָּא. דְּעָלְמָא סְגַלְגַּל הוּא כְּכַדּוּרָא דָא. וְכַד נָפֵיק מִמִּזְרָח, אָזֵיל בִּסְגַלְגְּלוּתָא, עַד דְּמָטָא לְתַתָּא, וּכְדֵין אִתְעֲבֵיד רַמְשָׁא. וּבְהַהוּא שַׁעֲתָא אָזֵיל וְנָחֵית בְּגַלְגַּלִּין דְּמַדְרֵיגָן יְדִיעָן, וְנָחֵית וְסָבֵב כָּל אַרְעָא וְיִשּׁוּבָא.</p>"],[9514011618,"<p>וְכַד נָחֵית וּמִתְכַּסְיָא מִינָן, רָמַשׁ לָן, וְנָהֵיר לְאִינוּן דְּדָיְירִין תְּחוֹת לָן. לְפוּם יִישׁוּבָא וּסְגַלְגַּלְתָּא דְאַרְעָא.</p>"],[9514011619,"<p>וּכְדֵין אָזֵיל וְנָחֵית, וּמַפְרִישׁ בֵּין מַיָא דִתְחוֹתוֹהִי דְּמַיָא דְּאוֹקְיָינוּס, וּבֵין מַיָא דְּאָזְלִין לְעֵילָא, וּמַפְרִישׁ בִּמְצִיעָתָא דְמַיָא, לְעַכָּבָא סִילוֹנָא דְמַיָא דְּנָפֵיק מִגֵּיהִנֹּם, דְּלָא יַעֲבֹר לְנַזְקָא בְּנֵי נָשָׁא. וְעַל דָּא לָא תִקְרֵי שִׁמְשָׁא, אֶלָּא לְשַׁמָּשָׁא לִבְנֵי נָשָׁא. דְּעַל כָּךְ מִתְקְרֵי שִׁמְשָׁא, שִׁמְשָׁא דִּמְשַׁמֵּשׁ לְכוֹלָא. אָמַר רִבִּי אֶלְעָזָר, אִלְמָלֵא דְּסָחֵי שִׁמְשָׁא בְּיַמָּא דְּאוֹקְיָינוּס, הֲוָה שָׂרֵיף וְאוֹקֵיד לְכוּלֵי עָלְמָא.</p>"],[9514011620,"<p>סָלֵיק מִתְּחוֹת אַרְעָא. וּמַגִּיעַ לְהַהוּא דַרְגָּא דְּאִתְקְרֵי קַרְבוּסָא, בִּלְשׁוֹן יָוָן. וּמֵהַהוּא דַרְגָּא שָׁרֵי לְמֵיסַק לְעֵילָא, וְקַל גַּלְגְּלוֹהִי אִשְׁתְּמַע לְכוּלְהוּ רְקִיעֲיָא בְּמַטְלָנוֹהִי, לְמֵיזַל עִם שִׁירָתֵיהּ דְּהוּא אֲמַר. וְלָא הֲוָה בַּר נָשׁ דִּשְׁמַע לֵיהּ, בַּר מִמּשֶׁה, דְּהֲוָה מְהֵימָן מַלְכָּא, וִיהוֹשֻׁעַ דִּמְשַׁמֵּשׁ לֵיהּ.</p>"],[9514011621,"<p>וְכַד אִיצְטְרִיךְ לֵיהּ יְהוֹשֻׁעַ, לַאֲגָחָא קְרָבָא, וַהֲוָה שְׁמַע קָל נְעִימוּתָא, וּנְהִימוּתָא דְּשִׁמְשָׁא, לָא יָכֵיל לֵיהּ לְמִיסְבַּל. מַה כְּתִיב. (יהושע י׳:י״ב) וַיֹּאמֶר לְעֵינֵי יִשְׂרָאֵל שֶׁמֶשׁ בְּגִבְעוֹן דּוֹם. מַאי דּוֹם. דּוֹם, מִלּוֹמַר שִׁירָה. דּוֹם, מִקָּל נְעִימוּתָא וּנְהִימוּתָא דִּילָךְ, דְּהָא הֲוָה שְׁמַע קוֹל מַטְלָנוֹהִי בְּמַטְלָנוּתֵיהּ.</p>"],[9514011622,"<p>אֲמַר רַבִּי בָּא, שִׁית מְאָה וְאַרְבְּעִין מַטְלָנִין עָבִיד שִׁמְשָׁא. בְּחוּשְׁבַּן שֶׁמֶשׁ. בֵּין יְמָמָא וְלֵילְיָא. וְאַסְחַר לְכוֹלָּא עָלְמָא בְּסַחְרָנוּתָא. וּלְמַאי אִצְטְרִיךְ. לְרַכְּכָא וּלְחַמְּמָא אַרְעָא, וּלְדַשְׁנָא עִשְׂבִין וִיבוּלִין, וּלְאַצְמָחָא פֵּירִין וְאִילָנִין.</p>"],[9514011623,"<p>אָמַר רִבִּי יְהוּדָה, תָּא חֲזֵי, כְּהַהוּא גַּוְונָא דִלְעֵילָא, עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא. מַה לְעֵילָא הֲווֹ שְׁמַיָא, אוּף לְתַתָּא הֲווֹ שְׁמַיָא. וְלָמָה אִתְקְרוּ שָׁמַיִם, אָמַר רִבִּי יְהוּדָה. אֵשׁ וּמַיִם.</p>"],[9514011624,"<p>אָמַר רִבִּי יִצְחָק, מֵהָכָא, (איוב כ״ה:ב׳) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. בְּמַלְאָכָיו לָא כְתִיב, אֶלָּא בִּמְרוֹמָיו. עַל דְּאִינוּן אֵשׁ וּמַיִם, וְעוֹשֶׂה שָׁלוֹם בֵּינֵיהֶם. כְּהַאי גַוְונָא לְתַתָּא, אֵשׁ וּמַיִם.</p>"],[9514011625,"<p>וְחוֹזֵר הָרָקִיעַ מִתַּחַת, וּמְחַמֵּם הָאֲדָמָה מֵחֲמִמִיּוּת הָאֵשׁ, וְהַשֶּׁמֶשׁ, וּמוֹרִיד הַקָּדוֹשׁ בָּרוּךְ הוּא הַמַּיִם עַל הָאָרֶץ וּמְקָרֵר הָאֲדָמָה, וְסִיֵּיעַ לַחֲמִימוּתָא דְמִתַּתָּא. וְהַאי וְהַאי, מוֹלִידִין וּמַצְמִיחִין לְאַרְעָא. וְכָלְהוֹ בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְתוֹעַלְתָּא דִּבְנֵי נָשָׁא.</p>"],[9514011626,"<p>רַבִּי אַבָּהוּ, וְר' חִיָּיא, וְר' נָתָן, הֲווֹ אָזְלֵי בְּאוֹרְחָא, אָמַר רִבִּי נָתָן, לֹא תְּהִיתוּן עַל אִלֵּין מָארֵיהוֹן דְּמַתְנִיתָּא, דִּגְזֵירַת פּוּמְהוֹן כִּגְזֵרַת מַלְאָכִין קַדִּישִׁין. וַאֲנָא דָּכִירְנָא מַה דַּאֲמָרוּ, דְּהָא שִׁמְשָׁא אִתְאֲצַל נְהִירוּתֵיהּ מִזִּיוָא דְאַסְפַּקְלַרְיָא דִלְעֵילָא, וְהַאי נְהִירוּתָא לָאו דִּילֵיהּ הוּא. מַשְׁמַע דִּכְתִיב (בראשית א׳:י״ד) יְהִי מְאוֹרוֹת הֲוָה לֵיהּ לְמֵימַר יְהִי אוֹרוֹת, מַאי מְאוֹרוֹת. אָמַר רִבִּי זֵירָא, מִן אוֹרוֹת. מ' תּוֹסֶפֶת, לְשַׁמָּשָׁא. כְּלוֹמַר, מִן אוֹרוֹת, וְתֵיבוּתָא הוּא אוֹרוֹת.</p>"],[9514011627,"<p>אָמַר רִבִּי חִיָּיא, אַל תִּתְמַהּ עָלָיו, דְּהָא תּוֹרָה אִתְאֲצַל מֵחָכְמְתָא דִלְעֵילָא, וּשְׁמַיָא אִתְאַצְלֵי מֵהַהוּא רְקִיעָא עִילָּאָה דְּעַל רֵישׁ חֵיוָתָא, וּכְהַאי גַוְונָא, כַּד תִּסְתַּכֵּל, כָּל מַה דִּלְעֵילָא וְתַתָּא, אִתְאֲצָלוּ דָּא מִן דָּא, וְדָא מִן דָּא, וְקוּדְשָׁא בְּרִיךְ הוּא עַל כֹּלָּא. וּמִן כּוּרְסֵי יְקָרֵיהּ שָׁרְיָיאן לְאִתְאֲצֵל דָּא מִן דָּא, וְכוּרְסֵי יְקָרָא מִנֵּיהּ, וְכָלְהוֹ כְּלָא חֲשִׁיבִין לְקִבְלֵיהּ. הֲדָא הוּא דִכְתִיב, (דניאל ד׳:ל״ב) וְכָל דָּיְירֵי אַרְעָא כְּלָא חֲשִׁיבִין. אָמַר רִבִּי אַבָּהוּ, לָא תִקְשֵׁי לָךְ הַאי, דְּהָא רֵישָׁא מִינָן בְּהֶבְדֵּל, שָׁרֵי בְּקַדְמִיתָא לְמִילְעָא בְּאוֹרַיְיתָא לְתוּרְגְּמָנָא, וְתוּרְגְּמָנָא לְדִסְמִיכֵי לֵיהּ, וְדִסְמִיכֵי לֵיהּ, לְדִסְמִיכֵי לֵיהּ. אִשְׁתְּכַח, דְּכַד מִסְתַּיֵים שְׁמַעְתָּא, דְּכָלְהוֹ תַּלְיָין מִן רֵישָׁא. וּכְהַאי גַוְונָא תִּשְׁכַּח לְעֵילָא, וּלְכָלְהוֹ עָלְמִין.</p>"],[9514011628,"<p>וְאָמַר רִבִּי אַבָּהוּ, משֶׁה, אִתְאֲצַל מִזִּיוָא עִילָּאָה. יְהוֹשֻׁעַ, אִיתְאֲצַל מִמּשֶׁה. זְקֵנִים, אִתְאֲצָלוּ מִיהוֹשֻׁעַ. נְבִיאִים, אִתְאֲצָלוּ מִזְּקֵנִים. נְשִׂיאִים וְרֵישָׁא דְעַמָּא, אִתְאֲצָלוּ מִנְבִיאִים. וְכָלְהוֹ דָּא מִן דָּא.</p>"],[9514011629,"<p>עַד דַהֲווֹ אָזְלֵי, פָּגְעוּ בֵּיהּ בְּר' אֶלְעָזָר, אֲמָרוּ הָא חַד מֵאִינוּן מָארֵי דִמְתִיבְתָּא אָתָא. אֲמָרוּ לֵיהּ, וַדַּאי דְּאַמְרִיתוּ דְּשִׁמְשָׁא אִתְאֲצַל נְהִירוּתֵיהּ מִזִּיוָא דְאַסְפַּקְלַרְיָא דִלְעֵילָא. אֲמַר, כָּךְ הוּא.</p>"],[9514011630,"<p>פְּתַח וַאֲמַר, (שיר השירים ד׳:ט״ו) מַעֲיַן גַּנִּים בְּאֵר מַיִם חַיִּים וְנוֹזְלִים מִן לְבָנוֹן. קוֹרְאָהּ מַעְיָן, וְאַחַר כַּךְ בְּאֵר, וְאַחַר כַּךְ נוֹזְלִים. בַּהֲדָא פְּסוּקָא אִית לְאִסְתַּכָּלָא, דְּהַאי מַעְיָן אִתְמְשֵׁיךְ מִן בֵּירָא. וּבֵירָא מִן נוֹזְלִים. וְנוֹזְלִים מִן לְבָנוֹן. לְמִינְדַע, דְּכָלְהוֹ אִתְאֲצָלוּ דָּא מִן דָּא וְדָא מִן דָּא. כָּךְ הוּא שִׁמְשָׁא, לָאו נְהִירוּתָא דִילֵיהּ הוּא, אֶלָּא אִתְמְשַׁךְ חַד חוּטָא דְזִיוָא דְּנָהֵיר לְשִׁמְשָׁא.</p>"],[9514011631,"<p>תְּנַן בְּמַתְנִיתִין דִּילָן, אוֹר שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתְּחִילָּה, אָדָם הָיָה רוֹאֶה בּוֹ וְצוֹפֶה מֵרֹאשׁ הָעוֹלָם וְעַד סוֹפוֹ. תָּא חֲזֵי, נְהִירוּתָא דְּשִׁמְשָׁא, הוּא חַד מִשִּׁתִּין אַלְפִין וְשִׁבְעִין וְחָמֵשׁ חוּלָקִין, מֵהַהוּא נְהִירוּתָא דְּאַסְפַּקְלַרְיָא דְּהַהוּא נְהוֹרָא דְּאִתְגְּנֵיז. וַאֲפִילּוּ בְּהַאי נְהִירוּתָא דְּשִׁמְשָׁא, לֵית אִינִישׁ יָכֵיל לְאִסְתַּכָּלָא בֵּיהּ, כָּל שֶׁכֵּן בְּהַהִיא נְהוֹרָא.</p>"],[9514011632,"<p>וְהָא אֲמָרָן, דְּאִינִישׁ יִסְתַּכֵּל בֵּיהּ מֵרֵישֵׁיהּ דְּעָלְמָא וְעַד סְיָיפֵי עָלְמָא. אֶלָּא הָכֵי גַּזַּרְנָא בְּמַתְנִיתָּא דִילָן, דִּבְהַהוּא נְהִירוּתָא, יָכֵיל אֵינַשׁ לְמִנְדַע וּלְמֶחֱזֵי בִּנְהִירוּ דְּחָכְמָתָא, כָּל מַה דְּהֲוָה, וְכָל מַה דְּיֶהֱוֵי, מֵרֵישֵׁיהּ דְּעָלְמָא עַד סְיָיפֵי עָלְמָא, וְהַהוּא אִתְגְּנֵיז לַצַּדִּיקִים לְעָלְמָא דְאָתֵי. מַאי לְעָלְמָא דְאָתֵי, כַּד תֵּיפוֹק נִשְׁמָתָא קַדִּישָׁא מֵהַאי עָלְמָא, וְיֵזֵיל בֵּיהּ לְעָלְמָא דְאָתֵי.</p>"],[9514011633,"<p>תָּא חֲזֵי, כְּתִיב (שמות ל״ד:כ״ח) וַיְהִי שָׁם עִם ה' אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה לֶחֶם לֹא אָכַל וּמַיִם לֹא שָׁתָה. מַאי טַעֲמָא, מִשּׁוּם דְאִתְהַנֵּי מֵהַהוּא זִיוָא. וְאַף עַל גַּב דְּנָחֵית מִתַּמָּן, וְהַהוּא נְהִירוּתָא לָא נָחֵית עִמֵּיהּ, לָא הֲווֹ יָכְלִין לְאִסְתַּכָּלָא בְּאַנְפּוֹי דְמשֶׁה, מִמַּה דְּאִסְתַּכַּל בְּקַדְמִיתָא, כַּד הֲוָה תַּמָּן, וְאִשְׁתָּאֲרוּ אַנְפּוֹהִי נְהִירִין כְּהַאי שִׁמְשָׁא.</p>"],[9514011634,"<p>סָטֵי רַבִּי אֶלְעָזָר לְאוֹרְחֵיהּ, וְאִינוּן אָזְלוּ אֲבַתְרֵיהּ, לְאוֹזְפֵיהּ לְאוֹרְחֵיהּ, תְּלַת מִילִּין. אֲמָרוּ לְרַבִּי אֶלְעָזָר, זַכָּאִין אַתּוּן מָארֵי מַתְנִיתָּא, דְּבָתַר גַּבּוֹי דְּמשֶׁה הֲוֵיתוּן, כַּד אִתְיְיהֵב אוֹרַיְיתָא עַל יְדֵיהּ. אֲזָלוּ רַבִּי חִיָּיא וְרַבִּי נָתָן, וְרַבִּי אַבָּהוּ לָא בָּעָא לְאִתְפְּרָשָׁא מִנֵּיהּ, וַאֲזַל עִמֵּיהּ לְאוֹרְחֵיהּ.</p>"],[9514011635,"<p>פְּתַח רַבִּי אֶלְעָזָר פּוּמֵיהּ וַאֲמַר, (בראשית א׳:י״ד) וַיֹּאמֶר אֱלֹהִים יְהִי מְאוֹרוֹת. תָּא חֲזֵי, עָבַד קוּדְשָׁא בְּרִיךְ הוּא תְּמַנֵּיסַר רְקִיעִין, דְּנָטְלִין לְמַטְלָנִיהוֹן, וְסָחֲרִין כָּל עָלְמָא. וְכָל חַד מִתְעַכֵּב הַהוּא שִׁיעוּרָא דְּאִתְיְיהֵיב לֵיהּ מִן מָארֵיהּ. וְכַד אַשְׁלֵים הַהוּא רְקִיעָא הַהוּא שִׁיעוּרָא, אִתְחַדֵּשׁ בְּעָלְמָא פִּתְגָּמִין טָבִין רַבְרְבִין סַגִּיאִין.</p>"],[9514011636,"<p>וְחָשְׁבִין בְּדַעְתַּיְיהוּ אִינוּן טִפְּשָׁאֵי דְלִבָּא, דִּבְסַחְרָנוּתָא דְּהַהוּא רְקִיעָא אִתְעֲבֵיד דָּא. וְלָא כָךְ הוּא. דְּהָא כָּל יוֹמָא וְיוֹמָא, מְחַדֵּשׁ קוּדְשָׁא בְּרִיךְ הוּא מִצַּפְרָא עַד רַמְשָׁא, פִּתְגָּמִין עִילָּאִין רַבְרְבִין וְתַקִּיפִין, וְזִמְנִין דְּאַשְׁלֵים הַהוּא רְקִיעָא מַטְלָנוֹהִי, וְיֶעְרַע בְּעָלְמָא גְּזֵירַת מַלְכָּא עִילָּאָה, וְחַשְׁבִין טִפְּשֵׁי לִבָּא, דִּבְגִינֵיהּ דְּהַהוּא רְקִיעָא הֲוָה, וְטָעֲיָין לִבְּהוֹן בְּטִפְּשׁוּתָא.</p>"],[9514011637,"<p>וְעָבַה קוּדְשָׁא בְּרִיךְ הוּא לְהַהוּא רְקִיעָא רְבִיעָאָה, וַאֲנַח בֵּיהּ שִׁמְשָׁא, וְאַסְחַר כָּל עָלְמָא בְּעִידָנִין וְזִמְנִין לְתוֹעַלְתָּא דְעָלְמָא לִבְנֵי נָשָׁא. וְתָנָא בְּמַתְנִיתָּא דִידָן, תְּלַת מְאָה וְאַרְבְּעִין מַשְׁקוֹפִין, אָזֵיל שִׁמְשָׁא, סָלֵיק וְנָחֵית בְּעִידָנִין וְזִמְנִין.</p>"],[9514011638,"<p>וְאָזֵיל וְשָׁרֵי, מִמַּשְׁקוֹפָא דְּמִזְרָח, מֵהַהוּא מַשְׁקוֹפָא דְּאִתְקְרֵי נוֹגַהּ, וְאָזֵיל בִּסְגַלְגְּלוּתָא, עַד דְּמָטָא לְמַשְׁקוֹפָא דְּאִתְקְרֵי קַרְבּוּסָא. כְּדֵין אָזֵיל לִסְיָיפֵי דְּצָפוֹן, שִׁיתָּא יַרְחֵי, עַד דְּמָטָא לְמַשְׁקוֹפָא דְּזָהֲרָא, וְאָזֵיל שִׁיתָּא יַרְחֵי, לְאַשְׁלָמָא שַׁתָּא לְתוֹעַלְתָּא דִּבְרִיָּיתָא, לְמֶעְבַּד זְרוֹעָא וַחֲצָדָא.</p>"],[9514011639,"<p>הֲדָא הוּא דִכְתִיב, (בראשית ח׳:כ״ב) עוֹד כָּל יְמֵי הָאָרֶץ זֶרַע וְקָצִיר וְקוֹר וָחוֹם וְקַיִץ וָחוֹרֶף. וּבְאַשְׁלָמוּתֵיהּ לְצַד דָּרוֹם, לְפוּם יִשּׁוּבָא דְאַרְעָא, קָצִיר. וְחוֹם. וְקַיִץ. וּבְאַשְׁלָמוּתֵיהּ לִסְיָיפֵי צָפוֹן זֶרַע. קוֹר. וָחוֹרֶף. וְכֹלָּא לְפוּם יִישּׁוּבָא דְאַרְעָא, כִּדְקָאֲמָרָן. וּבְהַאי גַוְונָא מַמָּשׁ, כְּמָא דְמִשְׁתַּמְּשִׁין בְּנֵי נָשָׁא לְהַאי נְהוֹרָא דְּהַאי רְקִיעָא, כְּדֵין כָּל חֵילֵי שְׁמַיָא מִשְׁתַּמְּשִׁין לִנְהוֹרָא דִרְקִיעָא, דְּעַל רֵישׁ חֵיוָתָא.</p>"],[9514011640,"<p>אָמַר רִבִּי אַבָּהוּ, מְאֹרֹת, לָמָּה חָסֵר ו\"ו. אָמַר לֵיהּ, עַל מַה דַּאֲמָרָן בְּקַדְמִיתָא, דְּלָאו נְהִירוּתֵיה שְׁלִים. דְּלֵית נְהִירוּתֵיהּ בַּר מַה דִּמְקַבֵּל כְּחַד חוּטָא בָּתַר כּוֹתְלָא, מֵהַהוּא נְהִירוּתָא דִלְעֵילָא.</p>"],[9514011641,"<p>וּבְגִינֵיהּ לָא אִתְקְרֵי נְהִירוּתָא שְׁלֵימָתָא, וְלָא יָאוֹת לְאִתְקְרֵי שְׁלֵימָתָא, אֶלָּא הַהוּא נְהוֹרָא דְּאִתְקְרֵי (דניאל ב׳:כ״ב) וּנְהוֹרָא עִמֵּיהּ שְׁרֵא. וְהַהוּא דְּאִתְגְּנֵיז לַצַּדִּיקִים, הוּא חַד מִס' אַלְפִין וְשִׁבְעִין וְחָמֵשׁ חוּלָקִין, מִנְהִירוּתָא דְּשָׁרֵי עִם קוּדְשָׁא בְּרִיךְ הוּא. וּנְהִירוּתָא דְּשִׁמְשָׁא הוּא חַד מִשִּׁתִּין אַלְפִין וְשִׁבְעִין וְחָמֵשׁ חוּלָקִין, מִנְּהִירוּתָא דְּגָנֵיז לְצַדִּיקַיָא לְעָלְמָא דְאָתֵי. וְעַל כְּדֵין לָא אִתְקְרֵי נְהִירוּתָא שְׁלֵימָתָא הַאי נְהִירוּתָא דְּשִׁמְשָׁא, וְלָא יָאוֹת לְאִתְקְרֵי.</p>"],[9514011642,"<p>וּלְפִיכָךָ אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, לָא תִקְשֵׁי לְכוֹ, דִּכְתִיב מְאֹרֹת, וְלָא שְׁלִים. דַּאֲנָא לָא עֲבָדִית לֵיהּ, אֶלָּא לְמַה דִּכְתִיב, (בראשית א׳:ט״ו) לְהָאִיר עַל הָאָרֶץ. לְשַׁמָּשָׁא לִבְנֵי אַרְעָא, וְדַי לְכוֹ לִבְנֵי אַרְעָא, לְבוּצִינָא דָא לְשַׁמָּשָׁא לְכוֹ.</p>"],[9514011643,"<p>אָמַר רִבִּי אֶלְעָזָר, וּמַה נְּהוֹרָא זְעֵירָא דָא, לָא יָכְלִין בְּנֵי נָשָׁא לְאִסְתַּכָּלָא בֵּיהּ, נְהוֹרֵיתָא דְּגָנֵיז לְצַדִּיקַיָּא עַל אַחַת כַּמָּה וְכַמָּה. אָמַר רִבִּי אַבָּהוּ, וְכָל שֶׁכֵּן נְהִירוּתָא דְּבוּצִינָא דְּשָׁרֵי קַמֵּי מַלְכָּא עִילָּאָה.</p>"],[9514011644,"<p>אָתָא לְנַשְׁקָא יְדֵיהּ דְּרַבִּי אֶלְעָזָר, אֲמַר כְּעַן יְדַעְנָא, דִּי בְקוּשְׁטָא הַאי מְאֹרֹת חָסֵר, וְיָאוֹת לוֹ לְמֶהֱוֵי חָסֵר יַתִּיר מֵהַאי. אֲמַר וַוי לְעָלְמָא כַּד תֵּפּוֹק מִנֵּיהּ, דְּעַד יוֹמָא דָא שָׁאֵילְנָא דָּא, וְלָא אַשְׁכַּחְנָא עִיקָּרָא דְמִילְּתָא, בַּר כְּעָן. הַהוּא אוֹרְחָא דְּנָפְקַת בֵּיהּ, יְהֵא סִימָנָא דִבְרָכָה לִי, עַל דְּעָרְעֵית לָךְ.</p>"],[9514011645,"<p>יָתֵיב עִמֵּיהּ תְּלָתִין יוֹמִין, וְאוֹלֵיף כָּל סְפֵקָא וְקוּשְׁיָא דְּהֲוָה לֵיהּ, וְאוֹלֵיף לֵיהּ שִׁתִּין טַעֲמֵי בְּפָרְשָׁתָא דִּבְרֵאשִׁית. אֲזַל לְאוֹרְחֵיהּ.</p>"],[9514011646,"<p>אַשְׁכַח לְרַבִּי חִיָּיא, אֲמַר לֵיהּ בְּמָטוֹ מִינָךְ רַבִּי אַבָּהוּ, דְּאֶטְעוֹם מֵהַהוּא מְתִיקָא דְּדוּבְשָׁא, דְּאַמְצֵית מִגְּזֵירַת קַדִּישִׁין עִילָּאִין. אָמַר לֵיהּ, חֲרָרָתָא דַּאֲפֵיקוּתָא, וְסוּבְתָא דְּדוּבְשָׁא, לָא מִתְיַישְׁבֵי כַּחֲדָא. וְאַף עַל פִּי כֵּן אוֹלֵיף לֵיהּ.</p>"],[9514011647,"<p>בָּכָה ר' חִיָּיא וַאֲמַר, נַדִּירְנָא עָלַי, דְעַד דְּאוֹלֵיף קַמֵּי מָארֵיהוֹן דְּמַתְנִיתָּא עִילָּאָה, לָא אֵיתֵיב הָכָא. יָתֵיב תַּמָּן תְּרֵיסַר שְׁנִין, כַּד אָתָא קָארוֹ לֵיהּ ר' חִיָּיא רַבָּה. אָמַר רִבִּי יִצְחָק, אוֹר גָּנוּז לְצַדִּיקַיָא לֶעָתִיד לָבֹא, הַהוּא דְּהוּא גָּנוּז. הֲדָא הוּא דִכְתִיב, (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִּיק וּלְיִשְׁרֵי לֵב שִׂמְחָה.</p>"],[9514011648,"<p>וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת. ר' פִּנְחָס פְּתַח בְּהַאי קְרָא (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְרָה לוֹ אִמּוֹ. אָמַר רִבִּי פִּנְחָס, חָזַרְנוּ עַל הַתּוֹרָה כּוֹלָּא, וְלָא אַשְׁכְּחָן עֲטָרָה דְּעָבְדַת בַּת שֶׁבַע לִשְׁלֹמֹה. כְּעָן אִית לְמֵימַר, הַאי דְּאָמַר רִבִּי יִצְחָק מַאי צְאֶינָה וּרְאֶינָה, הֲוָה לֵיהּ לְמִיכְתַּב בֹּאוּ וּרְאוּ. מַאי צְאֶינָה.</p>"],[9514011649,"<p>אֶלָּא אָמַר רִבִּי יִצְחָק, פְּסוּקָא דָא, דְּאִתְקְרֵי עַל אִינוּן זַכָּאִין דִּנְפָקוּ מִן עָלְמָא דֵין, וְאִתְקְּבָרוּ בְּאַרְעָא קַדִּישָׁא דְיִשְׂרָאֵל. אָמַר רִבִּי אֶלְעָזָר, וְדִנְפָקַת נִשְׁמַתְהוֹן תַּמָּן. וַעֲתִידָה בַּת קוֹל לְאִתְעָרָא בְּכָל צִיּוּנָא וְצִיּוּנָא דְּבָתֵּי קִבְרֵי, וְאָמְרָה צְאֶינָה וּרְאֶינָה, פּוֹקוּ מִתְּחוֹת בְּלֵיאוּתָא דְּעַפְרָא, וְאִיתְעָרוּ מִשְׁנַתְכוֹן. בְּנוֹת צִיּוֹן: כְּמָה דְאַתְּ אָמֵר, (מלכים ב כ״ג:י״ז) מָה הַצִּיּוּן הַלָּז.</p>"],[9514011650,"<p>אָמַר רִבִּי פִּנְחָס, זַכָּאִין אַתּוּן צַדִּיקַיָא לְמֶחֱמֵי בְּזִיוָוא יַקִּירָא עִלָּאָה דְּמַלְכָּא קַדִּישָׁא, דִּשְׁלָמָא כּוֹלָּא דִּילֵיהּ. וּבְאֵיזֶה זְכוּתָא, בִּשְׁבִיל עֲטָרָה שֶׁעִטְרָה לוֹ אִמּוֹ, בְּדִיל הַהוּא כִּתְרָא, דְּאַכְתְּרוּ לֵיהּ צַדִּיקַיָּא בְּמִלֵּי דְאוֹרַיְיתָא בְּעָלְמָא דֵין. אָמַר רִבִּי אַבָּהוּ, אִמּוֹ, כְּמוֹ אוּמוֹ. וְאֵיזֶהוּ אוֹם שֶׁל הַקָדוֹשׁ בָּרוּךְ הוּא. אֵלּוּ צַדִּיקִים שֶׁהֵם אוֹם הַיְדוּעָה לוֹ.</p>"],[9514011651,"<p>בְּיוֹם חֲתוּנָתוֹ, חַתְנוּת דָּא מִמַּאן הוּא. אָמַר רִבִּי פִּנְחָס, מֵהַהוּא אוֹם, חֲתוּנָתוֹ שֶׁל אוֹתוֹ אוֹם שֶׁלּוֹ. מַהוּ חֲתוּנָתוֹ בְּיוֹמָא דְּכַשְׁרָן לְמֶעְבַּד פִּיקּוּדֵי אוֹרַיְיתָא, דְּהוּא חֶדְוָותָא דְּצַדִּיקַיָא. וְאֵימָתַי כַּשְׁרָן. אָמַר רִבִּי יִצְחָק, מִתְּלֵיסַר שְׁנִין וּלְעֵילָא, דְּהַהוּא יוֹמָא חוֹבָתָא עַל צַדִּיקַיָא לְמֵיעְבַּד חֶדְוָותָא דְלִבָּא, כְּיוֹמָא דְסָלֵיק לַחוּפָּה. וּבְגִין הַהוּא זְכוּתָא, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַתְעָרָא לְהוֹ וּלְעַבְרָא כָּרוֹזָא קָדָמֵיהוֹן בְּחֶדְוָה, צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן.</p>"],[9514011652,"<p>אָמַר רִבִּי יִצְחָק, תָּא שְׁמַע, יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם, ר' יִצְחָק אָמַר, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְחַיֶּה אֶת הַמֵּתִים, וְיַעֲבֵר כָּרוֹזָא עַל כָּל צִיּוּנָא וְצִיּוּנָא. בֵּיהּ זִמְנָא נָחֵית הַהִיא נִשְׁמָתָא, כִּנְהוֹרָא וּבוּצִינָא דְּיַנְהַר בִּנְהִירוּ רְקִיעָא דִשְׁמַיָא, עַל הַהוּא גוּפָא דְּאַתְעַר מִן אַרְעָא. הֲדָא הוּא דִכְתִיב, יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם. וְלָמָּה, לְהָאִיר עַל הָאָרֶץ, עַל אוֹתוֹ הַגּוּף הַיּוֹצֵא מִן הָאָרֶץ.</p>"],[9514011653,"<p>ר' אַבָּהוּ אֲמַר, זוֹ הִיא זֹהַר הָרוּחַ, הַשּׁוֹרָה עַל הַגּוּף לְהַחֲיוֹתוֹ, וּלְהָאִיר אֲפֵלוֹ. הֲדָא הוּא דִכְתִיב, (בראשית א׳:י״ד) יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם. וְלָמָּה, לְהָאִיר עַל הָאָרֶץ, עַל הַיּוֹצֵא מִן הָאָרֶץ, כִּדְאֲמָרָן.</p>"],[9514011654,"<p>ר' יְהוּדָה בֶּן פַּזִי פָּגַע בֵּיהּ בְּרַב נַחְמָן, אָמַר לֵיהּ אוֹתוֹ הָרוּחַ שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת בּוֹ הַמֵּתִים, מַהוּ. אָמַר לֵיהּ, הוּא רוּחַ אַסְפַּקְלַרְיָא שֶׁל מַעְלָה, כַּאֲשֶׁר יַשִּׂיגוּ בְּנֵי אָדָם הַדֵּעוֹת הַנְּכוֹנוֹת. וּמְנָא לָן הָא. מִמַּה דִּכְתִיב, (יחזקאל ל״ז:י״ד) וְנָתַתִּי רוּחִי בָּכֶם וִחְיִיתֶם. וְנָתַתִּי רוּחַ בָּכֶם לֹא נֶאֱמַר, אֶלָּא רוּחִי, אוֹתוֹ הַנֶּאֱצָל מֵאַסְפַּקְלַרְיָא שֶׁלּוֹ. וּכְתִיב (שם) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם, וְאַחַר כַּךְ יִהְיֶה סִימָן יָדוּעַ בָּעוֹלָם, הֲדָא הוּא דִכְתִיב, (בראשית א׳:י״ד) וְהָיוּ לְאוֹתוֹת וּלְמוֹעֲדִים וּלְיָמִים וְשָׁנִים.</p>"],[9514011655,"<p>ק (בראשית א׳:כ״ו) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ. ר' אַבָּהוּ פְּתַח, (תהילים ח׳:ה׳-ו׳) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וּבֶן אָדָם כִּי תִפְקְדֶנּוּ וַתְּחַסְּרֵהוּ מְעַט מֵאֱלֹהִים. ר' תַּנְחוּם אָמַר, בְּשָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרוֹא אֶת הָאָדָם, נִתְיָיעֵץ עִם הַמַּלְאָכִים אוֹתָם הַסּוֹבְבִים אֶת כִּסְּאוֹ, וְאָמַר לָהֶם נַעֲשֶׂה אָדָם. אָמְרוּ לוֹ, רִבּוֹנוֹ שֶׁל עוֹלָם מַה טִיבוֹ שֶׁל אָדָם זֶה, מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ.</p>"],[9514011656,"<p>דָּבָר אַחֵר נַעֲשֶׂה אָדָם, ר' בּוּטָא בְּשֵׁם ר' בּוֹ אָמַר, חָזַרְנוּ עַל כָּל הַתּוֹרָה כּוּלָּה, וְלֹא מָצִינוּ שֶׁנִּתְיָיעֵץ הַקָדוֹשׁ בָּרוּךְ הוּא עִם הַמַּלְאָכִים לְעוֹלָם, עַל שׁוּם דָּבָר מִכָּל מַה שֶּׁהוּא צָרִיךְ לַעֲשׂוֹת.</p>"],[9514011657,"<p>וְעוֹד מָצִינוּ שֶׁאֵין לְמַעְלָה וּלְמַטָה שֶׁמַּשִּׂיגִים לְדַעְתּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְשֶׁהֵם רָצִים לְהַשִּׂיג, מִיָּד חוֹזְרִים לְאָחוֹר מֵהַשָּׂגָתָם, כְּהָדֵין קַנְבּוֹסָא דְּקוֹנָארֵי, דְּפָרַח וְחוֹזֵר לְדוּךְ דְשָׁארֵי. כָּךְ הֵם, עַד שֶׁחוֹזְרִים וְאוֹמְרִים בָּרוּךְ כְּבוֹד ה' מִמְקוֹמוֹ.</p>"],[9514011658,"<p>וְעוֹד אָמַר רַבִּי בּוּטָא, מָצִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אוֹר הָרִאשׁוֹן, וּבָרָא מִזֶּה הָאוֹר שְׁאָר הַמְשַׁמְּשִׁים שֶׁלּוֹ. אִם הָאוֹר הָרִאשׁוֹן שֶׁנִּבְרָא בַּתְּחִלָּה, לֹא נִתְיָיעֵץ עִמּוֹ, כְּשֶׁרָצָה לְהוֹצִיא מִמֶּנּוּ שְׁאָר צִבְאוֹתָיו, כָּל שֶׁכֵּן וְכָּל שֶׁכֵּן אָדָם לַהֶבֶל דָּמָה.</p>"],[9514011659,"<p>אָמַר רִבִּי יִצְחָק, הַנַּח לְרַבִּי בּוּטָא דְּעִם מָארֵי מַתְנִיתָּא שַׁוֵּי מְדוֹרֵיהּ. אֲמַר ר' בּוּטָא, אֲנָא לָא זָכֵינָא לְמֶהֱוֵי מְדוֹרָאי עִמְּהוֹן, אֲבָל קוּשְׁיָא הֲוָה דִידְהוֹן.</p>"],[9514011660,"<p>וּפֵירוּקָא שְׁמַעְנָא, דְּאָמַר רִבִּי בּוֹ, כְּהָדֵין מַלְכָּא דְּהֲוָה שַׁלִּיטָא עַל כֹּלָּא, וּבָעֵי לְאַחֲזָאָה גַרְמֵיהּ דְּכָלְהוֹ כְּלִילָן בֵּיהּ, וְהוּא כֹּלָּא. עָבִיד גַּרְמֵיהּ בְּלִישָׁן דְּסַגִּיאִין. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, הוֹאִיל דְּבָעֵי לְאַחֲזָאָה דְּכָל עָלְמָא דִידֵיהּ, כָּלֵיל כּוֹלָּא בִּידֵיהּ, וַאֲמַר לִישָׁן דְּסַגִּיאִין, לְאַחֲזָאָה דְּהוּא כּוֹלָּא. אָמַר רִבִּי יִצְחָק, אִי קָלָא מִן רָמַיָא שְׁמַעְתָּא מֵהַאי, אֵימָא דַהֲוָה שַׁפִּיר, דְּלָא אִתְיַשְּׁבָא בְּלִבָּאי הַאי פֵּירוּקָא.</p>"],[9514011661,"<p>רַבִּי שִׁמְעוֹן בֶּן יוֹחָאי אָתָא לִטְבֶרְיָא לְמִדְכֵּי לְכָל שׁוּקֵי טְבֶרְיָה, חָמוֹ לֵיהּ, ר' פִּנְחָס וְרַבִּי בָּא וְרַבִּי יִצְחָק. אֲמָרוּ, עַד אֵימָתַי נֵיתֵיב בִּקְיָימָא חָדָא, וְלָא נֵיכוֹל לְמֵהַךְ. אֲמָרוּ, הָא מָארֵי דְמַתְנִיתִין הָכָא, נִשְׁאַל קַמֵּיהּ.</p>"],[9514011662,"<p>אָתָא רַבִּי אַבָּהוּ תַּמָּן, אָמַר לֵיהּ, אִי לָא נִשְׁמַע מִלָּה דָא, הָא אִתְפַּתְּחָא פּוּמְהוֹן דְּמִינָאי בִּפְסוּקָא דָא. אָמַר לֵיהּ, לֵימָא לָן מַר עִיקָּרָא דִּפְסוּקָא דָא, אָמַר לֵיהּ מַאי הוּא. אֲמַר לֵיהּ הַאי נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ.</p>"],[9514011663,"<p>אָמַר רִבִּי שִׁמְעוֹן, כְּתִיב (ישעיהו מ״ב:י״ח-י״ט) הַחֵרְשִׁים שְׁמָעוּ וְהַעִוְרִים הַבִּיטוּ לִרְאוֹת. וְכִי לָעִוְרִים וְלַחֵרְשִׁים אָמְרָה תּוֹרָה הַאי. אֶלָּא עִוְרִים, שֶׁהֵם עִוְרִים בַּתּוֹרָה, שֶׁדֶּרֶךְ הַיָּשָׁר לִפְנֵיהֶם, וְהוֹלְכִים אָרְחוֹת עֲקַלְקַלּוֹת כְּעִוְרִים, וְלֹא יָדְעוּן עִיקָּרָא דְמִלְּתָא. הַאי פְּסוּקָא אִתְגְּזַר בְּמַתְנִיתָּא דִילָן, וְהָכֵי גָזַרְנָא.</p>"],[9514011664,"<p>כַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, הֲוָה עִיקָּרָא דְּכֹלָּא מַיָּא, וּמִן מַיָּא אַשְׁתֵּיל כָּל עָלְמָא. וְעָבַד קוּדְשָׁא בְּרִיךְ הוּא תְּלָתָא אוּמָּנִין, דְּיַעַבְדוּן אוּמָּנוּתֵיהּ בְּהַאי עָלְמָא, וְאִלֵּין אִינוּן: שְׁמַיָא, וְאַרְעָא, וּמַיָּא. וְעַל יְדוֹי דְּאִלֵּין, אִתְבְּרֵי כָּל מַה דִּי בְּעָלְמָא דֵין.</p>"],[9514011665,"<p>וְזַמִּין לְאִלֵּין תְּלָתָא, לְכָל חַד מִנְּהוֹן, לְאַפָּקָא בְּרִיָּיתָא דִּצְרִיךְ לְעָלְמָא. זַמִּין לְמַיָּא, אָמַר לֵיהּ אַתְּ אַפֵּיק לְאַרְעָא דִּתְחוֹתָךְ, וְאַתְּ זִיל אִתְכְּנֵישׁ לַאֲתַר חָד, וּמַיָּא עֲבַד כָּךְ, הֲדָא הוּא דִכְתִיב, (בראשית א) יִקָּווּ הַמַּיִם.</p>"],[9514011666,"<p>קְרָא לְאַרְעָא, אֲמַר לָהּ, אַתְּ אַפֵּיק בִּרְיָין מִינָךְ, בְּעִירִין וְחֵיוָתָן וּכְדְּדָמֵי לוֹן, מִיָּד עָבְדַת כָּךְ, הֲדָא הוּא דִכְתִיב (שם) וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ.</p>"],[9514011667,"<p>קְרָא לַשָּׁמַיִם, אֲמַר לוֹן, אַתּוּן אַבְדִּילוּ בֵּין מַיָּא לְמַיָּא, עֲבָדוּ כָּךְ, הֲדָא הוּא דִכְתִיב, (שם) וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ. קְרָא לְאַרְעָא, אֲמַר לָהּ אֲפִיקִי דְּשָׁאִים וְעִשְׂבִּים וִיבוּלִין וְאִילָנֵי חַקְלָא, מִיָּד מַה כְּתִיב בָּהּ. (שם) וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע.</p>"],[9514011668,"<p>קְרָא כְּמוֹ כֵן לַשָּׁמַיִם, אֲמַר לוֹן, יְהֵא בְּכוֹן נְהוֹרִין וּבוּצִינִין לְאַנְהָרָא עַל אַרְעָא, הֲדָא הוּא דִכְתִיב, (שם) יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם. קְרָא כְּמוֹ כֵן לְמַיָא, אֲמַר לוֹן, אַתּוּן אֲפִיקוּ רִיחֲשָׁא דְנוּנִין וְעוֹפִין, וּכְדְּדָמֵי לוֹן, הֲדָא הוּא דִכְתִיב (שם) יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה. וְעַל יְדֵיהוֹן דִּתְלָתָא אִלֵּין, אִתְעֲבֵיד כָּל עוֹבָדָא דִבְרֵאשִׁית, כָּל חַד וְחַד לְזִינֵיהּ.</p>"],[9514011669,"<p>כַד אֲתָא יוֹמָא שְׁתִיתָאָה, כָּלְהוֹ הֲווֹ זְמִינִין לְמִבְרֵי כִּשְׁאָר יוֹמִין. אֲמַר לוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא, לָא שׁוּם חַד מִנְּכוֹן, יָכֵיל לְמֶעְבַּד בְּרִיָה דָא בִּלְחוֹדוֹי, כִּשְׁאָר כָּל בְּרִיָּין דַּהֲווֹ עַד כָּאן, אֶלָּא כּוּלְכוֹן תִּתְחַבְּרוּן כַּחֲדָא וַאֲנָא עִמְכוֹן, וְנַעֲבֵיד אֵינָשָׁא. דְּהָא אַתּוּן לָא תֵיכְלוּל לְמֶעְבְּדֵיהּ בִּלְחוֹדֵיכוֹן, אֲבָל גּוּפָא יְהֵא דִילְכוֹן תְּלָתֵיכוֹן, וְנִשְׁמָתָא דִילִי.</p>"],[9514011670,"<p>וּלְפִיכָךָ קְרָא לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וַאֲמַר לוֹן נַעֲשֶׂה אָדָם, אֲנָא וְאַתּוּן. אֲנָא נִשְׁמָתָא, וְאַתּוּן גּוּפָא. וְכָךְ הוּא, דְּגוּפָא הוּא מִתְּלָתְהוֹן, דַּהֲווֹ אוּמָּנִין בְּעוֹבָדָא דִּבְרֵאשִׁית, וְנִשְׁמָתָא יָהֲבָהּ קוּדְשָׁא בְּרִיךְ הוּא, דְּאִשְׁתַּתַּף עִמְּהוֹן בָּהּ.</p>"],[9514011671,"<p>בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, כְּלוֹמַר דְּאִתְחֲזֵי לָנָא, בְּהַהוּא גּוּפָא דְּאִתְנְסַב מִנְּכוֹן, לְמִנְדַע וּלְאַדְמָאָה לְכוֹן, כְּהַהוּא דְּאִתְנְסֵיב מִנִּי, דְּהוּא נִשְׁמָתָא, דְּיִתְפְרַשׁ מֵעוֹבָדוֹי דְעָלְמָא, וִיהֵא תֵּאוֹבְתֵּיהּ וּרְעוּתֵיהּ לְעִילָּאִין קַדִּישִׁין.</p>"],[9514011672,"<p>וְעוֹד בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, דְּגוּפָא דְּאִתְנְסֵיב מִנְּכוֹן, לָא יְהֵא בְּקִיּוּמָא כְּגִינֵיכוֹן. מַאי כְּגִינֵיכוֹן. כְּאִינוּן בְּרִיָּין דְּאַפֵּקְתּוּן, עַל דְּאִיהִי עַפְרָא כִּשְׁאָר כָּל בִּרְיָין. וְהַהִיא נִשְׁמָתָא קַדִּישָׁא דַּאֲנָא יָהֵיב בֵּיהּ, דְּיֶהֱוֵי לָהּ קִיּוּמָא לְעָלְמִין, דְּלֵיתָה גּוּפָא, וְיִדְמֶה בְּקִיּוּמָא לִי.</p>"],[9514011673,"<p>אֲמַר רַבִּי אַבָּהוּ, הָדֵין הוּא בְּרֵירָא דְמִלְתָא, מִשּׁוּם דְּאִשְׁתְּכַח דְּבִבְרֵאשִׁית, הֲווֹ אִלֵּין תְּלָתָא, שְׁמַיָא וְאַרְעָא וּמַיָא.</p>"],[9514011674,"<p>ר' אֶלְעָזָר בַּר ר' שִׁמְעוֹן אֲמַר, יָאוֹת הוּא. אֲבָל אַרְעָא נָסְבָא חֵילָא דִּתְלָתְהוֹן בִּלְחוֹדָאָה, עַד דַּהֲוֵי בָהּ אַרְבַּע יְסוֹדוֹת קָיְימִין. מִן שְׁמַיָא תְּרֵין, וּמִן מַיָא חַד, וְחַד דְּבָהּ. וְהִיא אֲפֵיקַת גּוֹלְמָא דְאָדָם, וְקוּדְשָׁא בְּרִיךְ הוּא נִשְׁמָתָא. הֲדָא הוּא דִכְתִיב, (שם ב) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. הֲרֵי תַּרְוֵיהוֹן, אַרְעָא וְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִשְׁתַּתְּפוּ כַּחֲדָא לְמֶעְבַּד לֵיהּ, וּבְגִינֵיהּ אֲמַר נַעֲשֶׂה אָדָם, דְּקוּדְשָׁא בְּרִיךְ הוּא אֲמַר לָהּ עֲשִׂי אֶת הַגּוּף, וַאֲנָא נִשְׁמָתָא. אָמַר רִבִּי יִצְחָק, הָא כָּל סְפֵיקָא דָא אִתְעַבַּר מִינָן.</p>"],[9514011675,"<p>עוֹד אָמַר רִבִּי אֶלְעָזָר, כְּהַאי גַוְונָא, אִשְׁתַּתַּף קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמָא, בִּבְרִיָּיתָא דִּבְנֵי נָשָׁא. דְּהָא תָּנִינָן, שְׁלשָׁה שׁוּתָּפִין בָּאָדָם, הָאִישׁ וְאִשְׁתּוֹ וְקוּדְשָׁא בְּרִיךְ הוּא. אָמַר רִבִּי יְהוֹשֻׁעַ, כְּהַאי גַוְונָא, שְׁמַיָא וְאַרְעָא וְקוּדְשָׁא בְּרִיךְ הוּא. אָמַר רִבִּי שִׁמְעוֹן, שָׁמַיִם, כְּנֶגֶד אִישׁ. אֶרֶץ, כְּנֶגֶד אִשְׁתּוֹ. וּלְעוֹלָם קוּדְשָׁא בְּרִיךְ הוּא מְשׁוּתָּף עִמָּהֶם. וְעַל כֵּן נֶאֱמַר נַעֲשֶׂה אָדָם בִּלְשׁוֹן שׁוּתָּפוּת. וְאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מְשׁוּתָּף עִם שׁוּם בְּרִיָה, זוּלַת עִם אָדָם.</p>"],[9514011676,"<p>אָמַר רִבִּי יוֹסֵי, וּבִשְׁאָר הַבְּרִיּוֹת מִי מְשׁוּתָּף עִמָּהֶם. אָמַר רִבִּי שִׁמְעוֹן, כֹּחַ הָאֲדָמָה, דַּאֲמָרָן שֶׁהִיא נֶפֶשׁ חַיָּה. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵין מְשׁוּתָּף, אֶלָּא עַל הָאָדָם בִּלְבָד.</p>"],[9514011677,"<p>אָמַר רִבִּי יְהוּדָה, וַוי לָהֶם לָרְשָׁעִים, שֶׁאֵינָם רוֹצִים לְהִדָּבֵק בְּשׁוּתָּפוּתָא שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. בַּמֶּה. אָמַר רִבִּי יִצְחָק, בְּאוֹתָהּ הַנְּשָׁמָה שֶׁהוּא נָתַן, אֶלָּא הוֹלֵךְ וְדָבֵק בְּכֹח הַבְּהֵמוֹת. הֲדָא הוּא דִכְתִיב, (תהילים מ״ט:י״ג) וְאָדָם בִּיקָר בַּל יָלִין נִמְשַׁל כַּבְּהֵמוֹת נִדְמוּ. בַּל יָלִין, שֶׁלֹּא רָצָה לַעֲמוֹד בְּאוֹתוֹ יְקָר וְתִפְאֶרֶת שֶׁל הַנְּשָׁמָה. אֲבָל מֶה חַטָאתוֹ שֶׁעָשָׂה שֶׁנִּמְשַׁל כַּבְּהֵמוֹת, בְּאוֹתוֹ הַכֹּחַ שֶׁלָּהֶן, הַנִּכְרַת וְהַנִּדְמֶה מְהֵרָה, וְלֹא תַעֲלֶה לְמַעְלָה.</p>"],[9514011678,"<p>אָמַר רִבִּי שִׁמְעוֹן בֶּן פַּזִי, אָזְלָא הָא, כִּי הָא דְאָמַר רִבִּי יַעֲקֹב בֶּן אִידֵי, דְּאָמַר רִבִּי יַעֲקֹב בֶּן אִידֵי, מַאי דִכְתִיב, (איוב כ״ח:י׳) וְכָל יָקָר רָאֲתָה עֵינוֹ, אֵלּוּ נִשְׁמוֹתָן שֶׁל צַדִּיקִים, שֶׁהֵם יְקָר וְתִפְאֶרֶת לָעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>"],[9514011679,"<p>אָמַר רִבִּי אַבָּהוּ אָמַר רִבִּי יוֹנָתָן, בֹּא וּרְאֵה מַעֲלָתוֹ שֶׁל אָדָם, שֶׁהִבְדִּילוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל שְׁאָר הַנִּבְרָאִים. הָאֵיךְ. אָמַר רִבִּי אַבָּהוּ, כָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא, אָמַר לַפּוֹעֲלִים הָאֵלֶּה, שֶׁהֵם יַעֲשׂוּ לְבַדָּם, וְלֹא נִתְיַיחֵד הוּא עִמָּהֶם. אָמַר עַל בְּרִיּוֹת הָאָרֶץ, תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה וְגו'. אָמַר לַמַּיִם, יִשְׁרְצוּ הַמַּיִם, וְהוּא לֹא נִתְיַיחֵד עִמָּהֶם.</p>"],[9514011680,"<p>כְשֶׁבָּרָא הָאָדָם, נִתְיַיחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהֶם בַּעֲשִׂיָּיתוֹ, וְאָמַר נַעֲשֶׂה אָדָם. וְנָתַן בּוֹ קְלַסְתֵּר פָּנִים, רְאִיָּ\"ה, רֵי\"חַ, קוֹמָ\"ה, הֲלִיכָ\"ה, מִשׁוּ\"שׁ, דִּבּוּ\"ר, עֲשִׂיָּ\"ה, הִמְשִׁילוֹ בְּמַעֲשֵׂה יָדָיו, הֲדָא הוּא דִכְתִיב, (תהילים ח׳:ז׳) תַּמְשִׁילֵהוּ בְּמַעֲשֵׂה יָדֶיךָ כֹּל שַׁתָּה תַּחַת רַגְלָיו.</p>"],[9514011681,"<p>וּכְשֶׁזָּרַק בּוֹ נְשָׁמָה, קָם עַל רַגְלָיו, וְנִדְמָה לַתַּחְתּוֹנִים וְלָעֶלְיוֹנִים. נִדְמָה גּוּפוֹ לָאָרֶץ. וְנִשְׁמָתוֹ לָעֶלְיוֹנִים, בְּתוֹאַר, וְהָדָר, וְכָבוֹד, בְּאֵימָה, וּבְיִרְאָה. הֲדָא הוּא דִכְתִיב (שם) וְכָבוֹד וְהָדָר תַּעְטְרֵהוּ.</p>"],[9514011682,"<p>אָמַר רִבִּי יוֹנָתָן, רֵישָׁא דְּהַאי קְרָא, סְפֵיקָא בְּלִבָּאי, דִּכְתִיב (שם) וַתְּחַסְּרֵהוּ מְעַט מֵאֱלֹהִים. אָמַר רִבִּי אַבָּהוּ, בְּנִשְׁמָתֵיהּ דְּהִיא קַדִּישָׁא, וְדָמֵי לֵיהּ. אֲבָל מַאי גְרִיעוּתָא הוּא, עַל דְּהֲוָה גוּפָא, וְאִתְנְטֵל מִן אַרְעָא.</p>"],[9514011683,"<p>וְאִם תֹּאמַר בְּדַעַת וּבְחָכְמָה. אִי אֶפְשָׁר, דְּהָא רָחוֹק הוּא הָאָדָם מִן הָעֶלְיוֹנִים דְּאָמַר רִבִּי אֶלְעָזָר אָמַר רִבִּי תַּנְחוּם, הַמַּלְאָכִים הַקְּרוֹבִים, מְקַבְּלִים כֹּחַ שֶׁפַע אַסְפַּקְלַרְיָא שֶׁל מַעְלָה תְּחִלָּה, וּמֵהֶם יוֹרֵד לְאוֹתָם שֶׁאֵינָם קְרוֹבִים, וּמֵהֶם יוֹרֵד לַשָּׁמַיִם וְכָל צְבָאָם, וּמֵהֶם אֶל הָאָדָם.</p>"],[9514011684,"<p>אָמַר רִבִּי יוֹסֵי, כִּסֵּא הַכָּבוֹד מְקַבֵּל תְּחִלָּה, וּמִמֶּנּוּ לַמַּלְאָכִים הָעֶלְיוֹנִים, וּמֵהֶם לְאוֹתָם שֶׁאֵינָם כָּל כָּךְ עֶלְיוֹנִים וּגְבוֹהִים כְּמוֹתָם, וּמֵהֶם לַשָּׁמַיִם, וּמֵהֶם אֶל הָאָדָם.</p>"],[9514011685,"<p>אֲבָל בַּמֶּה נִדְמָה לוֹ הָאָדָם, אָמַר רִבִּי אַבָּהוּ, בַּנְּשָׁמָה, שֶׁהִיא קְדוֹשָׁה, וְלֹא תִכְלֶה לְעוֹלָם, עַל שֶׁנִּטְלָה מִמֶּנּוּ, מִכֹּחוֹ וּמִגְּבוּרָתוֹ. וְלֹא כְּמוֹ הַגּוּף שֶׁנִּיטַל מִן הָאֲדָמָה, וְיִכְלֶה וְיָשׁוּב עָפָר כְּשֶׁהָיָה.</p>"],[9514011686,"<p>אָמַר רִבִּי יִצְחָק אָמַר רַב, אָדָם, וְזִוּוּגוֹ עִמּוֹ, נִבְרְאוּ בְּיַחַד, הֲדָא הוּא דִכְתִיב, (בראשית ה׳:ב׳) זָכָר וּנְקֵבָה בְּרָאָם. וְנִטְלָה מִגַּבָּיו, וְהֵכִינָהּ, וְהֵבִיאָהּ אֶל הָאָדָם. הֲדָא הוּא דִכְתִיב, (שם ב) וַיִּקַּח אַחַת מִצַּלְעוֹתָיו.</p>"],[9514011687,"<p>ר' יְהוֹשֻׁעַ אָמַר, חַוָּה הָרִאשׁוֹנָה הָיְתָה, וּלְקָחָהּ מִמֶּנּוּ, וְהִיא נִזְקֵי דִּבְרִיָּיתָא. הֲדָא הוּא דִכְתִיב וַיִּקַּח אַחַת מִצַּלְעוֹתָיו, זוֹ הִיא הָרִאשׁוֹנָה שֶׁנִּלְקַח מִמֶּנּוּ, עַל שֶׁהִיא רוּחַ מַזֶּקֶת. וַיִּסְגֹּר בָּשָׂר תַּחְתֶּנָּה, שֶׁהֵקִים אַחֶרֶת בִּמְקוֹמָהּ.</p>"],[9514011688,"<p>רָבָא אָמַר, זוֹ הָיְתָה בָּשָׂר, וְהָאַחֶרֶת לֹא הָיְתָה בָשָׂר, וּמַאי הֲוַת. אָמַר רַבִּי יִצְחָק, זוּהֲמָא דְּאַרְעָא וּשְׁמָרֶיהָ.</p>"],[9514011689,"<p>אָמַר רִבִּי תַּנְחוּם, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם, נָתַן זוֹהַר פָּנָיו, שֶׁמֵּאִיר בְּכָל הָעוֹלָם. כֵּיוָן שֶׁחָטָא, מַה כְּתִיב בֵּיהּ, (קהלת ח׳:א׳) וְעֹז פָּנָיו יְשֻׁנֶּא.</p>"],[9514011690,"<p>רַבִּי אֱלִיעֶזְר וְרַבִּי עֲקִיבָא הֲווֹ אָזְלֵי בְּאוֹרְחָא, אָמַר לֵיהּ רַבִּי עֲקִיבָא, ר', אֵימָא לִי, הָא דִכְתִיב, (בראשית א׳:כ״ו) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם, לָמָּה לֹא נֶאֱמַר וַיְהִי כֵן מִיָּד, כִּשְׁאָר כָּל הַיָּמִים, כְּשֶׁהָיָה אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא דָּבָר, מִיָּד נֶאֱמַר וַיְהִי כֵן, וְכָאן לֹא נֶאֱמַר, אֶלָּא לְאַחַר שֶׁאָמַר נַעֲשֶׂה אָדָם, כְּתִיב וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם, הָיָה לוֹ לוֹמַר וַיְהִי כֵן.</p>"],[9514011691,"<p>אָמַר לֵיהּ, עֲקִיבָא, וְכִי זֹאת הָיְתָה בְּמַעֲשֵׂה בְרֵאשִׁית וְלֹא יוֹתֵר, וְהָא כְּתִיב (שם) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, וְלֹא נֶאֱמַר וַיְהִי כֵן, אֶלָּא וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ. וְכֵן (שם) יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם לְהָאִיר עַל הָאָרֶץ, הָיָה לוֹ לוֹמַר מִיָּד וַיְהִי כֵן, וּכְתִיב וַיַּעַשׂ אֱלֹהִים אֶת שְׁנֵי הַמְאוֹרוֹת הַגְּדוֹלִים.</p>"],[9514011692,"<p>אֶלָּא אֵימָא לָךְ, כָּל דָּבָר שֶׁלֹּא הָיָה בָּהֶם הַכֹּחַ הָאָצוּל מִלְּמַעְלָה, נֶאֱמַר מִיָד וַיְהִי כֵן. שֶׁהָאָרֶץ הוֹצִיאָה אוֹתָם בְּתַשְׁלוּם כָּל פְּעוּלָּתָם, וְלֹא הוּצְרְכָה לְהַמְתִּין לַכֹּחַ הָעֶלְיוֹן, לְהַשְּׁלִים תַּשְּׁלוּם אוֹתָהּ הַפְּעוּלָּה.</p>"],[9514011693,"<p>אֲבָל בְּכָל דָּבָר וְדָבָר שֶׁהוֹצִיאָה הָאָרֶץ, וְקִיּוּם תַּשְׁלוּם הַפְּעוּלָּה לֹא הָיְתָה בָהּ, הוּצְרְכָה לְהַמְתִּין עַד שֶׁיָּבֹא הַכֹּחַ מִלְּמַעְלָה, וְיַעֲשֶׂה הַקִּיּוּם וּשְׁלֵמוּת הַפְּעוּלָּה.</p>"],[9514011694,"<p>וְכֵן בְּכָאן בָּאָדָם, הָאָרֶץ הוֹצִיאָה אוֹתוֹ הַדָּבָר הַמַּסְפִּיק לָהּ לַעֲשׂוֹת, וְעָמְדָה, עַד שֶׁיִּתֵּן הַכֹּחַ אוֹתוֹ שֶׁיֵּשׁ בְּיָדוֹ לָתֵת, וּלְפִיכָךְ לֹא נֶאֱמַר מִיָּד וַיְהִי כֵן, עַד שֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא וְנָתַן בּוֹ הַכֹּחַ מִלְּמַעְלָה, וְעָשָׂה הַקִּיּוּם.</p>"],[9514011695,"<p>אָמַר לוֹ רַבִּי עֲקִיבָא, רַבִּי, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא עָשָׂה אֶת הָאָדָם אֶלָּא בַּשִּׁשִּׁי, אָמַר לֵיהּ, שֶׁלֹּא יְהֵא פִּתְחוֹן פֶּה לָאָדָם לוֹמַר, שֶׁהוּא סִיַּיע בְּשׁוּם דָּבָר מִכָּל מַה שֶּׁנִּבְרָא.</p>"],[9514011696,"<p>אֲזָלוּ, עַד דַּהֲווֹ אָזְלֵי, קָם רַבִּי אֱלִיעֶזְר, וְגָחִין רֹאשֵׁיהּ, וְשַׁוֵּי יְדוֹי עַל פּוּמֵיהּ, וּבָכֵי. אָמַר לֵיהּ רַבִּי עֲקִיבָא, רַבִּי, לָמָּה אַתְּ בָּכֵי. אָמַר לֵיהּ, עַל דָּא דִּשְׁאֵילְתָּא. חֵיזוּ חָזֵית, וְקַשְׁיָא מִלָּה.</p>"],[9514011697,"<p>עֲקִיבָא עֲקִיבָא, מַאן יִזְכֵּי לְהַאי אוֹרְכָא דְגָלוּתָא דְּאִתְמְשַׁךְ, דְּהָא לָא יָקוּם בַּר נָשׁ, דְּעָתִיד לִימְטֵי לַעֲנָנֵי שְׁמַיָא, עַד יוֹמָא שְׁתִיתָאָה. דְּהוּא בְּשִׁית אֶלֶף שְׁנִין, וְלָא בְּאַשְׁלָמוּתֵיהּ, בַּר בִּתְקוֹף תְּשׁוּבָה, דְּהָא שׁוּלְטָנָא דְּבַּר נָשׁ הַהִיא לֵיתֵיהּ אֶלָּא בִּשְׁתִיתָאָה.</p>"],[9514011698,"<p>וּבִשְׁבִיעָאָה, יִשְׁתָּאַר שְׁמִטָה בְּעָלְמָא, חָרוּב. וּבִתְמִינָאָה, יִתְחַדֵּשׁ עָלְמָא כְּמִלְּקַדְּמִין, וִיהֵא מַה דִּיהֵא. עַל דָּא (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ. וּבְגִינֵהוֹן נֶאֱמַר, (תהילים ק״ד:ל״א) יְהִי כְבוֹד ה' לְעוֹלָם יִשְׂמַח ה' בְּמַעֲשָׂיו.</p>"],[9514011699,"<p>(בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְגו'. רָבָא בְּשֵׁם ר' בְּרֶכְיָה אָמַר, בָּא הַכָּתוּב לְהוֹרוֹת, כִּי לְאַחַר שֶׁסִּפֵּר כָּל הַתּוֹלְדוֹת שֶׁהוֹצִיאוּ הַשָּׁמַיִם וְהָאָרֶץ, שֶׁלֹּא תֹאמַר בְּשִׁשָּׁה יָמִים נִבְרְאוּ כֻּלָּם, בְּרִיָּה זוֹ בְּיוֹם פְּלוֹנִי, וּבְרִיָּה זוֹ בְּיוֹם פְּלוֹנִי, אֶלָּא כָּל הַתּוֹלָדוֹת שֶׁנִּתְהַוּוּ מִן הַשָּׁמַיִם וּמִן הָאָרֶץ, אֵימָתַי הֲווֹ. תֵּדַע לָךְ אֵימָתַי. בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. כְּלוֹמַר, בְּאוֹתוֹ הַיּוֹם מַמָּשׁ, הָיוּ בָּהֶם כָּל הַתּוֹלָדוֹת, שֶׁנִּתְהַוּוּ מִן הַשָּׁמַיִם וּמִן הָאָרֶץ, דִּכְתִיב בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם.</p>"],[9514011700,"<p>רַבִּי יֵיסָא אָמַר, וְהָא כְתִיב (שם ה) זֶה סֵפֶר תּוֹלְדֹת אָדָם בְּיוֹם בְּרֹא אֱלֹהִים אָדָם, אִם כֵּן בְּאוֹתוֹ הַיּוֹם מַמָּשׁ הָיוּ כָּל הַתּוֹלָדוֹת.</p>"],[9514011701,"<p>אָמַר רִבִּי בְּרֶכְיָה, כָּךְ הוּא, בְּאוֹתוֹ הַיּוֹם נִתְהַוּוּ, שֶׁהֶרְאָהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ הַיּוֹם, כָּל תּוֹלְדוֹתָיו, וְהֶעֱבִירָם לְפָנָיו הַנְּשָׁמוֹת בִּדְיוּקְנֵיהוֹן, וְהָיָה אוֹמֵר, זֶה פְּלוֹנִי, וְזֶה פְּלוֹנִי. זֶה חָכָם הַדּוֹר, וְזֶה דַּיָּין הַדּוֹר, וְכֵן כָּל הַדּוֹרוֹת וּמַנְהִיגֵיהֶן.</p>"],[9514011702,"<p>ר' יִצְחָק בְּשֵׁם ר' חִיָּיא אָמַר, מַה כְּתִיב לְמַעְלָה מִן הָעִנְיָן. (שם ב) וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם. לְאַחַר שֶׁאָמַר (שם א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. מַהוּ אֶת כָּל אֲשֶׁר עָשָׂה. אֶת כָּל לְרַבּוֹת עִנְיַן הַמַּלְאָכִים, שֶׁהֵם טוֹב מְאֹד. וּבְכָל הַנִּבְרָאִים לֹא נֶאֱמַר אֶלָּא כִּי טוֹב בִּלְבָד, וּבְכָאן כִּי טוֹב מְאֹד. מְלַמֵּד שֶׁהַמַּלְאָכִים נִבְרְאוּ וְנֶאֱמַר עֲלֵיהֶם כִּי טוֹב מְאֹד.</p>"],[9514011703,"<p>וְאָמַר רִבִּי יִצְחָק לָמָּה עוֹד הוֹסִיף קְרָא וְאָמַר וַיְכֻלּוּ. אָמַר רִבִּי בְּרֶכְיָה, לָשׁוֹן כִּסּוּף הוּא. וְכָל צְבָאָם בִּכְלַל, הֵם הַמַּלְאָכִים הַנִּקְרָאִים צְבָא הַשָּׁמַיִם. הֲדָא הוּא דִכְתִיב, (מלכים א כ״ב:י״ט) וְכָל צְבָא הַשָּׁמַיִם עוֹמֵד עָלָיו. וּכְשֶׁגָּמַר הַמְלָאכָה, נִכְסְפָה וְכָלְתָה לְכָל רוֹאֶיהָ.</p>"],[9514011704,"<p>אָמַר רִבִּי נַחְמָן, וַיְכֻלּוּ: כָּלוּ מִמַּעֲשֶׂה, כָּלוּ מִמַּחֲשָׁבָה. וְעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיוֹם הַשַּׁבָּת דּוּגְמַת עוֹלָם הַבָּא. שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁבּוֹת בַּשְּׁבִיעִי, מַאי בַּשְּׁבִיעִי. בָּאֶלֶף הַשְּׁבִיעִי.</p>"],[9514011705,"<p>וְאָמַר רַב נַחְמָן, נֶפֶשׁ יְתֵירָה נִתּוֹסֶפֶת בָּאָדָם בְּיוֹם הַשַּׁבָּת. אָמַר לֵיהּ רַבִּי, מַאי נֶפֶשׁ יְתֵירָה זוֹ, אָמַר לֵיהּ, רוּחַ הַקֹּדֶשׁ שֶׁשּׁוֹרָה עָלָיו, וּמַכְתִּיר לָאָדָם בְּכֶתֶר קָדוֹשׁ, בְּכִתְרֵי הַמַּלְאָכִים. וְהוּא מֵאוֹתוֹ רוּחַ, שֶׁעָתִיד לִשְׁרוֹת עַל הַצַּדִּיקִים לֶעָתִיד לָבֹא. וְעַל כֵּן חַיָּיב אָדָם לְכַבֵּד אֶת יוֹם הַשַּׁבָּת, עַל הַאי אוּשְׁפִּיזָא קַדִּישָׁא דְּשָׁרְיָא עִמֵּיהּ.</p>"],[9514011706,"<p>וְאָמַר רִבִּי נַחְמָן, רוּחָא דָא אֵיךְ אִתְקְרֵי. מְכוּבָּד אִתְקְרֵי. קָדוֹשׁ אִתְקְרֵי. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ח:י״ג) וְקָרָאתָ לַשַּׁבָּת עוֹנֶג כְּמַשְׁמָעוֹ, לִקְדוֹשׁ ה' מְכֻבָּד, הִיא תּוֹסֶפֶת הָרוּחַ הַנִּקְרָא קְדוֹשׁ ה', הַנִּקְרָא מְכוּבָּד.</p>"],[9514011707,"<p>אָמַר רִבִּי יִצְחָק, כְּשֶׁסִּיְּימוּ הַמְלָאכוֹת כֻּלָּם, בֵּרְכָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵכִינָם בָּעוֹלָם, וְצִוָּה לְכָל אֶחָד וְאֶחָד שֶׁלֹּא יְשַׁנֶּה הֲכָנָתוֹ, מֵאוֹתוֹ הָעִנְיָן שֶׁעֲשָׂאָהוּ. וְשֶׁכָּל אֶחָד וְאֶחָד יוֹצִיא תּוֹלְדָתוֹ, הָרָאוּי לוֹ, מִכָּאן וּלְעוֹלָם. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ג׳) אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת. מַאי לַעֲשׂוֹת. לְהוֹלִיד וּלְהוֹצִיא כָּל דָּבָר כְּמוֹתוֹ. רַבִּי יְהוּדָה אוֹמֵר, זֶה גּוּף הַשֵּׁדִים, שֶׁלֹּא נִגְמְרָה מְלַאכְתָּם.</p>"],[9514011708,"<p>רַבִּי יוֹסֵי בַּר נַחְמָן אָמַר, כֵּיוָן שֶׁנִכְנַס שַׁבָּת, כָּל הַדְּבָרִים שֶׁנִּבְרְאוּ בְּמַעֲשֵׂה בְרֵאשִׁית, שָׁבְתוּ וְשָׁקְטוּ, כָּל אֶחָד לְפִי בְּרִיָּיתוֹ. דְּתָנִינָן, אוֹתָן הָאוּמָּנִין שֶׁהָיוּ מוֹצִיאִין תּוֹלְדוֹתָם בְּכָל יוֹם וָיוֹם, שָׁקְטוּ וְנָחוּ, וְרָאוּ כִּי כֻלָּם שְׁלֵמִים, וְכָל תּוֹלְדוֹתָם עִמָּהֶם, בְּקִיּוּם וּמַעֲשֶׂה.</p>"],[9514011709,"<p>הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. אָמַר רַב נַחְמָן, כְּאָדָם הַמְשַׁבֵּחַ וְאוֹמֵר, אֵלּוּ הֵם הַדְּבָרִים שֶׁאֵין כְּמוֹתָם. בְּהִבָּרְאָם, ר' יִצְחָק אָמַר, בְּהֵ\"א בְּרָאָם. ר' יְהוּדָה אוֹמֵר בְּהִבָּרְאָם, מַמָּשׁ בִּדְמוּתָם וּבִשְׁלֵימוּתָם.</p>"],[9514011710,"<p>וְרַב נַחְמָן אָמַר, אַל תִּקְרֵי בְּהִבָּרְאָם, אֶלָּא בְּאַבְרָהָם. שֶׁקִּבֵּל תּוֹרָתוֹ וּבְרִיתוֹ אֲשֶׁר שָׂם בּוֹ. וְאִלְמָלֵא אַבְרָהָם, שֶׁקִּבֵּל תּוֹרָתוֹ וּבְרִיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא נִתְקַיְּימוּ שָׁמַיִם וָאָרֶץ, שֶׁנֶּאֱמַר, (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי.</p>"],[9514011711,"<p>וְאַל תִּתְמַהּ עַל זֶה, דְּהָא תְּנַן כְּתִיב, (תהילים ק״ד:י״ח) הָרִים הַגְּבוֹהִים לַיְעֵלִים סְלָעִים מַחֲסֶה לַשְּׁפַנִּים. אִם הָרִים הַגְּבוֹהִים, נִבְרְאוּ בָּעוֹלָם לַיְעֵלִים. וְהַסְּלָעִים לֹא נִבְרְאוּ, אֶלָּא לַשְּׁפַנִּים. אַל תִּתְמַהּ לִהְיוֹת הָעוֹלָם נִבְרָא בִּשְׁבִיל אַבְרָהָם, שֶׁקִּיֵּים כָּל הַתּוֹרָה, וְכָל מַה שֶּׁנִּצְטַוָּוה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי יִצְחָק אָמַר בְּשֵׁם רַבִּי יְהוּדָה, בְּה' בְּרָאָם, הֲדָא הוּא דִכְתִיב, (שמות כ״ג:כ״א) כִּי שְׁמִי בְּקִרְבּוֹ.</p>"],[9514011712,"<p>עוֹד אָמַר רִבִּי יִצְחָק בְּשֵׁם רַבִּי יְהוּדָה, לֹא נִתְיַיחֵד שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל הַנִּבְרָאִים, זוּלָתִי בְּאֵלֶּה, דִּכְתִיב (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם כִּדְקָאֲמָרָן. וְלֹא נִזְכְּרוּ חַיּוֹת וּבְהֵמוֹת, וְלֹא שׁוּם נִבְרָא מֵאוֹתָם שֶׁהֵם נִפְסָדִים וְכָלִים, אֶלָּא עַל אוֹתָם שֶׁהֵם קַיָּימִים לְעוֹלָם, הִזְכִּיר שְׁמוֹתָיו.</p>"],[9514011713,"<p>רַב אָמַר, יוֹם שֶׁנִּכְסְפוּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּרִיַּית שָׁמַיִם וָאָרֶץ וְרָאָה הַשַּׁבָּת שֶׁהִיא מְנוּחָה וּקְדוּשָּׁה, הֵכִינוֹ לַדּוֹרוֹת.</p>"],[9514011714,"<p>וְתָאנָא, אֵין לְךָ בְּכָל שַׁבָּת וְשַׁבָּת, שֶׁאֵין הַקָדוֹשׁ בָּרוּךְ הוּא הוֹלֵךְ לָחוֹל עִם הַצַּדִּיקִים בַּגַּן עֵדֶן. וְנִיזּוֹנִין מֵהַהוּא זִיוָא דְּאַסְפַּקְלַרְיָא הַמְאִירָה. הֲדָא הוּא דִכְתִיב, (שיר השירים ד׳:ו׳) עַד שֶׁיָּפוּחַ הַיּוֹם, זֶה יוֹם הַשַּׁבָּת. אֵלֵךְ לִּי אֶל הַר הַמּוֹר וְאֶל גִּבְעַת הַלְּבוֹנָה, זֶה הָעוֹלָם הַבָּא.</p>"],[9514011715,"<p>וְאָמַר רַב הוּנָא, אַל תִּתְמַהּ עַל זֶה, וּמַה בָּעוֹלָם הַזֶּה נוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ קָדוֹשׁ לְכָל אֶחָד וְאֶחָד בְּיוֹם הַשַּׁבָּת, וּמַכְתִּירָן בּוֹ. הַצַּדִּיקִים שֶׁיֶּשְׁנָם בָּעוֹלָם הַבָּא, אֵינוֹ דִּין לְהַכְתִּיר לָהֶם בְּיוֹם הַשַּׁבָּת בְּכֶתֶר.</p>"],[9514011716,"<p>תָּא חֲזֵי, אָמַר רַב הוּנָא, אֲפִלּוּ הָרְשָׁעִים שֶׁבַּגֵּיהִנֹּם, מוּכְתָּרִין הֵם בְּיוֹם הַשַּׁבָּת, וְשׁוֹקְטִין וְנוֹחִין. דְּאָמַר רַב הוּנָּא, אֵין לְךָ רָשָׁע מִיִּשְׂרָאֵל שֶׁאֵין לוֹ מַעֲשִׂים טוֹבִים, דְּמַעַלְיָיא לְהוֹ לְעָלְמָא דְאָתֵי. וְאֵימָתַי מַעַלְיָיא לְהוֹ. בְּיוֹם הַשַּׁבָּת. לִהְיוֹת כֻּלָּם מוּכְתָּרִים בְּכֶתֶר שַׁבָּת.</p>"],[9514011717,"<p>אָמַר רִבִּי יוֹסֵי, וְכִי הָרְשָׁעִים שֶׁחִלְּלוּ שַׁבָּת בְּפַרְהֶסְיָא, יֵשׁ לָהֶם מַעֲלָה בְּכֶתֶר שַׁבָּת. אָמַר לֵיהּ, אֵין. דְּהָא תְּנַן, (שמות טז) וַיְהִי בַּיּוֹם הַשִּׁשִּׁי לָקְטוּ לֶחֶם מִשְׁנֶה לְכָךְ נִדּוֹנִים הָרְשָׁעִים בַּיּוֹם הַשִּׁשִּׁי מִשְׁנֶה, לְהַרְוִיחַ לָהֶם בְּיוֹם הַשַּׁבָּת.</p>"],[9514011718,"<p>כִי יוֹם שַׁבָּת נִקְרָא שָׁלֵם, וְלֹא נִגְרַע. לְפִיכָךְ אֵינוֹ נִגְרַע מֵהַטוֹב וְהַהֲנָאָה שֶׁבּוֹ, בֵּין לַצַּדִּיקִים בֵּין לָרְשָׁעִים. וּלְהוֹרוֹת שֶׁלֹּא לְחִנָּם אָמְרָה תּוֹרָה, וּשְׁמַרְתֶּם אֶת הַשַּׁבָּת. וְהִזְהִירָה עַל יוֹם הַשַּׁבָּת, יוֹתֵר מִכָּל הַתּוֹרָה כּוּלָּהּ. וְתָאנָא, כָּל הַמְקַיִּים אֶת הַשַּׁבָּת, כְּאִלּוּ מְקַיִּים אֶת כָּל הַתּוֹרָה.</p>"],[9514011719,"<p>אָמַר רַב יְהוּדָה אָמַר רַב, לֹא יָשַׁב הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כִּסֵּא כְבוֹדוֹ, עַד שֶׁבָּא שַׁבָּת, וְנִתְעַלָּה וְיָשַׁב עַל כִּסְּאוֹ. אָמַר לֵיהּ ר' יוֹסֵי, וְהָא קוֹדֶם שֶׁנִּבְרָא הָעוֹלָם יָשַׁב הָיָה הוֶֹה וְיִהְיֶה. אָמַר רִבִּי יְהוּדָה, אִי מַשְׁמַע לָן דְּעַל כִּסֵּא כְבוֹדוֹ מַמָּשׁ הוּא, לֹא.</p>"],[9514011720,"<p>אֶלָּא הָכֵי תָּנִינָן, עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, לֹא הָיָה מִי שֶׁיְקַלֵּס לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְיַכִּיר אוֹתוֹ. כֵּיוָן שֶׁבָּרָא עוֹלָמוֹ, בָּרָא הַמַּלְאָכִים, וְחַיּוֹת הַקֹּדֶשׁ, הַשָּׁמַיִם, וְכָל צְבָאָם, וּבָרָא אֶת הָאָדָם, וְכֻלָּם מוּכָנִים לְשַׁבֵּחַ לְיוֹצְרָם וּלְפָאֲרוֹ. וַעֲדַיִין לֹא הֲוָה פְּאֵר וְשֶׁבַח לְפָנָיו, עַד שֶׁנִּכְנַס שַׁבָּת, וְשָׁקְטוּ כֻּלָּם, וּפָצְחוּ רִנָּה וְשִׁבְחָה, הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וְאָז יָשַׁב עַל כִּסֵּא כְבוֹדוֹ. כְּלוֹמַר, אֲזַי הָיָה מִי שֶׁיַּכִּיר אֶת כְּבוֹדוֹ, וִישַׁבֵּחַ לִכְבוֹדוֹ.</p>"],[9514011721,"<p>וְאָמַר רִבִּי יְהוּדָה, אֵין לְךָ שֶׁבַח וְקִלּוּס לִפְנֵי הַקָדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שִׁבְחוֹ שֶׁל שַׁבָּת, הָעֶלְיוֹנִים וְתַחְתּוֹנִים כֻּלָּם מְשַׁבְּחִין לוֹ כְּאֶחָד, וַאֲפִילּוּ יוֹמוֹ שֶׁל הַשַּׁבָּת מַמָּשׁ, מְשַׁבֵּחַ לוֹ, הֲדָא הוּא דִכְתִיב, (תהילים צ״ב:א׳) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת.</p>"],[9514011722,"<p>(בראשית ב׳:ז׳) וַיִּיצֶר ה' אֱלֹהִים, ר' תַּנְחוּם פְּתַח, (ישעיהו מ״ב:ה׳) כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם וְגו'. כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ, בָּרָא אוֹתָם מֵאַיִן, וְהוֹצִיאָם אֶל הַפּוֹעַל, וְעָשָׂה מֵהֶם מַמָּשׁוּת. וּבְכָל מָקוֹם אַתָּה מוֹצֵא בּוֹרֵא, עַל דְּבַר שֶׁבְּרָאוֹ מֵאַיִן, וְהוֹצִיאוֹ לַפּוֹעַל.</p>"],[9514011723,"<p>אָמַר רַב חִסְדָּא, וְכִי הַשָּׁמַיִם מֵאַיִ\"ן נִבְרְאוּ, וַהֲלֹא מֵאוֹתוֹ הָאוֹר שֶׁל מַעְלָה נִבְרְאוּ. אָמַר רִבִּי תַּנְחוּם, כָּךְ הוּא, אֶלָּא גּוּף הַשָּׁמַיִם מֵאַיִן הָיָה, וְצוּרָתָם מִדְּבַר מַמָּשׁוּת. וְכֵן הוּא הָאָדָם.</p>"],[9514011724,"<p>וְתִמְצָא בַּשָּׁמַיִם בְּרִיאָה, וְאַחַר כָּךְ עֲשִׂיָּה. בְּרִיאָה בּוֹרֵא הַשָּׁמַיִם, כְּלוֹמַר מֵאַיִן. עֲשִׂיָּה, לְעוֹשֵׂה הַשָּׁמַיִם, מִדְּבַר מַמָּשׁוּת, מֵהָאוֹר שֶׁל מַעְלָה. וְאָמַר רִבִּי תַּנְחוּם, עֲשִׂיָּה הוּא תִּקּוּן הַדָּבָר בְּגוֹדֶל וּמַעְלָה מִכְּמוֹת שֶׁהָיָה. כְּמָא דְאַתְּ אָמֵר, (שמואל ב ח׳:י״ג) וַיַּעַשׂ דָּוִד שֵׁם.</p>"],[9514011725,"<p>אָמַר רִבִּי חֲנִילָאי, פְּסוּקָא דָא לָא אָתָא אֶלָּא לְהִדָּרֵשׁ. וַיִּיצֶר בִּשְׁנֵי יוּדִין, וְכָל הַשְּׁאָר אַתְּ מוֹצֵא בְּיוּד א'. אֶלָּא כָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָמוֹ, לֹא בָּרָא בְּמַעְלָה בְּבִינָה, אֶלָּא הָאָדָם לְבַדּוֹ. שֶׁנָּתַן בּוֹ כֹּחַ מִן הָעֶלְיוֹנִים, לָדַעַת וּלְהַכִּיר וּלְהַבְדִּיל בֵּין הַטוֹב וּבֵין הָרָע, וְהוּא מְעוּטָר בְּכָבוֹד וְהָדָר, כְּמָה דְאַתְּ אָמֵר (תהילים ח׳:ו׳) וְכָבוֹד וְהָדָר תַּעְטְרֵהוּ, וְהוּא מוֹשֵׁל עַל כָּל מַעֲשֵׂה יָדָיו, הֲדָא הוּא דִכְתִיב, (שם) תַּמְשִׁילֵהוּ בְּמַעֲשֵׂי יָדֶיךָ, וְאַחַר כָּל הַשֶּׁבַח הַזֶּה כְּשֶׁהוּא זוֹכֵר שֶׁהוּא עָפָר וְיָשׁוֹב אֶל הֶעָפָר, הַכֹּל נַעֲשָׂה הֶבֶל לְפָנָיו, וְאוֹמֵר וַוי. אָמַר רִבִּי יוֹחָנָן, פַּלֵּג הַתֵּיבָה, וַי יִצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה, (בראשית ב׳:ז׳) וְיָשׁוֹב אֶל הֶעָפָר כְּמוֹת שֶׁהָיָה.</p>"],[9514011726,"<p>דָּבָר אַחֵר וַיִּיצֶר י\"י אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה. אָמַר רִבִּי שָׁלוֹם, יְצָרוֹ בִּשְׁנֵי יְצָרִים, בְּיֵצֶר טוֹב וּבְיֵצֶר הָרָע. מַה שֶּׁאֵין כֵּן בִּשְׁאָר הַבְּרִיּוֹת. כְּדֵי לְנַסּוֹת בּוֹ אֶת הָאָדָם וְיִהְיֶה פִּתְחוֹן פֶּה לַצַּדִּיקִים, וְלֹא יִהְיֶה פִּתְחוֹן פֶּה לָרְשָׁעִים.</p>"],[9514011727,"<p>אָמַר רִבִּי אַבָּא, מִפְּנֵי מָה כְּתִיב ה', וְאַחַר כַּךְ אֱלֹהִים. אֶלָּא הַשֵּׁם שֶׁהוּא שְׁמוֹ מַמָּשׁ, שֵׁם הַקִּיּוּם. נֶאֱמַר עַל הַנְשָׁמָה, שֶׁהִיא בָּאָדָם קַיְּמֶת. אֱלֹהִים, שֶׁהוּא שֵׁם מְשׁוּתָּף, נֶאֱמַר עַל הַגּוּף, שֶׁיֵּשׁ בּוֹ שׁוּתָּפוּת.</p>"],[9514011728,"<p>אָמַר רִבִּי אַבָּהוּ, שֵׁם הַקִּיּוּם, גָּזֵיר וְשַׁלִּיטָא, כַּהֲדֵין טְרִיפִין שְׁקִיפִין דְּרַגְלִין. וְלָא אוֹזִיפִין לְאָחֳרָן. וּבְגִינֵי כָךְ, לָא אִדְכַּר בְּעוֹבָדוֹי דִבְרֵאשִׁית, אֶלָּא חַד אָת מִשְׁמוֹי, וְהוּא כְּמַאן דְּאָמַר בְּה\"א בְּרָאָם.</p>"],[9514011729,"<p>וְתָנִינָן בְּסִפְרָא דְּחָכְמְתָא רַבָּה דִשְׁלֹמֹה, שְׁמָא דִשְׁמִיטָה, מְטוּל שְׁזִיפָא, קְרָעוֹי דְּמַלְכָּא, קוּשְׁטִיזָא דַּאֲטֵיל בֵּיהּ בְּחוֹתָמָא זְעֵירְתָּא, לְמִשְׁלְטָא תְּחוֹתוֹי, שֶׁנֶּאֱמַר (שמות ט״ו:י״א) מִי כָמוֹכָה בָּאֵלִים ה'.</p>"],[9514011730,"<p>אֶת הָאָדָם, לְרַבּוֹת כָּל הַכֹּחוֹת שֶׁבּוֹ. עָפָר מִן הָאֲדָמָה, אָמַר רִבִּי אַבָּהוּ, תָּא חֲזֵי, הֵיךְ יָכֵיל אֵינַשׁ לְאִתְקָיְימָא בְּהַאי עָלְמָא, דְּהָא אוֹרַיְיתָא אַסְהֵיד בְּהוּ דְּהוּא עַפְרָא.</p>"],[9514011731,"<p>וְאָמַר רִבִּי יִצְחָק, עָפָר וְלֹא חוֹמֶר, דְּאִלּוּ הֲוָה מֵחוֹמֶר, הֲוָה יַתִּיר בְּקִיּוּמָא, דְּהָא בִּנְיָינָא דְאִתְבְּנֵי מֵחוֹמֶר קִיּוּמָא אִית לֵיהּ. אֲבָל עָפָר מַמָּשׁ, לָא יָכֵיל לְאִתְקָיְימָא. הֲדָא הוּא דִכְתִיב, (בראשית ג׳:י״ט) כִּי עָפָר אַתָּה וְאֶל עָפָר תָּשׁוּב, לָא אִיתְּמָר כִּי חוֹמֶר אָתָּה. אָמַר רִבִּי חָנִין, וְהָא כְּתִיב (איוב ד׳:י״ט) אַף שֹׁכְנֵי בָתֵּי חֹמֶר אֲשֶׁר בֶּעָפָר יְסוֹדָם.</p>"],[9514011732,"<p>אָמַר רִבִּי אַבָּהוּ, פְּסוּקָא דָא מְסַיֵּיעַ לָן, וְהוּא נֶאֱמַר עַל הָעוֹלָם הַזֶּה, שֶׁאֵינוֹ כֵּן בְּקִיּוּם. דְּהַאי כְּתִיב בִּבְנֵי נָשָׁא, דִּי מְדָרְהוֹן בְּהַאי עָלְמָא, דְּבִנְיָינֵיהּ בְּטִינָא, וְהוֹאִיל דְּהַהוּא בִּנְיָינָא בְּטִינָא הוּא, וְיִתְחֲזֵי לְקִיּוּמָא. מַאי חָזֵי לֵיהּ לִיסוֹדָא. כְּמָה דְאַתְּ אָמֵר (מלכים א ה׳:ל״א) אֲבָנִים גְּדוֹלוֹת אֲבָנִים יְקָרוֹת לְיַסֵּד הַבָּיִת. אֲבָל לָאו הָכֵי בִּנְיָינָא תַּקִּיפָא, דְּהוּא בִּנְיָינָא דְטִינָא, וִיסוֹדָא הוּא עַפְרָא, בְּגִין דָּא לָא לֶהֱוֵי בְּקִיּוּמָא. הֲדָא הוּא דִכְתִיב אַף שֹׁכְנֵי בָתֵּי חֹמֶר אֲשֶׁר בֶּעָפָר יְסוֹדָם, שֶׁאֵינוֹ שֶׁל קִיּוּם.</p>"],[9514011733,"<p>(בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וְגו', אוֹרַיְיתָא אִתְקַבָּלַת עַל אָדָם, חֲזוֹ מַה דַּעֲבַד בַּר נָשׁ דָּא, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהֵיב בֵּיהּ נִשְׁמָתָא קַדִּישָׁא, לְמֵיהַב לֵיהּ חַיִּין לְעָלְמָא דְאָתֵי, וְהוּא בְּחוֹבָתֵיהּ, אִתְחֲזַר לְהַהִיא נַפְשָׁא חָיְיתָא, דְּהוּא נַפְשָׁא דִּבְעִירָתָא, דַּאֲפֵיקַת אַרְעָא לִבְעִירָתָא וּלְחַיָיתָא. הֲדָא הוּא דִכְתִיב, (שם א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ.</p>"],[9514011734,"<p>אָמַר רִבִּי חִיָּיא, בֹּא וּרְאֵה וַיַּעַשׂ הָאָדָם לְנֶפֶשׁ חַיָּה לֹא נֶאֱמַר, אֶלָּא וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, הוּא מֵעַצְמוֹ חָזַר לְאוֹתוֹ כֹּחַ הַבְּהֵמוֹת, הַנִּגְזַר מִן הָאֲדָמָה, וְעָזַב כֹּחַ הַנְּשָׁמָה הַגְּזוּרָה מִלְּמַעְלָה, וְנוֹתֶנֶת חַיִּים לִבְעָלֶיהָ.</p>"],[9514011735,"<p>אָמַר רִבִּי תַּנְחוּם, נַחְזוֹר אֲנַן לְמַאי דְּשָׁרֵינָן בְּקַדְמִיתָא. (ישעיה מב) כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם. בָּרָא גּוּף שֶׁלָּהֶם מֵאַיִן, וְאַחַר כַּךְ נָטָה אוֹתָם כְּאֹהֶל. הֲדָא הוּא דִכְתִיב, (שם מ) וַיִּמְתָּחֵם כָּאֹהֶל לָשָׁבֶת. רַב הוּנָא אָמַר מֵהָכָא, הַנּוֹטֶה כַדּוֹק שָׁמָיִם.</p>"],[9514011736,"<p>רוֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ, ר' יִצְחָק אָמַר, הִתְפַּשֵּׁט בָּהּ כָּל הַצּוּרוֹת וְהַכֹּחוֹת שֶׁבָּהּ. (שם מב) נֹתֵן נְשָׁמָה לָעָם עָלֶיהָ, לְאַחַר שֶׁהִיא עָשְׂתָה הַגּוּף, אֲנִי נָתַתִּי הַנְּשָׁמָה עָלֶיהָ. מַאי עָלֶיהָ, עַל אוֹתוֹ מַעֲשֶׂה הַגּוּף שֶׁעָשְׂתָה. ר' חִיָּיא אָמַר, עָלֶיהָ לְאוֹתָם הַשּׁוֹלְטִים עַל כּוֹחֹתֶיהָ, לָהֶם נָתַתִּי הַנְּשָׁמָה.</p>"],[9514011737,"<p>וְרוּחַ לַהוֹלְכִים בָּהּ, לְאוֹתָם הַמִּשְׁתַּתְּפִים בָּהּ בְּכֹחוֹתֶיהָ, שֶׁאֵין לָהֶם אֶלָּא אוֹתָהּ נֶפֶשׁ חַיָּה, הַנִּקְרְאָה רוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת לְמַטָה לָאָרֶץ. וְעַל כֵּן נֶאֱמַר נוֹתֵן נְשָׁמָה לָעָם עָלֶיהָ, הַשּׁוֹלְטִים עָלֶיהָ עַל כֹּחוֹתֶיהָ, לָהֶם נְשָׁמָה קְדוֹשָׁה הַגְּזוּרָה מִלְּמַעְלָה. אֲבָל לַהוֹלְכִים בָּהּ הַמִּשְׁתַּתְּפִים עִמָּהּ בְּכוֹחוֹתֶיהָ, אֵין לָהֶם אֶלָא רוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת, הֲדָא הוּא דִכְתִיב, (קהלת ג׳:כ״א) וְרוּחַ לַהוֹלְכִים בָּהּ.</p>"],[9514011738,"<p>פָּרָשָׁתָא ז (בראשית ב׳:ח׳) וַיִּטַע ה' אֱלֹהִים גַּן בְּעֵדֶן מִקֶּדֶם. ר' יוֹסֵי וְר' חִיָּיא אָמְרֵי תַּרְוַיְיהוּ, כְּתִיב (שיר השירים ו׳:י״א) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי לִרְאוֹת בְּאִבֵּי הַנָּחַל, רְאֵה, כַּמָּה יֵשׁ לוֹ לְאָדָם לְהַרְהֵר וּלְדַקְדֵּק בְּלִבּוֹ בְּכָל יוֹם וָיוֹם, וּלְפַשְׁפֵּשׁ בְּמַעֲשָׂיו, וּלְדַקְדֵּק בְּכָל עִנְיָנָיו, וִיהַרְהֵר בְּלִבּוֹ, שֶׁלֹּא בְּרָאוֹ הַקָדוֹשׁ בָּרוּךְ הוּא, וְנָתַן בּוֹ נְשָׁמָה עֶלְיוֹנָה, וּמַעֲלָה עַל שְׁאָר בְּרִיּוֹתָיו, אֶלָּא לְהַרְהֵר בַּעֲבוֹדָתוֹ, וּלְהִדָּבֵק בּוֹ, וְלֹא יֵלֵךְ אַחַר הֶהָבֶל.</p>"],[9514011739,"<p>דְּאָמַר רִבִּי יוֹסֵי אָמַר רִבִּי חִיָּיא, כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא לְבַר נָשׁ, אַסְקֵיהּ קַמֵּיהּ בְּדִיוֹקְנֵיהּ, וְהוּא יָתֵיב וְאַתְרֵי בֵיהּ, וְאָמַר לֵיהּ אֲנָא עָבִיד לָךְ, בְּגִינִי לְמֶהֱוֵי אַתְּ שׁוּלְטָנָא וּמַלְכָּא עַל כּוֹלָּא, בְּגִינִי. אֲנָא לְעֵילָא, וְאַנְתְּ לְתַתָּא.</p>"],[9514011740,"<p>וְעוֹד, אֲנָא יָהֵיב בָּךְ נִשְׁמָתָא, לְמִנְדַע סוּכְלְתָנוּ וְחָכְמָתָא, מַה דְּלֵית כֵּן לִשְׁאָר בְּרִיָּין. הֱוֵי זָהִיר לְאִסְתַּכָּלָא בִּיקָרִי, הֱוֵי זָהִיר לְמֶעְבַּד פִּיקּוּדָי. וּבַר מִנִּי לָא יְהֵא שׁוּלְטָנָא יַקִּירָא כַּוָּותָךְ.</p>"],[9514011741,"<p>וּמְנָא לָן דְּאַתְרֵיהּ בֵּיהּ, וְאַזְהֵיר לֵיהּ עַל דָּא. הֲדָא הוּא דִכְתִיב, (איוב כ״ח:כ״ח) וַיֹּאמֶר לָאָדָם הֵן יִרְאַת ה' הִיא חָכְמָה וְסוּר מֵרָע בִּינָה. כְּלוֹמַר כְּשֶׁתָּחוּל יִרְאָתִי עָלֶיךָ אָז תַּשִּׂיג חָכְמָה, שֶׁהִיא לְמַעְלָה עַל הַכֹּל. כַּד חָמָא אָדָם, דְּהוּא שֻׁלְטָנָא יַקִּירָא עַל כּוֹלָּא, אִינְשֵׁי פִּיקּוּדָא דְּמָארֵיהּ, וְלָא עֲבַד מַה דְּאִתְפַּקַּד.</p>"],[9514011742,"<p>אָמַר רִבִּי תַּנְחוּם אָמַר רִבִּי חֲנִילָאי, לֹא עֲשָׂאוֹ הַקָדוֹשׁ בָּרוּךְ הוּא לָאָדָם, אֶלָּא לְהִשְׁתַּדֵּל בִּכְבוֹד קוֹנוֹ. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ג:ז׳) כָּל הַנִּקְרָא בִּשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו. מַאי לִכְבוֹדִי. לְהִשְׁתַּדֵּל וְלָדַעַת אֶת כְּבוֹדִי, וְלַחְשׁוֹב מִמַּעֲשָׂיו שֶׁיִּנָּתֵן לוֹ חֵלֶק טוֹב לעוֹלָם הַבָּא.</p>"],[9514011743,"<p>אָמַר רַב יְהוּדָה, בְּכָל יוֹם וָיוֹם ב\"ק יוֹצֵאת מִלְּמַעְלָה, וְאֵימָתַי. בִּזְּמַן שֶׁהַחַמָּה זוֹרַחַת, וְאוֹמֶרֶת אוֹי לָהֶם לַבְּרִיּוֹת שֶׁאֵינָם רוֹאִים אֶת כְּבוֹדִי, וְאֵינָם מִסְתַּכְּלִין לָדַעַת וְלַחְקוֹר אֶת כְּבוֹדִי.</p>"],[9514011744,"<p>דְּתָנִינָן, אָמַר רִבִּי אֶלְעָזָר בְּרֵיהּ דְּר' שִׁמְעוֹן, כַּד נָטָא שִׁמְשָׁא גַּדְפוֹי, לְמֵהַךְ בִּתְקִיפוּתָא דְּגַלְגַּלּוֹן מְבַטְשֵׁי בִּטְלָפֵיהוֹן, בְּטַרְפֵּי אִילָנַיָיא דְּגִנְתָּא דְעֵדֶן. וְכָל מַלְאָכִין עִילָּאִין, וְחֵיוָתָא קַדִּישָׁא, וְכוּרְסֵי יְקָרָא דְּמַלְכָּא, וּבוּסְמַיָא דְּגִנְתָּא דְעֵדֶן, וְאִילָנֵי, שְׁמַיָא וְאַרְעָא וְחֵילֵיהוֹן, מִזְדַּעְזְעָן וּמְשַׁבְּחָן לְמָארֵי כוֹלָּא.</p>"],[9514011745,"<p>וְזָקְפָן וְחָמָאן אַתְוָותֵיהּ דִּשְׁמָא קַדִּישָׁא דְּאִתְפְּרַשׁ, דְּגָלִיף בְּשִׁמְשָׁא בְּמַטְלָנוֹי, וְיַהֲבִין תּוּשְׁבְּחָן לְמָארֵי עָלְמִין. וְנָפִיק הַהוּא קָלָא, וְאָמְרֵי לְהוֹ לִבְרִיָּיתָא, דְּלָא מַשְׁגְּחָן בִּיקָר מַלְכָּא עִילָּאָה, כִּשְׁאָר כָּל בִּרְיָין דְּאִינוּן מַשְׁגִּיחִין וְיָהֲבִין תּוּשְׁבַּחְתָּא לִשְׁמֵיהּ.</p>"],[9514011746,"<p>וּבְּגִין כָּךְ אָמַר רִבִּי אֶלְעָזָר, אָסוּר לֵיהּ לְבַר נָשׁ לְמֵימַר תּוּשְׁבְּחָן דִּצְלוֹתֵיהּ, אֶלָּא עִם דִּמְדּוּמֵי חַמָּה, דִּכְתִיב (תהילים ע״ב:ה׳) יִירָאוּךָ עִם שָׁמֶשׁ.</p>"],[9514011747,"<p>וְכֵן אָמַר רִבִּי אֶלְעָזָר, צְלוֹתָא וְתוּשְׁבַּחְתָּא דְּלֵילְיָא, מִשֶּׁשָּׁקְעָה הַחַמָּה, עַד לָא אִתְחֲזֵי סִיהֲרָא. דִּכְתִיב יִירָאוּךָ עִם שָׁמֶשׁ, דָּא הִיא צְלוֹתָא דְצַפְרָא. וְלִפְנֵי יָרֵחַ וְגו', דָּא הִיא צְלוֹתָא דְלֵילְיָא.</p>"],[9514011748,"<p>ר' יְהוּדָה אָמַר מֵהָכָא, (מלאכי א׳:י״א) כִּי מִמִּזְרַח שֶׁמֶשׁ וְעַד מְבוֹאוֹ גָּדוֹל שְׁמִי. וּבְאֵיזֶה מָקוֹם. בַּגּוֹיִם. בְּאִינוּן דִּכְתִיב בְּהוּ, כִּי מִי גּוֹי גָּדוֹל.</p>"],[9514011749,"<p>מַאי טַעְמָא. דְּתָנִינָן, אָמַר רִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי אָמַר רִבִּי יוֹחָנָן, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מַלְאֲכֵי הַשָּׁרֵת לְמַעְלָה, לְקַלְסוֹ וּלְשַׁבְּחוֹ, וְאוֹמְרִים שִׁירָה וְרִנָּה לְפָנָיו, בְּכָל לַיְלָה וְלַיְלָה. וְעָשָׂה כְּנֶגְדָם יִשְׂרָאֵל לְמַטָה, לְקַלְּסוֹ וּלְשַׁבְּחוֹ, וְלוֹמַר שִׁיר וְשֶׁבַח לְפָנָיו בְּכָל יוֹם וָיוֹם.</p>"],[9514011750,"<p>וְתָאנָא, שָׁלשׁ מִשְׁמָרוֹת הֲוֵי הַלַּיְלָה, וּבְאֵלּוּ הַשָּׁלשׁ מִשְׁמָרוֹת, מִתְחַלְּקוֹת שָׁלשׁ כִּתּוֹת שֶׁל מַלְאֲכֵי הַשָּׁרֵת, לְשַׁבֵּחַ לְיוֹצְרָם, בְּכָל מִשְׁמָרָה וּמִשְׁמָרָה. וּכְנֶגְדָם יֵשׁ שָׁלשׁ תְּפִלּוֹת בַּיּוֹם, שֶׁמִּתְכַּנְּפִין יִשְׂרָאֵל לְשַׁבֵּחַ לְיוֹצְרָם, בְּכָל תְּפִלָּה בְּכָל יוֹם וָיוֹם.</p>"],[9514011751,"<p>תָּא שְׁמַע, אָמַר רִבִּי יְהוֹשֻׁעַ אָמַר רַב, בְּצַפְרָא כְּשֶׁהַחַמָּה זוֹרַחַת הוּא זְמַן תְּפִלָּה וּבָעוּתָא דְּיִשְׂרָאֵל. וּמִשֵּׁשׁ שָׁעוֹת וּלְמַעְלָה עַד תֵּשַׁע שָׁעוֹת, זְמַן תְּפִלַּת הַמִּנְחָה. וּמִשֶּׁשָּׁקְעָה הַחַמָּה, עַד שֶׁתֶּחְשַׁךְ, תְּפִלָּה הָאַחֲרוֹנָה. דְּארִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי אָמַר רִבִּי יוֹחָנָן אָמַר רַב, מִשֶּׁשָּׁקְעָה הַחַמָּה, עַד שֶׁיֵּרָאוּ שְׁנֵי כּוֹכָבִים, זְמַן תְּפִלָּה הָאַחֲרוֹנָה.</p>"],[9514011752,"<p>דְּהָכֵי תָּנִינָן, מִשֶּׁיֵּרָאוּ שְׁנֵי כּוֹכָבִים, הוּא תְּחִלַּת מִשְׁמָרָה רִאשׁוֹנָה, שֶׁבָּאִים כַּת הָרִאשׁוֹנָה שֶׁל מַלְאֲכֵי הַשָּׁרֵת, וּמַמְתִּינִים לָהֶם לְיִשְׂרָאֵל, עַד אוֹתָהּ שָׁעָה, וְאָז מַתְחִילִין לוֹמַר שִׁירָה. וְנִנְעֲלוּ כָּל הַשְּׁעָרִים מִתּוּשְׁבַּחְתָּן שֶׁל מַטָה, וְאֵין שְׁעָרִים נִפְתָּחִים, אֶלָּא לְמַלְאֲכֵי הַשָּׁרֵת הָאוֹמְרִים שִׁירָה.</p>"],[9514011753,"<p>וּמִי ארִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי הָכֵי, וְהָא תְּנַן, כָּל הַקּוֹרֵא בַּתּוֹרָה בַּלַּיְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ עָלָיו חוּט שֶׁל חֶסֶד בַּיּוֹם, שֶׁנֶּאֱמַר (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ, מִשּׁוּם דְּבַלַּיְלָה שִׁירֹה עִמִּי. וְהָכָא אַמְרִיתוּ דְּנִנְעֲלוּ כָּל הַשְּׁעָרִים לְמַטָה.</p>"],[9514011754,"<p>אָמַר ר' יְהוֹשֻׁעַ, הָתָם בְּמַאי קָאַמְרֵי, כְּשֶׁסִּיֵּים כָּל תּוּשְׁבַּחְתָּן בַּיּוֹם. וּמִפַּלְגוּתָא דְלֵילְיָא וּלְהָלְאָה, דְּעָסִיק בַּתּוֹרָה. מַאי טַעְמָא. מִשּׁוּם דִּבְהַהִיא שַׁעֲתָא קוּדְשָׁא בְּרִיךְ הוּא נָפִיק מֵאִינוּן עוֹלָמוֹת דִּכְסִיף בְּהוּ, וְאָזִיל לְאִשְׁתַּעְשָׁע עִם צַדִּיקַיָא בְּגִנְתָּא דְעֵדֶן. וְהַיְינוּ דְּאָמַר דָּוִד חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ.</p>"],[9514011755,"<p>דְּתָנָא, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנַס עִם הַצַּדִּיקִים בַּגַּן עֵדֶן, כָּל שַׁעֲרֵי שָׁמַיִם לְמַעְלָה, עַל הַחַיּוֹת וּלְמַטָה מֵהֶם, כּוּלָּם נִפְתָּחִים, וְהוּא עֵת רָצוֹן לַעֲסוֹק בַּתּוֹרָה.</p>"],[9514011756,"<p>וְאוֹתָם כִּתּוֹת שֶׁל מַלְאֲכֵי הַשָּׁרֵת, וְכָל בּוּסְמֵי גַּן עֵדֶן, וְהַצַּדִּיקִים, כּוּלָּם פּוֹצְחִים רִנָּה, לִפְנֵי מִי שֶׁאָמַר וְהָיָה הָעוֹלָם. הֲדָא הוּא דִכְתִיב, (שם קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ. אֵימָתַי צַדִּיקִים יוֹדוּ לִשְׁמֶךָ. כְּשֶׁיּוֹשְׁבִים יְשָׁרִים אֶת פָּנֶיךָ, דְּהוּא בְּשָׁעָה שֶׁיּוֹשְׁבִין לְפָנָיו בַּגַּן עֵדֶן.</p>"],[9514011757,"<p>וְכַת שְׁלִישִׁית שֶׁל מַלְאֲכֵי הַשָּׁרֵת אוֹמֶרֶת שִׁירָה, עַד שֶׁיִּבָּקַע הַשַּׁחַר. וְיֵשׁ חוֹבָה לְיִשְׂרָאֵל, בְּשָׁעָה שֶׁעוֹלֶה עַמּוּד הַשַּׁחַר, לָקוּם וּלְהִתְגַּבֵּר בְּשִׁירוֹת וְתִשְׁבָּחוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. מַאי טַעְמָא מִשּׁוּם דְּנָסְבִין שִׁירָתָא בָּתַר מַלְאֲכֵי הַשָּׁרֵת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מָצוּי לְמַטָה עִמָּהֶם. הֲדָא הוּא דִכְתִיב, (משלי ח׳:י״ז) וּמְשַׁחֲרַי יִמְצָאֻנְנִי. וְאָמַר רִבִּי יְהוּדָה וּבִלְבַד שֶׁלֹּא יַפְסִיק מִשֶּׁיַּתְחִיל, עַד שֶׁיִּתְפַּלֵּל כְּשֶׁהַחַמָּה זוֹרַחַת.</p>"],[9514011758,"<p>אָמַר רִבִּי יוֹחָנָן אָמַר רב, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹצֵא מֵאוֹתָן הָעוֹלָמוֹת דִּכְסִיף בְּהוּ, וּבָא לְהִכָּנֵס עִם הַצַּדִּיקִים בַּגַּן עֵדֶן, הוּא מַמְתִּין וְרוֹאֶה אִם שׁוֹמֵעַ קוֹל הָעוֹסֵק בַּתּוֹרָה, הַהוּא קָלָא נִיחָא קַמֵּיהּ, מִכָּל שִׁירִין וְתוּשְׁבְּחָן דְּאָמְרֵי מַלְאֲכֵי הַשָּׁרֵת לְעֵילָא. הֲדָא הוּא דִכְתִיב, (שיר השירים ו׳:י״א) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי לִרְאוֹת, מַאי לִרְאוֹת, אוֹתָם הָעוֹסְקִים בַּתּוֹרָה.</p>"],[9514011759,"<p>אָמַר רִבִּי יִצְחָק, וְכִי גַּן עֵדֶן הוּא נִקְרָא גִנַּת אֱגוֹז. אָמַר לֵיהּ ר' יוֹחָנָן, כֵּן, נִקְרָא גִּנַּת אֱגוֹז. כְּלוֹמַר גִּנַּת עֵדֶן, מָה הָאֱגוֹז הוּא סָתוּם מִכָּל עֲבָרָיו, וְיֵשׁ עָלָיו כַּמָּה קְלִיפּוֹת. כָּךְ עֵדֶן שֶׁל מַעְלָה, הוּא סָתוּם מִכָּל עֲבָרָיו, וְיֵשׁ עָלָיו כַּמָּה שְׁמִירוֹת, שֶׁלֹּא שָׁלְטוּ לִרְאוֹת, לֹא מַלְאָךְ, וְלֹא שָׂרָף, וְלֹא חַשְׁמַל, וְלֹא עֵין נָבִיא, וְלֹא חוֹזֶה, דִּכְתִיב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתֶךָ.</p>"],[9514011760,"<p>אָמַר רִבִּי שִׁמְעוֹן, אֲנָא הֲוֵית קַמֵּי דְּר' בְּרוֹקָא, וְהָיָה אוֹמֵר, כְּדֵין אֶזְכֶּה לְמַעְלַת גִּנַּת אֱגוֹז עִם חֲסִידֵי יִשְׂרָאֵל. וְלָא הֲוָה יְדַעְנָא מַאי הוּא. עַד דִּשְׁמַעְנָא לְהָא דְּאריב\"ז, קַרְיֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְגִנְתָּא דְעֵדֶן גִּנַּת אֱגוֹז, מָה הָאֱגוֹז קְלִיפָּה אַחַר קְלִיפָּה, וּפִרְיוֹ מִבִּפְנִים. כָּךְ עֵדֶן, עוֹלָם אַחַר עוֹלָם, וְהוּא מִבִּפְנִים.</p>"],[9514011761,"<p>תָּאנֵי ר' שִׁמְעוֹן, הַגַּן הַזֶּה מֵאַיִן נָטוּעַ. הַקָּדוֹשׁ בָּרוּךְ הוּא נָטַע אוֹתוֹ מִּתַּחְתָּיו שֶׁל עֵדֶן. דְּאִי תֵימָא שֶׁזֶּה כְּנֶגֶד זֶה בְּשָׁוֶה, אִי אֶפְשָׁר, אֶלָּא הַגַּן בָּאָרֶץ, וְעֵדֶן עָלָיו מִלְמַעְלָה. וּמֵאַיִן תַּמְצִיתוֹ שֶׁל גַּן, מֵעֵדֶן הוּא.</p>"],[9514011762,"<p>אָמַר לֵיהּ ר' יְהוּדָה, לִדְבָרֶיךָ, מַאי כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵּא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, הָיָה לוֹ לוֹמַר וְנָהָר יוֹרֵד מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, דְמַשְׁמַע דְּמִלְמַעְלָה יוֹרֵד לְמַטָה לַגַּן. אֶלָּא אָמַר רִבִּי שִׁמְעוֹן, עֵדֶן לְמַטָה, וְעֵדֶן לְמַעְלָה. גַּן לְמַעְלָה, גַּן לְמַטָה. וּשְׁנֵיהֶם מְכֻוָּונִים זֶה כְּנֶגֶד זֶה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָטַע זֶה מִתַּחַת זֶה.</p>"],[9514011763,"<p>וְכִי הוּא נְטָעוֹ מַמָּשׁ, כֵּן. דְּאָמַר רִבִּי יְהוּדָה, עַל שֶׁאֵין מַטָעוֹתָיו כִּשְׁאָר מַטָעוֹת, וְהֵם מוּבְחָרִים מִשְּׁאָר מַטָעוֹת, הוּא הָיָה מַטַע ה', כְּמָה דְאַתְּ אָמֵר, (ישעיהו ס״א:ג׳) מַטַע ה' לְהִתְפָּאֵר, כְּלוֹמַר לְשַׁבֵּחַ, וְזֶהוּ לְהִתְפָּאֵר, כְּלוֹמַר אֵין זֶה כִּי אִם מַטַע ה' וְלֹא מֵאַחֵר.</p>"],[9514011764,"<p>אָמַר רִבִּי יַעֲקֹב בַּר אִידֵי, עַל כָּל פָּנִים מַטַע ה' הוּא, שֶׁנָּטַע שָׁם כָּל עֵץ נֶחְמָד לְמַרְאֶה. וְהֵיאַךְ נָטַע. אֶלָּא כְּשֶׁהוֹצִיאָה הָאָרֶץ אִילָנֶיהָ וּפֵירוֹתֶיהָ, הוֹצִיאָהּ בַּתְּחִלָּה בַּגַּן עֵדֶן, וְאַחַר כַּךְ בְּכָל הָעוֹלָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּחַר הַמָּקוֹם הַהוּא, וְהֵכִינוֹ לִהְיוֹת שָׁם לְעוֹלָם. וְהוּא פּוֹקֵד אוֹתוֹ, וּמַשְׁקֶה בְּטוּבוֹ, מֵאוֹתוֹ הַטוֹב הַנִּשְׁפַּע מֵעֵדֶן שֶׁל מַעְלָה, הֲדָא הוּא דִכְתִיב, יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי וְגו', אֵלּוּ אִילָנוֹת שֶׁבְּגַּן עֵדֶן.</p>"],[9514011765,"<p>שָׁאַל ר' חַגַּי לְר' יְהוּדָה, תֹּאמַר שֶׁגַּן עֵדֶן הוּא בָּאָרֶץ, לְמַאי אִיצְטְרִיךְ. אָמַר לֵיהּ, לַהֲנָאָתֵיהּ דְּנִשְׁמָתָא. דִּמְקַבֵּל מֵהַהוּא עֵדֶן דִּלְעֵילָא. דִּי סַלְּקָא דַּעְתָּךְ דִּלְכָל נִשְׁמָתָא, הָא תָּנִינָן לְאִינוּן דְּלָא יַהֲבוּ לְהוֹ רְשׁוּתָא לְסַלְּקָא לְעֵילָא, אִית לְהוֹ הֲנָאָה וְכִיסוּפָא בְּהַהוּא דִּלְתַתָּא, מִמַּה דִּמְקַבֵּל מִלְעֵילָא.</p>"],[9514011766,"<p>אָמַר רִבִּי יְהוּדָה, בְּכָל רֵישׁ יַרְחָא וְיַרְחָא, סָלְקֵי לְהוֹ לִמְתִיבְתָּא עִילָּאָה דִּלְעֵילָא. הֲדָא הוּא דִכְתִיב, (שם סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ וְגו'. וּבְהַאי גַּן עֵדֶן דִלְתַתָּא יָתִיב אָדָם, וְשַׁוֵּי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֶהֱוֵי מְדוֹרֵיהּ בֵּיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ח׳) וַיָּשֶׂם שָׁם אֶת הָאָדָם אֲשֶׁר יָצָר.</p>"],[9514011767,"<p>רַבִּי חִיָיא וְר' יוֹסֵי הֲווֹ אָזְלֵי בְּאוֹרְחָא, אָמַר רִבִּי יוֹסֵי לְר' חִיָּיא, הָא תָּנִינָן בְּמַתְנִיתָּא דִידָן, דְּכָל מַה דַּעֲבֵיד קוּדְשָׁא בְּרִיךְ הוּא בֵּין לְעֵילָא בֵּין לְתַתָּא, כָּלְהוֹ כְסִיפִין וְשָׁקְדִין לִמְהַךְ לְזִינֵיהּ, גּוּפָא אָזִיל בָּתַר זִינֵיהּ, לְאַרְעָא, דְּאִתְנַסֵּיבַת מִינָהּ. וְנִשְׁמָתָא לֵית לֵיהּ כִּסּוּפָא, אֶלָּא לַאֲתַר דְּאִתְנְסֵיבַת מִתַּמָּן. דְּכָל מַה דְּעָבִיד, כָּסִיף בָּתַר זִינֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים פ״ד:ג׳) נִכְסְפָה וְגַם כָּלְתָה נַפְשִׁי לְחַצְרוֹת ה', וְלָא לְעָלְמָא הָדֵין, כְּגוּפָּא.</p>"],[9514011768,"<p>אָמַר לֵיהּ ר' חִיָּיא, אֵימָא לָךְ מִלָּה דְּהִיא רָזָא, וְלָא יָדְעִין בְּנֵי נָשָׁא. אַרְכִין רֵישֵׁיהּ, וּבָכֵי וְחַיֵּיךְ. שָׁתִיק ר' יוֹסֵי, לְבָתַר אָמַר לֵיהּ רַבִּי חִיָיא, זַכָּאִין אִינוּן צַדִּיקַיָא, וַוי לְהוֹן לְרַשִּׁיעַיָא. זַכָּאִין אִינוּן צַדִּיקַיָא, דְּאִתְקְרוֹן חַיִּים לְעָלְמָא דְאָתֵי. וְכִי בְּדִיל דְּנִשְׁמְתָא קָיְימָא בְּקִיּוּמָהָא, אִינוּן קָיְימִין, וְגוּפָא מִתְרַקֵּב בְּאַרְעָא, אַף עַל גַּב דְּהֲוָה שְׁלִים זַכַּאי. וְהָתְנַן, דְּתָדִיר נִשְׁמָתָא בְּקִיּוּמָא קָיְימָא.</p>"],[9514011769,"<p>אֶלָּא הָכֵי אִתְגְּזַר, דְּכַד אִתְפַּטַר צַדִּיקָא מֵעָלְמָא דֵין, זַמֵּין לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא גּוּפָא אָחֳרָא, זַכָּאָה וְטַב, דְּלָא לֶהֱוֵי כְּהַאי זוּהֲמָא וְלִכְלוּכָא דְּגוּפָא דֵין, וּמְעַיֵּיל בֵּיהּ הַהוּא נִשְׁמָתָא קַדִּישָׁא, וְהוּא אַשְׁרֵי לֵיהּ בְּקִיּוּמֵיהּ, בְּהַהוּא גוּפָא, בְּהַאי גִּנְתָּא דְעֵדֶן דִּלְתַתָּא, וְהַהוּא לֶהֱוֵי לוֹן עָלְמָא אָחֳרָא, עָלְמָא דְאָתֵי.</p>"],[9514011770,"<p>וּבְכָל רֵישׁ יַרְחָא וְיַרְחָא, נָפְקִין, וְחָזָן חַיָּיבַיָא דְּטָרְדִין לוֹן בַּגֵּיהִנֹּם, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:כ״ד) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפּוֹשְׁעִים בִּי. מֵאֵיזֶה מָקוֹם יָצְאוּ. תָּאנֵי רַבִּי בָּא, מִגַּן עֵדֶן שֶׁל מַטָה. וְלָמָּה, לִרְאוֹת לָרְשָׁעִים. וְקוּדְשָׁא בְּרִיךְ הוּא, סָלֵיק לוֹן לִמְתִיבְתָּא דִרְקִיעָא, בְּכָל שַׁבַּתָּא וְשַׁבַּתָּא, וּבְכָל רֵישׁ יַרְחָא וְיַרְחָא, הֲדָא הוּא דִכְתִיב וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ.</p>"],[9514011771,"<p>רַבִּי שִׁמְעוֹן אֲמַר, בְּכָל לַיְלָה וְלַיְלָה, וְכַד אָתֵי צַפְרָא, מְחַדֵּשׁ לוֹן נִשְׁמָתַיְיהוּ, הֲדָא הוּא דִכְתִיב, (איכה ג׳:כ״ג) חֲדָשִׁים לַבְּקָרִים רַבָּה אֱמוּנָתֶךָ. ר' יִצְחָק אָמַר אֲפִילּוּ לְכָל אָדָם נָמֵי. בְּהַאי עָלְמָא נָאִים בְּשִׁינְתֵיהּ, בְּכָל לַיְלָה, וְסָלְקָא נִשְׁמָתָא לְעֵילָא, וְאִשְׁתַּכְּחַת בְּכַמָּה חִיּוּבִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וּמְהֵימְנוּתָא רַבָּה, דְּקוּדְשָׁא בְּרִיךְ הוּא אַחְזַר לָהּ לְגוּפָא, וּמְחַדֵּשׁ לָהּ קוּדְשָׁא בְּרִיךְ הוּא. וְלָמָּה, רַבָּה אֱמוּנָתֶךָ. מִפְּנֵי שֶׁרַבָּה אֱמוּנָתֶךָ.</p>"],[9514011772,"<p>מִכָאן אָמַר רִבִּי יִצְחָק, הַמִּתְחַיֵּיב בְּמָמוֹן לַחֲבֵירוֹ, וַחֲבֵירוֹ מוֹצִיא לוֹ מַה שֶּׁיַּחֲזִיק בְּיָדוֹ, אָסוּר לוֹ לְהַחֲזִיק בּוֹ, עַד שֶׁיִּתְּנֵהוּ לוֹ חֲבֵירוֹ, וַאֲפִילּוּ שֶׁיִּתְּנֵהוּ לוֹ בֵּי דִינָא, הֲדָא הוּא דִכְתִיב, (שמות כ״ב:כ״ה) אִם חָבֹל תַּחְבֹּל שַׂלְמַת רֵעֶךָ.</p>"],[9514011773,"<p>רַבִּי יְהוּדָה בֶּן רִבִּי סִימוֹן אָמַר, (בראשית ב) וַיָּשֶׂם שָׁם אֶת הָאָדָם אֲשֶׁר יָצָר, בִּכְלַל. אָמַר רִבִּי שִׁמְעוֹן, (שם) וַיַּנִּיחֵהוּ בּגַּן עֵדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ. וְכִי מַאי עֲבוֹדָה הָכָא. אֶלָא עֲבוֹדַת הַנְּשָׁמָה, לְהַשְּׁלִים לָהּ בְּתַשְׁלוּמֶיהָ, מַה שֶּׁלֹּא הִשְׁלִימָה בָּזֶה הָעוֹלָם.</p>"],[9514011774,"<p>רַבִּי שִׁמְעוֹן אָמַר, הִנִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאָדָם הָרִאשׁוֹן בְּגַּן עֵדֶן, וְנָתַן לוֹ תּוֹרָתוֹ, לַעֲבוֹד בָּהּ, וְלִשְׁמוֹר מִצְוֹתֶיהָ. הֲדָא הוּא דִכְתִיב, (שם) וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן. וּכְתִיב (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁיִּהְיֶה לוֹ לָאָדָם הֲנָאָה בְּגַן זֶה, יַעֲסוֹק בָּהּ וְיִשְׁמוֹר אוֹתָהּ. וּמִפְּנֵי הָעִדּוּנִין וַהֲנָאוֹת שֶׁהָיוּ לוֹ לָאָדָם שָׁם, לֹא שָׁמַר תּוֹרָתוֹ, עַד שֶׁגֵּרְשָׁהוּ מִשָּׁם.</p>"],[9514011775,"<p>רַבִּי אַבָּא בְּשֵׁם ר' חִיָּיא אָמַר, עֵץ מַמָּשׁ הָיָה, וְהָיוּ שְׁנַיִם, הָאֶחָד הַנּוֹתֵן חַיִּים לָאָדָם. וְהָאֶחָד שֶׁהָאוֹכְלוֹ יֵדַע הַטוֹב וְהָרָע. לָדַעַת הַדֶּרֶךְ הַטוֹב וְהַיָּשָׁר, שֶׁיּוּכְשַׁר הָאָדָם. וְהַדֶּרֶךְ הָרַע, שֶׁיִּתְקַלְקֵל בָּהּ הָאָדָם. וּלְפִיכָךְ צִוָּהוּ הַקָדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יֹאכַל מִמֶּנּוּ, פֶּן יִדְחֶה הַטוֹב, וְיַחְזִיק בָּרָע.</p>"],[9514011776,"<p>וְעַל כֵּן נֶאֱמַר מִכָּל עֵץ הַגָן אָכֹל תֹּאכַל, זֶהוּ עֵץ הַחַיִּים, שֶׁהָיָה לוֹ לָאָדָם לֶאֱכוֹל מִמֶּנּוּ. וְהוּא לֹא חָטָא אֶלָּא בְּעֵץ הַדַּעַת טוֹב וָרָע, שֶׁנִּצְטַוָּוה שֶׁלֹּא יֹאכַל מִמֶּנּוּ. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:י״ז) וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת.</p>"],[9514011777,"<p>מִכָאן אָמַר רַבִּי שִׁמְעוֹן, גְּזֵירָה נִגְזְרָה עַל אָדָם, קוֹדֶם, לָמוּת, עַל שֶׁנִּלְקַח מִן הָאֲדָמָה. מַשְׁמַע דִּכְתִיב, בְּיוֹם אֲכָלְךָ מִמֶּנּוּ. מְלַמֵּד שֶׁאִלְמָלֵי לֹא חָטָא, הָיוּ לוֹ חַיִּים אֲרוּכִּים, כֵּיוָן שֶׁחָטָא, הוּא הָעוֹנֶשׁ, שֶׁיְּקַצֵּר יָמָיו, וְיָמוּת בְּאוֹתוֹ הַיּוֹם. לְאַחַר שֶׁעָשָׂה תְּשׁוּבָה, נָתַן לוֹ יוֹמוֹ דְּקוּדְשָׁא בְּרִיךְ הוּא, שֶׁהוּא אֶלֶף שָׁנָה.</p>"],[9514011778,"<p>וְזוֹ רְאָיָה שֶׁהַגְּזֵרָה הָיְתָה קוֹדֶם לָמוּת, שֶׁאִלְמָלֵא כָךְ, כְּשֶׁעָשָׂה תְּשׁוּבָה הָיָה לוֹ לְבַטֵל הַגְּזֵירָה. אֶלָּא אָמַר רַבִּי שִׁמְעוֹן, עָשָׂה תְּשׁוּבָה וּבִטֵל הַגְּזֵירָה שֶׁנִּגְזְרָה עָלָיו, בְּיוֹם אֲכָלְךָ מִמֶּנּוּ, וְהֶאֱרִיךְ לוֹ יָמִים שֶׁנָּתַן לוֹ יוֹמוֹ.</p>"],[9514011779,"<p>רַבִּי בְּרוֹקָא אָמַר, הוּא נִצְטַוָּוה עַל הַשֵּׁם, וְחָטָא בַּשֵּׁם. נִצְטַוָּוה עַל הַשֵּׁם, זֶהוּ הַשֵּׁם הַמְיוּחָד, דִּכְתִיב וְעֵץ הַחַיִּים וְגו'. וְהוּא חָטָא בַּשֵּׁם, זֶהוּ שֵׁם הַמְשׁוּתָּף, דִּכְתִיב וְעֵץ הַדַּעַת טוֹב וָרָע.</p>"],[9514011780,"<p>אָמַר רִבִּי אַבָּהוּ, וּמַה הַמַּקְרִיב קָרְבָּן לְשֵׁם זֶה, אָמְרָה תּוֹרָה (שמות כ״ב:י״ט) זוֹבֵחַ לָאֱלֹהִים יָחֳרָם. הַמַּחֲלִיף שְׁמוֹ הַמְיוּחָד בִּשְׁבִילוֹ, עַל אַחַת כַּמָּה וְכַמָּה.</p>"],[9514011781,"<p>וְחָטָא בַּשֵּׁם מְנָא לָן. אָמַר רִבִּי בְּרוֹקָא דִּכְתִיב (בראשית ג) \"וַתִּקַּח \"מִפִּרְי\"וֹ \"וַתֹּאכַ\"ל, שֶׁהוּא הַשֵּׁם הַיּוֹצֵא מִמֶּנּוּ, דּוּגְמַת הַפְּרִי הַיּוֹצֵא מִן הָעֵץ. אָמַר רִבִּי אַבָּהוּ, לְפִיכָךְ כִּנָּה כָּל הָעִנְיָן בְּאֵלּוּ אִילָנֵי גַּן עֵדֶן.</p>"],[9514011782,"<p>אָמַר רִבִּי יִצְחָק, חָזִינָן דְּהָא תְּלַת מִן חַבְרַיָיא, עַל דָּא אִתְעֲנָשׁוּ. אָמַר רִבִּי יְהוּדָה, הָא דְּאָמַר רִבִּי בְּרוֹקָא אֵין לְהַרְהֵר עוֹד בַּפָּרָשָׁה, דַּאֲנָא כְּהַאי גַוְונָא שְׁמַעְנָא מֵאֲבוֹי, וּכְעַן אִדְכַּרְנָא, וּמִכָּאן צָרִיךְ דְּרָשָׁה.</p>"],[9514011783,"<p>(שם ג) וְהַנָּחָשׁ הָיָ\"ה עָרוּ\"ם מִכָּל חַיַּת הַשָּׂדֶה. תָּאנֵי ר' יוֹסֵי, זֶהוּ יֵצֶר הָרָע, שֶׁהוּא הַנָּחָשׁ הַמֵּסִית לִבְנֵי אָדָם. וְלָמָּה נִקְרָא נָחָשׁ. מַה הַנָּחָשׁ הוֹלֵךְ עֲקַלָּתוֹן, וְאֵינוֹ הוֹלֵךְ בְּדֶרֶךְ יְשָׁרָה. כָּךְ יֵצֶר הָרָע, מַשְׂטִין לָאָדָם בְּדֶרֶךְ רָע, וְלֹא בְּדֶרֶךְ יָשָׁר.</p>"],[9514011784,"<p>תָּאנֵי ר' יוֹסֵי, מַאי הָיָה עָרוּם מִכָּל חַיַּת הַשָּׂדֶה, פִּקֵּחַ מֵאוֹתוֹ נֶפֶשׁ הַחַיָּה אֲשֶׁר בַּגּוּף, וְהוּא הָיָה הַמֵּסִית לָאָדָם, עַד שֶׁנִּגְרַשׁ מֵהֲנָאַת גַּן עֵדֶן.</p>"],[9514011785,"<p>תְּנַן הָתָם, אָמַר ר\"י בֶּן רִבִּי סִימוֹן, אַשְׁגַּחְנָא בְּהַאי מִלָּה דְּאָמַר רִבִּי בְּרוֹקָא, וְשָׁאִיל לֵיהּ, וְאַשְׁכַּחְנָא דְּעִיקַּר קַבָּלָה הֲוָה בִּידוֹי. וְהָכֵי אִתְגְּזַר בְּסִפְרָא קַדְמָאָה, דְּמַתְנִיתָּא דְּרַבִּי אֶלְעָזָר בֶּן עֲרָךְ.</p>"],[9514011786,"<p>אָמַר רַבִּי שִׁמְעוֹן, הַנָּחָשׁ כְּשֶׁהִשִּׁיא לָאִשָּׁה, מַה כְּתִיב. (שם) וַתֵּרֶא הָאִשָּׁה כִּי טוֹב. מַאי כִּי טוֹב. אָמַר רִבִּי אֶלְעָזָר בַּר שָׁלוֹם, הִסְכִּימָה בְדַעְתָּהּ כִּי הוּא טוֹב, שֶׁנֶּאֱמַר (תהלים קלה) כִּי טוֹב ה'. (שם קו) הוֹדוּ לַה' כִּי טוֹב. וְכִי תַאֲוָה הוּא לְעֵינַיִם, שֶׁהִיא הַתַּאֲוָה שֶׁמִּתְאַוִּים עֶלְיוֹנִים וְתַחְתּוֹנִים, לָדַעַת וּלְהַשִּׂיג, מִיָּד וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל.</p>"],[9514011787,"<p>אָמַר רִבִּי שִׁמְעוֹן, אִחְלְפָא שׁוּלְטָנָא בְּפוּלְחָנָא. אָמַר רִבִּי אֶלְעָזָר, כְּמָה דְאַתְּ אָמֵר (שמות כג) אַל תַּמֶּר בּוֹ, אַל תְּמִירֵנִי בּוֹ. אָמַר רִבִּי יְהוּדָה, וְלָא אֲמִינָא דְּלֵית לְהַרְהֵר עוֹד בַּפָּרָשָׁה דַּי בְּהָא דְּאָמַר רִבִּי בְּרוֹקָא בְּרֵישׁ פָּרָשָׁתָא, וְלָא אִצְטְרִיךְ יַתִּיר אֶלָּא דְּרָשָׁא. אָמַר רִבִּי יִצְחָק, מַאי (בראשית ג) וַיִּתְפְּרוּ עֲלֵה תְּאֵנָה, מְתַרְגֵּם רַב נַחְמָן בַּר אַחָא וַחֲבֵרוֹ, תַּסְקוּפֵי מִלִּין.</p>"],[9514011788,"<p>(שם) וַיִּשְׁמְעוּ אֶת קוֹל ה' אֱלֹהִים וְגו'. אָמַר רִבִּי פִּנְחָס, וּמַה קּוֹזְדִיטָא דַּאֲהִירְנָא בָּעְיָיא רוּחַ הַיּוֹם. תְּנַן אָמַר רִבִּי אֶלְעָזָר, אֲמִיטוֹן בִּבְהִירוּתָא, לְדָא דַּאֲמָרָן, לְמָה הוּא דוֹמֶה אָדָם בָּעוֹלָם הַזֶּה, לְצִפוֹרָא דְּאָזְלַת, כַּד נָפְקַת מִקִּינָהּ, וְלָא אַשְׁכָּחַת מַאן דְּאַכְנֵישׁ לָהּ. כָּךְ הוּא הָאָדָם, כֵּיוָן שֶׁהַנְּשָׁמָה יוֹצְאָה, שׁוּב אֵינוֹ יוֹדֵעַ, וּמֵבִין לְהַגּוּף. בַּר הַהוּא גּוּפָא, מִנְהִירוּ טוּבָא דְּאִיזְדַּמַּן לֵיהּ לְאִשְׁתַּעְשְׁעָא בְּגִנְתָּא דְּעֵדֶן.</p>"],[9514011789,"<p>אָמַר רִבִּי אַבָּא, מִתְהַלֵּךְ, מְהַלֵּךְ הֲוָה לֵיהּ לְמֵימַר, מַהוּ מִתְהַלֵּךְ. אָמַר רִבִּי בָּא, וְכִי חוֹשְׁבִין בְּנֵי אָדָם שֶׁהַקָדוֹשׁ בָּרוּךְ הוּא הָיָה. תָּא שְׁמַע, דִּכְתִיב אֶת קוֹל, הוּא דִּכְתִיב בֵּיהּ, (שמות ט) וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל. וְכֵן (יחזקאל א) וַיְהִי קוֹל מֵעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם. אָמַר רַב חִסְדָּא אָמַר רִבִּי יוֹחָנָן, קוֹל כְּתִיב, מִתְהַלֵּךְ לְרוּחַ, הֲדָא הוּא דִכְתִיב, (שם לז) וַיְהִי קוֹל כְּהִנָּבְאִי וְהִנֵּה רַעַשׁ.</p>"],[9514011790,"<p>אָמַר רִבִּי יוֹחָאי, וְהָא ר' יְהוּדָה חֲבֵרֵינוּ אֲמַר, דְּכָאן צָרִיךְ דְּרָשָׁא, וְאַתֶּם אוֹמְרִים מַעֲשֵׂה מֶרְכָּבָה. אָמַר רִבִּי אֲלֶכְּסַנְדְּרִי, יַתִּיר מֵעוֹבָדָא דְמֶרְכָּבָה הוּא, דְּהָא רָזִין עִילָּאִין אֲנַן חֲזֵינָן דְּאִתְגַּלְּיָין הָכָא.</p>"],[9514011791,"<p>תָּנוּ רַבָּנָן, כְּשֶׁחָלָה רַבִּי שִׁמְעוֹן בֶּן יוֹחָאי. עָאלוּ קַמֵּיהּ ר' פִּנְחָס, וְר' חִיָּיא, וְר' אַבָּהוּ. אָמְרוּ לוֹ, מַאן דְּהוּא קְיָימָא דְעָלְמָא, שָׁכִיב. אֲמַר לוֹן, לָא בִּי דִּינָא דִּלְעֵילָא מְעַיְינִין בְּדִינָאי, דְּהָא אֲנָא חֲזָאי דְּלֵית אֲנָא מִתְיְיהֵב לְמַלְאָכָא וּלְדַיָּינָא דִלְעֵילָא. דַּאֲנָא לָאו כִּשְׁאָר בְּנֵי נָשָׁא.</p>"],[9514011792,"<p>אֶלָּא הַאי דִינָא דִּילִי, קוּדְשָׁא בְּרִיךְ הוּא דַּיְינֵיהּ, וְלָא בִּי דִּינֵיהּ. וְהַיְינוּ דַּאֲמַר דָּוִד, בְּבָעוּתֵיהּ קַמֵּיהּ (תהילים מ״ג:א׳) שָׁפְטֵנִי אֱלֹהִים וְרִיבָה רִיבִי. וְכֵן שְׁלֹמֹה אֲמַר, (מלכים א ח׳:נ״ט) לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ, הוּא בִּלְחוֹדוֹי, וְלָא אַחֲרָן.</p>"],[9514011793,"<p>דְּהָא תָּנִינָן, כְּשֶׁהָאָדָם הוּא שׁוֹכֵב, בֵּי דִינָא דִּלְעֵילָא מִסְתַּכְּלִין בְּדִינוֹי, אִית מִנְּהוֹן דְּנָטָאן לְכַף זְכוּת, דְּאַחְזְיָין זְכוּתָא דְּבַר נָשׁ, וְאִית מִנְּהוֹן דְּנָטָאן לְכַף חוֹבָה, דְּאַחְזְיָין חוֹבָה דְּבַר נָשׁ. וּנְפֵיק אִינִישׁ מִן דִּינָא, כְּמָה דְּהוּא בָּעֵי.</p>"],[9514011794,"<p>אֲבָל מַאן דְּדָאִין לֵיהּ מַלְכָּא עִילָּאָה, דְּשַׁלִּיט עַל כּוֹלָא, הוּא טַב, וְלָא יָכִיל אִינִישׁ לְמֶהֱוֵי בְּהַהוּא דִינָא, בַּר טַב. מַאי טַעְמָא, דְּהָא תָּנִינָן, מְכִילוֹי דְּמַלְכָּא עִילָּאָה, נָטֵי לִזְכוּתָא תָּדִיר, וְהוּא כּוּלֵיהּ צַד רַחְמָנוּתָא, וּבְיָדוֹ לְשָׁבְקָא לְחֶטְאִין וְחוֹבִין, הֲדָא הוּא דִכְתִיב, (תהילים ק״ל:ד׳) כִּי עִמְךָ הַסְּלִיחָה וְגו', וְלֹא עִם אַחֵר.</p>"],[9514011795,"<p>וּבְגִין כָּךְ בָּעֵינָא קַמֵּיהּ דְּהוּא יָדִין דִּינָאי, וַאֲנָא אָעֵיל תְּלֵיסַר אַבָּבֵי לְעָלְמָא דְאָתֵי, דְּלָא אֲעֲבָרוֹ לוֹן בַּר אֲבָהָתָא, וְלָא יְהֵא מַאן דְּיִמְחֵי בְּיָדִי, וְעוֹד דְּלָא אֶתְבַּע רְשׁוּתָא מִנְּהוֹן.</p>"],[9514011796,"<p>אָמַר רַבִּי שִׁמְעוֹן מִלָּה, וְחָמוֹן בֵּי מַרְעֵיהּ, דְּלָא הֲוָה הוּא תַּמָּן. תְּוָוהוּ, וְלָא הֲוָה יָכִיל חַד מִנְּהוֹן לְמַלָּלָא בְּפוּמֵיהּ, מִדְחִילוּ רַבָּה דַּהֲוֵי עֲלֵיהוֹן. עַד דַּהֲווֹ יָתְבֵי, סָלֵיק לוֹן רֵיחִין דְּבוּסְמֵי סַגִּיאִין, וְכָל חַד וְחַד מִנְּהוֹן אִתְיַישַׁר חֵילֵיהּ, עַד דְּחָמוֹ לְרַבִּי שִׁמְעוֹן, וַהֲוָה מְמַלֵּל מִלִּין, וְלָא הֲוָה חָמָאן אַחֲרָן בַּר מִינֵיהּ.</p>"],[9514011797,"<p>לְבָתַר עִידָן, אֲמַר לוֹן רַבִּי שִׁמְעוֹן, חֲמִיתּוֹן מִידֵי. אָמַר לֵיהּ ר' פִּנְחָס, לָא, אֶלָּא כּוּלָּנָא תְּוָוהִין עַל דְּלָא חָמֵינָא לָךְ בְּבֵי מַרְעָךְ, זְמַן רַב, וְכַד חָמֵינָא לָךְ סָלֵיק לָךְ רֵיחִין דְּבוּסְמִין דְּגִנְתָּא דְּעֵדֶן, וְשָׁמַעְנָא קָלָךְ מְמַלֵּל, וְלָא יְדַעְנָא מָאן מְמַלֵּל עִמָּךְ.</p>"],[9514011798,"<p>אֲמַר לוֹן, וְלָא שְׁמַעְתּוּן מִלָּה אוֹחֲרָנָא בַּר מִדִּידִי. אֲמָרוּ לָאו. אֲמַר לוֹן, לֵית אַתּוּן חַזְיָין לְמֶחֱמֵי סְבַר עַתִּיק יוֹמִין.</p>"],[9514011799,"<p>אֲמַר לוֹן, אֵימָא לְכוֹ מִלָּה, תְּוַוהְנָא עַל ר' פִּנְחָס, דְּלָא חָמָא. דַּאֲנָא חָמִית לֵיהּ כְּעַן בְּהַהוּא עָלְמָא, לְתַתָּא מֵרַבִּי אֶלְעָזָר בְּרִי.</p>"],[9514011800,"<p>וּכְעַן שָׁדְרוּ בְּדִילִי מִלְּעֵילָא, וְאַחְזְיָן לִי אַתְרָא דְּצַדִּיקַיָא לְעָלְמָא דְּאָתֵי, וְלָא אִתְיְישַׁר בְּלִבָּאי דּוּכְתָּאי, בַּר עִם אֲחִיָּה הַשִּׁילוֹנִי. וּבָרֵירְנָא דּוּכְתָּאי, וְאָתֵינָא, וַאֲתוֹ עִמִּי תְּלַת מְאָה נִשְׁמָתִין דְּצַדִּיקַיָא, וְעֵילָא מִנְּהוֹן אָדָם הָרִאשׁוֹן, דְּהֲוָה יָתֵיב גַּבָּאי, וְהוּא הֲוָה מְמַלֵּל עִמִּי. וּבָעֵי, דְּלָא יִתְגַּלֵּי חוֹבֵיהּ לְכָל עָלְמָא. בַּר הַהוּא דְּאָמְרָה אוֹרַיְיתָא בְּגִינֵיהּ, וְאִתְכַּסֵּי בְּהַהוּא אִילָנָא דְּגִנְתָּא דְּעֵדֶן.</p>"],[9514011801,"<p>וַאֲמֵינָא לֵיהּ אֲנָא דְּהָא חַבְרַיָיא גִּלּוּ. אֲמַר הַהוּא דְּגִלּוּ חַבְרַיָיא בֵּינַיְיהוּ טַב וְשַׁפִּיר, אֲבָל לִשְׁאָר בְּנֵי עָלְמָא לָא. מַאי טַעְמָא, דְּחָס קוּדְשָׁא בְּרִיךְ הוּא עַל יְקָרֵיהּ, וְלָא בָּעָא לְפִרְסוּמֵי חוֹבֵיהּ, אֶלָּא בְּהַהוּא אִילָנָא דַּאֲמַר דַּאֲכַל מִנֵּיהּ.</p>"],[9514011802,"<p>וְקוּדְשָׁא בְּרִיךְ הוּא גָּלֵי לִי בְּרוּחַ הַקֹּדֶשׁ, וּלְחַבְרַיָיא, דְּלִישְׁתָּעוֹ אִינוּן בֵּינַיְיהוּ, וְלָא לְדַרְדְּקֵי דְּחַבְרַיָיא, וּלְאִינוּן דְּיֵיתוֹן לְעָלְמָא. דְּהוּא מִלָּה דְּלָא יָדְעֵי כָּל אִינְשֵׁי, וְטָעְיָין בֵּיהּ, לָאו מִשּׁוּם חוֹבָתָא דְחָב, אֶלָּא מִשּׁוּם יְקָרָא דִּשְׁמָא עִילָּאָה, דִּבְנֵי נָשָׁא לָא זְהִירִין בֵּיהּ, וּכְתִיב זֶה שְׁמִי לְעוֹלָם. וְיֵיתוֹן לְמִשְׁאַל מַה דְּלָא צְרִיכֵי לוֹן.</p>"],[9514011803,"<p>וְהַיְינוּ דִּכְתִיב, (שמות יט) פֶּן יֶהֶרְסוּ אֶל ה' לִרְאוֹת וְנָפַל מִמֶּנּוּ רָב, מַאי וְנָפַל מִמֶּנּוּ רָב. הָכֵי גָּזַרְנָא, הַאי חַבְרָא דְּאוֹרֵי שְׁמָא קַדִּישָׁא לְכוֹלָא, הוּא נָפֵיל וְנִתְפַּס בְּהַהוּא חוֹבָא, יַתִּיר מִנַּיְיהוּ, דִּכְתִיב וְנָפַל מִמֶּנּוּ רָב, הָרַב נוֹפֵל וְנִתְפַּס בְּאוֹתוֹ עָוֹן.</p>"],[9514011804,"<p>קָרֵיב לְגַבֵּיהּ רַבִּי אֶלְעָזָר בְּרֵיהּ, אָמַר לֵיהּ אַבָּא, מָה אֲנָא הָתָם. אָמַר לֵיהּ זַכָּאָה חוּלָקָךְ בְּרִי, זְמַן סַגֵּי יְהֵא דְּלָא תִּתְקַבֵּר גַּבָּאי, אֲבָל בְּהַהוּא עָלְמָא, דּוּכְתָּא דִּידִי וְדִידָךְ בָּרֵירְנָא. זַכָּאִין אִינוּן צַדִּיקַיָא, דְּזַמִּינִין אִינוּן לִמְשַׁבְּחֵי לְמָארֵי עָלְמָא, כְּאִינוּן מַלְאָכִין שַׁמָּשִׁין דְּקַמֵּיהּ, הֲדָא הוּא דִכְתִיב, (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ.</p>"],[9514011805,"<p>רַבִּי בָּא בְּשֵׁם רַב הוּנָא אָמַר, כֵּיוָן שֶׁחָטָא אָדָם, וְגָזְרוּ עָלָיו אוֹתָן הַגְּזֵרוֹת, גֵּרְשָׁהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָן הַהֲנָאוֹת וְהָעִידּוּנִין שֶׁהָיוּ לוֹ בְּעֵדֶן, וּמִינָּה שׁוֹמְרִים לְשַׁעֲרֵי גַּן עֵדֶן. וּמִי הֵם, הֵם הַכְּרוּבִים. הֲדָא הוּא דִכְתִיב, (בראשית ג) וַיַּשְׁכֵּן מִקֶּדֶם לְגַן עֵדֶן אֶת הַכְּרוּבִים וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. כְּדֵי לִשְׁמוֹר אוֹתוֹ הַדֶּרֶךְ וְהַפֶּתַח.</p>"],[9514011806,"<p>שֶׁאָז נִגְזַר, שֶׁלֹּא יְהֵא רְשׁוּת לְכָל אָדָם מִכָּאן וָאֵילָךְ, לְהִכָּנֵס שָׁם, זוּלָתִי הַנְּשָׁמוֹת הַצְּרוּפוֹת עַל יְדֵי הַכְּרוּבִים תְּחִלָּה. אִם רוֹאִים שֶׁהִיא רְאוּיָה לִיכָּנֵס, תִּכָּנֵס. וְאִם לָאו, דּוֹחִים אוֹתָהּ לַחוּץ, וְתִשָּׂרֵף בְּאוֹתוֹ הַלַּהַב, אוֹ תְּקַבֵּל עוֹנְשָׁהּ.</p>"],[9514011807,"<p>וְתָאנָא, כְּנֶגְדָם הָיוּ בַּמִּקְדָּשׁ, כְּשֶׁנִּכְנַס הַכֹּהֵן לִפְנַי וְלִפְנִים. דְּתַנְיָא, אָמַר רִבִּי אַבָּא אר\"י בְּשֵׁם רַב הוּנָא, לִפְנַי וְלִפְנִים הוּא דּוּגְמָתוֹ שֶׁל גַּן עֵדֶן. וּכְשֶׁנִּכְנַס הַכֹּהֵן לְשָׁם, נִכְנַס בִּנְּשָׁמָה, וְלֹא בְּגוּף. בְּאֵימָה, בְּיִרְאָה, בְּרֶתֶת, בְּזִיעַ, בִּנְקִיּוּת, בְּטָהֳרָה. וְהַכְּרוּבִים עוֹמְדִים שָׁם שׁוֹמְרִים, כְּדוּגְמַת אוֹתָם הַכְּרוּבִים הָעוֹמְדִים בְּשַׁעֲרֵי גַּן עֵדֶן.</p>"],[9514011808,"<p>זָכָה הַכֹּהֵן, נִכְנַס שָׁם בְּשָׁלוֹם, וְיוֹצֵא בְּשָׁלוֹם. לֹא זָכָה, מִבֵּין ב' הַכְּרוּבִים יוֹצֵא לַהַב, וְיִשָּׂרֵף וְיָמוּת בִּפְנִים. אָמַר רִבִּי יְהוּדָה, אַשְׁרֵי הַזּוֹכֶה לַעֲבוֹר מֵהֶם בְּשָׁלוֹם. אָמַר רִבִּי פְּרַחְיָה, אֵין לְךָ בָּעוֹלָם דָּבָר שֶׁאֵין בּוֹ מַעֲלָה כְּדוּגְמָתוֹ.</p>"],[9514011809,"<p>הַנָּחָשׁ שֶׁהֶעֱרִים לְחַוָּה, הוּא דָּבָר נוֹפֵל עַל הַלָּשׁוֹן. אָמַר רַב יוֹסֵף, הֵיאַךְ, אָמַר לֵיהּ, כְּתַרְגּוּמוֹ, נָחָשׁ חִיוְיָא הוּא, חִוְיָא זָכָר, וְהִיא חַוָּה, נְקֵבָה. דָּבָר נוֹפֵל עַל הַלָּשׁוֹן. כְּדוּגְמָתוֹ (במדבר כא) נְחַשׁ נְחשֶׁת, דָּבָר נוֹפֵל עַל הַלָּשׁוֹן.</p>"],[9514011810,"<p>אָמַר רִבִּי יוֹסֵי, וְהָא כְתִיב (בראשית ג׳:כ׳) וַיִּקְרָא הָאָדָם שֵׁם אִשְׁתּוֹ חַוָּה כִּי הִיא הָיְתָה אֵם כָּל חָי. אָמַר לֵיהּ ר' פְּרַחְיָה, קָרָא לָהּ עַל שֵׁם הֶעָתִיד, הָיָה לוֹ לִקְרוֹא אוֹתָהּ חַיָּה, עַל שֵׁם חַי, וְנִקְרְאָה עַל שֵׁם הֶעָתִיד חַוָּה, דַּעֲתִיד חִיוְיָה לְמִסְטֵי לְחַוָּה.</p>"],[9514011811,"<p>(שם) הוּא יְשׁוּפְךָ רֹאשׁ. אָמַר ר\"י, כָּךְ דַּרְכּוֹ שֶׁל נָחָשׁ, אֵין הַקָּשָׁה שֶׁלּוֹ מֵאָדָם, אֶלָּא בָּרֹאשׁ. וְאֵין הַנְּשִׁיכָה מֵהַנָּחָשׁ לְאָדָם, אֶלָּא בֶּעָקֵב. אָמַר רִבִּי יִצְחָק בַּר רַבִּי יוֹסֵי לְמַאן דְּאָמַר דְּיֵצֶר הָרָע הֲוָה, מַאי נֵימָא בְּהַאי פְּסוּקָא.</p>"],[9514011812,"<p>אָמַר לוֹ ר' יוֹסֵי, מְלַמֵּד שֶׁאֵין הֲרִיגָה לְנָחָשׁ אֶלָּא בָּרֹאשׁ. וּמִי הוּא הָרֹאשׁ. זֶה רֹאשׁ הַיְשִׁיבָה. וְאֵין הַנָּחָשׁ הַזֶּה הוֹרֵג לְאָדָם, אֶלָּא בֶּעָקֵב, כְּשֶׁעוֹשֶׂה לוֹ מַעֲשֵׂה עֲבֵירוֹת, וְדָשׁ בָּהֶם בֶּעָקֵב, הֲדָא הוּא דִכְתִיב, (תהילים מ״ט:ו׳) עֲוֹן עֲקֵבַי יְסוּבֵּנִי.</p>"],[9514011813,"<p>אָמַר רַבִּי יִצְחָק מֵהָכָא, (ישעיהו ה׳:י״ח) הוֹי מוֹשְׁכֵי הֶעָוֹן בְּחַבְלֵי הַשָּׁוְא וְכַעֲבוֹת הָעֲגָלָה חַטָאָה. כְּלוֹמַר, עוֹשֶׂה עֲבֵירוֹת וְדָשׁ בָּהֶם בֶּעָקֵב, שֶׁחוֹשֵׁב שֶׁאֵינָם כְּלוּם, כְּמוֹ חַבְלֵי הַשָּׁוְא, שֶׁאוֹרֵג הָעַכָּבִישׁ. וּלְאַחַר כֵּן הֵם כַּעֲבוֹת הָעֲגָלָה חַטָאָה, חֲזָקִים וְקָשִׁים, עַד שֶׁנֶּאֱסָפִים כֻּלָּם וְהוֹרְגִּים לָאָדָם, וְכֵן הוּא אוֹמֵר וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב, בְּאוֹתוֹ עֲוֹן הֶעָקֵב הוֹרֵג יֵצֶר הָרָע לָאָדָם.</p>"],[9514011814,"<p>אָמַר ר' יִצְחָק, בֹּא וּרְאֵה, כְּמוֹ שֶׁנִּתְקַלְּקְלוּ כָּךְ נִדּוֹנוּ. הַנָּחָשׁ בַּתְּחִלָּה, אַחֲרָיו הָאִשָּׁה, וְאַחֲרָיו הָאָדָם. הַיְינוּ דִּכְתִיב (בראשית ג׳:י״ז) וּלְאָדָם אָמַר כִּי שָׁמַעְתָּ לְקוֹל אִשְׁתְּךָ.</p>"],[9514011815,"<p>אָמַר רִבִּי יַעֲקֹב בַּר אִידֵי, אִם אָדָם חָטָא, אֲדָמָה מַה חָטְאָה. אֶלָּא אָמַר רִבִּי יַעֲקֹב בַּר אִידֵי, כְּשֶׁנִּבְרָא הָאָדָם, הַשָּׁמַיִם וְהָאָרֶץ הָיוּ עֵדִים. מְלַמֵּד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתָם עֵדִים, עַל מַה שֶּׁיַּעֲשֶׂה הָאָדָם, שֶׁלֹּא יֹאמַר מִי רוֹאֲנִי. וְאוֹתָם הָעֵדִים מְפַרְסְמִין חַטָאָיו, הֲדָא הוּא דִכְתִיב, (איוב כ׳:כ״ז) יְגַלּוּ שָׁמַיִם עֲוֹנוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ.</p>"],[9514011816,"<p>וְתָנָא, בְּאוֹתוֹ הַיּוֹם שֶׁעָבַר אָדָם, הַשָּׁמַיִם הֶחֱשִׁיכוּ אוֹרָם, וְהָאָרֶץ לֹא יָדְעָה מַה לַּעֲשׂוֹת, עַד שֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא וְקִלֵּל אוֹתָהּ, עַל שֶׁהִתְעַכְּבָה בְּעֵדוּתָהּ, שֶׁלֹּא תּוֹסִיף תֵּת כֹּחָהּ לִזְרוֹעַ וְלִקְצוֹר כְּבָרִאשׁוֹנָה, וְעָמְדָה בְּקִלְּלוֹתֶיהָ, עַד שֶׁבָּא אַבְרָהָם אָבִינוּ, וְנִתְבַּסֵּס הָעוֹלָם.</p>"],[9514011817,"<p>ר\"נ אָמַר, עַד שֶׁבָּא נֹחַ, דִּכְתִיב, (בראשית ה׳:כ״ט) זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ וּמֵעִצְּבוֹן יָדֵינוּ. וּלְפִיכָךְ נִקְרְאָה עַל שְׁמוֹ, דִּכְתִיב (שם ט) אִישׁ הָאֲדָמָה, עַל שֶׁיָּצְאָה מִקִּלְּלָתָהּ בִּשְׁבִילוֹ.</p>"],[9514011818,"<p>אָמַר רַב נַחְמָן בַּר יִצְחָק, אָדָם הָרִאשׁוֹן, כֵּיוָן שֶׁנִּטְרַד מִגַּן עֵדֶן, חָשַׁב שֶׁיָּמוּת מִיָּד, וְהָיָה בּוֹכֶה וּמִתְחַנֵּן, וְשָׁב בִּתְשׁוּבָה, עַד שֶׁקִּבְּלוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְשׁוּבָה, וְהֶאֱרִיךְ יָמָיו, וְקִיֵּים בּוֹ דְּבָרוֹ, דִּכְתִיב בְּיוֹם אֲכָלְךָ מִמֶּנּוּ, וְנָתַן לוֹ יוֹמוֹ, שֶׁהוּא אֶלֶף שָׁנָה. לְהוֹרוֹת לְכָל הָעוֹלָם, שֶׁהַקָדוֹשׁ בָּרוּךְ הוּא חַנּוּן וְרַחוּם הוּא, וּמְקַבֵּל בִּתְשׁוּבָה לַשָּׁבִים, וְאֵינוֹ חָפֵץ מֵהֶם, זוּלָתִי שֶׁיִּחְיוּ, דִּכְתִיב (יחזקאל י״ח:ל״א) וְלָמָּה תָמּוּתוּ בֵּית יִשְׂרָאֵל וְהָשִׁיבוּ וִחְיוּ.</p>"],[9514011819,"<p>אָמַר רִבִּי יִצְחָק, אַשְׁרֵיהֶם הַבָּנִים שֶׁהָאָב אוֹמֵר לָהֶם כָּךְ. וַוי לָהֶם לַבָּנִים, שֶׁאֵינָם שׁוֹמְעִים מִמֶּנּוּ. אָמַר רַב יְהוּדָה אָמַר רַב, לָא חָזִינָן רַחְמָנוּתָא כְּרַחְמָנוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא, בְּכָל מָקוֹם אַתְּ מוֹצֵא כְּשֶׁחָטְאוּ יִשְׂרָאֵל, וְשָׁבוּ לְמוּלוֹ, פָּשַׁט יָדוֹ וְקִבְּלָם, וּמָחַל לָהֶם מִיָּד, הֲדָא הוּא דִכְתִיב, (מיכה ז׳:י״ח) מִי אֵל כָּמוֹךָ נוֹשֵׂא עָוֹן וְעוֹבֵר עַל פֶּשַׁע.</p>"],[9514011820,"<p>פָּרָשָׁתָא ח (בראשית ד) וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ. ארִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, יֵשׁ לָנוּ לְהַרְהֵר בְּהָא פָּרָשָׁתָא, וְכָּל שֶׁכֵּן בְּהַאי פְּסוּקָא, דְּאָמְרָה חַוָּה, קָנִיתִי אִישׁ אֶת ה'.</p>"],[9514011821,"<p>אָמַר רִבִּי יִצְחָק, אֲנָא יְדַעְנָא לֵיהּ כִּפְשִׁיטוּתֵיהּ. דְּהָא תְּנַן, אָמַר רַב יְהוּדָה אָמַר רַב, הַאי מַאן דְּאִתְיְילֵיד לֵיהּ בַּר, כַּד שָׁרֵי לְמַלָּלָא, חוֹבָה עֲלֵיהּ לַאֲלָפָא לֵיהּ פְּסוּקֵי דְאוֹרַיְיתָא, דְּאִינוּן דְּחִילוּ מִן קֳדָם ה', דְּכַד יִרְבֵּי יַדְכַּר לוֹ לְאִינוּן כְּתוּבִין, לְדַחֲלָא מִן מָארֵיהּ.</p>"],[9514011822,"<p>רַבִּי עֲקִיבָא, הֲוָה יָתֵיב קַמֵּיהּ דְּר' אֱלִיעֶזְר, אָמַר לֵיהּ מַאי הַאי פָּרָשָׁתָא דִפְסִיקָא דָא, דַּאֲמַר וַתֵּלֶד אֶת קַיִן, וַתֹּאמֶר קָנִיתִי אִישׁ אֶת ה'. אָמַר לֵיהּ, עֲקִיבָא, אֵימָא לָךְ, יוֹמָא דְּר' בְּרוֹקָא וּשְׁאָר חַבְרַיָיא גִּלּוּ הַהוּא חוֹבָה דַּעֲבֵיד אָדָם, לָא הֲוָה אִצְטְרִיךְ לְאִינוּן דְּלָא יָדְעֵי עֲמִיקְתָּא וּמַסְתַּרְתָּא. וְהַהוּא יוֹמָא דְּאִתְגְּלֵי, אִשְׁתְּמַע כֹּלָּא מֵהַאי פְּסוּקָא.</p>"],[9514011823,"<p>אָדָם נִצְטַוָּה עַל הַשֵּׁם, וְחָטָא בַּשֵּׁם. נִצְטַוָּה עַל הַשֵּׁם, הוּא הַשֵּׁם הַמְיוּחָד, דִּכְתִיב (שם ב) וְעֵץ הַחַיִּים וְגו'. וְחָטָא בַּשֵּׁם, זֶהוּ שֵׁם הַמְשׁוּתָּף, דִּכְתִיב וְעֵץ הַדַּעַת טוֹב וָרָע.</p>"],[9514011824,"<p>וְחַוָּה הָיְתָה תְּחִלָּה בַּעֲבֵירָה עַל זֶה. דִּכְתִיב (שם ג) וַתִּקַּח מִפִּרְיוֹ. וּלְאַחַר שֶׁחָטְאוּ, וְיָדְעוּ עֲוֹנָם עַל מַה שֶּׁעָבְרוּ, הִתְמַרְמְרוּ עַל מַה שֶּׁחָטְאוּ, וְהִיא בְּיוֹתֵר, מִפְּנֵי שֶׁהִיא הָיְתָה תְּחִלָּה לָעֲבֵירָה, לַעֲבוֹר עַל שְׁמוֹ הַגָּדוֹל. כֵּיוָן שֶׁנּוֹלַד לָהּ בֵּן, הִרְגִּישָׁה בַּדָּבָר, וְאָמְרָה קָנִיתִי אִישׁ אֶת ה' שֶׁהוּא הַשֵּׁם הַמְיֻחָד, וְעַל כֵּן לֹא אָמְרָה הַשֵּׁם הַמְשׁוּתָּף.</p>"],[9514011825,"<p>אָמַר רִבִּי עֲקִיבָא, הַאי טַעְמָא, חוֹזֵר עַל מַה דְּאָמַר רִבִּי אַבָּהוּ, (שמות כב) זוֹבֵחַ לָאֱלֹהִים יָחֳרָם. אָמַר רִבִּי אֱלִיעֶזְר, חָזְרָה חַוָּה לְהוֹדוֹת עַל אוֹתוֹ עָוֹן שֶׁעָבְרָה, וְאָמְרָה, לֹא יִהְיֶה זֶה כָּמוֹנוּ, לָתֵת כָּבוֹד לְאַחֵר זוּלָתוֹ. אֲבָל זֶה יִהְיֶה אֶת הַשֵּׁם מַמָּשׁ, וְלֹא לְאַחֵר.</p>"],[9514011826,"<p>אָמַר רִבִּי יִצְחָק, וְשַׁפִּיר קָאָמַר ר' עֲקִיבָא, דְּאִתְחַזַּר עִנְיָינָא עַל מַה דְּאָמַר רִבִּי אַבָּהוּ. וְכֵן חַוָּה אָמְרָה אֶת ה', וְלֹא לְשֵׁם אַחֵר. וְכֵן חַנָּה אָמְרָה (שמואל א א) וּנְתַתִּיו לַה' כָּל יְמֵי חַיָּיו, וְלֹא לְשֵׁם אַחֵר. וְעַל זֶה אָמְרָה תּוֹרָה, (שמות לד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר, כִּי ה' קַנָּא שְׁמוֹ, אֵל קַנָּא הוּא.</p>"],[9514011827,"<p>אָמַר רִבִּי יְהוּדָה, עַד אֵימָתַי יְטַיְילוּן חַבְרַיָיא בְּרָזִין עִילָּאִין דְּמַלְכָּא. אָמַר רַבִּי אֲלֶכְּסַנְדְּרָאי, תָּנִינָן, מוֹסְרִין סִתְרֵי תוֹרָה לַחֲבֵרִים הָרְאוּיִים לְכָךְ, כְּגוֹן אֲנַן וְחַבְרַיָיא כְּגווָֹנָן.</p>"],[9514011828,"<p>(בראשית ד) וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הֶבֶל, אָמַר רִבִּי אֱלִיעֶזְר לְרַבִּי עֲקִיבָא, מַה שְּׁמִיעַ לָךְ בְּהַאי. אָמַר לֵיהּ עַל כָּךְ אֲנָא יָתֵיב קַמָּךְ. אָמַר לֵיהּ, אַסְתֵּים פּוּמָךְ, וּפְתַח עֵינָךְ וְאוּדְנָךְ, וַאֲצֵית.</p>"],[9514011829,"<p>דְּרֶמֶז הוּא דְקָא רָמַז, עַל הַהוּא שְׁמָא זְעֵירָא, דְּאִתְאֲצַל מִשְּׁמָא קַדִּישָׁא, דַּאֲנָא וְאַתְּ יְדַעְנָא. וּבְהַאי שְׁמָא חָבְיָין סַגִּיאִין בְּנֵי נָשָׁא, וְהוּא רֶמֶז מְהֵימְנוּתָא, לְמַאן דְּאִסְתַּכַּל בְּחָכְמְתָא.</p>"],[9514011830,"<p>עוֹד אָמַר רִבִּי אֱלִיעֶזְר, עֲקִיבָא, רֶמֶז דְּאִתְקַטַל הֶבֶל, אוֹרֵי עַל מְהֵימְנוּתָא דִשְׁמָא יַקִּירָא עִילָּאָה דְּמַלְכָּא, דִּכְתִיב (ישעיהו ב׳:י״א) וְנִשְׂגָּב ה' לְבַדּוֹ. אָמַר רִבִּי עֲקִיבָא, וַוי לְעָלְמָא כַּד תֵּיפוֹק מִנֵּיהּ, כְּעַן אֲנָא מִסְתַּכֵּל בְּחָכְמְתָא סַגִּיאָה. אָמַר לֵיהּ, הָא אֲמָרִית לָךְ אַסְתֵּים פּוּמָךְ, דְּהָא חָזֵינָא דְּדַי לִי וְלָךְ בְּעָלְמָא.</p>"],[9514011831,"<p>אָמַר ר' יְהוּדָה, נִתְחַזֵּר קַיִן לִהְיוֹת עוֹבֵד אֲדָמָה, וְהֶבֶל רוֹעֵה צֹאן, זֶה הֵבִיא קָרְבָּן, וְזֶה הֵבִיא קָרְבָּן. אָמַר רִבִּי יְהוּדָה, קַיִן בָּא בְּגַסּוּת הָרוּחַ, וְהֶבֶל בִּנְמִיכוּת הָרוּחַ, דִּכְתִיב (תהילים נ״א:י״ט) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. מַה כְּתִיב (בראשית ד׳:ד׳-ה׳) וַיִּשַׁע ה' אֶל הֶבֶל וְאֶל מִנְחָתוֹ וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה. אָמַר רִבִּי יְהוּדָה, לָמָּה נָפְלוּ פָנָיו, עַל שֶׁלֹּא נִתְקַבְּלָה מִנְחָתוֹ.</p>"],[9514011832,"<p>וְתָאנָא, אר\"י, אוֹתוֹ הַיּוֹם רֹאשׁ הַשָּׁנָה הָיָה, יוֹם שֶׁדִּין כָּל הַנְּשָׁמוֹת, עוֹבְרִים לְפָנָיו. אָמַר לוֹ, לָמָּה חָרָה לְךָ, הֲלֹא אִם תֵּיטִיב שְׂאֵת, אָמַר רִבִּי יְהוּדָה, כְּלוֹמַר אִם תֵּיטִיב, יִהְיֶה לְךָ שְׂאֵת.</p>"],[9514011833,"<p>לַפֶּתַח חַטָאת רוֹבֵץ, כְּלוֹמַר, לְאוֹתָם פִּתְחֵי גַּן עֵדֶן, שֶׁהַנְּשָׁמוֹת עוֹבְרוֹת בּוֹ, חַטָאת רוֹבֵץ. הַחַטָאת שֶׁתַּעֲשֶׂה יִהְיֶה מְזוּמָן שָׁם, וְשָׁם תְּקַבֵּל עוֹנְשֶׁךָ. וְאֵלֶיךָ תְּשׁוּקָתוֹ, כְּלוֹמַר אִם תֵּטִיב מַעֲשֶׂיךָ, וְהַחַטָאת הַהוּא יִכְסוֹף לְךָ שֶׁתַּעֲשֶׂה עֲבֵירוֹת. אַתָּה תִּמְשָׁל בּוֹ, שֶׁלֹּא יוּכַל לְקַטְרֵג עִמְךָ.</p>"],[9514011834,"<p>תָּאנָא, אָמַר רִבִּי יוֹסֵי, אֲנָא חָמֵינָא לְרַבִּי עֲקִיבָא, שֶׁשָּׁאַל לְרַבִּי אֱלִיעֶזְר דָּבָר זֶה. אָמַר לֵיהּ, עֲקִיבָא, סַק עֵינָךְ לְעֵילָא, וְאַתְּ תִּיב גַּבַּאי, דְּהָא מְפֹרָשׁ כּוֹלָּא בַּמֶּה דַאֲמַרְנָא. זְקַף עֵינוֹי, לְבָתַר אַרְכִין רֵישֵׁיהּ, אֲמַר, הָא עֲבִדְּנָא כְּעוֹבָדָא דְּחִיוְּיָא, וְלָא יְדַעְנָא. קָרֵיב גַּבּוֹי ר' אֱלִיעֶזְר, וְלָחִישׁ לֵיהּ, אָתָא ר' עֲקִיבָא, וּנְשֵׁיק יְדוֹי, וּבְכָה, וַאֲמַר, כּוֹלָּא הוּא כְּמָה דַּאֲמַרְתְּ בְּקַדְמִיתָא. זָקְפָאן זְקִיפָן, תַּתָּאָן תַּתָּאִין, דְּלָא יָכֵיל קוּדְשָׁא בְּרִיךְ הוּא בַּהֲדֵי שׁוּתָּפִין.</p>"],[9514011835,"<p>אָמַר ר' שִׁמְעוֹן, חַוָּה אָמְרָה, שֶׁקָּנְתָה אִישׁ אֶת ה', שֶׁהוּא ה' הַמְיוּחָד. וְהוּא קִלְקֵל מַעֲשָׂיו, וְלֹא רָצָה לַעֲמוֹד בְּדֶרֶךְ הַיָּשָׁר, הֲדָא הוּא דִכְתִיב, (שם) וַיֵּצֵא קַיִן מִלִּפְנֵי ה', יָצָא מֵאוֹתוֹ הַכְּלַל שֶׁאָמְרָה אִמּוֹ.</p>"],[9514011836,"<p>וּבִשְׁבִיל כָּךְ מַה כְּתִיב. וַיֵּשֶׁב בְּאֶרֶץ נוֹד, שֶׁהָיָה נָד בָּאָרֶץ. וְהוּא כְּמוֹ כֵן עָשָׂה תְּשׁוּבָה, כְּשֶׁהוֹדָה עַל חַטָאתוֹ, וְקִבֵּל עָלָיו עוֹנְשׁוֹ. דְּתָנִינָן, כָּל הַמִּתְוַדֶּה חַטֹאתָיו וּמִתְבַּיֵּישׁ מֵהֶן מוֹחֲלִין לוֹ מִיָּד עַל כָּל עֲוֹנוֹתָיו. הֲדָא הוּא דִכְתִיב, (משלי כ״ח:י״ג) וּמוֹדֶה וְעוֹזֵב יְרוּחָם.</p>"],[9514011837,"<p>ר' חִיָּיא אֲמַר מֵהָכָא, (ויקרא ה׳:ה׳) וְהִתְוַדָּה אֲשֶׁר חָטָא, וְנֶאֱמַר (שם) וְנִסְלַח לוֹ. ר' יֵיסָא אָמַר, אֵין דָּבָר בָּעוֹלָם עוֹמֵד בִּפְנֵי הַתְּשׁוּבָה. קַיִן נִגְזַר עָלָיו נָע וָנָד תִּהְיֶה בָּאָרֶץ, וּכְשֶׁעָשָׂה תְּשׁוּבָה, פָּקַע הַחֵצִי. דִּכְתִיב, (בראשית ד׳:י״ב) וַיֵּשֶׁב בְּאֶרֶץ נוֹד, אֲבָל נָע לֹא נֶאֱמַר.</p>"],[9514011838,"<p>תָּנוּ רַבָּנָן, עַל הַכֹּל הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹחֵל, וְאֵינוֹ מוֹחֵל עַל כְּבוֹד שְׁמוֹ. וּמִי אֵינוֹ מוֹחֵל, וַהֲרֵי מְנַשֶּׁה מֶלֶךְ יְהוּדָה הֵמִיר כְּבוֹדוֹ שֶׁל מָקוֹם בַּהֲבָלִים. שָׁאנֵי מְנַשֶּׁה, דְּהוּא בְּגַרְמֵיהּ יָדַע דְּהֶבֶל הוּא, וְלָא שַׁוֵּי לֵיהּ עִיקָּר בְּלִבֵּיהּ, דִּבְרֵי ר' יְהוּדָה. ר' שִׁמְעוֹן אוֹמֵר, אֵין לְךָ דָּבָר שֶׁבָּעוֹלָם שֶׁעוֹמֵד בִּפְנֵי הַתְּשׁוּבָה כְּלַל.</p>"],[9514011839,"<p>אָמַר רִבִּי יִצְחָק, מַאי דִּכְתִיב, (בראשית ד׳:כ״ב) וַאֲחוֹת תּוּבַל קַיִן נַעֲמָה. אֶלָּא אָמַר רִבִּי יִצְחָק, צַדֶּקֶת הָיְתָה, וּנְעִימָה בְּמַעֲשֶׂיהָ. ר' אַבָּהוּ אָמַר, פְּשׁוּטוֹ שֶׁל מִקְרָא מוֹרֶה, עַל שֶׁהָיְתָה חֲכָמָה בִּמְלֶאכֶת הַבַּרְזֶל, כְּמוֹ אָחִיהָ תּוּבַל קַיִן. מַשְׁמַע דִּכְתִיב, הוּא הָיָה אֲבִי כָּל חֹרֵשׁ נְחשֶׁת וּבַרְזֶל, וַאֲחוֹת תּוּבַל קַיִן נַעֲמָה, הוּא הוֹצִיא אוּמָּנוּת זוֹ, וַאֲחוֹתוֹ עִמּוֹ. הֲדָא הוּא דִכְתִיב, וַאֲחוֹת תּוּבַל קַיִן נַעֲמָה, שֶׁהָיְתָה בְּקִיאָה כְּמוֹתוֹ, וא\"ו דְּוַאֲחוֹת מוֹסִיף עַל הָעִנְיָן שֶׁל מַעְלָה.</p>"],[9514011840,"<p>רַבִּי בָּא אָמַר, אִמָּן שֶׁל שֵׁדִים הָיְתָה, וְהוֹלִידָה אוֹתָם. דְּהָא אִימָּא דְּאַשְׁמְדַאי, מַלְכָּא דְּשֵׁידֵי, נַעֲמָה שְׁמָהּ. ר' יִצְחָק בְּשֵׁם ר' יוֹחָנָן אָמַר, עַל שֵׁם יוֹפְיָהּ נִקְרֵאת כָּךְ, וּמִמֶּנָּהּ יָצְאוּ אוֹתָן דִּכְתִיב (שם ו) כִּי טוֹבוֹת הֵנָּה, בְּמַרְאֶה וּבְיוֹפִי.</p>"],[9514011841,"<p>אָמַר רַבִּי יוֹסֵי, לָמָּה נֶאֱמַר בְּשֵׁת (שם ה) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ, וּבְקַיִן וּבְהֶבֶל לֹא נֶאֱמַר. אָמַר לֵיהּ ר' חִיָּיא, קַיִן וְהֶבֶל לֹא הָיוּ, אֶלָּא לְאַחֲזָאָה רְמִיזָא עִילָּאָה, וְרָזָא יַקִּירָא, וְלָא אָתוֹ לְאִתְיַשְּׁבָא עָלְמָא מִנְהוֹן. אֲבָל שֵׁת, לָא אָתָא לְעָלְמָא, אֶלָּא לְאִשְׁתַּלְשְׁלָא עָלְמָא מִינֵיהּ, וּבְגִין כָּךְ אֲמַר בִּדְמוּתוֹ כְּצַלְמוֹ.</p>"],[9514011842,"<p>תַּנְיָא חֲנוֹךְ בֶּן יֶרֶד צַדִּיק הָיָה, וְקִבֵּל עַל עַצְמוֹ לְהַרְשִׁיעַ. וּלְקָחוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹדֶם זְמַנּוֹ, לַעֲשׂוֹת חֶסֶד עִמּוֹ וְשֶׁיִּתֵּן לוֹ שָׂכָר טוֹב לָעוֹלָם הַבָּא.</p>"],[9514011843,"<p>ר' אַבָּהוּ אָמַר, אֲנַן תְּנַן, (שם כא) כִּי שָׁמַע אֱלֹהִים אֶת קוֹל הַנַּעַר בַּאֲשֶׁר הוּא שָׁם. אִיכָּא דְּאָמְרֵי בַּאֲשֶׁר הוּא שָׁם, שֶׁהָיָה צַדִּיק בְּאוֹתָהּ שָׁעָה. וּלְפִיכָךְ שָׁמַע הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת קוֹלוֹ.</p>"],[9514011844,"<p>וַאֲנַן לֹא גַּזְרִינָן הָכֵי בְּמַתְנִיתִין, דְּהָא אָמַר רִבִּי יְהוּדָה אָמַר רִבִּי יִצְחָק, לָמָּה נִתְגָּרֵשׁ יִשְׁמָעֵאל מִבֵּיתוֹ שֶׁל אַבְרָהָם, וּמָה רָאֲתָה שָׂרָה שֶׁאָמְרָה גָּרֵשׁ אֶת הָאָמָה הַזֹּאת וְאֶת בְּנָהּ, אֶלָּא הָכָא כְּתִיב, (שם) וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית אֲשֶׁר יָלְדָה לְאַבְרָהָם מְצַחֵק. אָמַר רִבִּי יִצְחָק, אֵין מְצַחֵק אֶלָּא בַּעֲבוֹדָה זָרָה. כְּתִיב הָכָא מְצַחֵק, וּכְתִיב הָתָם (שמות ל״ב:ו׳) וַיָּקוּמוּ לְצַחֵק, מַה לְּהַלָּן עֲבוֹדָה זָרָה, אַף כָּאן עֲבוֹדָה זָרָה. וּבְהַהִיא שַׁעֲתָא רָשָׁע הֲוָה, אִם כֵּן בְּמַאי נוֹקִים בַּאֲשֶׁר הוּא שָׁם.</p>"],[9514011845,"<p>אֶלָּא מֵהַהוּא דְּגָזַרְנָא בְּמַתְנִיתִין דִּילָן, דְּאָמַר רִבִּי יְהוּדָה, אֵין בֵּית דִּין שֶׁל מַעְלָה דָּנִין אֶת הָאָדָם, עַד שֶׁיִּהְיֶה בֶּן כ' שָׁנָה. וּבֵית דִּין שֶׁל מַטָה, מִי\"ג שָׁנִים וּלְמַעְלָה. וְיִשְׁמָעֵאל בְּהַהִיא שַׁעֲתָא, לֹא הָיָה בַּר כ' שָׁנָה, וּלְפִיכָךְ לֹא דָּנוּהוּ, דְּהָא רָאוּי הָיָה לְעוֹנְשָׁא, אֶלָּא דְּיוֹמוֹהִי הוּא דְּלָא חִיְיבוּהוּ, וְהַיְינוּ דִּכְתִיב, בַּאֲשֶׁר הוּא שָׁם, בְּיוֹמִין דְּהוּא שָׁם.</p>"],[9514011846,"<p>אָמַר רִבִּי יִשְׁמָעֵאל, וְהָא חֲזִינָן רַבְיָא דְּלֵיתֵיהּ בַּר עֶשְׂרִים, וְהוּא טַב וְקוֹרֵא וְשׁוֹנֶה וּמֵת, מַאן סָלֵיק לֵיהּ מֵעָלְמָא. אִי תֵימָא בְּחוֹבֵיהּ דַּאֲבוּהָ. לָא. דְּהָא אִיהוּ מִי\"ג וּלְעֵילָא. וְאִי תֵימָא בְּחוֹבִין דִּידֵיהּ, הָא לֵיתֵיהּ בַּר כ' שָׁנָה.</p>"],[9514011847,"<p>אָמַר רִבִּי יְהוּדָה, מלה\"ד, לְמֶלֶךְ שֶׁהָיָה לוֹ פַּרְדֵּס, וְיוֹם אֶחָד נִכְנַס לְטַיֵּיל בְּאוֹתוֹ פַּרְדֵּס, וְרָאָה שׁוֹשַׁנִּים קְטַנִּים צוֹמְחִים בְּתוֹכוֹ, וְהָיָה עוֹלֶה רֵיחָם לְפָנָיו שֶׁאֵין כְּמוֹתָם בָּעוֹלָם, אָמַר הַמֶּלֶךְ, אִי עַכְשָׁיו כְּשֶׁהֵם קְטַנִּים כָּךְ, כְּשֶׁיִּגְדְּלוּ עַל אַחַת כַּמָּה וְכַמָּה.</p>"],[9514011848,"<p>לְאַחַר יָמִים נִכְנַס בְּאוֹתוֹ פַּרְדֵּס, וְהָיָה חוֹשֵׁב שֶׁיִּמְצָא אוֹתָם הַשּׁוֹשַׁנִּים שֶׁנָּתְנוּ רֵיחַ בַּתְּחִלָּה כְּשֶׁהָיוּ לַחִים וּקְטַנִּים וּמַעֲלִים רֵיחַ, גְּדוֹלִים וְטוֹבִים עַתָּה, וְיֶהֱנֶה מֵהֶם. כֵּיוָן שֶׁהִשְׁגִּיחַ בָּהֶם, רָאָה שֶׁהֵם יְבֵשִׁים בְּלֹא רֵיחַ. וְכָעַס, אָמַר, אִלּוּ בַּתְּחִלָּה כְּשֶׁהָיוּ לַחִים וְטוֹבִים וּמַעֲלִים רֵיחַ, לִקַטְתִּים, הָיִיתִי נֶהֱנֶה בָהֶם, עַכְשָׁיו בַּמֶּה אֶהֱנֶה, הָא יְבֵשִׁים הֵם.</p>"],[9514011849,"<p>לַשָּׁנָה הָאַחֶרֶת, נִכְנַס הַמֶּלֶךְ בַּפַּרְדֵּס, וְרָאָה שׁוֹשַׁנִּים קְטַנִּים וְנוֹתְנִים רֵיחַ, אָמַר הַמֶּלֶךְ, לִקְטוּ אוֹתָן עַכְשָׁיו, וְאֶהֱנֶה בָּהֶן, קוֹדֶם שֶׁיִּיבְּשׁוּ, כְּמוֹ שֶׁעָשׂוּ קוֹדֶם לָכֵן.</p>"],[9514011850,"<p>כָךָ הַקָּדוֹשׁ בָּרוּךְ הוּא, רוֹאֶה בְּנֵי אָדָם קְטַנִּים, וְנוֹתְנִין רֵיחַ, וְהַכֹּל גָּלוּי לְפָנָיו, וְרוֹאֶה שֶׁעֲתִידִין לְהַרְשִׁיעַ, וְיִהְיוּ חֲשׁוּבִים כְּקַשׁ יָבֵשׁ, וּמַקְדִּים לָהֶם חֶסֶד, כְּדֵי לֵיהָנוֹת בָּהֶם בַּגַּן עֵדֶן, וְעַכְשָׁיו כְּשֶׁהֵם טוֹבִים, מְסַלְּקָן מִן הָעוֹלָם הַזֶּה, לִיתֵּן לָהֶם שָׂכָר טוֹב בָּעוֹלָם הַבָּא. הֲדָא הוּא דִכְתִיב, (שיר השירים ו) אֲנִי לְדוֹדִי וְדוֹדִי לִי הָרוֹעֶה בַּשּׁוֹשַׁנִּים, הַמַּנְהִיג עוֹלָמוֹ כְּעִנְיַן שׁוֹשַׁנִּים.</p>"],[9514011851,"<p>אָמַר רִבִּי אַבָּהוּ, אֲנָא מְסַיֵּיעַ לְהָא דְּאָמַר רִבִּי יְהוּדָה, דְּהָא חָזֵינָן כְּהַאי גַּוְונָא דְּעָבִיד הַקָּדוֹשׁ בָּרוּךְ הוּא עִם יָרָבְעָם בֶּן נְבָט, דְּכַד הֲוָה רַבְיָא הֲוָה זַכַּאי וְטַב. דִּתְנַן, מַאי דִּכְתִיב, (מלכים א י״א:כ״ט) וּשְׁנֵיהֶם לְבַדָּם בַּשָּׂדֶה, מְלַמֵּד שֶׁשְּׁקוּלִים הֵם בְּצִדְקוּתָם וּבִזְכוּתָם מִכָּל יִשְׂרָאֵל.</p>"],[9514011852,"<p>אָמַר ר' בְּרֶכְיָה, בְּאוֹתָהּ שָׁעָה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַפַּמַּלְיָא שֶׁל מַעְלָה, רֵיחוֹ שֶׁל יָרָבְעָם עוֹלֶה לְפָנַי, וַאֲנִי רוֹצֶה לְסַלְּקוֹ מִן הָעוֹלָם עַכְשָׁיו, כְּשֶׁיֵּשׁ בּוֹ רֵיחַ. אָמְרוּ לְפָנָיו, רִבּוֹנוֹ שֶׁל עוֹלָם, אַתָּה דַּיָּין אֱמֶת, אִם עַכְשָׁיו הוּא כֵּן, כָּל שֶׁכֵּן כְּשֶׁיִּגְדַּל. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, גָּלוּי וְיָדוּעַ לְפָנַי שֶׁיַּעֲשֶׂה הָרַע בְּעֵינַי. אָמְרוּ לְפָנָיו, רִבּוֹנוֹ שֶׁל עוֹלָם, אִם לְפָנֶיךָ גָּלוּי, לָנוּ וְלִפְנֵי כָּל הָעוֹלָם מִי גָלוּי. הִנִּיחוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9514011853,"<p>מַה כְּתִיב (שם יב) וַיִּוָּעַץ הַמֶּלֶךְ וַיַּעַשׂ שְׁנֵי עֶגְלֵי זָהָב, חָטָא וְהֶחְטִיא. בְּאוֹתָהּ שָׁעָה אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא אָמַרְתִּי לָכֶם שֶׁאֲנִי רוֹצֶה לְסַלְּקוֹ מִן הָעוֹלָם קוֹדֶם זֶה, חֲבָל דַּעֲבִידַת כֵּן.</p>"],[9514011854,"<p>בָּא אֲבִיָה בְּנוֹ, וְהָיָה עוֹשֶׂה טוֹב כְּשֶׁהָיָה קָטָן, וּמַה טוֹב הָיָה עוֹשֶׂה, אָמַר רִבִּי יוֹסֵי אָמַר רִבִּי חֲנִינָא, עוֹלֵי הָרֶגֶל הָיוּ עוֹלִים עַל יָדוֹ, שֶׁלֹּא מִדַּעַת אָבִיו. רָאָה הַקָדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא טוֹב, וְסִלְּקוֹ מֵהָעוֹלָם קֹדֶם יָמָיו, כְּדֵי לַעֲשׂוֹת חֶסֶד עִמּוֹ, וּלְהַנְחִילוֹ לָעוֹלָם הַבָּא, קוֹדֶם שֶׁיַּבְאִישׁ רֵיחוֹ, וְזֶהוּ הַחֶסֶד שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם בְּרִיּוֹתָיו.</p>"],[9514011855,"<p>כָךָ חֲנוֹךְ, בְּעוֹד שֶׁהָיָה צַדִּיק, וְהַדּוֹר כֻּלָּם חַיָּיבִין, רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאִם יַנִּיחֵהוּ יִלְמוֹד מִמַּעֲשֵׂיהֶם, וְסִלְּקוֹ קוֹדֶם זְמַנּוֹ מִן הָעוֹלָם, קוֹדֶם שֶׁיַּבְאִישׁ רֵיחוֹ. הֲדָא הוּא דִכְתִיב, (בראשית ה׳:כ״ד) וְאֵינֶנּוּ כִּי לָקַח אוֹתוֹ אֱלֹהִים, כְּלוֹמַר, וְאֵינֶנּוּ בָּעוֹלָם הַזֶּה, לְמַלְאוֹת יָמָיו, כִּי לָקַח אוֹתוֹ אֱלֹהִים קוֹדֶם זְמַנּוֹ, לַעֲשׂוֹת עִמּוֹ חֶסֶד לְהַנְחִילוֹ חַיֵּי הָעוֹלָם הַבָּא.</p>"],[9514011856,"<p>(שם ו) וַיִּרְאוּ בְּנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם. מַאן אִינוּן בְּנֵי הָאֱלֹהִים. ר' יִרְמְיָה אָמַר, גְּדוֹלֵי הַדּוֹר, שֶׁהָיוּ אֲבוֹתֵיהֶם גְּדוֹלֵי הַדּוֹר, וְלֹא הָיוּ מוֹחִין בְּיָדָם. אָמַר רַבִּי חֲנִינָא לְרַב הוּנָא מַה דְּאָמַר בְּנֵי הָאֱלֹהִים. עַל שֵׁם שֶׁנִּבְרְאוּ מִשֵּׁם זֶה, דִּכְתִיב (שם א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם.</p>"],[9514011857,"<p>(איוב א׳:ו׳) וַיְהִי הַיּוֹם וַיָּבוֹאוּ בְּנֵי הָאֱלֹהִים כו'. אָמַר רִבִּי שִׁמְעוֹן בֶּן לָקִישׁ, הוּא שָׂטָן, הוּא יֵצֶר הָרָע, הוּא מַלְאַךְ הַמָּוֶת. אָמַר רִבִּי יְהוּדָה, אוֹתוֹ הַיּוֹם, יוֹם שֶׁל רֹאשׁ הַשָּׁנָה הָיָה. יוֹם שֶׁיֵּשׁ לְכָל אָדָם לַחֲזוֹר לְמוּטָב, וְכָךְ תִּרְאֶה, אֵין דַּרְכּוֹ שֶׁל יֵצֶר הָרָע לְקַטְרֵג, אֶלָּא בְּשָׁעָה שֶׁהָאָדָם רוֹצֶה לַחֲזוֹר לְמוּטָב.</p>"],[9514011858,"<p>תַּנְיָא, סָבָא בְּבֵיתָא, סִמָנָא טָבָא בְּבֵיתָא. צַדִּיקָא בְּדָרָא, סִימָנָא טָבָא הֲוֵי בְּעָלְמָא. דִּתְנַן, הַקָּדוֹשׁ בָּרוּךְ הוּא מַטִיל אֵימַת הַדַּיָּין וְהַמַּנְהִיג עַל בְּנֵי אָדָם. דְּכָל זְמַן שֶׁאֵימַת הַדַּיָּין עַל הַדּוֹר, בְּיָדוּעַ שֶׁהוּא צַדִּיק, וְהֵם צַדִּיקִים. נִיטְלָה אֵימָתוֹ מִבְּנֵי אָדָם, הוּא חַיָּב, וְהֵם יוֹתֵר מִמֶּנּוּ.</p>"],[9514011859,"<p>וּבָא הַכָּתוּב לְהוֹרוֹת, (בראשית ו׳:ד׳) הַנְפִילִים הָיוּ בָּאָרֶץ, אֵלּוּ אָדָם וְאִשְׁתּוֹ, שֶׁהֵם הָיוּ שֶׁנָּפְלוּ בָּאָרֶץ, בְּלֹא אָב וָאֵם. וְלָמָּה נִקְרְאוּ נְפִילִים. שֶׁנָּפְלוּ מִמַּעֲלָתָם שֶׁהָיָה לָהֶם. כְּלוֹמַר, נְפָלִים הֵם מִכְּמוֹת שֶׁהָיוּ כְּבָר. נְפָלִים הֵם, עַל שֶׁנִּטְרְדוּ מִגַּן עֵדֶן, וְלֹא חָזְרוּ לְשָׁם.</p>"],[9514011860,"<p>עַל כֵּן חָזְרָה תּוֹרָה וְאָמְרָה, אֵלּוּ הָיוּ בָּאָרֶץ, שֶׁהָיְתָה אֵימָתָם עַל כָּל הַבְּרִיּוֹת, וַעֲדַיִין הָיוּ קַיָּימִים, וְלֹא מָנְעוּ בְּנֵי הַדּוֹר מִלַּעֲשׂוֹת עֲבֵירוֹת. וּמִי הֵם אוֹתָם הָעוֹבְרִים הָעֲבֵירוֹת. גְּדוֹלֵי הַדּוֹר, אַנְשֵׁי הַשֵּׁם, שֶׁהָיוּ גְדוֹלִים בַּדּוֹר.</p>"],[9514011861,"<p>אָמַר רִבִּי פִּנְחָס, מִכָּאן מַשְׁמָעוּתוֹ דִּקְרָא, דִּכְתִיב (שם) הַנְּפִילִים הָיוּ בָּאָרֶץ בַּיָּמִים הָהֵם, לָהֶם הַמְנִיעָה לִמְנוֹעַ עַצְמָן מֵהָעֲבֵירוֹת בִּשְׁבִילָם, וְלֹא מָנְעוּ, וּלְעֵינֵיהֶם מַמָּשׁ בָּאִים אֶל בְּנוֹת הָאָדָם בִּזְנוּת, וְיָלְדוּ לָהֶם. וּמִי הָיוּ אוֹתָם הַנְּפִילִים שֶׁהָיוּ בַּדּוֹר. אוֹתָם הַגִּבּוֹרִים שֶׁלֹּא נִרְאֶה בַּדּוֹר כְּמוֹתָם. אַנְשֵׁי הַשֵּׁם: שֵׁם הַיָּדוּעַ שֶׁקָּרָא לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, דִּכְתִיב (שם ה) וַיִּקְרָא אֶת שְׁמָם אָדָם.</p>"],[9514011862,"<p>וְר' חִזְקִיָּה אֲמַר, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, וִיהַב לוֹן אוֹרַיְיתָא קַדִּישָׁא, וְאַזְהַר לוֹן, וִיהַב לוֹן עֵיטָא, לְאִסְתַּמָּרָא מֵעֵילָא וְתַתָּא, בְּגִין דְּלָא יִשְׁלוֹט בְּהוּ בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי. וְאִינוּן יָדְעֵי לְדַחְיָיא מִנַּיְיהוּ כָּל מְקַטְרְגִין, וְכָל קַסְטִירִין, בְּגִין דִּיהוֹן חוּלָקָא דְּעַדְבֵיהּ וְאַחְסַנְתֵּיהּ, כְּמָה דְאַתְּ אָמֵר (דברים ל״ב:ט׳) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>"],[9514011863,"<p>תָּא חֲזֵי, בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה, קוּדְשָׁא בְּרִיךְ הוּא יָתֵיב בְּדִינָא עַל עָלְמָא, וְכָל בְּנֵי עָלְמָא עָאלִין לְחוּשְׁבְּנָא, וְלָא אִית מָאן דְּלָא עָאל בְּחוּשְׁבְּנָא. וְסִפְרִין דְּחַיִּין וּמֵתִין פְּתִיחָן בְּהַהוּא יוֹמָא.</p>"],[9514011864,"<p>וְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּאִתְרְעֵי בְּהוּ, יְהַב לוֹן עֵיטָא לְאִשְׁתֵּזָבָא מִכָּל מְקַטְרְגִין דִּלְעֵילָא, דְּאִינוּן אִתְמַנָּן בְּכָל זִמְנָא דְּדִינָא שַׁרְיָא עַל עָלְמָא. בְּהַאי יוֹמָא אִזְדַּמְּנָן יִשְׂרָאֵל לְאַתְעָרָא רַחֲמֵי עֲלַיְיהוּ. וּבַמֶּה. בַּשּׁוֹפָר.</p>"],[9514011865,"<p>דְּהָא קָלָא דְּנָפֵיק, סָלֵיק לְעֵילָא, וְאִתְעַר שׁוֹפָר דִּלְעֵילָא. כְּדֵין אִתְעָרוּ רַחֲמֵי מֵאַתְרַיְיהוּ. וְקוּדְשָׁא בְּרִיךְ הוּא קָם מִכּוּרְסַיָּיא דְּדִינָא וְיָתֵיב בְּכוּרְסַיָא דְּרַחֲמֵי, וְחָיֵיס עֲלַיְיהוּ דְיִשְׂרָאֵל, וְלָא אִתְיְיהֵיב רְשׁוּ לִמְקַטְרְגָא עֲלֵיהוֹן.</p>"],[9514011866,"<p>וְיִשְׂרָאֵל תָּיְיבֵי בִּתְיוּבְתָּא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְתָקְעֵי שׁוֹפָר, וְאִתְעָרוּ רַחֲמֵי. דְּהָא הַהוּא קָלָא דְּנָפַק, אִתְעָרוּתָא דְּרַחֲמֵי אִיהוּ. וּכְדֵין, דִּלְטוֹרָא לָא יָכֵיל לְקָיְימָא קַמֵּי כּוּרְסְיָיא דְרַחֲמֵי. דְּהָא לָא אָתֵי מֵהַהוּא סִטְרָא, וְלָא אִשְׁתְּכַח קַטֵיגוֹרָא.</p>"],[9514011867,"<p>בְּיוֹמָא דְּכִפּוּרֵי, דְּאִיהוּ חֲתִימָא דְדִינָא, וְקָיְימֵי יִשְׂרָאֵל בִּקְדוּשָׁתָא דְּמָארֵיהוֹן. בְּהַהוּא יוֹמָא, בְּגִין דְּלָא יִקְרַב דִּלְטוֹרָא לְמַקְדְּשָׁא, יָהֲבִין לֵיהּ שָׂעִיר, דְּאָתֵי מִסִּטְרָא דְרוּחָא מְסָאֲבָא, וְהוּא מְסָאֲבָא, וְרוּחָא מְסָאֲבָא אִתְהַנֵּי מִינֵיהּ, וְהוּא אִתְעַסַּק בֵּיהּ, וְלָא קָרֵיב לְמַקְדְּשָׁא לְסָאֲבָא. וּכְדֵין אַנְפִּין נְהִירִין, וְיִשְׂרָאֵל אִשְׁתְּזִיבוּ מִנֵּיהּ.</p>"],[9514011868,"<p>בְּזִמְנָא אָחֳרָא כַּד סְגִיאוּ חוֹבֵי בְּנֵי נָשָׁא, הַאי דִּלְטוֹרָא, בְּשַׁעֲתָא דְדִינָא אִיתְעַר עַל חוֹבֵי עָלְמָא, כְּדֵין אִיהוּ אָתֵי וְאִשְׁתְּכַח מְקַטְרְגָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִסְתָּאַב מַקְדְּשָׁא, וְכָל אַנְפִּין עֲצִיבִין, וְדִינָא אִשְׁתְּכַח. וְעַל דָּא קֵץ כָּל בָּשָׂר בָּא לְפָנַי. לְפָנַי וַדַּאי, לְמִתְבַּע עַל חוֹבֵי בְּנֵי עָלְמָא, דְּאִינוּן גָּרְמוּ.</p>"],[9514011869,"<p>תָּא חֲזֵי, כָּל בַּר נָשׁ דְּיַעֲבֵד וְיִנְטַר פִּיקּוּדֵי אוֹרַיְיתָא, נִשְׁמָתָא אִסְתַּמְּרָא בְּגוּפֵיהּ, דְּאִיהוּ תֵּיבָה, וְלָא אִתְעֲנַשׁ, וְלָא יִשְׁלוֹט עֲלֵיהּ מַלְאַךְ הַמָּוֶת. וְכָל בַּר נָשׁ דְּלָא נָטֵיר וְלָא קַיַּים פִּקּוּדֵי אוֹרַיְיתָא, וְאַעֲבַר עֲלֵיהּ, מַלְאַךְ הַמָּוֶת כְּדֵין יִשְׁלוֹט עֲלֵיהּ.</p>"],[9514011870,"<p>תָּא חֲזֵי, תֵּיבָה, אִיהוּ גּוּפָא. נֹחַ וְאִשְׁתּוֹ, י\"ה. שֵׁם וְאִשְׁתּוֹ, ו\"ה. וְאִתְעֲבֵיד הַשֵּׁם מָלֵא, ידו\"ד אֶחָד. יֶפֶת וְאִשְׁתּוֹ, י\"ה. חָם וְאִשְׁתּוֹ, וְאִינוּן כְּדוּגְמָא.</p>"],[9514011871,"<p>וְהָא (בראשית ו׳:י״ג) וַיֹּאמֶר אֱלֹהִים לְנֹחַ. אֱלֹהִים, דָּא שְׁכִינְתָּא, קֵץ כָּל בָּשָׂר וְגו'. (שם) צֹהַר תַּעֲשֶׂה לַתֵּיבָה, דָּא אִיהוּ רָזָא דְגוּפָא. אַתָּה וּבָנֶיךָ וְגו', גּוּבְרִין לְחוֹד, וְנָשִׁין לְחוֹד. (שם) וַיַּעַשׂ נֹחַ, דָּא בְּרִית קַדִּישָׁא. כְּכָל אֲשֶׁר צִוָּה אֹתוֹ אֱלֹהִים, דָּא שְׁכִינְתָּא. (שם ז) וַיֹּאמֶר ה' לְנֹחַ, הָכָא מִדַּת רַחֲמִים.</p>"],[9514011872,"<p>(שם) וּמִן הַבְּהֵמָה אֲשֶׁר לֹא טְהוֹרָה הִיא שְׁנַיִם אִישׁ וְאִשְׁתּוֹ, דְּהָא הִיא מִסִּטְרָא דִּמְסָאֲבָא, וְעַל דָּא אֲמַר, וְהַאֲבַדְתִּי. וָאֶסְתַּכֵּל דְּלֵית בֵּיהּ, אֶלָּא תְּרֵין, וְלָא אִית בְּהוֹן שִׁבְעָה שִׁבְעָה, כְּמָה דִכְתִיב בְּעוֹף הַשָּׁמַיִם, אַרְבַּע סְרֵי דְּכַר וְנוּקְבָא, לְחַיּוֹת זֶרַע עַל פְּנֵי כָל הָאָרֶץ. (שם) שְׁנַיִם שְׁנַיִם בָּאוּ וְגו' אֶסְתַּכֵּל וְחָמֵי, עַל מַה דַּאֲמַר בְּקַדְמִיתָא וּמִן הַבְּהֵמָה אֲשֶׁר לֹא טְהוֹרָה הִיא, וּלְבָתַר שְׁנַיִם שְׁנַיִם.</p>"],[9514011873,"<p>אָמַר רִבִּי יְהוּדָה, תָּא חֲזֵי לֵית לָךְ בְּכָל לֵילְיָא וְלֵילְיָא, דְּלָא תֵיפוֹק נִשְׁמָתָא מִגּוּפָא דְּבַּר נָשׁ, דְּאִיקְרֵי יוֹנָה. דִּכְתִיב, (שם ח) וַיְשַׁלַּח אֶת הַיּוֹנָה. הֲקַלּוּ הַמַּיִם, אִלֵּין מַיִם זֵדוֹנִים, כְּמָה דְאַתְּ אָמֵר (תהילים קכ״ד:ה׳) הַמַּיִם הַזֵּדוֹנִים. דְּאִינוּן מִסִּטְרָא דִּמְסָאֲבוּ. מֵעַל הָאָרֶץ, דְּאִינוּן לְעֵיל מִן אַרְעָא, אִלֵּין מַלְאֲכֵי חַבָּלָה.</p>"],[9514011874,"<p>מַה כְּתִיב. וְלֹא מָצְאָה הַיּוֹנָה מָנוֹחַ, דְּאִתְמְנָעֵי מֵעָלְמָא עִילָּאָה, וּמִן צַדִּיקִים דִּלְעֵילָא, וּמִכָּל בִּרְכָאן. הֲדָא הוּא דִכְתִיב, (בראשית ח׳:ט׳) וַתָּשָׁב אֵלָיו אֶל הַתֵּיבָה כִּי מַיִם עַל פְּנֵי כָל הָאָרֶץ.</p>"],[9514011875,"<p>אַפֵּיק לָהּ תִּנְיָינוּת, וַיּוֹסֶף שַׁלַּח אֶת הַיּוֹנָה מֵאִתּוֹ, וּמִגוֹ דּוֹחֲקָא וְצַעֲרָא, וַתָּבֹא אֵלָיו הַיּוֹנָה לְעֵת עֶרֶב, דְּלָא הֲוַת נָהֲרָא לוֹן שַׁעֲתָא דְרַוְוחָא, כְּמָה דַּהֲוַת בְּקַדְמִיתָא, וְאִתְחַשַּׁךְ לָהּ יוֹמָא, וְאִתְעָרַב לָהּ שִׁמְשָׁא.</p>"],[9514011876,"<p>וּמָה אֲמָרַת לְנֹחַ וְלִבְנוֹי. (שיר השירים ה׳:ז׳) מְצָאוּנִי הַשּׁוֹמְרִים הַסּוֹבְבִים בָּעִיר. אִלֵּין נָטְרֵי תַּרְעֵי יְרוּשָׁלַיִם. וְעִם כָּל דָּא, (בראשית ח׳:י״א) וְהִנֵּה עָלֶה זַיִת טָרָף בְּפִיהָ, וְעַל דָּא וַיֵּדַע נֹחַ כִּי קַלּוּ הַמַּיִם, וְאִתְתַּקָּפוּ מַלְאֲכֵי דִקְדֻשָּׁה עַל מַלְאֲכֵי חַבָּלָה. וַיִּיָחֶל עוֹד שִׁבְעַת יָמִים אֲחֵרִים כו', וְלֹא יָסְפָה כו', חָרְבוּ הַמַּיִם מֵעַל הָאָרֶץ.</p>"],[9514011877,"<p>בָּתַר דְּאִסְתַּתַּר וְאַעֲבַר הַהוּא זִימְנָא דְּשַׁלֵּיט מַלְאַךְ הַמָּוֶת, וְאִתְעֲבָרוּ חַיָּיבִין מֵעָלְמָא, מַה כְּתִיב, (שם) וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ.</p>"],[9514011878,"<p>סְפִינְתָּא אַמְתִילַת לְתֵיבוּתָא דְנֹחַ, וְאִית בָּהּ גּוּבְרִין יְהוּדָאִין וְיִשְׁמְעֵאלִים וּבְנֵי עֵשָׂו, כְּדוּגְמָא דָא אִית בְּגוּפָא, כָּלֵיל מִכּוֹלְהוֹן, דְּגוּפָא דָא, לָאו אִיהוּ מִן נִשְׁמָתָא קַדִּישָׁא, וְדָא הוּא דַּאֲמַר לְנֹחַ, דְּאִיהוּ נִשְׁמָתָא לְנִשְׁמָתָא, כְּמָה דְאַתְּ אָמֵר (שם ו) עֲשֵׂה לְךָ תֵּבַת עֲצֵי גֹפֶר.</p>"],[9514011879,"<p>וְהָא הוּא דַּאֲמַר לְאַבְרָם, לֶךְ לְךָ מֵאַרְצְךָ, לָמָּה תְּרֵי זִימְנֵי. אֶלָּא, פּוֹק מִן דִּירָתָךְ וּמִן גּוּפָךְ, וּמִן בֵּית אָבִיךָ, דְּאִית שְׁלָם דִּלְעֵילָא. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ, דָּא גוּפָא, דְּאִיהִי תֵּיבַת נֹחַ.</p>"],[9514011880,"<p>וּבְדוּגְמָא דָא הֲוָה נֹחַ, הֲדָא הוּא דִכְתִיב, (שם ח) וַיְשַׁלַּח אֶת הַיּוֹנָה. וַאֲפִיקוּ לָהּ לַיּוֹנָה מִן תֵּיבוּתָא, וְיַהֲבוּ לָהּ בְּמַיָּא. בְּדוּגְמָא דָא נָפְקָא לָהּ יוֹנָה מִן תֵּיבוּתָא דְנֹחַ, כְּמָא דְאַתְּ אָמֵר וְלֹא יָסְפָה שׁוּב אֵלָיו עוֹד.</p>"],[9514011881,"<p>ר\"י אֲמַר, נֹחַ כַּד הֲוָה בְּתֵיבוּתָא, הֲוָה דָחֵיל דְּלָא יִדְכַּר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין, וְכֵיוָן דְּאִתְעֲבָרוּ חוֹבֵי עָלְמָא, כְּדֵין מַה כְּתִיב וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ.</p>"],[9514011882,"<p><Noneb>מדרש הנעלם </b></p>"],[9514011883,"<p>רַבִּי פְּתַח בְּהַאי קְרָא, (שיר השירים ה) מְצָאֻנִי הַשֹׁמְרִים הַסֹּבְבִים בָּעִיר הִכּוּנִי פְצָעוּנִי נָשְׂאוּ אֶת רְדִידַי מֵעָלַי שֹׁמְרֵי הַחֹמוֹת. כַּמָּה חֲבִיבָה הִיא הַנְּשָׁמָה, הַנְּתוּנָה מִתַּחַת כִּסֵּא הַכָּבוֹד, מִמְּקוֹם הַקּוֹדֶשׁ, מֵאַרְצוֹת הַחַיִּים, כְּמָה דְאַתְּ אָמֵר (תהלים קטז) אֶתְהַלֵּךְ לִפְנֵי ה' בְּאַרְצוֹת הַחַיִּים.</p>"],[9514011884,"<p>וְלָמָּה קְרָאוֹ דָּוִד אַרְצוֹת הַחַיִּים, וְכִי לְמַעְלָה יֵשׁ אֲרָצוֹת. אָמַר רִבִּי יִצְחָק, לֹא אֲרָצוֹת מַמָּשׁ, וְלֹא אַדַעְתָּא דַּאֲרָצוֹת אֲמָרוֹ דָּוִד, אֶלָּא לְשׁוֹן רִיצּוּי הוּא, כְּמָה דְאַתְּ אָמֵר (יחזקאל כ) אֶרְצֶה אֶתְכֶם. כְּלוֹמַר, אָמַר דָּוִד, אֶתְהַלֵּךְ לִפְנֵי ה', בַּמָּקוֹם אֲשֶׁר יִרְצוּ תָּמִיד הַצַּדִּיקִים, הַנִּקְרָאִים חַיִּים, אֲשֶׁר רְצוֹנָם וְחֶפְצָם לָלֶכֶת שָׁמָּה. וּמִמְּקוֹם הַקּוֹדֶשׁ, בָּאָה הַנְּשָׁמָה לְהָאִיר עַל הַגּוּף הֶאָפֵל, כְּדֵי לְהוֹלִיכוֹ בְּדֶרֶךְ יְשָׁרָה, וְלַעֲבוֹד עֲבוֹדָתוֹ וּרְצוֹן בּוֹרְאוֹ, לָבֹא לְמָחָר וְלִיטוֹל שְׂכָרוֹ.</p>"],[9514011885,"<p>אָמַר רִבִּי יְהוּדָה, אִלְמָלֵי לָא הֲוֵינָא בְּעָלְמָא יָאוֹת לָן, וְלָא נֵיהַב חוּשְׁבְּנָא לְמָארֵיהּ דְּפִיתְקָא, לְבָתַר אֲמַר, הַדְרֵי בִי.</p>"],[9514011886,"<p>תָּא חֲזֵי, מַה כְּתִיב בָּאָדָם, (בראשית ב) לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ אֶעֱשֶׂה לוֹ עֵזְר כְּנֶגְדוֹ. אָמַר רִבִּי, זוֹ הִיא הַנְּשָׁמָה שֶׁהִיא אֶצְלוֹ עֵזְר, לְהוֹלִיכוֹ בְּדַרְכֵי קוֹנוֹ. וְהַיְינוּ דִּתְנַן בָּא לִיטָהֵר מְסַיְּיעִין אוֹתוֹ. תָּנוּ רַבָּנָן, כְּשֶׁהָאָדָם הוֹלֵךְ בְּדַרְכֵי קוֹנוֹ, הַרְבֵּה מְסַיְּיעִין אוֹתוֹ. נִשְׁמָתוֹ מְסַיַּיעַת אוֹתוֹ. מַלְאֲכֵי הַשָּׁרֵת מְסַיְּיעִין אוֹתוֹ. שְׁכִינָתוֹ שֶׁל מָקוֹם מְסַיַּיעַת אוֹתוֹ. וְכֻלָּם מַכְרִיזִין לְפָנָיו וְאוֹמְרִים, (משלי ד) בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ וְאִם תָּרוּץ לֹא תִכָּשֵׁל. רַבִּי נָתָן אוֹמֵר, נִשְׁמָתָן שֶׁל צַדִּיקִים מְסַיְּיעִין אוֹתוֹ.</p>"],[9514011887,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי חָמוֹי, הֲווֹ אָזְלוֹ מֵאוּשָׁא לְלוֹד. אָמַר רִבִּי יוֹסֵי לְר' אֶלְעָזָר, אֶפְשָׁר דְּשָׁמַעְתָּ מֵאָבִיךָ, מַאי דִכְתִיב, (בראשית לב) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. אָמַר לֵיהּ הָכֵי שְׁמִיעַ לִי מֵאַבָּא, אִינוּן הֲווֹ מַלְאָכִים דְּאוּזְפוּהוּ בְּקַדְמִין מֵאַרְעָא דְיִשְׂרָאֵל. אָמַר לֵיהּ, מָאן אִינוּן. אָמַר לֵיהּ לָא יְדַעְנָא. אָמַר לֵיהּ, יָאוֹת לְכוֹן צַדִּיקַיָא, מִלָּה דְפוּמְכוֹן כְּכִתְרָא דְּמַלְכוּתָא, בְּרֵישָׁא דְמַלְכָּא.</p>"],[9514011888,"<p>עַד דַּהֲווֹ אָזְלֵי מָטוֹ לִמְעַרְתָּא דְלוֹד, שְׁמָעוּ הַהוּא קָלָא דַּאֲמַר, תְּרֵין עוּזְלִין דְּאַיַּילְתָּא, עֲבָדוֹ קֳדָמַי רְעוּתָא דְּנִיחָא לִי, וְאִינוּן הֲווֹ מַשִּׁרְיָיתָא קַדִּישָׁא, דְּעָרַע יַעֲקֹב קַמֵּיהּ. אִתְרְגֵישׁ רִבִּי אֶלְעָזָר, וְאִצְטָעֵר בְּנַפְשֵׁיהּ, וַאֲמַר, מָארֵיהּ דְּעָלְמָא, כָּךְ אוֹרְחוֹי, טַב לָן דְּלָא נִשְׁמַע, שְׁמַעְנָא וְלָא יְדַעְנָא.</p>"],[9514011889,"<p>אִתְרְחֵישׁ לֵיהּ נִיסָּא, וּשְׁמַע הַהוּא קָלָא דַּאֲמַר, אַבְרָהָם וְיִצְחָק הֲווֹ. נְפַל עַל אַנְפּוֹי, וְחָמָא דִּיוּקְנָא דְאָבִיו, אָמַר לֵיהּ, אֲנָא שָׁאֵילְנָא, וַאֲתֵיבוּנָא, דְּאַבְרָהָם וְיִצְחָק הֲווֹ, דְּעָרְעוּ לְיַעֲקֹב, כַּד אִשְׁתֵּיזֵיב מִלָּבָן.</p>"],[9514011890,"<p>אָמַר לֵיהּ, בְּרִי, פּוּק פִּיקָתָךְ, וְסַב סִיבָתָךְ, דְּפוּם מְמַלֵּל רַבְרְבָן הוּא. וְלָא דָא הוּא בִּלְחוֹדוֹהִי, אֶלָּא לְכָל צַדִּיקָא, נִשְׁמַתְהוֹן דְּצַדִּיקַיָא מְעָרְעָן קֳדָמוֹהִי לְשֵׁזָבוּתֵיהּ. וְאִינוּן מַלְאָכַיָא קַדִּישֵׁי עִילָּאֵי.</p>"],[9514011891,"<p>וְתָּא חֲזֵי, יִצְחָק קַיָּים הֲוָה בְּהַהוּא שַׁעֲתָא, אֲבָל נִשְׁמָתָא קַדִּישָׁא אִתְנְסֵיבַת בְּכוּרְסֵי יְקָרָא דְמָארֵיהּ, כַּד אִתְעַקַּד עַל גַּבֵּי מַדְבְּחָא, וּמִכְּדֵין אִסְתִּימוּ עֵינוֹי מִלְּמֶחֱזֵי. וְהַיְינוּ דִּכְתִיב, (שם לא) וּפַחַד יִצְחָק הָיָה לִי.</p>"],[9514011892,"<p>אָמַר לֵיהּ מָה אֲנַן תַּמָּן. אָמַר לֵיהּ, אֲנָא וְאַתְּ מַלְאָכֵי עִילָּאָה, לְאִשְׁתַּעְשְׁעָא בִּמְשִׁיחָא מַלְכָּא דְּדָוִד. קָם, עַד דְּהֲוָה קָם, חָמָא חָמוּהִי דְּאַנְפּוֹי נְהִירִין כְּשִׁמְשָׁא.</p>"],[9514011893,"<p>אָמַר לֵיהּ חָמוּי, מִלָּה חַדְתָּא שְׁמַעְתְּ, אוֹ בִּנְהִירוּ יְקָרָא זִיוָא דְמשֶׁה אִסְתַּכַּלְתְּ. אָמַר לֵיהּ לָא. אֶלָּא זַכָּאִין אִינוּן צַדִּיקַיָא, דְּנָטְרִין לְהוֹן מַשִּׁרְיָיתֵי קַדִּישֵׁי עִילָּאֵי, שֶׁנֶּאֱמַר (תהילים צ״א:י״א) כִּ\"י מַלְאָכָי\"ו יְצַוֶּ\"ה לָ\"ךְ לִשְׁמָרְךָ בְּכָל דְּרָכֶיךָ.</p>"],[9514011894,"<p>אָמַר רִבִּי יְהוּדָה, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא יְרוּשָׁלַיִם לְמַעְלָה, כְּנֶגֶד יְרוּשָׁלַיִם שֶׁל מַטָה. וְנִשְׁבַּע שֶׁלֹּא יָבֹא שָׁם, עַד שֶׁיָּבוֹאוּ יִשְׂרָאֵל בִּירוּשָׁלַיִם שֶׁל מַטָה. שֶׁנֶּאֱמַר, (הושע י״א:ט׳) בְּקִרְבְּךָ קָדוֹשׁ וְלֹא אָבוֹא בְּעִיר.</p>"],[9514011895,"<p>וְשֶׁבַע כִּתּוֹת שֶׁל מַלְאֲכֵי הַשָּׁרֵת שׁוֹמְרִים אוֹתָם סָבִיב, וְעַל כָּל פֶּתַח וּפֶתַח כִּתּוֹת שֶׁל מַלְאֲכֵי הַשָּׁרֵת. וְהֵם הַפְּתָחִים הַנִּקְרָאִים שַׁעֲרֵי צֶדֶק. וְאֵלּוּ הֵם הַפְּתָחִים, הַמְכֻוָּונִים לְהִכָּנֵס שָׁם נְפָשׁוֹת הַצַּדִּיקִים. וְדָּוִד הַמֶּלֶךְ עָלָיו הֲשָׁלוֹם נִכְסַף לָהֶם, שֶׁנֶּאֱמַר (תהילים קי״ח:י״ט-כ׳) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ, זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבוֹאוּ בוֹ.</p>"],[9514011896,"<p>וּלְמַעְלָה מֵהֶם שׁוֹמְרִים מה\"ש, בְּחוֹמוֹת הָעִיר. שֶׁנֶּאֱמַר (ישעיה סב) עַל חוֹמוֹתַיִךְ יְרוּשָׁלַיִם, זוֹ הִיא יְרוּשָׁלַיִם שֶׁל מַעְלָה, הִפְקַדְתִּי שׁוֹמְרִים, אֵלּוּ מה\"ש. וְתָאנָא, שֶׁבַע פְּתָחִים יֵשׁ לִנְפָשׁוֹת הַצַּדִּיקִים, לְהִכָּנֵס עַד מְקוֹם מַעֲלָתָם. וְעַל כָּל פֶּתַח וּפֶתַח שׁוֹמְרִים.</p>"],[9514011897,"<p>הַפֶּתַח הָרִאשׁוֹן, נִכְנֶסֶת הַנְּשָׁמָה בִּמְעָרַת הַמַּכְפֵּלָה. שֶׁהִיא סְמוּכָה לְגַּן עֵדֶן. וְאָדָם הָרִאשׁוֹן, שׁוֹמֵר עָלָיו. זָכְתָה, הוּא מַכְרִיז וְאוֹמֵר, פַּנּוּ מָקוֹם, שָׁלוֹם בּוֹאֵךְ. וְיָצְאָה מִפֶּתַח הָרִאשׁוֹן.</p>"],[9514011898,"<p>הַפֶּתַח הַשֵּׁנִי בְּשַׁעֲרֵי גַּן עֵדֶן, וּמוֹצְאָה אֶת הַכְּרוּבִים, וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. זָכְתָה, נִכְנֶסֶת בְּשָׁלוֹם. וְאִם לָאו, שָׁם תְּקַבֵּל עוֹנְשָׁהּ, וְתִשָּׂרֵף בְּלַהַב הַכְּרוּבִים. וּכְנֶגְדָם הָיוּ הַכְּרוּבִים בַּמִּקְדָּשׁ, בְּשָׁעָה שֶׁהַכֹּהֵן נִכְנַס בְּיוֹם הַכִּפּוּרִים, זָכָה נִכְנַס בְּשָׁלוֹם. לֹא זָכָה, מִבֵּין שְׁנֵי הַכְּרוּבִים יוֹצֵא לַהַב, וְנִשְׂרַף מִבִּפְנִים, וּמֵת. וְהָיוּ מְכֻוָּונִים כְּנֶגֶד אֵלּוּ אֲשֶׁר בְּשַׁעַר גַּן עֵדֶן, לְצַרֵף הַנְּשָׁמוֹת.</p>"],[9514011899,"<p>זָכְתָה הַנְּשָׁמָה, נוֹתְנִין לָהּ פִּינְקָס סִימָן לִיכָּנֵס, וְנִכְנֶסֶת לַגַּן עֵדֶן אֲשֶׁר בָּאָרֶץ. וְעַמּוּד אֶחָד שֶׁל עָנָן וְנוֹגַהּ מְעוֹרָב זֶה בָּזֶה, וְעָשָׁן וְנוֹגַהּ סְבִיבָיו. שֶׁנֶּאֱמַר, (ישעיהו ד׳:ה׳) וּבָרָא ה' עַל כָּל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶיהָ עָנָן יוֹמָם וְעָשָׁן וְנוֹגַהּ. וְהוּא נָעוּץ מִלְּמַטָה לְמַעְלָה לְשַׁעֲרֵי שָׁמָיִם. זָכְתָה לַעֲלוֹת לְמַעְלָה, עוֹלָה בְּאוֹתוֹ עַמּוּד. לֹא זָכְתָה יוֹתֵר, נִשְׁאֶרֶת שָׁם, וּמִתְעַדֶּנֶת מֵהַטוֹב אֲשֶׁר לְמַעְלָה. דְּאָמַר רִבִּי יוֹסֵי, רָאִיתִי גַּן עֵדֶן, וְהוּא מְכֻוָּון כְּנֶגֶד פָּרוֹכֶת קֶרַח הַנּוֹרָא אֲשֶׁר לְמַעְלָה. וְהִיא נֶהֱנֵית מִזִּיו הַשְּׁכִינָה, אֲבָל אֵינָהּ נִיזּוֹנֵית מִמֶּנָּהּ.</p>"],[9514011900,"<p>זָכְתָה לַעֲלוֹת, עוֹלָה בְּאוֹתוֹ עַמּוּד, עַד שֶׁמַּגַּעַת עַד הַפֶּתַח הַשְּׁלִישִׁי. וְהוּא נֶגֶד הָרָקִיעַ הַנִּקְרָא זְבוּל. וּמַגַּעַת עַד יְרוּשָׁלַיִם אֲשֶׁר שָׁם. וְשָׁם הַשּׁוֹמְרִים. זָכְתָה, פּוֹתְחִין לָהּ הַפְּתָחִים וְנִכְנֶסֶת.</p>"],[9514011901,"<p>לֹא זָכְתָה, נוֹעֲלִים הַשְּׁעָרִים, וְדוֹחִים אוֹתָהּ לַחוּץ, וְנוֹטְלִים פִּינְקָסָהּ מִמֶּנָּהּ, וְהַנְּשָׁמָה אוֹמֶרֶת, (שיר השירים ז) מְצָאוּנִי הַשּׁוֹמְרִים הַסּוֹבְבִים בָּעִיר, אֵלּוּ מַלְאֲכֵי הַשָּׁרֵת, הַשּׁוֹמְרִים בֵּית הַמִּקְדָּשׁ וִירוּשָׁלַיִם אֲשֶׁר לְמַעְלָה. נָשְׂאוּ אֶת רְדִידַי מֵעָלַי. זֶהוּ פִּינְקָס סִימָן שֶׁלָּהּ. שׁוֹמְרֵי הַחוֹמוֹת, כְּמָה דְאַתְּ אָמֵר (ישעיהו ס״ב:ו׳) עַל חוֹמוֹתַיִךְ יְרוּשָׁלַיִם הִפְקַדְתִּי שׁוֹמְרִים.</p>"],[9514011902,"<p>זָכְתָה לַעֲלוֹת, נִכְנֶסֶת שָׁם בְּאוֹתָן הַשְּׁעָרִים, וּמְשַׁבַּחַת לְהַקָּדוֹשׁ בָּרוּךְ הוּא בְּבֵית הַמִּקְדָּשׁ אֲשֶׁר לְמַעְלָה. וּמִיכָאֵל הַשַּׂר הַגָּדוֹל מַקְרִיב אוֹתָהּ לְקָרְבָּן. אָמַר רִבִּי יִצְחָק לְרַבִּי חִיָּיא, מַה קָּרְבָּן הוּא זֶה, יָכוֹל לוֹמַר כִּשְׁאָר הַקָּרְבָּן. אָמַר רִבִּי חִיָּיא, הַקְרָבָה זוֹ הִיא כְּאָדָם הַמַּקְרִיב דּוֹרוֹן לִפְנֵי הַמֶּלֶךְ.</p>"],[9514011903,"<p>וּמִיכָאֵל הוֹלֵךְ עִמָּהּ, עַד הַפֶּתַח הָרְבִיעִי וְהַחֲמִישִׁי וְהַשִּׁשִּׁי, אוֹמֵר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, רִבּוֹנוֹ שֶׁל עוֹלָם, אַשְׁרֵי בָּנֶיךָ, בְּנֵי אוֹהֲבֶיךָ אַבְרָהָם יִצְחָק וְיַעֲקֹב, אַשְׁרֵיהֶם הַצַּדִּיקִים הַטוֹבִים הַזּוֹכִים לָזֶה. עַד שֶׁמַּגִּיעִים לַשַּׁעַר הַשְּׁבִיעִי, שֶׁהוּא עֲרָבוֹת, וְגִנְזֵי חַיִּים טוֹבִים מְצוּיִין שָׁם, וְכָל נִשְׁמוֹתֵיהֶם שֶׁל צַדִּיקִים כֻּלָּם שָׁם, וְנַעֲשִׂים מַלְאֲכֵי הַשָּׁרֵת, וּמְקַלְּסִין לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִזּוֹנִין מִזִּיו הַשְּׁכִינָה, אַסְפַּקְלַרְיָא הַמְאִירָה, וְשָׁם הַמְנוּחָה וְהַנַּחֲלָה, וְנוֹחַ חַיֵּי הָעוֹלָם הַבָּא, אֲשֶׁר עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתֶךָ.</p>"],[9514011904,"<p>וְזֶהוּ, אֵלֶּה תּוֹלְדוֹת נֹחַ נֹחַ אִישׁ צַדִּיק תָּמִים. מִי רָאוּי לִהְיוֹת בְּזוֹ הַהֲנָאָה וְהַמְנוּחָה וְהַמַּרְגּוֹעַ, מִי שֶׁהוּא אִישׁ צַדִּיק תָּמִים. אָמַר רַב פָּפֵּי, זֹאת הַמְנוּחָה לְמַעְלָה, הִיא אֶת הָאֱלֹהִים הִתְהַלֶּךְ נֹחַ, לְמַעְלָה, וְלֹא לְמַטָה.</p>"],[9514011905,"<p>(בראשית ו׳:ט׳) אֵלֶּה תּוֹלְדוֹת נֹחַ, ר' אֲלֶכְּסַנְדְּרָאי פְּתַח (תהילים פ״א:י׳-י״א) לֹא יִהְיֶה בְךָ אֵל זָר וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר. לֹא יִהְיֶה בְךָ אֵל זָר, זֶה יֵצֶר הָרָע. וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר, שֶׁלֹּא תִּבְעוֹל אֲרָמִית.</p>"],[9514011906,"<p>רַבִּי אֶלְעָזָר אוֹמֵר, לֹא יִהְיֶה בְךָ אֵל זָר, שֶׁלֹּא תְּהֵא נֹחַ לִכְעֹס. שֶׁכָּל הַכּוֹעֵס, כְּאִלּוּ עוֹבֵד ע\"א. דְאָמַר רִבִּי עֲקִיבָא, כָּךְ הוּא דַּרְכּוֹ שֶׁל יֵצֶר הָרָע, הַיּוֹם אוֹמֵר לֵךְ עֲשֵׂה כָךְ, וּלְמָחָר אוֹמֵר לֵךְ עֲבוֹד עֲבוֹדָה זָרָה, וְהוֹלֵךְ וְעוֹבֵד.</p>"],[9514011907,"<p>הוּא הָיָה אוֹמֵר, כַּעַס תַּלְמִיד חָכָם גָּדוֹל מִכּוּלָּן. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּדְבָרִים שֶׁהֵם כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא, דְּאָמְרָה תּוֹרָה (משלי כ״א:ל׳) אֵין חָכְמָה וְאֵין תְּבוּנָה וְאֵין עֵצָה לְנֶגֶד ה'. אֲבָל בִּדְבָרִים אֲחֵרִים אָסוּר לוֹ לִכְעוֹס. וְהָרַב אֵצֶל תַּלְמִיד, כְּדֵי שֶׁיְהֵא מָצוּי בִּכְבוֹדוֹ וּבְמוֹרָאוֹ מוּתָּר. וְאֵצֶל שְׁאָר הָעָם לְמַעַן יִהְיֶה מוֹרָאוֹ עֲלֵיהֶם לְשֵׁם שָׁמַיִם, מוּתָּר. וּשְׁאָר אֲנָשִׁים אָסוּר, שֶׁאֵין כַּעֲסָנוּתָם לְיִרְאַת שָׁמַיִם.</p>"],[9514011908,"<p>אָמַר רִבִּי שִׁמְעוֹן, מִדַּת הַצַּדִּיק, קָשֶׁה לִכְעוֹס, וְנֹחַ לִרְצוֹת. וְזוֹ הַמִּדָּה גְּדוֹלָה מִכּוּלָּם, וּבָא הַכָּתוּב לְהוֹרוֹת, אֵלֶּה תּוֹלְדוֹת נֹחַ, נֹחַ בְּדַעְתּוֹ, נֹחַ בְּדִיבּוּרוֹ, נֹחַ בְּמַהֲלָכוֹ. וּמִי עוֹשֶׂה זֶה. אִישׁ צַדִּיק. וּכְשֶׁמֵּת, אוֹמְרִים עָלָיו, אֵי עָנָיו, אֵי חָסִיד. תָּמִים הָיָה בְּדוֹרוֹתָיו, וּלְמַאי יִזְכֶּה, אֶת הָאֱלֹהִים הִתְהַלֶּךְ נֹחַ, לְמַעְלָה עַל כָּל הַמַּעֲלוֹת.</p>"],[9514011909,"<p>וַיּוֹלֶד נֹחַ שְׁלשָׁה בָנִים. תָּאנֵי רַבִּי כְּרוּסְפְּדָאי, אֵלּוּ ג' הַנְהָגוֹת אֲשֶׁר בָּאָדָם. הַנְהָגַת הַנְּשָׁמָה, לִהְיוֹת לוֹ עֵזְר בַּעֲבוֹדַת בּוֹרְאוֹ, וְהִיא הַנִּקְרֵאת שֵׁם. וְהַנְהָגַת הַתַּאֲוָה, וְהַיֵּצֶר הָרָע, הַמַּנְהִיג וְהַמְחַמֵּם אֶת הַגּוּף בִּדְבַר עֲבֵירוֹת, וְהִיא הַנִּקְרֵאת חָם. וְהַנְהָגַת הַיצ\"ט, הַמַּנְהִיג אֶת הָאָדָם בְּכָל טוֹב, וּלְיַפּוֹת מַעֲשָׂיו בַּתּוֹרָה וּבְיִרְאַת הַשֵּׁם, וְהִיא הַנִּקְרֵאת יֶפֶת. וְהַהַנְהָגָה הַזּוֹ יַנְהִיג הָאָדָם לְהוֹלִיכוֹ בְּדֶרֶךְ חַיִּים.</p>"],[9514011910,"<p>וּמִי מְעַכֵּב וּמַפְסִידוֹ. (בראשית ו׳:י״א) וַתִּשָּׁחֶת הָאָרֶץ לִפְנֵי הָאֱלֹהִים, זֶהוּ הַגּוֹלֶם, הַמַּפְסִיד וְהַמַּשְׁחִית אֶת הַכֹּל. וְעָלָיו אָמַר שְׁלֹמֹה בְּחָכְמָתוֹ, (משלי ו׳:ל״ב) מַשְׁחִית נַפְשׁוֹ הוּא יַעֲשֶׂנָּה. מַאי הוּא יַעֲשֶׂנָּה, אָמַר רַבִּי כְּרוּסְפְּדָאי הַגּוֹלֶם יַעֲשֶׂנָּה נִשְׁחֶתֶת.</p>"],[9514011911,"<p>דָּבָר אַחֵר אֵלֶּה תּוֹלְדוֹת נֹחַ, מַה כְּתִיב לְמַעְלָה מֵהָעִנְיָן, (בראשית ו׳:ו׳-ז׳) וַיִּנָּחֶם ה' כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ וַיִּתְעַצֵּב אֶל לִבּוֹ. רַבִּי אֱלִיעֶזְר אוֹמֵר, בֹּא וּרְאֵה שֶׁאֵין כְּמִדַּת בָּשָׂר וָדָם, מִדּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מִדַּת בָּשָׂר וָדָם, עוֹשֶׂה מַה שֶּׁעוֹשֶׂה, וּלְאַחַר כֵּן מִתְחָרֵט וּמִתְעַצֵּב מִמֶּנּוּ, יָכוֹל אַף הַקָּדוֹשׁ בָּרוּךְ הוּא כֵּן.</p>"],[9514011912,"<p>תָּא שְׁמַע, דִּכְתִיב (דברים ל׳:ט״ו) רְאֵה נָתַתִּי לְפָנֶיךָ הַיּוֹם אֶת הַחַיִּים וְאֶת הַטוֹב וְאֶת הַמָּוֶת וְאֶת הָרָע. וְהִזְהִיר לָאָדָם וְאָמַר, (דברים ל׳:ט״ו) וּבָחַרְתָּ בַּחַיִּים לְמַעַן תִּחְיֶה. וְאִם הוּא הוֹלֵךְ בְּדֶרֶךְ רָע, הוּא בַּעֲוֹנוֹ יָמוּת. שֶׁנֶּאֱמַר, (משלי ה׳:כ״ב) עֲוֹנוֹתָיו יִלְכְּדוּנוּ אֶת הָרָשָׁע. כָּךְ כְּתִיב, (בראשית ו׳:ה׳) וַיַּרְא ה' כִּי רַבָּה רָעַת הָאָדָם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲנִי רוֹאֶה כִּי כֻלָּם מְחוּיָּיבִים, וְאִם יִכְלוּ בְּרָעָתָם, הֲרֵי יֵאָבֵד עוֹלָמִי. כֵּיוָן שֶׁרָאָה לְנֹחַ וּבָנָיו שֶׁהָיוּ צַדִּיקִים וְיִשָּׁאֵר פְּלֵיטָה בָּעוֹלָם, הִתְנַחֵם וְשָׂמַח.</p>"],[9514011913,"<p>וְא\"ר אֱלִיעֶזְר, הַאי וַיִּנָּחֶם, לְשׁוֹן נְחָמָה הוּא. וְכֵן כָּל וַיִּנָּחֶם שֶׁבַּתּוֹרָה, לְשׁוֹן נְחָמָה הוּא. רוֹאֶה אֶת הָרַע, וְרוֹאֶה אֶת הַטוֹב, וּמִתְנַחֵם עִם הַטוֹב. א\"ל ר' עֲקִיבָא, לִדְבָרֶיךָ, מַאי וַיִּתְעַצֵּב אֶל לִבּוֹ. א\"ל, בֹּא וּרְאֵה מִדַּת רַחְמָנוּתוֹ שֶׁל הקב\"ה, כִּי אע\"פ שֶׁהִתְנַחֵם לָקַח עִצָּבוֹן עַל אֲבֵדַת הָרְשָׁעִים, שֶׁאע\"פ שֶׁהָיוּ רְשָׁעִים, אֵינוֹ חָפֵץ בְּמִיתָתָן, וְלֹא הָיְתָה שִׂמְחָה לְפָנָיו.</p>"],[9514011914,"<p>א\"ר יְהוּדָה, מַאי דִכְתִיב וְנֹחַ מָצָא חֵן בְּעֵינֵי ה'. שְׁמוֹ גָרִים, נֹחַ בְּהִפּוּךְ חֵן. וְלָמָּה פָּתַח קְרָא בְּתוֹלְדוֹתָיו תְּחִלָּה, כְּדֵי לְהַרְאוֹת לָעוֹלָם כְּמוֹ שֶׁהוּא הָיָה צַדִּיק, אַף הֵם הָיוּ צַדִּיקִים, וּרְאוּיִין לְהִתְיַשֵּׁב הָעוֹלָם מֵהֶם.</p>"],[9514011915,"<p>וּמְנָא לָן תָּא חֲזֵי, כֵּיוָן שֶׁנִּכְנְסוּ לַתֵּיבָה, רָאוּ בְּצַעֲרוֹ שֶׁל עוֹלָם, וְנִצְטַעֲרוּ, וּמָנְעוּ עַצְמָם מִפְּרִיָּה וּרְבִיָּה. וְאעפ\"י שֶׁיָּצְאוּ, יָצְאוּ כְּמוֹ כֵן. עַד שֶׁרָאָה הקב\"ה מַעֲשֵׂיהֶם, וְאָמַר, לֹא תֹּהוּ בָּרָאתִי עוֹלָמִי, וְאַתֶּם פְּרוּ וּרְבוּ, הִזְדַּוְּוגוּ לִנְשׁוֹתֵיכֶם, וַעֲשׂוּ פְּרִיָּה וּרְבִיָּה. בְּאוֹתָהּ שָׁעָה, בֵּרְכָם, שֶׁנֶּאֱמַר, וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וגו'.</p>"],[9514011916,"<p>אֵלֶּה תּוֹלְדוֹת נֹחַ. רַבִּי פִּנְחָס פָּתַח, וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טֹבֹת הֵנָּה. מַאן אִינוּן בְּנֵי הָאֱלֹהִים, בְּנֵי גְדוֹלֵי הַדּוֹר. מְלַמֵּד שֶׁהָיוּ טוֹבוֹת מַרְאֶה, כְּתִיב הָכָא כִּי טוֹבוֹת הֵנָּה, וּכְתִיב הָתָם טוֹבַת מַרְאֶה מְאֹד. הָיוּ הוֹלְכוֹת עֲרוּמוֹת, וַאֲנָשִׁים הוֹלְכִים עֲרוּמִים, וְאֵלּוּ וְאֵלּוּ רוֹאִים אֶת עֶרְוָתָם, וְנוֹאֲפִים אֵלּוּ אֶת אֵלּוּ. וְלָמָּה נִקְרְאוּ בְּנֵי הָאֱלֹהִים, שֶׁהָיוּ גִּבּוֹרִים גְּדוֹלִים עֲנָקִים.</p>"],[9514011917,"<p>אָמַר ריב\"ל, זִימְנָא חָדָא עֲרָעִית בְּטוּרָא דְטִינָרָא דְּעֵיטָם. וְאַשְׁכָּחִית בִּתְרֵי סִטְרֵי טִינָרָא, תְּרֵין גּוּבְרִין, וְדַמְיָין בִּתְרֵין פּוּמִין, דָּא עִילָּאָה דְדָא. וַהֲווֹ מְמַלְּלוּ דָּא עִם דָּא, תָּא וְנַעַבְרֵיהּ מִן עָלְמָא. אִזְדַּמַּן לְהוֹ הַהוּא גוּבְרָא רַבְרְבָא, דְאַגְרַת בַּת מָחֳלַת, וּשְׁמֵיהּ יוֹסֵף שִׁידָא, אֲמַר לְהוֹן, הֲלֹא דָא הוּא רַבָּה סַגִּיאָה עִילָּאָה דְּדָרָא, דִּי בִּגְזֵרַת פּוּמֵיהּ אַעֲבִירָנָא מִן יִשּׁוּבָא דְאַרְעָא, וְדָא הוּא דְמַכְרְזֵי עֲלֵיהּ בִּרְקִיעָא.</p>"],[9514011918,"<p>עַד דַּהֲוֵינָא אָזְלֵי, אַשְׁכַּחְנָא אִמָּהוֹן דְּגוּבְרַיָיא הָאִינוּן, אָמְרָה לִבְרַתָּא זְעֵירְתָּא, אִלֵּין אִינוּן חֲגָבַיָיא זְעֵירַיָיא, דְּחֵילְהוֹן בְּפוּמְהוֹן, אַיְיתֵי לְהוֹן גַּבָּאי, וְנַעֲבֵיד מִנְּהוֹן טַעֲמָא דְתַבְשִׁילָא לְאָחוּךְ. עַד דַּאֲתַת, אִיתְרְחֵישׁ לָן נִיסָּא, וְאִיתְעֲבֵיד מִקַּדְמָהָא נַהֲרָא דְמַיָא רַבְרְבָא, שְׁמַעְנָא דַּהֲוַות אֲמָרַת, אִימָּא אִימָּא, פַּרְפָּרָא רַבַּאת סַבְרָנָא עֲבָרַת, וְעָרַקְנָא מִנְּהוֹן, וְאִשְׁתְּזֵיבְנָא.</p>"],[9514011919,"<p>וְאָמַר ריב\"ל, בִּימֵי דוֹר הַמַּבּוּל עָשָׂה הקב\"ה קְנֵה הַחִטִים, כִּקְנֵה אַרְזֵי הַלְּבָנוֹן. וְלֹא הָיוּ זוֹרְעִים וְקוֹצְרִים, אֶלָּא הָרוּחַ מְנַשֶּׁבֶת, וּמְנַשֵּׁר הַחִטִים לְמַטָה, וְאוֹסְפִים אוֹתָן. וְכֵן בְּכָל שָׁנָה וְשָׁנָה. לְאַחַר שֶׁחָטְאוּ, אָמַר עֹד כָּל יְמֵי הָאָרֶץ זֶרַע וְקָצִיר וְקֹר וָחֹם וְקַיִץ וָחֹרֶף וְיוֹם וָלַיְלָה לֹא יִשְׁבֹּתוּ.</p>"],[9514011920,"<p>וְא\"ר יְהוֹשֻׁעַ, לֹא נֶחְתַּם גְּזַר דִּינָם שֶׁל דּוֹר הַמַּבּוּל, עַד שֶׁפָּשְׁטוּ יְדֵיהֶם בַּגֶּזֶל, שֶׁנֶּאֱמַר וַתִּמָּלֵא הָאָרֶץ חָמָס.</p>"],[9514011921,"<p>וּבִימֵי דּוֹר הַמַּבּוּל הָיוּ פְּרִיָּה וּרְבִיָּה הַרְבֵּה, וּמִשָּׁעָה שֶׁהָיְתָה הָאִשָּׁה יוֹלֶדֶת, הָיוּ הוֹלְכִים וְשׁוֹלְחִים אוֹתָם כְּצֹאנָם, שֶׁנֶּאֱמַר יְשַׁלְּחוּ כַּצֹּאן עֲוִילֵיהֶם וְיַלְדֵיהֶם יְרַקֵּדוּן. וּלְאַחַר כָּל זֶה מַאי כְּתִיב בְּהוּ, (שם) וַיֹּאמְרוּ לָאֵל סוּר מִמֶּנּוּ וְדַעַת דְּרָכֶיךָ לֹא חָפָצְנוּ. עַד שֶׁנִּגְזַר דִּינָם וְהֶעבִירָם מִן הָעוֹלָם.</p>"],[9514011922,"<p>תָּנוּ רַבָּנָן, נֹחַ הָיָה מַתְרֶה בָּהֶם קוֹדֶם, וְלֹא שָׁמְעוּ מִמֶּנּוּ. שָׁהָה בַּעֲשִׂיַּית הַתֵּיבָה, לְמַעַן יִרְאוּ וְיָשׁוּבוּ, וְהָיוּ מַלְעִיבִין בּוֹ, עַד שֶׁגָּבַר עֲלֵיהֶם הַתְּהוֹם שֶׁהָיוּ הַמַּיִם יוֹצְאִין רוֹתְחִין כָּאֵשׁ, וְהַמַּיִם מִלְּמַעְלָה, וְנִמְחוּ מִן הָעוֹלָם.</p>"],[9514011923,"<p>אָמַר רִבִּי יִצְחָק, מַאי דִכְתִיב, (תהילים כ״ט:י׳) ה' לַמַּבוּל יָשָׁב, וְכִי לְדָוִד הָיָה לוֹמַר דָּבָר זֶה. וְכָל הָעוֹלָם יוֹדְעִין, שֶׁהוּא רִאשׁוֹן וְאַחֲרוֹן וַאֲזַי וְקוֹדֶם.</p>"],[9514011924,"<p>אֶלָּא אָמַר רִבִּי יִצְחָק, בֹּא וּרְאֵה בְּכָל מָקוֹם אַתְּ מוֹצֵא אֱלֹהִים מִדַּת הַדִּין, ה' מִדַּת הָרַחֲמִים. וְאַף עַל פִּי שֶׁמִּדַּת הַדִין הִיא, מִדַּת רַחֲמִים הָיְתָה בוֹ, שֶׁאִלְּמָלֵא כָּךְ אִתְחָרַב עָלְמָא. אֲבָל לְמַעַן אוֹתוֹ מִדַּת רַחֲמִים, אִתְיַישֵׁב עָלְמָא.</p>"],[9514011925,"<p>וְכֵן אַתְּ מוֹצֵא רְפוּאָה זוֹ, בְּכָל דִּין שֶׁהוּא עוֹשֶׂה. וְכֵן (בראשית י״ט:כ״ד) וַה' הִמְטִיר עַל סְדוֹם, נִשְׁאָר מִמֶּנּוּ פְּלֵיטָה. (שמות ל״ב:ל״ה) וַיִּגֹּף ה' אֶת הָעָם, נִשְׁאָר פְּלֵיטָה. וְכֵן כֻּלָּם.</p>"],[9514011926,"<p>אָמַר רִבִּי יְהוּדָה, חַכְּמִין הֲווֹ דָּרָא דְּטוֹפָנָא טְפֵי, דַּהֲווֹ יָדְעֵי מַה דַּעֲתִיד לְמֶהֱוֵי. אֲבָל נָסַבּוּ סוּכְלְתָנוֹ בְּלִבְּהוֹן. וַאֲמָרוּ, אִי קוּדְשָׁא בְּרִיךְ הוּא מַיְיתֵי טוֹפָנָא, אֲנַחְנָא גּוּבְרִין רָאמֵי קוֹמָתָא, וְנָשׁוּט עַל אַפֵּי מַיָּא, וְנִשְׁתֵּיזִיב. וְאִי מִן תְּהוֹמָא יֵיתֵי מַיָּא, רַגְלָנָא נָשׂוֹי עַל בֵּירָא דְמַיָּא, וְלָא יִפְקוֹן מַיָּא וְנִשְׁתֵּזִיב.</p>"],[9514011927,"<p>כַד אָתָא טוֹפָנָא, אַרְתַּח קוּדְשָׁא בְּרִיךְ הוּא מַיָּא דִתְהוֹמָא, וַהֲווּ מַשְׁוֵי רַגְלֵיהוֹן עַל עֵינָא דְמַיָּא, וְאִתְמְשַׁךְ מָשְׁכֵיהּ מִנֵּיהּ, וּנְפָלוּ. וּמַיָּא מִלְּעֵילָא הֲווֹ מִתְגַּבְּרֵי עִם מַיָּא דִתְהוֹמָא, וַהֲווּ מִתְגַּלְגְּלִין וְנַחֲתִין, נְמוֹקִין בִּרְתִיחוּתָא דִתְהוֹמָא לְבָבֶל. (בראשית ז׳:ט״ו) וַיָּבֹאוּ אֶל נֹחַ אֶל הַתֵּבָה. ר' יוֹחָנָן פְּתַח, (תהילים ס״ה:ה׳) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךָ נִשְׂבְּעָה בְּטוּב בֵּיתֶךָ קְדשׁ הֵיכָלֶךָ. בֹּא וּרְאֵה, כַּמָּה יֵשׁ לְאָדָם לִיזָּהֵר, וְלִבְדּוֹק עַצְמוֹ וּמַעֲשָׂיו בְּכָל יוֹם וָיוֹם.</p>"],[9514011928,"<p>הֵיאַךָ קָם בְּצַפְרָא, יֵימַר, יְהִי רָצוֹן מִלְּפָנֶיךָ ה' אֱלֹהַי, שֶׁיְהֵא לִבִּי נָכוֹן וּמָסוּר בְּיָדִי, שֶׁלֹּא אֶשְׁכָּחֶךָֹּ. אוֹשֵׁיט רַגְלוֹהִי לְמֵיזַל, יְעַיֵּין בְּצַעֲדֵי רַגְלוֹהִי, דְּלָא יְשׂוּטוּן לְאַבְאָשָׁא. אֲזָל לִדְבַר מִצְוָה, יִרְהַט. שֶׁנֶּאֱמַר (הושע י״א:י׳) אַחֲרֵי ה' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג. וַאֲפִילּוּ בְּשַׁבָּת מִצְוָה לְמִירְהַט. עָבַר כָּל יוֹמָא, צָרִיךְ לְמִבְדַּק גּוּפֵיהּ, מַה דַּעֲבַד בְּהַהוּא יוֹמָא, וְאִי צָרִיךְ יַעֲשֶׂה מִיָּד תְּשׁוּבָה עָלָיו קוֹדֶם שֶׁיִּישַּׁן.</p>"],[9514011929,"<p>תָּנוּ רַבָּנָן, מַאי דִכְתִיב, (שיר השירים ח׳:י״א) כֶּרֶם הָיָה לִשְׁלֹמֹה בְּבַעַל הָמוֹן נָתַן אֶת הַכֶּרֶם לַנֹּטְרִים אִישׁ יָבִא בְּפִרְיוֹ אֶלֶף כָּסֶף. אָמַר רִבִּי יְהוּדָה, כֶּרֶם הָיָה לִשְׁלֹמֹה, לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. בְּבַעַל הָמוֹן, אֵלּוּ מַלְאֲכֵי שָׁלוֹם. נָתַן אֶת הַכֶּרֶם לַנֹּטְרִים אֵלּוּ שׁוֹמְרֵי מִשְׁמֶרֶת בָּאָרֶץ. אִישׁ יָבִיא בְּפִרְיוֹ אֶלֶף כָּסֶף, אֶלֶף הֲנָאוֹת שֶׁהַנְּשָׁמָה כּוֹסֶפֶת בָּהֶם.</p>"],[9514011930,"<p>דָּבָר אַחֵר כֶּרֶם הָיָה לִשְׁלֹמֹה, זוֹ הִיא הַתּוֹרָה. בְּבַעַל הָמוֹן, מִן הַשָּׁמַיִם. נָתַן אֶת הַכֶּרֶם לַנֹּטְרִים, אֵלּוּ יִשְׂרָאֵל, שֶׁהֵם שׁוֹמְרֵי מִשְׁמַרְתָּהּ. אִישׁ יָבִיא בְּפִרְיוֹ אֶלֶף כָּסֶף, שֶׁל שְׂכָרָהּ.</p>"],[9514011931,"<p>רַבִּי יוֹסֵי וְר' חִיָּיא הֲווֹ אָזְלֵי בְּאוֹרְחָא, אָמַר רִבִּי חִיָּיא, אֵימָא לָן מִמִּילֵי מַעַלְיָיתָא דְּהֲוָה אָמַר אָבוּךְ מִתַּעֲנוּגֵי הַנְּשָׁמָה. אָמַר לֵיהּ נֵיפוֹק מִכָּאן, דְּקַפּוֹטְקִיָּא אִלֵּין בְּצִירֵי מֵעוֹבָדֵי דְכַשְׁרָן. אָמַר לֵיהּ כָּךְ יָאוֹת לָן לְמִלְעֵי בְּאוֹרַיְיתָא, וְנִשְׁתֵּיזִיב מִנְּהוֹן. אֲמַר, בַּאֲתַר דְּסַכָּנָה, לָא אֲמָרוּהָ רַבָּנָן.</p>"],[9514011932,"<p>לְבָתַר דִּנְפָקוּ וַאֲזָלוּ בְּאוֹרְחָא, אָמַר רִבִּי יוֹסֵי, אֵימָא לָךְ מִילְתָא, וְהִיא טְמִירְתָא בֵּינֵי מַטְמוֹנַיָיא דְּאַבָּא, בְּבֵי גְּנָזוֹהִי. וְדָא הִיא, דִּכְתִיב, כֶּרֶם הָיָה לִשְׁלֹמֹה וכו', הַאי כֶּרֶם, דָּא הִיא נִשְׁמָתָא קַדִּישָׁא, דְּאִתְנְטָעַת לְעֵילָא, תְּחוֹת כּוּרְסֵי יְקָרֵיהּ. לִשְׁלֹמֹה, מַלְכָּא דִּשְׁלָמָא כּוֹלָּא דִילֵיהּ. בְּבַעַל הָמוֹן, הוּא כּוּרְסֵי יְקָרֵיהּ דְּשַׁלִּיטָא עַל כָּל חֵילֵי שְׁמַיָא וְאַרְעָא, וְהוּא מָארֵיהּ דְּכָל חֵילָא. יְהַב נִשְׁמָתָא דָא, לְמִי, לַנּוֹטְרִים, אִלֵּין נָטְרֵי פִּקּוּדוֹי.</p>"],[9514011933,"<p>וְאִית לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא עָלְמִין סַגִּיאִין לְעֵילָא, עַל כָּל חַיָילֵי שְׁמַיָא, וְאֶלֶף וּמָאתָן עָלְמִין אָחֳרָנִין, דְּעָיִיל בְּהוֹן לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא בְּגִנְתָּא דְעֵדֶן. אִישׁ יָבִיא בְּפִרְיוֹ אֶלֶף כָּסֶף, אֶלֶף עָלְמִין דִּכְסִיף בְּהוֹן קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514011934,"<p>אָמַר רִבִּי יִצְחָק, מְסַיֵּים אֲנִי לְהַאי מִילְתָא דְר' יוֹסֵי, וְכָךְ הִיא, מִמַּה דִּכְתִיב אַחֲרָיו, כַּרְמִי שֶׁלִּי לְפָנָי הָאֶלֶף לְךָ שְׁלֹמֹה וּמָאתַיִם לַנֹּטְרִים אֶת פִּרְיוֹ, שֶׁכִּסֵּא הַכָּבוֹד מַכְרֶזֶת וְאוֹמֶרֶת, רִבּוֹנוֹ שֶׁל עוֹלָם, זוֹ הַנְּשָׁמָה נִיטְלָה מִמֶּנּוּ, הֲרֵי הִיא לְפָנָי. (שם) הָאֶלֶף לְךָ שְׁלֹמֹה, שֶׁלְּךָ הֵם אוֹתָם הָאֶלֶף עוֹלָמוֹת, וְאֵינָם רְאוּיִם לְאַחֵר. וּמָאתַיִם לַנֹּטְרִים אֶת פִּרְיוֹ, זֶה עֵדֶן, שֶׁיֵּשׁ בּוֹ מָאתַיִם עוֹלָמוֹת הֲנָאוֹת וְכִיסוּפִין לְנַפְשׁוֹת הַצַּדִּיקִים.</p>"],[9514011935,"<p>דִּתְנַן, אָמַר רַבִּי, בְּכָל לַיְלָה וְלַיְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנַס בְּכָל אוֹתָן הָעוֹלָמוֹת, וּבִשְׁעַת חֲצִי הַלַּיְלָה, נִכְנַס בְּמָאתַיִם עוֹלָמוֹת שֶׁל גַּן עֵדֶן, לְהִשְׁתַּעְשֵׁעַ עִם הַצַּדִּיקִים. שֶׁנֶּאֱמַר, (שיר השירים ז׳:י״ד) חֲדָשִׁים גַּם יְשָׁנִים דּוֹדִי צָפַנְתִּי לָךְ. וְדָוִד הַמֶּלֶךְ עָלָיו הֲשָׁלוֹם, נִכְסַף לִבּוֹ, כְּשֶׁרָאָה מַעֲלוֹת הַצַּדִּיקִים, אָמַר רִבּוֹנוֹ שֶׁל עוֹלָם, (תהילים ס״ה:ה׳) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךָ.</p>"],[9514011936,"<p>אָמַר רִבִּי אַבָּהוּ, בֹּא וּרְאֵה כַּמָּה יֵשׁ לוֹ לָאָדָם לְהִזָּהֵר, הוֹאִיל וְנִשְׁמַת אֵל בְּאַפָּיו, לְהִטָהֵר מֵעֲוֹנוֹתָיו, וּלְעַיֵּין בְּמַעֲשָׂיו, וְלֹא יֶחֱטָא לִפְנֵי קוֹנוֹ, לְמַעַן תִּהְיֶה מַעֲלָתוֹ עִם שְׁאָר הַצַּדִּיקִים, וְלֹא יִמָּצֵא מוֹחֶה בְּיָדוֹ, בַּעֲלוֹתוֹ לִרְאוֹת אֶת פְּנֵי ה'.</p>"],[9514011937,"<p>וּמִמִּי אַתָּה לָמֵד, מִן הַתֵּיבָה. בֹּא וּרְאֵה, מַאי דִכְתִיב, (בראשית ז׳:ט״ו) וַיָּבֹאוּ אֶל נֹחַ אֶל הַתֵּבָה, בְּלֹא רְשׁוּת. דְּאָמַר רִבִּי יִצְחָק, כָּל אוֹתָן הָעוֹפוֹת וְהַחַיּוֹת וְהַבְּהֵמוֹת שֶׁלֹּא חָטְאוּ, הֵם בָּאִים, וְהַתֵּיבָה קוֹלַטְתָּן, וְאוֹתָן שֶׁחָטְאוּ, הַתֵּיבָה דּוֹחָה אוֹתָן לַחוּץ. וּמַה הַתֵּיבָה, שֶׁהוּא עֵץ יָבֵשׁ כָּךְ. פִּתְחֵי הַשָּׁמַיִם וְשׁוֹמְרֵיהֶם, וְשׁוֹמְרֵי הַמִּשְׁמָרוֹת, וְכִסֵּא הַכָּבוֹד, שֶׁיֵּשׁ בָּהֶם הָרְשׁוּת, עַל אַחַת כַּמָּה וְכַמָּה לִהְיוֹת קוֹלְטִין, לְמִי שֶׁלֹּא חָטְאוּ, וְלִהְיוֹת דּוֹחִים לְמִי שֶׁחָטְאוּ.</p>"],[9514011938,"<p>רַבִּי חִיָּיא אָמַר, נֹחַ מִקְּטַנֵּי אֲמָנָה הָיָה, שֶׁלֹּא הָיָה מַאֲמִין שֶׁיָּבֹא הַמַּבּוּל, וְלֹא נִכְנַס לַתֵּיבָה עַד שֶׁהַמַּיִם דְּחָקוּהוּ, שֶׁנֶּאֱמַר וַיָּבֹא נֹחַ מִפְּנֵי מֵי הַמַּבּוּל.</p>"],[9514011939,"<p>אָמַר רִבִּי יִצְחָק, בֹּא וּרְאֵה, כְּשֶׁהוֹרִיד הַקָדוֹשׁ בָּרוּךְ הוּא הַמַּיִם, הוֹרִידָם תְּחִלָּה בְּרַחֲמִים, כְּדֵי לְהַרְאוֹת לָעוֹלָם, שֶׁאִם יָשׁוּבוּ יְקַבְּלֵם. מַשְׁמַע דִּכְתִיב בַּתְּחִלָּה, (שם) וַיְהִי הַגֶּשֶׁם, וּלְהַלָּן הוּא אוֹמֵר, (שם) וַיְהִי הַמַּבּוּל, שֶׁאִם יַחְזְרוּ יִהְיוּ גִּשְׁמֵי בְּרָכָה, לֹא חָזְרוּ, הָיָה מַבּוּל.</p>"],[9514011940,"<p>וְאָמַר רִבִּי יִצְחָק, שְׁבוּעָה נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאֵינוֹ חָפֵץ בְּמִיתָתָן שֶׁל רְשָׁעִים, שֶׁנֶּאֱמַר, (יחזקאל ל״ג:י״א) חַי אָנִי נְאֻם ה' אֱלֹהִים אִם אֶחְפֹּץ בְּמוֹת הָרָשָׁע כִּי אִם בְּשׁוּב רָשָׁע מִדַּרְכּוֹ וְחָיָה וכו'. וְחָיָה בִּשְׁנֵי עוֹלָמוֹת, הָעוֹלָם הַזֶּה וְהָעוֹלָם הַבָּא.</p>"],[9514011941,"<p>וְאָמַר רִבִּי יִצְחָק, אַשְׁרֵי הַבָּנִים שֶׁאוֹמְרִים לָהֶם כָּךְ, וְהָשִׁיבוּ וִחְיוּ. (שם) שׁוּבוּ שׁוּבוּ מִדַּרְכֵיכֶם הָרָעִים וְלָמָּה תָמוּתוּ בּ\"י. כִּי הוּא אֵינוֹ חָפֵץ בְּמִיתָתָן שֶׁל רְשָׁעִים אֶלָּא שֶׁיַּחְזְרוּ בִּתְשׁוּבָה לְמַעַן יִחְיוּ.</p>"],[9514011942,"<p>ר' יוֹחָנָן פָּתַח, (איוב י״א:כ׳) וְעֵינֵי רְשָׁעִים תִּכְלֶינָה וּמָנוֹס אָבַד מִנְּהֶם וְתִקְוָתָם מַפַּח נָפֶשׁ. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְכַת לִסְטִים שֶׁהָיוּ שׁוֹדְדִים בֶּהָרִים, שָׁמַע הַמֶּלֶךְ, וְשָׁלַח עֲלֵיהֶם גְּיָיסוֹתָיו, וּתוֹפְסָם וְהִנִּיחוּם בְּמִגְדָּל גָּבוֹהַּ. וְהָיוּ בָהֶם פִּקְחִים, אָמְרוּ יְדַעְנָא בְּנַפְשָׁתָנָא דַּעֲבַדְנָא עוֹבָדִין בִּישִׁין, וְלָא יָכֵילְנָא לְאִשְׁתֵּזָבָא. מֶה עָשׂוּ, חָפְרוּ חֲפִירָה אַחַת בַּמִּגְדָּל, וְיָצְאוּ וּבָרְחוּ לָהֶם. טִיפֵּשׁ אֶחָד הָיָה בֵּינֵיהֶם, וְרָאָה אֶת הַחֲפִירָה, וְלא רָצָה לָנוּס לְהִמָּלֵט.</p>"],[9514011943,"<p>לְמָחָר בָּא הַמֶּלֶךְ לִרְאוֹת אֶת הַמִּגְּדָל, וְאֶת הַלִּסְטִים, רָאָה אֶת הַחֲפִירָה שֶׁעָשׂוּ וְנָסוּ וְנִמְלְטוּ. אָמַר לָזֶה, שׁוֹטֶה, חֲבֵרֶיךָ בָּרְחוּ בְּזוֹ הַחֲפִירָה וְנִמְלְטוּ מִדִּינִי, מָה אֲנִי יָכוֹל לַעֲשׂוֹת עוֹד לָהֶם, אֲבָל אַתָּה שֶׁרָאִיתָ אֶת הַחֲפִירָה בְּעֵינֶיךָ, וְלֹא רָצִיתָ לְהִמָּלֵט יְנַקְּרוּ עֵינֶיךָ, וְאַחַר כָּךְ יִתְלוּ אוֹתְךָ עַל עֵץ.</p>"],[9514011944,"<p>כָךָ הַלִּסְטִים, אֵלּוּ הָרְשָׁעִים הַהוֹלְכִים בְּמַחֲשַׁכִּים. הָרְשָׁעִים הַפִּקְחִים, מָה הֵם עוֹשִׂים. אָמְרוּ חָטָאנוּ לַמֶּלֶךְ, אָנָה נִמָּלֵט מִדִּינוֹ. אֲבָל נִפְתַּח דֶּרֶךְ הַתְּשׁוּבָה, וּנְבַקֵּשׁ רַחֲמִים, וְנִבְרַח וְנִימָּלֵט, וְכָךְ עָשׂוּ. הַטִפְּשִׁים מָה הֵם עוֹשִׂים, רוֹאִים דֶּרֶךְ הַתְּשׁוּבָה פָּתוּחַ לִפְנֵיהֶם, שֶׁפָּתְחוּ הָאֲחֵרִים, וְנִמְלְטוּ מִדִּין שָׁמַיִם, וְהֵם אֵינָם רוֹצִים לְהִמָּלֵט.</p>"],[9514011945,"<p>אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, שׁוֹטִים, אֲחֵיכֶם בָּרְחוּ וְנִמְלְטוּ, בְּאוֹתוֹ דֶּרֶךְ שֶׁל תְּשׁוּבָה שֶׁפָּתְחוּ, מָה אֲנִי יָכוֹל לַעֲשׂוֹת עוֹד לָהֶם, אֲבָל אַתֶּם עֵינֵיכֶם שֶׁרָאוּ הַחֲפִירָה, דֶּרֶךְ הַתְּשׁוּבָה פָּתוּחַ לִפְנֵיכֶם, וְלֹא רְצִיתֶם לְהִכָּנֵס בְּתוֹכוֹ וְלָנוּס וּלְהִמָּלֵט, מַאי כְּתִיב בְּכוֹ, וְעֵינֵי רְשָׁעִים תִּכְלֶינָה. שֶׁרָאוּ הַדֶּרֶךְ פָּתוּחַ וּמָנוֹס אָבַד מִנְּהֶם, שֶׁלֹּא רָצוּ לָנוּס וּלְהִמָּלֵט. וְתִקְוָתָם מַפַּח נֶפֶשׁ לָעוֹלָם הַבָּא.</p>"],[9514011946,"<p>כָךָ דּוֹר הַמַּבּוּל, רָאוּ לְנֹחַ עוֹשֶׂה הַתֵּיבָה, וּמַתְרֶה בָּהֶם בְּכָל יוֹם, וְרָאוּ אוֹתוֹ נִכְנָס לַתֵּיבָה, וְלֹא רָצוּ לָשׁוּב. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעֵינֵי רְשָׁעִים תִּכְלֶינָה וּמָנוֹס אָבַד מִנְּהֶם, שֶׁלֹּא רָצוּ לָשׁוּב וְלָנוּס מִדִּינִי, וְתִקְוָתָם מַפַּח נָפֶשׁ, שֶׁלֹּא יָקוּמוּ לְיוֹם הַדִּין, שֶׁנֶּאֱמַר (איוב כ״ו:ה׳) הָרְפָאִים יְחוֹלָלוּ מִתַּחַת מַיִם וְשֹׁכְנֵיהֶם.</p>"],[9514011947,"<p>(בראשית ט׳:כ׳) וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה. אָמַר רִבִּי יוֹסֵי, לָמָּה נִקְרָא אִישׁ הָאֲדָמָה. שֶׁנִּתְיַישְׁבָה מִמֶּנּוּ הָאֲדָמָה. כְּלוֹמַר אֲדוֹן הָאֲדָמָה. רַבָּנָן אָמְרֵי, אִישׁ הָאֲדָמָה, לְפִי שֶׁבִּשְׁבִילוֹ עָמְדָה הָאֲדָמָה בְּכֹחָהּ וְטִבְעָהּ. שֶׁנֶּאֱמַר (שם ה) זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ וּמֵעִצְבוֹן יָדֵינוּ מִן הָאֲדָמָה אֲשֶׁר אֵרַרָהּ ה'. תֵּדַע לָךְ, כֵּיוָן שֶׁחָטָא אָדָם נִתְאַרְרָה הָאֲדָמָה, שֶׁנֶּאֱמַר (שם ג) אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךָ. וְעָמְדָה בְּקִלְּלוֹתֶיהָ, עַד שֶׁבָּא נֹחַ וּבִטֵל הַקְּלָלָה.</p>"],[9514011948,"<p>דְּתַנְיָא אָמַר רִבִּי חִיָּיא רַבָּה, בְּשָׁעָה שֶׁאָמַר הַקָדוֹשׁ בָּרוּךְ הוּא לְנֹחַ צֵא מִן הַתֵּיבָה, אָמַר לְפָנָיו רִבּוֹנוֹ שֶׁל עוֹלָם, לְאָן אֵצֵא, אֵצֵא לָאֲדָמָה שֶׁנִּתְאָרְרָה. וּמִפְּנֵי שֶׁנִּתְאָרְרָה אָבְדוּ שׁוֹכְנֶיהָ, וְנִתְאָרְרוּ כּוּלָּם וְנִתְמַעֲטוּ. אָמַר הַקָדוֹשׁ בָּרוּךְ הוּא, לֹא כָךְ אַתֶּם, אֶלָּא שִׁרְצוּ בָאָרֶץ וּרְבוּ בָהּ. הָאֲחֵרִים אָבְדוּ בָהּ, אֲבָל אַתֶּם פְּרוּ וּרְבוּ וְשִׁרְצוּ בָהּ.</p>"]]});
